  // Thrume as a country beyond a march: the company that comes in by the salt road is the world's own.
  Entity party: group "Your company".
}

data/adventures/thrume/saltgrave.kyr:
Module thrume "Thrume" {
  Description "Saltgrave: the Salt Office, the dream-houses, the night carts.".

  Place salt_office "the Salt Office" is building within saltgrave.
  Place saltcellar "the Saltcellar" is building within saltgrave.
  Place red_lantern "the Red Lantern" is building within saltgrave.
  Place shrine "the Hearth-Mother's shrine" is building within saltgrave.
  Place chandlery "Dunmore's chandlery" is building within saltgrave.

  Place salt_road "the salt road below the town" is room within lowroad at 0, 0.
  Place market "the market square" is room within saltgrave at 1, 1.
  Place office_floor "the Salt Office" is room within salt_office at 2, 1.
  Place provost_room "the provost's room" is room within salt_office at 2, 0.
  Place inn_room "the Saltcellar's taproom" is room within saltcellar at 0, 1.
  Place lantern_front "the Red Lantern's front room" is room within red_lantern at 1, 2.
  Place smoke_room "the smoke-room" is room within red_lantern at 2, 2.
  Place lantern_back "the back room of the Red Lantern" is room within red_lantern at 2, 3.
  Place shrine_room "the shrine" is room within shrine at 0, 0.
  Place chandlery_shop "Dunmore's chandlery" is room within chandlery at 0, 2.
  Place miners_row "the miners' row" is room within saltgrave at 1, 0.
  Place carters_yard "the carters' yard" is room within saltgrave at 1, 3.
  Place cart_road "the cart road" is room within fellside at 1, 1.
  Place scree_foot "the foot of the scree road" is room within fellside at 0, 0.

  Passage salt_gate "the town gate" is road between salt_road and market taking 20 minutes.
  Passage office_door "the Salt Office door" is door between market and office_floor.
  Passage provost_door "the provost's door" is door between office_floor and provost_room.
  Passage inn_door "the Saltcellar's door" is door between market and inn_room.
  Passage lantern_door "the Red Lantern's door" is door between market and lantern_front.
  Passage smoke_curtain "the smoke-room curtain" is doorway between lantern_front and smoke_room.
  Passage lantern_back_door "the Lantern's back door" is door between smoke_room and lantern_back.
  Passage back_yard_gate "the yard gate behind the Lantern" is gate between lantern_back and carters_yard.
  Passage shrine_door "the shrine door" is door between market and shrine_room.
  Passage chandlery_door "Dunmore's door" is door between market and chandlery_shop.
  Passage row_lane "the row lane" is path between market and miners_row taking 10 minutes.
  Passage yard_lane "the yard lane" is path between market and carters_yard taking 10 minutes.
  Passage cart_track "the cart road" is road between carters_yard and cart_road taking 1 hour.
  Passage scree_lane "the north lane" is path between miners_row and scree_foot taking 30 minutes.

  Observe road_scene at salt_road when not dark() "The salt road comes up out of the river country between fields gone white at the edges, as if salted. Ahead, Saltgrave sits under the fells in its own dust: new timber, white roofs, a church tower with no church yet. Beyond the town the fells go up and up, brown and long and oddly smooth, like something lying under a blanket.".
  Observe road_night at salt_road when dark() "The town's lights are few and yellow. One lantern, red, burns later than the rest.".
  Observe market_scene at market when not dark() and not woken(fells) "A square of trodden white dust. Carts, salt-dust on everything, a dry pump, a notice on a post, and on one side a narrow house with a red lantern over its door, unlit by day.".
  Observe market_night at market when dark() and not woken(fells) "The square is empty but for a dog. Over the narrow house on the south side, the red lantern is lit.".
  Observe office_scene at office_floor when true "Scales, sacks, a long counter and a clerk behind it. On the wall a map of the workings, Number One to Number Four, and on Number Four someone has written CLOSED in red, and someone else has crossed it out.".
  Observe provost_scene at provost_room when true "A good room for a raw town: a carpet, a decanter, a strongbox. A ledger lies open on the desk.".
  Observe inn_scene at inn_room when true "Low beams, salt-cured hams, and miners drinking without talking. In the best corner a man in the Margravine's blue and silver eats alone, with a sword across the bench beside him.".
  Observe front_scene at lantern_front when true "A dim room hung with red cloth, warm and sweet-smelling, very quiet. A little table, and a chair behind it.".
  Observe smoke_scene at smoke_room when true "Pallets in a row, and on them people asleep with their eyes moving under the lids: miners, a girl in a good dress, an old man. A brazier burns something red that smells of iron and rain. Every sleeper's lips are moving, and they are all saying the same thing.".
  Observe back_scene at lantern_back when true "A storeroom: sacks of red salt, blankets, rope. A row of pegs by the yard gate, and on them the coats of people who are not wearing them.".
  Observe shrine_scene at shrine_room when true "A whitewashed room with a hearth for an altar. The fire on it is the only one in Saltgrave that never goes out. Prayers are nailed on the wall on scraps: for the men in the Number Four, for a son, for sleep.".
  Observe chandlery_scene at chandlery_shop when true "Candles, rope, lamp-oil, picks. Everything a mine needs, and too much of it, now the mine is shut.".
  Observe row_scene at miners_row when true "A double row of salt-white cottages. Forty doors have a twist of black wool on the latch: the families of the men the giants took.".
  Observe yard_scene at carters_yard when not dark() "A yard of salt-carts with their shafts down, and the stable smell. The carts have stood idle since the mine was shut; their axles are freshly greased.".
  Observe cart_road_scene at cart_road when true "The cart road climbs the fellside in long loops toward the black mouths of the workings. The turf on either side is warm to the hand.".
  Observe scree_foot_scene at scree_foot when true "The north lane gives out into scree. A path goes up it, very steep, toward the shoulder of the fells and a smudge of smoke under the glacier.".
  Passage scree_climb_long "the scree road" is path between scree_foot and scree_road taking 2 hours.

  // The Margravine's envoy, and the price on the thane.
  Person varne "Sir Odo Varne" at inn_room {
    Role "the Margravine's envoy". Ancestry human. Calling warrior. Level 6. Peaceable.
  }
  Discovery bounty_known "The Margravine's notice: FOR THE HEAD OF THE GIANT MÓRRACH, THAT CALLS HIMSELF THANE, THE LORDSHIP OF HARROWBY AND ITS RENTS. SIR O. VARNE, FOR IDONY VASK, MARGRAVINE OF EBB." {
    Source notice "the notice on the market post" at market readable by party.
    Known by varne.
  }
  Topic varne_bounty with varne "Ask Sir Odo Varne about the giants" when true once {
    Says "'They came down off the fells four months ago,' says Varne, 'and smashed every mine-head we have, and carried off forty men, and burned the overseer in his house.' He wipes his knife. 'The Margravine must have the salt by the new moon. Harle's host will be at the Ebb by then, and the companies she means to hire want paying in something heavier than promises. Bring me the thane's head and you are lords. Overseer Brannoc has gone down the old adit with a crew to keep the salt coming meanwhile. He is not a man who stops.'".
    On discuss { Assert knows(actor, bounty_known). Assert knows(actor, brannoc_below). }
  }
  Discovery brannoc_below "Overseer Brannoc has gone down the old adit of the Number Four with a crew, to keep cutting red salt for the Margravine.".
  Topic varne_truth with varne "Tell Sir Odo Varne what the red salt is" when knows(actor, thrume_known) and knows(actor, salt_is_blood) once {
    Says "Varne hears you out without interrupting, which is a courtesy you did not expect. At the end he is quiet a long time. 'If you are lying, you are the best liars I ever met,' he says. 'If you are not, the Margravine is cutting the throat of the ground she stands on.' He takes a folded paper from his coat, sealed in blue wax, writes on it, and holds it out. 'Brannoc obeys the seal. Not me. The seal. Give him this.'".
    On discuss { Assert lends(varne, seal_letter, actor). Assert at(seal_letter, inn_room). }
  }
  Kind margrave_seal "a letter under the Margravine's blue seal" is treasure worth 0 weighing 0.
  Item seal_letter "an order under the Margravine's seal" is margrave_seal at limbo owned by varne.
  Place limbo "nowhere" is room within lowroad at 1, 0.

  // The provost and his ledger.
  Person hauk "Provost Lisle Hauk" at provost_room {
    Role "provost of the Salt Office". Ancestry human. Peaceable.
    Objects "Hauk sees {?i} in your hands and goes the colour of tallow. 'That is the Office's,' he says. 'I will have the watch on you.'".
  }
  Discovery ledger_known "The Salt Office ledger: every week since spring, forty crowns in salt-silver from 'the Lantern, for quiet', in the provost's own hand. Beside the last three entries, a tally of carts: four, six, nine." {
    Source office_ledger "the Salt Office ledger" at provost_room readable by party.
    Known by hauk.
  }
  Topic hauk_lantern with hauk "Ask Provost Hauk about the Red Lantern" when not knows(actor, ledger_known) once {
    Says "'A respectable house,' says Hauk. 'Miners need their rest. The Office licenses it.' He moves the ledger an inch further from you without looking at it.".
  }
  Topic hauk_ledger with hauk "Ask Provost Hauk what the carts in his ledger carry" when knows(actor, ledger_known) once {
    Says "Hauk sits down. 'Sleepers,' he says, very low. 'The ones who sleep too deep to wake. She says they are taken up to the hot springs above the workings, to be cured. She pays for the carts. She pays for my not asking.' He looks at his hands. 'I have not asked. I have a daughter in Ebb.'".
    On discuss { Assert knows(actor, carts_known). }
  }

  // The dream-house.
  Person quietly "Mother Quietly" at lantern_front {
    Role "keeper of the Red Lantern". Ancestry human. Peaceable.
    State smiling "Mother Quietly sits behind her little table with her hands folded, smiling. Her eyes do not move when she looks at you; her head does.".
    State emptied "Mother Quietly sits behind her little table with her hands folded. There is nobody behind her eyes at all.".
  }
  Person dreamers "the dreamers" at smoke_room {
    Role "sleepers on the pallets". Ancestry human. Numbers 4. Peaceable.
  }
  Discovery dream_shared "Everyone who sleeps on the red salt dreams the same dream: a palace in a sky too close to the ground, and a great slow heart beating under the floor.".
  Topic dreamers_dream with dreamers "Listen to what the sleepers are saying" when true once {
    Says "You lean close. They are all saying it, the girl in the good dress and the old man and the miners, in the same breath: 'The sky is so close. The floor is beating. The sky is so close. The floor is beating.' One of the miners opens his eyes, looks at you without seeing you, and says, quite clearly, 'He is turning over,' and sleeps again.".
    On discuss { Assert knows(actor, dream_shared). }
  }
  Topic quietly_col with quietly "Ask Mother Quietly about Col Dunmore" when knows(actor, col_gone) and state(quietly, smiling) once {
    Says "'Such a sad boy,' says Mother Quietly. 'His father in the mine. He slept so beautifully.' Her head tilts; her eyes stay where they were. 'He has gone up to the springs, to be cured. They all go up, the deep sleepers. Would you like to rest a little? You look so tired.'".
  }
  Action rest_on_salt(actor: group, site: place) "Lie down on a pallet and breathe the red smoke" {
    Description "Mother Quietly says it is the best sleep in the world. The dreamers' faces say she may be right.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, smoke_room) and not dreamt(actor).
    Time 6.
    On success { Assert dreamt(actor). }
    Result "You sleep, and you are standing in a palace of white stone with the sky so close above it you could touch the clouds. Under the floor something vast is beating, very slowly, and the whole palace rises and falls with it like a chest. Far away, at the end of a long hall, someone grey with no mouth turns to look at you, and you wake on the pallet with your heart going like a bird's.".
  }
  Relation dreamt(group).
  // Seen only by those who have dreamt on the salt: what the Court's thralls look like to the dreaming.
  Person watcher "the grey thing behind Mother Quietly" at lantern_front {
    Role "something grey and soft-faced, standing where her shadow should be". Ancestry human. Peaceable.
    Seen when dreamt(viewer).
  }
  Topic watcher_speaks with watcher "Look the grey thing in its soft face" when true once {
    Says "It has no mouth. It speaks anyway, inside your head, in the kindest voice you have ever heard: 'You slept so well. Come down and sleep with us. It is so quiet in Hush.' Mother Quietly, in front of it, smiles a little wider, as if she had said it.".
    On discuss { Assert knows(actor, hush_named). }
  }

  // The night carts.
  Person hushed "the night carters" at lantern_back {
    Role "two men with still eyes, who do not speak". Ancestry human. Calling warrior. Level 2. Numbers 2. Peaceable.
  }
  Relation carting(group). Relation ringBroken(group).
  Rule carters_out when dark() and at(hushed, lantern_back) and not ringBroken(hushed) and untilLight(clock) > 36 { Assert at(hushed, carters_yard). Assert carting(hushed). }
  Rule carters_back when at(hushed, carters_yard) and (untilLight(clock) <= 36 or ringBroken(hushed)) { Assert at(hushed, lantern_back). Retract carting(hushed). }
  Observe carts_by_night at carters_yard when carting(hushed) "Two men with still eyes are lifting sleepers out of the Lantern's back gate, wrapped in blankets, and laying them in a salt-cart like sacks. Nobody sleeping wakes. When the cart is full they lead the horse out on the cart road toward the workings, without a lantern." teaches carts_known.
  Discovery carts_known "By night the Red Lantern's carters carry the deepest sleepers up the cart road to the workings, in salt-carts.".

  // Breaking the ring: Mother Quietly cornered.
  Topic quietly_carts with quietly "Ask Mother Quietly where the carts go" when knows(actor, carts_known) and state(quietly, smiling) once {
    Says "Mother Quietly's smile does not change. Then it does not change for too long. Her hands come apart on the table, slowly, as if someone else were unfolding them, and she sits back. Her mouth opens. 'Down,' she says, in a voice with no breath behind it. 'Down to Hush, where it is quiet.' Then nothing is behind her eyes at all. Something drops from her fingers and rolls across the table: a grey pebble, humming.".
    On discuss { Assert state(quietly, emptied). Assert ringBroken(hushed). Assert knows(actor, hush_named). Assert knows(actor, quietly_emptied). }
  }
  Discovery hush_named "The sleepers carried from the Red Lantern go 'down to Hush, where it is quiet'.".
  Discovery quietly_emptied "Cornered, Mother Quietly was emptied like a cup by whatever was behind her, and dropped a grey humming stone.".
  Kind hush_stone "a grey pebble that hums at the edge of hearing" is treasure worth 1 weighing 0.
  Item hush_pebble "a grey humming pebble" is hush_stone at lantern_front hidden until quietly_emptied.

  // Hesper Dunmore and her son.
  Person hesper "Hesper Dunmore" at chandlery_shop {
    Role "chandler, whose son has not come home". Ancestry human. Peaceable.
    Sells rations for 2 coin from 8. Sells torch for 1 coin from 12. Sells rope for 1 coin from 4.
  }
  Discovery col_gone "Col Dunmore, sixteen, started sleeping at the Red Lantern after his father died in the Number Four, and has not come home in three nights.".
  Topic hesper_col with hesper "Ask Hesper Dunmore what is wrong" when true once {
    Says "'My boy,' says Hesper, and puts down the candle she was trimming. 'Col. His father died in the Number Four in the spring, and Col couldn't sleep, and someone told him about the Red Lantern. He slept there every night after. Three nights ago he didn't come home.' She looks at you. 'The watch says he's gone off to the giants for the bounty. He's sixteen and he's frightened of dogs. Will you look?'".
    On discuss { Assert knows(actor, col_gone). }
  }
  Topic hesper_news with hesper "Tell Hesper Dunmore where Col was taken" when knows(actor, hush_named) and knows(actor, col_gone) once {
    Says "Hesper listens with both hands flat on her counter. 'Down,' she says. 'Down where?' Then: 'No. Don't tell me. Bring him up.' She pushes a cloth of bread and cheese across the counter and will not take money for it.".
    On discuss { Increase quantity(actor, rations) by 2. }
  }

  // The shrine: rest, healing, and a priest who knows the old stories.
  Person agathe "Sister Agathe" at shrine_room {
    Role "keeper of the Hearth-Mother's fire". Ancestry human. Calling cleric. Level 4. Peaceable.
    Offers healing "the Hearth-Mother's blessing and clean linen" for 2 coin.
  }
  Topic agathe_fells with agathe "Ask Sister Agathe about the fells" when true once {
    Says "'The old shepherds had a saying,' says Agathe. 'Walk soft on Thrume, he's only sleeping.' She smiles. 'They meant the giant in the stories. The one the hills were made from.' She looks at the prayers on the wall. 'Since the Number Four broke through, I have had more prayers for sleep than for anything else. People here cannot sleep, and when they do they all dream the same.'".
  }

  // The Saltcellar.
  Person landlord "Gil Sorrow" at inn_room {
    Role "landlord of the Saltcellar". Profession innkeeper. Peaceable.
    Sells rations for 2 coin from 8. Sells torch for 1 coin from 6.
  }

  // The miners' row: the families, and the way to the giants.
  Person wives "the miners' wives" at miners_row {
    Role "women of the miners' row". Ancestry human. Numbers 3. Peaceable.
  }
  Topic wives_giants with wives "Ask the miners' wives about the giants" when true once {
    Says "'They didn't kill anyone that night,' says a woman with a baby on her hip. 'Only the overseer, and that was the fire. They took the men out of the Number Four like you'd take kittens out of a well, and carried them up the scree road.' Another says: 'Aud Brenning's with them. Aud doesn't die easy.' The first: 'If you go up there for the Margravine's money, you can bring ours home while you're about it.'".
  }

  Objective find_col when knows(party, col_gone) and not freed(col) "Hesper Dunmore's son Col did not come home from the Red Lantern.".
  Objective lay_thane when knows(party, bounty_known) and not knows(party, thrume_known) "The Margravine will pay a lordship for Thane Mórrach's head.".
}

data/adventures/thrume/shoulder.kyr:
Module thrume "Thrume" {
  Description "The Shoulder Hall: the giants' hold on the ridge, forty miners held in it, and the keepers' way down into the body.".

  Place scree "the scree road" is wilderness within fells at 0, 1.
  Place hold "the Shoulder Hall" is site within fells at 1, 1.
  Place glacier "the Shoulder glacier" is wilderness within fells at 1, 0.
  Place cellars "the glacier cellars" is level within hold.

  Place scree_road "the top of the scree road" is room within scree at 0, 0.
  Place gate_yard "the gate-yard" is room within hold at 1, 2.
  Place kennels "the wolf-pens" is room within hold at 0, 2.
  Place long_hall "the long hall" is room within hold at 1, 1.
  Place thane_seat "the high seat" is room within hold at 1, 0.
  Place hearth "the mothers' hearth" is room within hold at 0, 1.
  Place barracks "the young bloods' house" is room within hold at 2, 1.
  Place pens "the thrall-pens" is room within hold at 2, 2.
  Place midden "the midden under the pens" is room within glacier at 2, 1.
  Place glacier_foot "the glacier's foot" is room within glacier at 1, 1.
  Place ice_cellar "the ice cellar" is room within cellars at 1, 0.
  Place cage_room "the cage of ice" is room within cellars at 2, 0.
  Place stair_head "the head of the Keepers' Stair" is room within cellars at 0, 0.
  Initially Assert unlit(ice_cellar). Initially Assert unlit(cage_room). Initially Assert unlit(stair_head).

  Passage scree_climb "the last of the scree" is path between scree_road and gate_yard taking 30 minutes.
  Passage kennel_gate "the wolf-pen gate" is gate between gate_yard and kennels.
  Passage hall_doors "the hall doors" is door between gate_yard and long_hall.
  Passage seat_steps "the steps to the high seat" is steps between long_hall and thane_seat.
  Passage hearth_way "the hearth passage" is doorway between long_hall and hearth.
  Passage bloods_door "the young bloods' door" is door between gate_yard and barracks.
  Passage pens_gate "the pens gate" is gate between gate_yard and pens.
  Passage midden_chute "the midden chute" is crawl between pens and midden taking 10 minutes needing climbing or rope.
  Passage midden_path "the ice under the midden" is path between midden and glacier_foot taking 20 minutes.
  Passage glacier_track "the edge of the glacier" is track between scree_road and glacier_foot taking 1 hour.
  Passage crevasse "the blue crevasse" is tunnel between glacier_foot and ice_cellar taking 20 minutes hidden until crevasse_known.
  Passage cellar_stair "the cellar stair" is stair between ice_cellar and long_hall.
  Passage cage_way "the cold passage" is passage between ice_cellar and cage_room.
  Passage keepers_arch "the keepers' arch" is arch between ice_cellar and stair_head.

  Observe sroad_scene at scree_road when not dark() "The scree gives out under a hold of black timber and grey stone that sits on the shoulder of the fells under a glacier, like a hut under a wave. Its doors are three times the height of a man.".
  Observe sroad_night at scree_road when dark() "Above you the hold's smoke-holes glow red. Somebody up there is singing, very low; you feel it in the stones before you hear it.".
  Observe gyard_scene at gate_yard when true "A yard of trodden snow and bones. The gate-posts are whole pine trunks. A pole of grey wood stands by the hall doors, hung with a hammer the size of a child.".
  Observe hall_scene at long_hall when not dark() "A hall long enough to race horses in, smoky, roofed with whole trees. Benches you would need a ladder for run down both sides of a fire-trench.".
  Observe hall_night at long_hall when dark() "The fire-trench is down to embers. Along both walls, on the benches and under them, giants sleep in their furs like a range of low hills, breathing slow. One of them is talking in its sleep.".
  Observe seat_scene at thane_seat when true "The high seat is a block of the mountain itself, left where it stood when the hall was built round it, polished by a thousand years of sitting. It is warm.".
  Observe hearth_scene at hearth when true "A round room, warm, smelling of milk and smoke. Four great pillars hold up the roof, and every one is carved from floor to rafters in lines too small for the hands that must have cut them.".
  Observe barracks_scene at barracks when true "Sleeping platforms, war-gear, and a table scored with a map of the dale below: Saltgrave, the mine-heads, the road. Someone has driven a knife through the town.".
  Observe pens_scene at pens when not freed(aud) and not razed(scree) "Forty miners in a pen of stakes, under a roof of hides. They are cold and filthy and alive, which they did not expect.".
  Observe pens_empty at pens when freed(aud) "The pen of stakes is empty, and the hides flap.".
  Observe pens_razed at pens when razed(scree) and not freed(aud) "Do not look at the pens.".
  Observe midden_scene at midden when true "The midden spills out from under the pens onto the ice. Above you a square chute goes up into the dark; there are hand-holds in it, worn.".
  Observe foot_scene at glacier_foot when not dark() "The glacier ends here in a wall of blue ice, cracked, sweating, groaning to itself in the sun.".
  Observe foot_night at glacier_foot when dark() "The glacier ends here in a wall of ice that is faintly blue even in the dark. It ticks and groans as the cold takes hold of it.".
  Observe icecellar_scene at ice_cellar when true "A cellar cut in the glacier. The walls are blue and give back no light. Joints of meat hang from hooks. A cold passage goes off to one side; on the other, an arch of old grey stone, older than the hall, opens on a stair going down.".
  Observe stairhead_scene at stair_head when true "A stair as wide as a road goes down into the mountain in long flights, the treads worn into dips by enormous feet. The air coming up it is warm, and smells faintly of blood and salt.".

  Discovery crevasse_known "A crevasse at the glacier's foot runs back under the hold, into its ice cellar." {
    Found by searching glacier_foot "Behind a slab of fallen ice a blue crevasse runs back into the glacier, and the air in it smells of smoke and meat.".
    Known by aud.
  }

  // The giants. Nothing in the hold is scaled to the company.
  Species shoulder_giant "a giant of the Shoulder" like colossus.
  Person morrach "Thane Mórrach" at thane_seat {
    Role "thane of the Shoulder Hall". Species shoulder_giant. Level 12. Peaceable.
    State presiding "Thane Mórrach sits the high seat with his hands on his knees: grey-bearded, heavy, very still, and twice as tall as the door you came in by.".
    State deposed "Thane Mórrach sits on the floor beside the high seat with his hands bound in front of him in a ship's cable. Skarn sits the seat.".
  }
  Person skarn "Skarn" at barracks {
    Role "first of the young bloods". Species shoulder_giant. Level 9. Temperament obedient.
    Uses go, assail. Plans 6 steps.
  }
  Person bloods "the young bloods" at barracks {
    Role "young giants spoiling for a war". Species shoulder_giant. Level 7. Numbers 3. Temperament obedient.
    Uses go, assail. Plans 6 steps.
  }
  Initially Assert serves(bloods, skarn).
  Person rememberer "the Rememberer" at hearth {
    Role "the thane's mother, keeper of the song". Species shoulder_giant. Level 10. Peaceable.
    Wants heart_salt.
  }
  Person wolves "the hold's wolves" at kennels {
    Role "frost wolves the size of ponies". Species frost_wolf. Numbers 2.
    Temperament territorial.
    Warns "Two white wolves the size of ponies get up out of the straw, without hurry, and stand between you and everything else.".
  }

  // The hostages.
  Person aud "Aud Brenning" at pens {
    Role "foreman of the Saltgrave miners". Ancestry dwarf. Calling warrior. Level 3. Peaceable.
  }
  Person kell "Tobias Kell" at pens {
    Role "a miner who will not meet your eye". Ancestry human. Calling thief. Level 2. Peaceable.
  }

  // The alarm. By day a stranger in the yard is challenged and has a little while to answer at the guest-pole; by
  // night the hold sleeps, and the long hall can be crept through by the light-footed.
  Relation roused(place). Relation guest(group). Relation freed(group). Relation gagged(group). Relation sawUs(group).
  Relation challenged(group). Measure answerBy(group).
  Rule seen_in_yard when at(party, gate_yard) and not dark() and not guest(party) and not roused(hold) and not challenged(party) and not sworn(morrach)
    says "A giant crossing the yard with a bucket stops, and looks down at you, and sets the bucket down. He says one word, a question, in a voice like a rockfall, and his eyes go to the pole by the hall doors and back to you." {
    Assert challenged(party). Set answerBy(party) to watch(clock) + 2.
  }
  Rule challenge_unanswered when challenged(party) and not guest(party) and not roused(hold) and watch(clock) >= answerBy(party)
    says "The giant with the bucket stops waiting. He shouts, and the hall doors bang open." { Assert roused(hold). }
  Rule seen_in_hall when (at(party, long_hall) or at(party, barracks)) and not dark() and not guest(party) and not roused(hold) and not sworn(morrach)
    says "A roar goes up from the benches." { Assert roused(hold). }
  // Crossing the sleeping hall: the light-footed pass; others may not.
  Relation crept(group).
  Rule hall_wakes when at(party, long_hall) and dark() and not guest(party) and not sworn(morrach) and not capable(party, stealth) and not roused(hold) and dice(long_hall) <= 35
    says "Your boot finds a bone in the dark. It cracks like a branch. Along the wall a shape the size of a hayrick sits up, and says something, and then shouts it." { Assert roused(hold). }
  Pursuit hunt for skarn "hunting the intruders" priority 20 when roused(hold) and able(skarn) seeks assails(skarn, party).
  Pursuit hunt_with for bloods "hunting the intruders with Skarn" priority 20 when roused(hold) and able(bloods) seeks assails(bloods, party).

  // Guest-right.
  Action ask_guest_right(actor: group, site: place) "Strike the guest-pole and ask for hall-right" {
    Description "The old law of the hills: whoever asks hall-right at the pole is under the thane's roof until they leave it, and may not lift a hand there.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gate_yard) and not guest(actor) and not roused(hold).
    Time 1.
    On success { Assert guest(actor). Assert tolerates(morrach, actor). Assert tolerates(skarn, actor). Assert tolerates(bloods, actor). }
    Result "The hammer is almost too heavy to lift. The pole rings like a bell. The hall doors open, and a giant looks down at you for a long moment, and stands aside.".
  }
  Rule guest_broken when guest(party) and not sworn(morrach) and (at(party, pens) or at(party, ice_cellar) or at(party, barracks))
    says "Skarn's voice, from across the yard: 'Guests. Look where the guests are.' And then, louder, to the whole hold." {
    Retract guest(party). Retract tolerates(skarn, party). Retract tolerates(bloods, party). Retract tolerates(morrach, party). Assert roused(hold).
  }

  // Kell sells whoever comes to the pens, as soon as their backs are turned, unless Aud has him held.
  Rule kell_sees when at(party, pens) and not guest(party) and not sawUs(kell) { Assert sawUs(kell). }
  Rule kell_sells when sawUs(kell) and not at(party, pens) and not gagged(kell) and not roused(hold) and not freed(aud) and not sworn(morrach)
    says "From the pens behind you a man's voice goes up, high and clear, calling for Skarn by name." { Assert roused(hold). }
  Topic aud_kell with aud "Ask Aud Brenning about the man who won't look at you" when sawUs(kell) and not gagged(kell) once {
    Says "'Tobias Kell,' says Aud, not quietly. 'He showed them where we slept. He'll be shouting before you're over the stakes.' She looks at Kell, and two of her miners get up and sit down either side of him. 'Not today, Tobias.'".
    On discuss { Assert gagged(kell). }
  }
  Topic aud_deep with aud "Ask Aud Brenning why the giants came" when true once {
    Says "'We broke into something at the bottom of the Number Four,' says Aud. 'Red salt, a whole wall of it, and warm. Warm, under a mountain. The next week they came.' She lowers her voice. 'I kept a piece back. It's in the midden under us, wrapped in my shirt. I don't know why I did that.'".
    On discuss { Assert knows(actor, salt_hidden). }
  }
  Discovery salt_hidden "Aud Brenning hid a lump of the red salt from the bottom of the Number Four in the midden under the pens.".
  Kind heart_salt "a lump of red heart-salt, warm to the touch" is treasure worth 40 weighing 1.
  Item salt_lump "a shirt wrapped round something warm" is heart_salt at midden hidden until salt_hidden.

  // The Rememberer.
  Discovery song_seen "The carvings on the hearth pillars are a song in the giants' writing, and it is about something they keep.".
  Observe pillars_teach at hearth when true "Close to, the lines on the pillars are writing, tiny and endless, the same few signs over and over: a mountain, a heart, a closed eye." teaches song_seen.
  Discovery thrume_known "Thrume is not a mountain. It is a titan, sleeping, and the range is its body; the red salt is its blood. The giants of the Shoulder are its keepers, and the mine is a wound.".
  Relation saltReturned(group).
  Event salt_given near rememberer when keeps(rememberer, ?s) and itemKind(?s, heart_salt)
    "The Rememberer holds the red salt against her blind eyes, then against her cheek, as you would a sick child's forehead. 'Warm,' she says. 'He is warm. They have cut him to the blood.'" then {
    Assert saltReturned(rememberer).
  }
  Topic rememberer_truth with rememberer "Ask the Rememberer who is warm" when saltReturned(rememberer) once {
    Says "She turns her face to you. 'Sit down, small ones. Thrume is not a mountain. Thrume is the last of the old ones, the ones who were here before the hills, and he sleeps, and the hills are him. We are his keepers. Your miners have cut into him to the blood, and he is beginning to dream.' Her hand finds the pillar beside her. 'When he dreams, things walk. You have one in our cellar.'".
    On discuss { Assert knows(actor, thrume_known). }
  }
  Discovery song_known "The keepers' song, as the Rememberer sang it: the names of the old ones, one by one, and Thrume's last. A song is a thing remembered by the living; nothing that eats forgetting can eat it.".
  Topic rememberer_song with rememberer "Ask the Rememberer to teach you the song" when knows(actor, thrume_known) and (dreamt(actor) or knows(actor, mouth_known)) once {
    Says "She is quiet a long time. She leans close and breathes in, as if smelling your hair. 'You have been in his dream,' she says. 'I can smell the sky on you.' Then: 'The song is not for small ones. Then: 'But the small ones are going where we cannot.' She sings. It is long, and very low, and your teeth ache with it, and it is only names: the old ones, one by one, the hills that walked, and last of all Thrume's. When she stops, you find you can sing it back to her, every name. 'Do not forget it,' she says. 'It is the one thing down there that cannot be eaten, while one of us remembers.'".
    On discuss { Assert knows(actor, song_known). }
  }
  Topic rememberer_cage with rememberer "Ask the Rememberer about the thing in the cellar" when knows(actor, thrume_known) once {
    Says "'The first of his dreams to walk,' she says. 'A dream of salt. We caught it in the snow below the workings, killing sheep, and the ice holds it. When he dreams harder, they will come out of the hills by dozens.' Her face turns toward the floor. 'Do not let it out. It is not wicked. It is only what he is dreaming, and he is dreaming badly.'".
  }

  // The thane: his terms, his ring, and the miners.
  Relation sworn(group).
  Topic morrach_why with morrach "Ask Thane Mórrach why he took the miners" when state(morrach, presiding) once {
    Says "The thane looks down at you for a long moment. 'Because they were cutting,' he says. His voice is very quiet for a voice that big. 'Your Margravine wants a war. My young bloods want a war. I want the cutting to stop. Forty of them in my pens and the cutting stops.' He opens one hand. 'And then she sent another down the old hole, with more men, and the cutting goes on.'".
  }
  Topic morrach_oath with morrach "Swear to Thane Mórrach that you will close the wound" when knows(actor, thrume_known) and state(morrach, presiding) and not sworn(morrach) {
    Says "The thane gets up. You had not seen him stand; it takes some time. He takes a ring from his finger, a ring of grey stone the size of a cart-wheel's hub, and puts it down on the floor in front of you. 'The keepers' ring,' he says. 'The arch in my cellar opens to it, and the stair below goes down into him, a long way down. Close the wound, small ones. Stop the cutting. And take your miners home; I have no more use for them.' Behind you, across the yard, someone throws a cup against a wall.".
    On discuss { Assert sworn(morrach). Assert guest(actor). Assert tolerates(morrach, actor). Assert tolerates(skarn, actor). Assert tolerates(bloods, actor). Assert at(thane_ring, thane_seat). Assert freed(aud). Assert at(aud, miners_row). Assert at(kell, miners_row). Retract roused(hold). }
  }
  Kind keepers_ring "the keepers' ring, a band of grey stone the size of a hub" is treasure worth 0 weighing 2.
  Item thane_ring "the keepers' ring" is keepers_ring at limbo.
  Thing keepers_door "the keepers' arch" on keepers_arch {
    State shut blocking "The arch of grey stone is closed by a slab with a round socket in it, as big as a hub, and worn smooth.".
    State open "The slab has gone down into the floor of the arch. Warm air comes up the stair beyond.".
    Change open_arch "Set the keepers' ring in the socket of the arch" from shut to open needing keepers_ring.
  }
  Observe miners_home at miners_row when freed(aud) "The twists of black wool are gone from the latches. Aud Brenning is going from door to door with a list in her hand, crossing names off.".
  Topic aud_home with aud "Ask Aud Brenning about the Number Four" when freed(aud) and at(aud, miners_row) once {
    Says "'The old adit,' she says. 'Brannoc went down it with twelve men and a quota. Below the old workings it comes out in the red, and below the red, I don't know. We never went past the warm face.' She folds the list. 'If you go down there, there's a rope ladder at the Number Four sump that goes further than we ever did. We found it there. We didn't put it there.'".
    On discuss { Assert knows(actor, sump_ladder). }
  }
  Discovery sump_ladder "At the sump of the Number Four hangs a ladder that goes deeper than the miners ever went. They did not put it there." {
    Found by searching sump "Behind a fall of salt beside the sump a hole goes down, and a ladder of fine grey rope hangs into it.".
    Found by searching vein_foot "A ladder of fine grey rope hangs out of a hole in the cave roof, swaying in the warm air. It goes up toward the workings.".
  }

  // Skarn throws down the thane if the hold is roused and blood is spilled; the young bloods go to war.
  Relation razed(place). Relation coup(place).
  Rule skarn_rises when roused(hold) and (dead(bloods) or hurt(skarn)) and not coup(hold) and able(skarn)
    says "Somewhere in the hold a voice roars, and another answers it, and then the whole hall is shouting one name, and it is not the thane's." {
    Assert coup(hold). Assert state(morrach, deposed). Assert at(skarn, thane_seat).
  }
  Relation hurt(group).
  // The young bloods' clock: at dark on the second night they kill the miners and go down on Saltgrave, unless the
  // thane has given the miners up.
  Rule massacre when watch(clock) >= 216 and dark() and not freed(aud) and able(skarn) and not razed(scree)
    says "In the dark the hold wakes all at once: torches, a horn, and then from the pens a sound you will not forget. Then the young bloods go out of the gate and down the scree road toward Saltgrave, singing." {
    Assert razed(scree). Assert at(skarn, market). Assert at(bloods, market). Increase stirring(fells) by 1.
  }
  Observe market_raided at market when razed(scree) "Half the square is burnt. The pump is a stump. A giant's footprint is pressed into the dust in front of the Salt Office, deep enough to stand in.".

  // The thing in the ice.
  Thing ice_cage "the cage of ice" at cage_room {
    State frozen "In a cage of blue ice something white turns and turns like salt poured slowly into water. It has no face, and it is looking at you.".
    State melted "A pool of meltwater, and an empty cage, and a white crust like frost all across the floor.".
    Change melt "Melt the cage of ice with fire" from frozen to melted needing flame.
  }
  Person salt_dream "the salt-dream" at limbo {
    Role "a walking dream of salt". Species salt_elemental. Level 6.
    Temperament savage.
    Comes "The white thing pours out of the broken ice and comes at you, hissing like a struck match.".
  }
  Rule dream_loose when state(ice_cage, melted) and at(salt_dream, limbo) { Assert at(salt_dream, cage_room). }

  Objective free_miners when not freed(aud) and not razed(scree) "Forty miners are held in the Shoulder Hall, and the young bloods mean to kill them on the second night.".
  Objective learn_why when knows(party, song_seen) and not knows(party, thrume_known) "The giants keep something, and their song says what.".
  Objective close_wound when sworn(morrach) and cutting(brannoc) "You swore to Thane Mórrach to stop the cutting.".
}

data/adventures/thrume/tomb.kyr:
Module thrume "Thrume" {
  Description "The Heart-Tomb: the Hollow Smiths' killing gauntlet around the heart of Thrume. Every trap is an argument for their doctrine: what wakes, kills; what kills, wakes.".

  Place tomb "the Heart-Tomb" is site within fells at 3, 1.
  Place tomb_outer "the outer tomb" is level within tomb.
  Place tomb_halls "the halls of the tomb" is level within tomb.
  Place tomb_pit "the oubliette" is level within tomb.
  Place tomb_core "the core of the tomb" is level within tomb.

  Place tomb_mouth "the foot of the long throat" is room within tomb_outer at 0, 0.
  Place salt_landing "the head of the salt stair" is room within tomb_outer at 1, 0.
  Place hammer_hall "the hall of the hammers" is room within tomb_halls at 0, 0.
  Place doctrine_hall "the Hall of Doctrine" is room within tomb_halls at 1, 0.
  Place face_room "the Sleeper's Face" is room within tomb_halls at 2, 0.
  Place door_hall "the Hall of Doors" is room within tomb_halls at 2, 1.
  Place breaths_room "the Room of Three Breaths" is room within tomb_halls at 3, 1.
  Place gearworks "the Gearworks" is room within tomb_halls at 3, 0.
  Place warder_gallery "the gallery over the Warder" is room within tomb_halls at 4, 0.
  Place oubliette "the oubliette" is room within tomb_pit at 2, 1.
  Place false_heart "the Chamber of the Heart" is room within tomb_core at 0, 0.
  Place warder_hall "the Warder's corridor" is room within tomb_core at 1, 0.
  Place locks_room "the hall of the locks" is room within tomb_core at 2, 0.
  Place heart_chamber "the Keeper's Chair" is room within tomb_core at 3, 0.
  Initially Assert unlit(tomb_mouth). Initially Assert unlit(salt_landing). Initially Assert unlit(hammer_hall).
  Initially Assert unlit(face_room). Initially Assert unlit(door_hall). Initially Assert unlit(oubliette). Initially Assert unlit(warder_hall).
  Initially Assert unlit(locks_room).

  Passage long_throat "the long throat" is tunnel between throat_head and tomb_mouth taking 2 hours needing climbing or rope.
  Passage landing_way "the outer passage" is passage between tomb_mouth and salt_landing.
  Passage salt_stair "the salt stair" is stair between salt_landing and hammer_hall.
  Passage hammer_gate "the Gate of Three Hammers" is gate between hammer_hall and doctrine_hall.
  Passage doctrine_way "the end of the painted hall" is doorway between doctrine_hall and face_room.
  Passage behind_eye "the way behind the left eye" is crawl between face_room and door_hall hidden until eye_way_known.
  Passage true_door "the door that is not there" is doorway between door_hall and breaths_room hidden until true_door_known.
  Passage pit_climb "the oubliette shaft" is shaft between oubliette and door_hall one way taking 1 hour needing climbing or rope.
  Passage breath_way "the far side of the Room of Three Breaths" is passage between breaths_room and gearworks
    opening when exhaling(fells) "Between the Room of Three Breaths and the Gearworks the salt-dust is up in a roaring white wall, drawn in toward a grating as if into a mouth. Nobody crosses it on the in-breath.".
  Passage gallery_walk "the gallery walk" is passage between gearworks and warder_gallery.
  Passage core_stair "the core stair" is stair between gearworks and false_heart taking 10 minutes.
  Passage plinth_way "the way behind the plinth" is passage between false_heart and warder_hall hidden until plinth_known.
  Passage warder_end "the end of the Warder's corridor" is passage between warder_hall and locks_room.
  Passage heart_door "the Door of Three Locks" is door between locks_room and heart_chamber.
  Passage keepers_rise "the keepers' road" is passage between heart_chamber and stair_foot taking 3 hours
    opening when sungClean(fells) or sealed(fells) "A road goes up from the Keeper's Chair, closed by a slab carved with giants' signs; it opens only to keepers.".

  // What it costs.
  Hazard unmaking "Unmade" means "Kill ally.".
  Hazard tread_fall "The false tread" means "Deal (2d6) physical damage to ally unless dexterity save against (13).".
  Hazard bronze_blow "The bronze hammer's answer" means "Deal (3d6) necrotic damage to ally unless constitution save against (14).".
  Hazard lid_needle "The right lid's needle" means "Deal (1d6) poison damage to ally unless dexterity save against (13). Apply poisoned to ally for 3 turns unless constitution save against (12).".
  Hazard blades "The scything door" means "Deal (4d6) physical damage to ally unless dexterity save against (15).".
  Hazard brine_spray "The brine door" means "Deal (3d6) poison damage to ally unless dexterity save against (14).".
  Hazard crushing "The falling door" means "Deal (4d6) physical damage to ally unless dexterity save against (14).".
  Hazard burning_salt "The burning door" means "Deal (3d6) fire damage to ally unless dexterity save against (14).".
  Hazard salt_choke "The in-breath's dust" means "Deal (1d6) poison damage to ally unless constitution save against (13).".
  Hazard scald "The Gearworks' steam" means "Deal (3d6) fire damage to ally unless dexterity save against (14).".
  Hazard ceiling_fall "The roof of the false heart" means "Deal (4d6) physical damage to ally unless dexterity save against (15).".
  Hazard stays_behind "The one who stays" means "Kill ally.".

  Observe tmouth_scene at tomb_mouth when true "The long throat ends on a floor of red stone, smooth as the inside of a cheek. Ahead, a passage. Cut over it, very small, in the smiths' square hand: TURN BACK. HE IS ONLY SLEEPING.".
  Observe landing_scene at salt_landing when true "A stair of white salt goes down into the dark, each tread cut sharp and unworn. Nobody has walked on it for a thousand years.".

  // 1. The salt stair: the third tread is no tread.
  Thing false_tread "the third tread of the salt stair" on salt_stair {
    State whole dangerous "The treads of the salt stair are cut sharp and white, every one alike.".
    State found "The third tread of the salt stair has fallen away on a hinge of salt into a black slot. There is room to step over it.".
    Hurts with tread_fall when whole then found.
  }
  Rule tread_shown when tried(false_tread, prodding) and state(false_tread, whole)
    says "The pole goes down on the third tread and the tread goes down with it, swinging away on a hinge of salt into a slot that goes down further than you can hear." {
    Assert state(false_tread, found).
  }

  // 2. The Gate of Three Hammers: iron wakes the sleeper; bronze wakes the dead; salt sleeps.
  Observe hammer_scene at hammer_hall when true "A gate of grey iron fills the hall's end. Three hammers hang before it on chains: one of iron, one of bronze, one of red salt. Cut over the gate: IRON WAKES THE SLEEPER. BRONZE WAKES THE DEAD. STRIKE WITH WHAT IS SLEEPING, AND PASS INSTEAD.".
  Thing gate_bar "the Gate of Three Hammers" on hammer_gate {
    State shut blocking "The grey gate is shut. It has no lock, no handle and no hinges you can see.".
    State open "The grey gate has swung inward, silent, on hinges that were not there before.".
  }
  Action strike_iron(actor: group, site: place) "Strike the gate with the iron hammer" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hammer_hall) and state(gate_bar, shut).
    Time 1.
    On success { Assert strikes(unmaking, actor). Increase stirring(fells) by 1. }
    Result "The iron rings on the iron, and the ring goes on and on, down into the floor, and under your feet the whole mountain flinches. The one who swung the hammer is standing very still. Then they are not standing at all.".
  }
  Action strike_bronze(actor: group, site: place) "Strike the gate with the bronze hammer" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hammer_hall) and state(gate_bar, shut).
    Time 1.
    On success { Assert strikes(bronze_blow, actor). Increase stirring(fells) by 1. }
    Result "The bronze booms. Something cold comes up out of the floor like water out of a sponge, and through whoever is nearest, and away.".
  }
  Action strike_salt(actor: group, site: place) "Strike the gate with the hammer of salt" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hammer_hall) and state(gate_bar, shut).
    Time 1.
    On success { Assert state(gate_bar, open). }
    Result "The salt hammer makes no sound at all against the iron. It crumbles in your hand to red dust. The gate swings open.".
  }

  // 3. The Hall of Doctrine: it teaches, and it lies once, at the Smith-Master's order.
  Observe doctrine_scene at doctrine_hall when true "A long gallery, painted from floor to vault in colours a thousand years old. Panel after panel shows the smiths at their work in this tomb, as a lesson: a smith prodding a stair with a pole; a smith with a red hammer at a gate; a smith creeping past a great face by its left eye; a smith searching a wall between painted doors; a smith crossing a dusty room while a giant breathes out; three wheels, with a smith setting them. The last panel shows a smith kneeling to a figure in a crown, saying words.".
  Discovery panels_read "The Hall of Doctrine's last panels, read close: the wheels of the Gearworks set iron at rest, salt at rest, bone awake; and, under the kneeling smith, the doctrine, which the crowned figure answers.".
  Observe panels_teach at doctrine_hall when true "Close to, the panel of the wheels has words painted under each: IRON, REST. SALT, REST. BONE, WAKE. Under the kneeling smith: WHAT WAKES, KILLS." teaches panels_read.

  // 4. The Sleeper's Face: never go where he is awake.
  Observe sface_scene at face_room when true "The end of the hall is a face. A titan's face, cut in red stone, as tall as a house: eyes closed, mouth open. The mouth is perfectly black. Nothing in it reflects your light. It makes no sound, and the air does not move in it.".
  Action enter_mouth(actor: group, site: place) "Walk into the Sleeper's open mouth" {
    Description "It is wide enough for a cart. Beyond it there is only black.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, face_room).
    Time 1.
    On success { Assert strikes(unmaking, actor). }
    Result "The first of you steps into the black, and is not anywhere. No sound. No sign. The black is just as it was.".
  }
  Thing left_lid "the Sleeper's left eyelid" at face_room {
    State lidded "The left eyelid of the face, on your left as you face it, is a slab of red stone as big as a door.".
    State pressed "The left eyelid has sunk into the stone, and behind it a low way runs back into the dark.".
    Tries pushing.
  }
  Thing right_lid "the Sleeper's right eyelid" at face_room {
    State lidded "The right eyelid of the face is a slab of red stone as big as a door, with a crack at its edge.".
    State sprung "A needle as long as a finger stands out of the crack at the right eyelid's edge.".
    Tries pushing.
  }
  Discovery eye_way_known "Behind the Sleeper's left eyelid, a low way runs on into the dark.".
  Observe eye_opens at face_room when state(left_lid, pressed) "Where the left eyelid was, a low way runs back into the dark." teaches eye_way_known.
  Rule left_gives when tried(left_lid, pushing) and state(left_lid, lidded)
    says "The left eyelid sinks under your hands with a sigh of air, like a sleeper's breath, and the stone behind it slides away." {
    Assert state(left_lid, pressed).
  }
  Rule right_bites when tried(right_lid, pushing) and state(right_lid, lidded)
    says "Something in the crack at the right lid's edge goes snick." {
    Assert state(right_lid, sprung). Assert strikes(lid_needle, party).
  }

  // 5. The Hall of Doors: every door you can see is a death; the door is the one that is not there.
  Observe doors_scene at door_hall when true "A long hall with six doors along its walls, three to a side, each of a different wood, each with a different handle: bone, bronze, iron, salt, glass, horn. The end wall is bare red stone.".
  Thing door_bone "the door with the bone handle" at door_hall { State shut "A door of pale ash with a handle of bone.". State open "The ash door hangs open on a blank wall.". Change open_bone "Open the door with the bone handle" from shut to open. }
  Thing door_bronze "the door with the bronze handle" at door_hall { State shut "A door of oak with a handle of bronze.". State open "The oak door hangs open on a blank wall, scored with blade-marks.". Change open_bronze "Open the door with the bronze handle" from shut to open. }
  Thing door_iron "the door with the iron handle" at door_hall { State shut "A door of black yew with a handle of iron.". State open "The yew door hangs open on nothing; the floor beyond it was never there.". Change open_iron "Open the door with the iron handle" from shut to open. }
  Thing door_salt "the door with the salt handle" at door_hall { State shut "A door of pine with a handle of white salt.". State open "The pine door hangs open on a wall of crumbled salt.". Change open_salt "Open the door with the salt handle" from shut to open. }
  Thing door_glass "the door with the glass handle" at door_hall { State shut "A door of pear-wood with a handle of glass.". State open "The pear-wood door hangs open on a blackened wall.". Change open_glass "Open the door with the glass handle" from shut to open. }
  Thing door_horn "the door with the horn handle" at door_hall { State shut "A door of elm with a handle of horn.". State open "The elm door hangs open on a slab of fallen stone.". Change open_horn "Open the door with the horn handle" from shut to open. }
  Relation sprungDoor(entity).
  Rule bone_door when state(door_bone, open) and not sprungDoor(door_bone) says "Behind the ash door is a wall, and the wall breathes out a fine white salt that burns the eyes and throat." { Assert sprungDoor(door_bone). Assert strikes(brine_spray, party). }
  Rule bronze_door when state(door_bronze, open) and not sprungDoor(door_bronze) says "The oak door opens on a wall, and out of a slot in the wall a blade the length of a man comes round at waist height." { Assert sprungDoor(door_bronze). Assert strikes(blades, party). }
  Rule iron_door when state(door_iron, open) and not sprungDoor(door_iron) says "The yew door swings outward and the floor under you swings with it, down." { Assert sprungDoor(door_iron). Assert at(party, oubliette). }
  Rule salt_door when state(door_salt, open) and not sprungDoor(door_salt) says "The salt handle crumbles. So does the wall behind the door, and the roof above it, all at once." { Assert sprungDoor(door_salt). Assert strikes(crushing, party). }
  Rule glass_door when state(door_glass, open) and not sprungDoor(door_glass) says "Behind the pear-wood door the air catches fire." { Assert sprungDoor(door_glass). Assert strikes(burning_salt, party). }
  Rule horn_door when state(door_horn, open) and not sprungDoor(door_horn) says "The elm door opens and the slab above it, which you had not noticed, comes down." { Assert sprungDoor(door_horn). Assert strikes(crushing, party). Increase stirring(fells) by 1. }
  Discovery true_door_known "In the bare end wall of the Hall of Doors, a door with no frame and no handle, cut so fine its edges are a hair." {
    Found by searching door_hall "You go over the bare end wall a hand's breadth at a time. Low down, a hair-fine line; then another, upright; then the shape of a door with no frame and no handle, which swings when you lean on it.".
  }
  Discovery iron_drop_known "Behind the door with the iron handle, the floor of the Hall of Doors swings down into a pit.".
  Observe iron_drop_seen at door_hall when state(door_iron, open) "Beyond the yew door the floor hangs down on a hinge over a black drop." teaches iron_drop_known.
  Passage iron_drop "the drop behind the yew door" is shaft between door_hall and oubliette one way hidden until iron_drop_known.
  Observe oubliette_scene at oubliette when true "A round pit of red stone, smooth, very deep. Far above, a square of less dark. On the floor, the bones of three people who were not patient, and scratched on the wall by one who was: THE SHAFT HAS HOLDS. FEEL FOR THEM.".

  // 6. The Room of Three Breaths: out is open.
  Observe breaths_scene at breaths_room when exhaling(fells) "A long room of red stone. A warm wind blows gently from a grating in the far wall, and the floor is drifted with salt-dust like snow, rippled. The far door stands clear.".
  Observe breaths_in at breaths_room when not exhaling(fells) "The wind in the long room has turned, and the salt-dust is up off the floor in a roaring white wall, pouring toward the grating in the far wall. You cannot see your hand.".
  Rule dust_chokes when at(party, breaths_room) and not exhaling(fells)
    says "The salt-dust is in your mouth, your nose, your eyes." { Assert strikes(salt_choke, party). }

  // 7. The Gearworks: iron at rest, salt awake, bone at rest. The painted panel lies.
  Observe gear_scene at gearworks when true "A chamber full of machinery: three great wheels standing on their edges, one of iron, one of red salt, one of bone, each as tall as a mill-wheel and each marked round its rim REST and WAKE. A lever as long as a spear stands up out of the floor. A stair goes down beyond a grating; a gallery goes off along the wall.".
  Thing iron_wheel "the iron wheel" at gearworks {
    State awake "The iron wheel stands with WAKE uppermost.". State rest "The iron wheel stands with REST uppermost.".
    Change iron_rest "Turn the iron wheel to REST" from awake to rest. Change iron_wake "Turn the iron wheel to WAKE" from rest to awake.
  }
  Thing salt_wheel "the salt wheel" at gearworks {
    State rest "The salt wheel stands with REST uppermost.". State awake "The salt wheel stands with WAKE uppermost.".
    Change salt_rest "Turn the salt wheel to REST" from awake to rest. Change salt_wake "Turn the salt wheel to WAKE" from rest to awake.
  }
  Thing bone_wheel "the bone wheel" at gearworks {
    State awake "The bone wheel stands with WAKE uppermost.". State rest "The bone wheel stands with REST uppermost.".
    Change bone_rest "Turn the bone wheel to REST" from awake to rest. Change bone_wake "Turn the bone wheel to WAKE" from rest to awake.
  }
  Thing great_lever "the great lever" at gearworks {
    State up "The great lever stands upright.". State down "The great lever is thrown down.".
    Change throw "Throw the great lever" from up to down.
  }
  Thing core_grating "the grating over the core stair" on core_stair {
    State shut blocking "A grating of grey iron closes the stair going down.".
    State open "The grating over the core stair stands open.".
  }
  Rule gears_right when state(great_lever, down) and state(iron_wheel, rest) and state(salt_wheel, awake) and state(bone_wheel, rest) and state(core_grating, shut)
    says "Somewhere in the walls a long chain runs, and the grating over the stair rises into the roof." { Assert state(core_grating, open). }
  Rule gears_wrong when state(great_lever, down) and state(core_grating, shut) and not (state(iron_wheel, rest) and state(salt_wheel, awake) and state(bone_wheel, rest))
    says "The lever goes down, and the wheels shudder, and every joint in the machinery blows white steam at once." { Assert strikes(scald, party). Assert state(great_lever, up). Increase stirring(fells) by 1. }

  // 8. The Warder: kills what moves while it is wound; it can be unwound only from the gallery above.
  Observe wgallery_scene at warder_gallery when true "A narrow gallery high in the wall over a long corridor. Below, a figure of grey iron stands in the middle of the corridor. Beside you, in the gallery wall, a great key is set in a spring-case, like a clock's.".
  Thing warder_spring "the Warder's spring" at warder_gallery {
    State wound "The great key stands in its spring-case, the spring tight.".
    State unwound "The great key has been turned back; the spring lies slack in its case.".
    Change unwind "Turn the great key back and let the Warder's spring run down" from wound to unwound needing brawn or lockwork.
  }
  Person warder "the Warder" at warder_hall {
    Role "a figure of grey iron, twice a man's height, with blades for hands". Species automaton. Level 14. Temperament obedient.
    Comes "The Warder moves. It is very fast for something so heavy.".
  }
  Rule warder_strikes when at(party, warder_hall) and state(warder_spring, wound) and able(warder) { Assert assails(warder, party). }
  Observe warder_still at warder_hall when state(warder_spring, unwound) "The Warder stands in the middle of the corridor with its blade-hands at its sides, run down, like a clock nobody wound.".

  // 9. The false heart, and the last of the Hollow Smiths.
  Observe fheart_scene at false_heart when not state(decoy, taken) "A chamber like the inside of a crown. On a plinth in the middle, a heart of red crystal as big as a cart, glowing, beating slowly, beautifully. Before it stands a tall figure in a smith's leather apron gone black with age, with a crown of iron on its skull, quite still.".
  Thing decoy "the great red heart" at false_heart {
    State resting "The heart of red crystal glows on its plinth.".
    State taken "The plinth is bare and cracked. Red crystal lies in shards across the floor.".
    Change pry "Prise the great red heart from its plinth" from resting to taken needing brawn.
  }
  Person ardath "the crowned figure" at false_heart {
    Role "a tall figure in a smith's apron, crowned with iron". Species lich. Level 13. Peaceable.
    State keeping "The crowned figure stands before the heart with its hands folded on a smith's hammer. It watches you with nothing in its eye-sockets.".
  }
  Rule ardath_rises when state(decoy, taken) and not hostile(ardath, party)
    says "The roof of the chamber comes down in red slabs. Through the dust the crowned figure lifts its hammer, and its voice is a forge-bellows: 'THIEF.'" {
    Assert strikes(ceiling_fall, party). Assert hostile(ardath, party). Assert assails(ardath, party). Increase stirring(fells) by 1.
  }
  Discovery plinth_known "Behind the plinth of the false heart, a way goes on, for those the crowned figure lets pass.".
  Topic ardath_doctrine with ardath "Say the doctrine of the Hollow Smiths to the crowned figure" when knows(actor, doctrine_known) and not hostile(ardath, actor) once {
    Says "'What wakes, kills,' you say. The crowned figure answers, in a voice like old iron: 'What kills, wakes.' It is quiet a long time. 'You are not ours. But you have our words.' It turns, and lays a hand on the plinth. 'This is a lie. I keep it so that thieves stop here. I have kept it for a thousand years. I do not remember why.' The plinth slides aside. 'The true heart is beyond. He is sleeping. Do not wake him. Do not kill him.' Its hand stays on the plinth. 'I was paid to kill him, once. We all were. I am sorry. Tell him I am sorry.'".
    On discuss { Assert knows(actor, plinth_known). }
  }

  // 10. The Door of Three Locks: the keepers' ring, the Smith-Master's hammer, the Abbess's Eye.
  Observe locks_scene at locks_room when true "A door of red stone, round, like a great closed eye. In it, three sockets: a round one the size of a hub; a narrow one the shape of a little hammer's head; and a broad shallow one, lid-shaped.".
  Thing ring_lock "the round socket" on heart_door {
    State empty blocking "The round socket in the door is empty.". State filled "The keepers' ring sits in the round socket.".
    Change set_ring "Set the keepers' ring in the round socket" from empty to filled needing keepers_ring.
  }
  Thing token_lock "the narrow socket" on heart_door {
    State empty blocking "The narrow socket is empty.". State filled "The Smith-Master's hammer sits in the narrow socket.".
    Change set_token "Set the Smith-Master's hammer in the narrow socket" from empty to filled needing smith_token.
  }
  Thing eye_lock "the lid-shaped socket" on heart_door {
    State empty blocking "The lid-shaped socket is empty.". State filled "The Abbess's Eye lies in the lid-shaped socket, and is open.".
    Change set_eye "Lay the Abbess's Eye in the lid-shaped socket" from empty to filled needing abbess_eye.
  }

  // 11. The Keeper's Chair.
  Observe chair_scene at heart_chamber when true "A small chamber, plain, round, warm. In the floor, in a basin of grey stone, the heart of Thrume: not crystal, flesh, dark red, the size of a cottage, beating once in a long while. The whole room moves with it. Beside the basin, a chair of grey stone, carved with the giants' signs, empty.".
  Relation seated(group).
  Passage into_dream "the dream beyond the Chair" is passage between heart_chamber and cloud_landing taking 1 hour
    opening when seated(party) "The Chair is empty. Whoever sits in it, the keepers say, sits in his dream.".
  Action sit_chair(actor: group, site: place) "Sit in the Keeper's Chair, and go into his dream" {
    Description "The stone is warm. The giants' signs on it are the same three, over and over: a mountain, a heart, a closed eye.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, heart_chamber) and not seated(actor) and not woken(fells).
    Time 1.
    On success { Assert seated(actor). }
    Result "You sit. The heart beats, once, and the room goes away. You are standing on a cloud, and the cloud holds you, and above you a palace of white stone floats in a sky so close you could touch it.".
  }
  Action stay_keeper(actor: group, site: place) "One of you stays in the Chair, and keeps him sleeping" {
    Description "The keepers say someone must sit by the heart and sing, for ever, or he will stir again. Nobody who stays comes back.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, heart_chamber) and not sealed(fells) and not woken(fells) and not sungClean(fells).
    Time 6.
    On success { Assert sealed(fells). Assert strikes(stays_behind, actor). Set stirring(fells) to 0. }
    Result "One of you sits down in the Chair, and puts a hand on the warm stone of the basin, and begins, very low, to hum. The heart slows. When the rest of you go, the one in the Chair does not look up.".
  }
  Action cut_heart(actor: group, site: place) "Cut into the heart of Thrume for the Margravine's salt" {
    Description "The heart is blood, and the blood is the red salt, and there is more of it here than in all the workings. Ebb would win its war.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, heart_chamber) and capable(actor, digging) and not cutOut(fells) and not woken(fells).
    Time 12.
    On success { Assert cutOut(fells). Set stirring(fells) to 0. Increase quantity(actor, gold) by 400. }
    Result "It takes a long time. The heart does not wake. It beats slower, and slower, and the red that comes out of it goes hard and glittering in the air as it runs, and you fill sack after sack. At the end it beats once more, and then it does not, and the whole mountain is very still, and very cold.".
  }
  Action wake_heart(actor: group, site: place) "Strike the heart of Thrume, and wake him" {
    Description "What kills, wakes.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, heart_chamber) and not woken(fells).
    Time 1.
    On success { Set stirring(fells) to 10. }
    Result "You strike. The heart stops. Then it beats, once, so hard you are thrown off your feet, and again, and again, faster, and the floor tilts, and does not tilt back.".
  }

  Objective cross_tomb when at(party, tomb_mouth) and not seated(party) "The heart of Thrume lies at the bottom of the Hollow Smiths' tomb.".
}

data/adventures/what-tessary-owes/afterm:
Module tessary "What Tessary Owes" {
  // ── After the Settlement ──────────────────────────────────────────────────────────────────────────────────────────
  // In a world that goes on (a generated world holding Tessary as one country among others), the city is still there
  // after its story ends, and shows what became of it.
  Query homecoming() means matured(ossel) and (discharged(ossel) or saultWarden(ossel) and saultHoldsNote(ossel)).
  Query factorRules() means matured(ossel) and saultHoldsNote(ossel) and not saultWarden(ossel).

  Observe after_withies at withies when homecoming() "Boots stand on the mats inside the stilt-house doors now, pairs and pairs of them, put there the way the army taught. Somebody has taken the red coats in off the rails. Somebody else is teaching a soldier who has been asleep for three months how to mend an eel-trap again, and laughing at him.".
  Observe after_withies_held at withies when matured(ossel) and foreclosed(ossel) "From the eaves of the stilt-houses, all along the boardwalks, boots hang by their laces, pair by pair, turning a little in the wind off the sea. Nobody takes them down.".
  Observe after_withies_factor at withies when factorRules() "Half the men of the Withies are in the Factor's coats now, grey with a salt-white collar, and go out to Panhythe at dawn in step without being told. Their wives watch them go from the doors.".
  Observe after_landgate_kept at landgate when matured(ossel) and keptPromise(ossel) "On the board: a surveyor's notice, and a list of the strips upriver, and names against them in a clerk's hand, and against some of the names a cross where a man who cannot write has made his mark. Someone has written THEY KEPT IT across the top in charcoal, and someone else has written ABOUT TIME.".
  Observe after_landgate_release at landgate when matured(ossel) and released(ossel) "On the board, the Board's notice of a medal for the Long Muster, to be presented on the steps of the Council House. Under it, in pencil, in a great many hands: NO THANK YOU.".
  Observe after_landgate_factor at landgate when factorRules() "On the board, a single printed bill on good paper, with the Great Seal at the foot and a pair of crossed rakes beside it: THE WARDEN OF THE CITY GIVES NOTICE. The rest is about curfews and the price of bread, which has gone down.".
  Observe after_landgate_void at landgate when matured(ossel) and (noteVoid(ossel) or noteTorn(ossel)) "On the board: THE BOARD OF MOIETIES WILL HEAR THE QUESTION OF THE VETERANS' SETTLEMENT AGAIN AT THE SPRING SITTING. Someone has written under it, very neatly, AND WE WILL BE THERE.".
  Observe after_yard_release at legion_yard when matured(ossel) and released(ossel) "There are things on the Oath Stone's plinth now: a cap badge, a child's drawing of a soldier, a pair of boots, a stub of candle. People keep bringing them. Nobody has told anyone to.".
  Observe after_yard_factor at legion_yard when factorRules() "The Yard is full again: the Long Muster drilling in the Factor's grey under her own sergeants, very smartly, and very quietly. The Oath Stone stands in the middle of the parade ground and the files wheel round it without looking at it.".
  Observe after_tidewall_factor at tidewall when factorRules() "Soldiers in grey stand along the Tidewall at intervals, facing the city, not the sea.".
  Observe after_drum at drum_taproom when matured(ossel) and not heldNow(durrance) and homecoming() "The Third Company's drum hangs over the bar with its head bare. The Drum is full, every bench, and the noise is the noise of people who have somewhere to go in the morning.".
  Observe after_steps_foreclosed at tideline_steps when matured(ossel) and foreclosed(ossel) and dark() "Far out past the bar, the sea is showing stars that are not the stars over Tessary: a great many, very close and very bright, in no shapes you know. Then a wave goes over them and they are gone.".
  Observe after_bath_torn at bath_hall when matured(ossel) and noteTorn(ossel) "In the arch of the plunge-room a hollow man in a grey coat stands a little apart from the others, very still, with one hand held out, palm up, ruled like paper. It does not come any nearer.".
  Observe after_chamber_void at weighing_chamber when matured(ossel) and noteVoid(ossel) "The pan where the black glass lay is empty. The pointer of the Balance stands off the level by the width of a city, and a Scruple sits on a stool at the foot of it with a ledger, writing down, very carefully, how far.".
  Observe after_countinghouse_warden at sault_office when matured(ossel) and saultWarden(ossel) and saultHoldsNote(ossel) "The War Note hangs on the wall behind the Factor's desk in a plain frame, a sheet of black glass that does not reflect anything. Under it, pinned, a letter from the King of Hethra about the working of brine, much annotated.".

  // The Valuer, freed, keeps a stall on Scriveners' Row.
  Person tally_freed "the scrivener in grey" at scriveners_row {
    Role "who keeps a stall at the end of the Row: CONTRACTS READ, DISPUTES WEIGHED, NO LIES TOLD (NONE)". Ancestry human. Peaceable. Pronouns they. Manner stoic.
    Seen when matured(ossel) and tallyFreed(ossel).
  }
  Topic tally_freed_asked with tally_freed "Ask the scrivener in grey how they are" when true once {
    Says "The scrivener in grey looks up from a lease, and the ruled lines on their face move in a way that, on anyone else, would be a smile. 'I have a name,' they say, 'and a stall, and three disputes about fences, and a mudlark who brings me an eel on Fourth-day, which I have learned to eat.' They consider. 'I said a great many things to you that were exact. I will say one that is not: I am happy. I cannot measure it. I note it all the same.'".
  }
  Rule tally_goes_up when matured(ossel) and tallyFreed(ossel) and at(tally, ?p) { Retract at(tally, ?p). Assert tallyBelow(ossel). }
  Rule tally_parts when matured(ossel) and tallyFreed(ossel) and travelsWith(tally, party) { Retract travelsWith(tally, party). Assert tallyBelow(ossel). }
}

Module tessary "What Tessary Owes" {
  // ── The fortnight ─────────────────────────────────────────────────────────────────────────────────────────────────
  // Tessary keeps its days by the ebbs. Low water comes twice a day, about the eleventh hour and about the eleventh of
  // the night, and lasts some five hours each time; while it lasts the outer basin drains through the Swatch and
  // Lowtide stands out of the water. The night ebb at two in the morning is the one the city counts: each is a night of
  // the fortnight. On the first, the eighth and the fifteenth it is a spring ebb, the lowest of all, and on those
  // nights the Balance takes its interest. The fifteenth is the Feast of Settlement, when the war note falls due.
  Query lowWater() means hour(clock) >= 10 and hour(clock) <= 14 or hour(clock) >= 22 or hour(clock) <= 2.
  // The hour the water turns, when anyone still down in Lowtide had better be on a roof.
  Query turning() means hour(clock) == 14 or hour(clock) == 2.
  Measure night(place). Relation counted(place).
  // The first night counted is the first two o'clock at least five hours after the company comes.
  Rule night_turns when hour(clock) == 2 and not counted(ossel) and watch(clock) >= 30 {
    Increase night(ossel) by 1. Assert counted(ossel). }
  Rule night_passes when hour(clock) != 2 and counted(ossel) { Retract counted(ossel). }
  Query springNight() means night(ossel) == 1 or night(ossel) == 8 or night(ossel) == 15.
  // From the evening of the fourteenth night's day the city is keeping the Feast.
  Query feastEve() means night(ossel) >= 14.

  // Where word of the city's doings reaches the company: anywhere in Tessary, not under the sea. A company that has
  // been below hears what happened when it comes up.
  Relation cityRoom(place).
  // News already gone round, so it is not told twice.
  Relation spread(fact).
  Initially Assert cityRoom(throat_head).
  Initially Assert cityRoom(tidewall).
  Initially Assert cityRoom(legion_yard).
  Initially Assert cityRoom(tideline_steps).
  Initially Assert cityRoom(scriveners_row).
  Initially Assert cityRoom(terraces).
  Initially Assert cityRoom(withies).
  Initially Assert cityRoom(landgate).
  Initially Assert cityRoom(saltgate).
  Initially Assert cityRoom(pans).
  Initially Assert cityRoom(teazle_room).
  Initially Assert cityRoom(drum_taproom).
  Initially Assert cityRoom(sault_office).
  Initially Assert cityRoom(warehouse_floor).
  Initially Assert cityRoom(cistern).
  Initially Assert cityRoom(muster_hall).
  Initially Assert cityRoom(seals_hall).
  Initially Assert cityRoom(seals_inner).
  Initially Assert cityRoom(exchequer_room).
  Initially Assert cityRoom(pounce_stall).
  Initially Assert cityRoom(council_chamber).
  Initially Assert cityRoom(kings_rooms).
  Initially Assert cityRoom(marrable_room).
  Initially Assert cityRoom(chapel).
  Initially Assert cityRoom(chandlery).
  Initially Assert cityRoom(causeway_end).
  Query inTessary() means at(party, ?p) and cityRoom(?p).

  // A place the company has left and come back to is told shortly: what changed, not the whole of it again.
  Relation visitedNow(place). Relation visitedBefore(place).
  Rule arrives_at when at(party, ?p) and not visitedNow(?p) { Assert visitedNow(?p). }
  Rule leaves_from when visitedNow(?p) and not at(party, ?p) { Retract visitedNow(?p). Assert visitedBefore(?p). }

  // ── The calling ───────────────────────────────────────────────────────────────────────────────────────────────────
  // At a spring ebb the Balance calls a dozen of the collateral, in the order of the Muster's roll. They come down
  // through the Withies in step, barefoot, set their boots together on the top step and walk out over the wet sand
  // toward the Hall of Oaths. In the morning their families find the boots.
  Measure held(place). Measure callings(place). Relation bootsOnSteps(place). Relation callingDue(place).
  Initially Set held(ossel) to 138. Initially Set callings(ossel) to 0.
  Rule calling_due when counted(ossel) and springNight() and night(ossel) < 15 and callings(ossel) < night(ossel) and not interestPaid(ossel) {
    Assert callingDue(ossel). Set callings(ossel) to night(ossel). }
  Relation interestPaid(place).
  Rule interest_waived when counted(ossel) and springNight() and callings(ossel) < night(ossel) and interestPaid(ossel) {
    Set callings(ossel) to night(ossel). Retract interestPaid(ossel). }
  Rule calling_happens when callingDue(ossel) {
    Retract callingDue(ossel). Increase held(ossel) by 12. Assert bootsOnSteps(ossel). Assert calledLast(ossel). }
  Relation calledLast(place).
  Rule boots_taken when bootsOnSteps(ossel) and hour(clock) == 9 { Retract bootsOnSteps(ossel). }
  Rule calling_told at tideline_steps when calledLast(ossel) says "They come down through the Withies a little after two, twelve of them, in step, though nobody is calling the step. Barefoot. Their eyes are open. At the top of the Watersteps each of them stops, and stoops, and sets his boots side by side on the stone, toes to the water, and straightens, and walks down into the sea. The water is very low. They walk out over the sand toward the walls in the basin, getting smaller, keeping step, until the dark has them." teaches calling_witnessed { Retract calledLast(ossel). }
  Rule calling_unseen when calledLast(ossel) { Retract calledLast(ossel). }
  Discovery calling_witnessed "At the spring ebb, twelve veterans of the Long Muster walked barefoot and in step down the Watersteps and out across the drained basin toward the drowned city, as if called, and left their boots paired on the top step.".
}

data/adventures/what-tessary-owes/compan:
Module tessary "What Tessary Owes" {
  // The company of the campaign played alone: one traveller come down the marsh road with a little coin (placed.kyr is
  // the world's own company, come in by the Causeway).
  Company party "You" of 1 at causeway_end.
  Initially Set quantity(party, gold) to 12. Initially Set quantity(party, rations) to 2.
}

Module tessary "What Tessary Owes" {
  // ── The Valuer about the city ───────────────────────────────────────────────────────────────────────────────────
  // By day the inventory in the Withies; by night the Watersteps, watching the water.
  Rule tally_to_steps when hour(clock) >= 21 and at(tally, withies) and not travelsWith(tally, party) and not tallyBelow(ossel) {
    Retract at(tally, withies). Assert at(tally, tideline_steps). }
  Rule tally_to_withies when hour(clock) >= 7 and hour(clock) < 21 and at(tally, tideline_steps) and not travelsWith(tally, party) and not tallyBelow(ossel) {
    Retract at(tally, tideline_steps). Assert at(tally, withies). }
  Relation tallyBelow(place).
  // What the Valuer does with a contradiction: a filing.
  Relation tallyHeardPrior(place). Relation tallyKnowsDominion(place).
  Topic tell_tally_prior with tally "Tell the Valuer that the city promised its soldiers land and a pension before it pledged them" when knows(actor, enlist_promise) and knows(actor, promise_weight) and not tallyHeardPrior(ossel) once {
    Says "The Valuer stops writing. 'The recruiting bill,' they say. 'Eleven years old. The Muster was raised when the war began; the note was drawn when the war was a year old, and going badly.' They are silent for a while. 'The promise to the soldiers was made first.' They look at the ledger as if it had said something rude. 'A prior promise, of the same weight, to the same persons, unkept. And the city pledged those persons to us as if they were its own.' A long pause. 'That is not on my inventory. I find I cannot stop thinking about it.'".
    On discuss { Assert tallyHeardPrior(ossel). }
  }
  Topic tell_tally_dominion with tally "Tell the Valuer that the Factor means to buy the note in order to govern the city" when knows(actor, sault_bid) and not tallyKnowsDominion(ossel) once {
    Says "'To govern,' says the Valuer. 'With the collateral.' Their voice does not change; the ruled lines on their face do. 'A note may be taken up at foreclosure by whoever pledges its weight. It may not be taken up for dominion. That is the ninth chapter.' They write for some time. 'I will file an objection to the Factor's bid with the Broker's superiors. It will be heard. Whether it is heard in time I cannot say.'".
    On discuss { Assert tallyKnowsDominion(ossel). }
  }
  Relation objectionFiled(place).
  Rule objection_heard when tallyKnowsDominion(ossel) and night(ossel) >= 12 and not objectionFiled(ossel) and not tallyUnravelled(ossel) { Assert objectionFiled(ossel). Assert brokerSuspended(ossel). }

  // The indictment: only a Valuer who has seen the Room of Defaults, and kept faith with the company that showed
  // it to them, will bring it.
  Action ask_indictment(actor: group, site: place) "Ask the Valuer to indict the Comptroller before the Assembly" {
    Speaker tally. Time 1.
    Grave "If the Assembly finds against him, the Comptroller will unravel, or at best be put down from his office; and the Valuer will have done the gravest thing a Scruple can do.".
    Requires able(actor) and company(actor) and at(actor, site) and travelsWith(tally, actor) and tallySawDefaults(ossel)
      and not brokeFaith(actor) and not indictmentFiled(ossel) and not tallyUnravelled(ossel) and not caughtCopying(actor)
      and (tallyHeardPrior(ossel) or keptFaith(actor) or tallyKnowsDominion(ossel)).
    On success { Assert indictmentFiled(ossel). Retract travelsWith(tally, actor). Assert tallyBelow(ossel). Assert at(tally, clerks_hall).
      Assert holdingAdmits(actor). }
    Result "The Valuer is quiet for a long time. 'Yes,' they say. 'It must be one of us, and it must be someone who has read the entry, and I have read it.' They take out a fresh sheet and write on it, standing, in a hand that does not shake. When they have done they fold it once. 'The Assembly will sit in the Weighing Chamber on the night of the Settlement, from midnight, and the Notary will come out of the Holding to sit with it. I will be there. You should be there; you read it with me.' They look at you. 'I am leaving you here. I have a great deal to prepare and I find I would rather be alone.'".
  }
  Rule indictment_spoken when indictmentFiled(ossel) and swornSilence(party) and not forswornParty(party)
    says "Somewhere under the sea a promise of silence you made to the Comptroller breaks, and you feel it go, a cold hand laid flat between your shoulders." {
    Assert forswornParty(party). }

  // ── The Release ───────────────────────────────────────────────────────────────────────────────────────────────────
  // Durrance, if she is free and has thought it through, can call the Muster to the Oath Stone on the night of the
  // Feast to release the city from its promise to them; the Factor's men will try to break it up.
  Relation releaseCalled(place). Relation releaseGathered(place). Relation releaseBroken(place). Relation releaseHeld(place).
  Query cityPaying() means votePassed(ossel) and not sealStolen(ossel).
  Topic ask_release with durrance "Ask Durrance to call the Muster to the Oath Stone on the night of the Feast, to release the city" when durranceKnowsRelease(durrance) and not heldNow(durrance) and not releaseCalled(ossel) and not cityPaying() and night(ossel) <= 14 and not serves(durrance, sault) once {
    Says "Durrance has had her days to think, and she has thought. 'Eleven years,' she says. 'And the Board votes no, or yes and then lets the Factor walk off with the Seal, and either way the lads stay under the sea.' She stands up. 'So we do it. The Muster on the Stone at the Feast, as many as I can get, and we say it: we hold you quit. Keep your land. Keep your pension. Give us back our own.' She laughs, short. 'I'll have to tell them it was my idea. They'll never stand for it if it was a stranger's.' She looks at you. 'The Factor will send her lightermen. Be there.'".
    On discuss { Assert releaseCalled(ossel). }
  }
  Rule release_gathers when releaseCalled(ossel) and night(ossel) == 14 and hour(clock) == 22 and not releaseGathered(ossel) and not heldNow(durrance) and at(durrance, ?p) {
    Assert releaseGathered(ossel). Retract at(durrance, ?p). Assert at(durrance, legion_yard). }
  Rule release_gathers_with when releaseCalled(ossel) and night(ossel) == 14 and hour(clock) == 22 and not releaseGathered(ossel) and travelsWith(durrance, party) {
    Assert releaseGathered(ossel). }
  Observe release_scene at legion_yard when releaseGathered(ossel) and not released(ossel) and not releaseBroken(ossel) "The Legion Yard is full of soldiers. Not in step, not in ranks: a crowd of men and women in old red coats and whatever else they have, with lanterns, thousands of them, filling the Yard and the wall-walk and the lane, and more coming. Durrance stands on the Oath Stone's plinth with one hand on the Stone. It is very quiet for so many people. Out on the Tidewall the Feast's bonfires are burning, and the city's year of contracts is going up in sparks.".
  Event release_crowd at legion_yard when releaseGathered(ossel) and not released(ossel) and not releaseBroken(ossel) "They come in through the Yard gate in ones and twos at first, and then in files, and then in a crowd that does not stop: soldiers of the Long Muster in their old red coats and in their working clothes, with lanterns, with their wives and husbands and children, filling the parade ground and the wall-walk and the lane behind. Nobody gives an order. Durrance climbs up onto the plinth and lays her hand on the Oath Stone and waits, and the Yard goes quiet round her a rank at a time.".
  Event lightermen_turned_back at legion_yard when releaseGathered(ossel) and fiskTurned(fisk) and night(ossel) == 14 and hour(clock) == 23 and not released(ossel) "There is a stir at the Yard gate. A dozen men in salt-stiff jerkins have come up the lane with cudgels, and found the gate full of the Third Company, with Benno Fisk in front of them in his old red coat. Nobody raises a hand. The lightermen look at the crowd behind Fisk for a long moment, and then they go back down the lane the way they came, and the crowd lets them.".
  Rule lightermen_come when releaseGathered(ossel) and hour(clock) == 23 and night(ossel) == 14 and able(lightermen) and not saultStopped(ossel) and at(lightermen, ?p) and not at(lightermen, legion_yard) and not fiskTurned(fisk) {
    Retract at(lightermen, ?p). Assert at(lightermen, legion_yard). }
  Rule lightermen_at_yard at legion_yard when at(lightermen, legion_yard) and releaseGathered(ossel) and at(party, legion_yard) and not assails(lightermen, party) and able(lightermen) and not released(ossel)
    says "There is a shout from the gate. Sault's lightermen are coming through the crowd with cudgels, shoving, a dozen of them, making for the plinth." {
    Assert assails(lightermen, party). }
  Rule release_broken when releaseGathered(ossel) and at(lightermen, legion_yard) and able(lightermen) and hour(clock) == 0 and not at(party, legion_yard) and not released(ossel) and not releaseBroken(ossel) {
    Assert releaseBroken(ossel). }
  Rule release_broken_told when releaseBroken(ossel) and not spread(release_broken_known)
    and inTessary() says "Word comes from the Legion Yard: the Factor's lightermen broke up the Muster at the Oath Stone with cudgels, and the Watch stood by, and Durrance was carried off the plinth with a broken head." { Assert spread(release_broken_known). }
  Discovery release_broken_known "The Factor's lightermen broke up the Muster's gathering at the Oath Stone on the Feast night.".
  Relation saultStopped(place).
  Action stand_release(actor: group, site: place) "Stand with the Muster at the Oath Stone while they say it" {
    Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, legion_yard) and releaseGathered(ossel)
      and not released(ossel) and not releaseBroken(ossel) and night(ossel) == 14 and hour(clock) >= 23
      and not (at(lightermen, legion_yard) and able(lightermen)).
    On success { Assert released(ossel). }
    Result "Durrance says it first, alone, with her hand on the Stone, in a voice that carries to the back of the Yard without being raised: 'The city of Tessary promised me land and a pension if I came home. I came home. I hold it quit.' Then the Third Company says it, ragged, and then the Yard, all of it, eight thousand voices or near enough, not together, a long rolling noise like surf: I hold it quit. And under your feet, under the Yard, under the Tidewall and the drowned streets, something very large and very far down settles by a hair's breadth, like a pan of a scale coming level.".
  }
  Rule release_by_itself when releaseGathered(ossel) and hour(clock) == 1 and night(ossel) == 14 and not released(ossel) and not releaseBroken(ossel)
    and not (at(lightermen, legion_yard) and able(lightermen)) { Assert released(ossel). }

  // ── The Assembly ──────────────────────────────────────────────────────────────────────────────────────────────────
  Relation assemblySits(place). Relation assemblyHeard(place). Relation mercyAsked(place). Relation comptrollerUnravelled(place).
  Relation comptrollerDeposed(place).
  Rule assembly_convenes when indictmentFiled(ossel) and night(ossel) == 14 and hour(clock) == 0 and not assemblySits(ossel) {
    Assert assemblySits(ossel). Retract at(tally, clerks_hall). Assert at(tally, weighing_chamber).
    Retract at(comptroller, comptroller_office). Assert at(comptroller, weighing_chamber). }
  Event assembly_comes at weighing_chamber when assemblySits(ossel) "At midnight they come down the Counting Stair, all of them: the Scruples in their grey coats, in silence, in rows, more of them than you have seen in all the halls together, and fill the floor of the nave under the Balance. The Comptroller comes last and stands alone. Then the Door of the Holding brightens, and something steps out of it that is made of fine ruled lines of light, as a drawing of a clerk is made of lines, and takes its place at the foot of the Balance. The Valuer steps forward with one folded sheet. Nobody has said a word.".
  Observe assembly_scene at weighing_chamber when assemblySits(ossel) and not noteVoid(ossel) "The Assembly of the Scruples is sitting. They stand in rows on the floor of the nave under the Balance, all of them, grey and pale and silent, with their ruled hands folded. At the foot of the Balance the Notary stands, come out of the Holding for the first time in five hundred years, a figure drawn in lines of light. The Comptroller stands alone before it. The Valuer stands alone before him, with one folded sheet.".
  Action testify(actor: group, site: place) "Testify before the Assembly to what you read in the Room of Defaults" {
    Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, weighing_chamber) and assemblySits(ossel)
      and knows(actor, note_designed) and not assemblyHeard(ossel).
    On success { Assert assemblyHeard(ossel). }
    Result "You tell them what you read, and where, and when, and who was with you. The floor of the nave registers every word; the ruled lines along the walls brighten and hold. Nobody interrupts. When you have finished the Notary turns its face of lines to the Comptroller. He does not deny it. He cannot. 'I would draw it again,' he says, to the Assembly, to the Balance, to the Door with the white floor beyond it. 'There was no other way to close it. There is still none.'".
  }
  Action ask_mercy(actor: group, site: place) "Ask the Assembly to put the Comptroller down from his office, and spare him unravelling" {
    Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, weighing_chamber) and assemblyHeard(ossel)
      and not mercyAsked(ossel) and not noteVoid(ossel).
    On success { Assert mercyAsked(ossel). }
    Result "There is a long silence in the nave. Then the Notary speaks. 'A promise made to be broken is no promise,' it says. 'That is the law. What becomes of the one who made it is the Assembly's.' It looks at the Valuer. The Valuer looks at the Comptroller for a long time. 'He has kept the ledger for eleven hundred years,' they say. 'Let him keep the archive. Under supervision. Without the black glass.' And the rows of grey figures bow, all together, which is apparently how the Scruples vote.".
  }
  Rule note_voided when assemblySits(ossel) and hour(clock) == 1 and night(ossel) == 14 and not noteVoid(ossel) and not tallyUnravelled(ossel)
    says "In the Weighing Chamber the Notary lays a line of light through the sheet of black glass in the pan, end to end, and the glass goes grey, and then clear, and then is nothing. 'Void,' it says. 'A promise made to be broken is no promise. The collateral is released.' The pointer of the Balance swings, a long slow arc, and stops where it stops: not level. There is still a hole in the ledger the size of a city. But it is the Comptroller's, now, and not the Muster's." {
    Assert noteVoid(ossel). }
  Rule comptroller_unravels when noteVoid(ossel) and not mercyAsked(ossel) and not comptrollerUnravelled(ossel)
    says "The Comptroller does not cry out. The ruled lines of his face begin to come apart, very slowly, like a page left in rain, and then less slowly, and then he is a coat with nobody in it, standing at the foot of the Balance with its hands out, as if it wanted to be given something. Two of the Weights come and lead it away toward the stair, quite gently. Nobody watches it go except the Valuer." {
    Assert comptrollerUnravelled(ossel). Retract at(comptroller, weighing_chamber). }
  Rule comptroller_put_down when noteVoid(ossel) and mercyAsked(ossel) and not comptrollerDeposed(ossel) { Assert comptrollerDeposed(ossel). }

  // ── The Factor on the night ───────────────────────────────────────────────────────────────────────────────────────
  // If her broker is suspended she comes to the Weighing Chamber herself, with lightermen, by the cistern and the
  // drowned streets, to pledge in person at foreclosure; if he is not, her bid is lodged on the fourteenth day.
  Relation saultBidLodged(place). Relation saultInChamber(place). Relation saultWarden(place).
  Rule bid_lodged when night(ossel) == 14 and hour(clock) == 12 and not brokerSuspended(ossel) and able(sault) and not saultBidLodged(ossel) {
    Assert saultBidLodged(ossel). }
  Rule sault_goes_down when night(ossel) == 14 and hour(clock) == 23 and brokerSuspended(ossel) and able(sault) and not saultInChamber(ossel) and at(sault, ?p) and not saultStopped(ossel) {
    Assert saultInChamber(ossel). Retract at(sault, ?p). Assert at(sault, weighing_chamber). Retract peaceable(sault). }
  Observe sault_in_chamber at weighing_chamber when saultInChamber(ossel) and at(sault, weighing_chamber) and not matured(ossel) "Factor Sault is here, in the nave of the Weighing Chamber, in a sea-cloak still wet from the Hall of Oaths, with a lantern and two lightermen and a paper in her hand. She is looking up at the Balance with her mouth slightly open, like anyone. Then she sees you, and puts the look away. 'Of course,' she says. 'Of course it's you.'".
  Topic sault_terms with sault "Put terms to the Factor: take up the note and call the Muster out only to send them home to their land" when (saultInChamber(ossel) or saultExposed(ossel) or brokerSuspended(ossel) or saultShaken(ossel)) and knows(actor, sault_bid) and knows(actor, salt_springs) and not saultWarden(ossel) and not matured(ossel) and able(sault) once {
    Says "Factor Sault hears you out with her head on one side. 'Warden of the Settlement,' she says. 'Hold the note and never use it but to send them home. And for that?' You tell her: the salt springs of Hethra, which the war was fought for, and which nobody else in Tessary knows how to work. She laughs. 'You've been talking to Amaury.' She is quiet a long time. 'They'd still owe me,' she says. 'The city. For ever.' She looks at the Balance. 'All right. Write it down, whatever you people write it on. I'll swear it. I'd rather be owed than hated, and I'd rather be either than beaten.'".
    On discuss { Assert saultWarden(ossel). }
  }
  Action stop_sault(actor: group, site: place) "Stand between the Factor and the Balance" {
    Time 0.
    Requires able(actor) and company(actor) and at(actor, site) and at(sault, site) and saultInChamber(ossel) and able(sault)
      and not saultWarden(ossel) and not matured(ossel) and not assails(sault, actor).
    On success { Assert assails(sault, actor). Assert assails(lightermen, actor). }
    Result "'Don't,' says Factor Sault, almost kindly, and draws.".
  }
  Rule lightermen_with_sault when saultInChamber(ossel) and at(lightermen, ?p) and not at(lightermen, weighing_chamber) and able(lightermen) {
    Retract at(lightermen, ?p). Assert at(lightermen, weighing_chamber). }
  Rule sault_beaten when saultInChamber(ossel) and not able(sault) and not saultStopped(ossel) { Assert saultStopped(ossel). }
  Rule sault_captured when captured(sault, party) and at(party, ?p)
    says "You come round on the floor of the nave with your head ringing. Factor Sault is standing over you, wiping her hands. 'Stay down,' she says. 'It's nearly two.'" {
    Retract captured(sault, party). }
  Initially Assert takesPrisoners(sault).

  // The Valuer's last resort: in the chamber at the Settlement, with nothing else left, they can take the black
  // glass out of the pan and break it. A Scruple who breaks the note breaks a promise held by the Balance.
  Action ask_tear(actor: group, site: place) "Ask the Valuer to take the War Note out of the pan and break it" {
    Speaker tally. Time 1 minute.
    Grave "The Valuer will be breaking a promise the Balance holds. You know what happens to a Scruple who does.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, weighing_chamber) and at(tally, weighing_chamber)
      and tallySawDefaults(ossel) and not indictmentFiled(ossel) and not brokeFaith(actor) and night(ossel) == 14 and hour(clock) >= 0
      and hour(clock) < 2 and not released(ossel) and not deedsDelivered(ossel) and not noteTorn(ossel).
    On success { Assert noteTorn(ossel). Assert tallyUnravelled(ossel). Retract travelsWith(tally, actor). Retract willing(tally, actor). Assert tallyBelow(ossel). }
    Result "The Valuer looks at you, and then up at the Balance, for a long moment. 'Yes,' they say. 'Somebody should break it who knows what it is.' They climb the side of the pan like a child climbing into a boat, and walk across the bottom of it to the sheet of black glass, and pick it up in both ruled hands, and break it over their knee. It breaks like ice. The pointer of the Balance swings, slowly, all the way across the dial. And the ruled lines on the Valuer's face begin, very gently, to come undone. 'Oh,' they say, looking at their hands. 'That is what it feels like.' They sit down in the bottom of the pan. 'Tell the child,' they say, 'that the eel was very kind,' and then there is nobody in the grey coat at all.".
  }
  Rule tally_with_party_down when travelsWith(tally, party) and at(party, weighing_chamber) and not at(tally, weighing_chamber) { Assert at(tally, weighing_chamber). }
  Rule tally_off_floor when at(tally, weighing_chamber) and travelsWith(tally, party) and not at(party, weighing_chamber) { Retract at(tally, weighing_chamber). }

  // ── The Settlement ────────────────────────────────────────────────────────────────────────────────────────────────
  // At the fifteenth spring ebb the note matures. What is true of the city at that moment decides what follows.
  Rule maturity when night(ossel) == 15 and not matured(ossel) { Assert matured(ossel). Assert settling(ossel). }
  Relation settling(place).
  Rule settle_kept when settling(ossel) and deedsDelivered(ossel) { Retract settling(ossel). Assert keptPromise(ossel). Assert discharged(ossel). }
  Rule settle_released when settling(ossel) and released(ossel) { Retract settling(ossel). Assert discharged(ossel). }
  Rule settle_void when settling(ossel) and noteVoid(ossel) { Retract settling(ossel). Assert discharged(ossel). }
  Rule settle_torn when settling(ossel) and noteTorn(ossel) { Retract settling(ossel). Assert discharged(ossel). }
  // A bid for dominion, objected to by a Valuer, fails; a Warden's bid, sworn to send the Muster home, does not.
  Rule settle_taken when settling(ossel) and (saultBidLodged(ossel) or (saultInChamber(ossel) and able(sault) and not saultStopped(ossel)))
    and (not objectionFiled(ossel) or saultWarden(ossel)) {
    Retract settling(ossel). Assert saultHoldsNote(ossel). }
  Rule settle_foreclosed when settling(ossel) { Retract settling(ossel). Assert foreclosed(ossel). }
  // Discharged: every oath in the pan goes home.
  Rule held_wake when discharged(ossel) and heldNow(?s) { Retract heldNow(?s). Retract asleep(?s). Assert cameHome(?s). Assert wokeHome(?s). }
  Rule held_warden when saultHoldsNote(ossel) and saultWarden(ossel) and heldNow(?s) { Retract heldNow(?s). Retract asleep(?s). Assert cameHome(?s). Assert wokeHome(?s). }
  Rule held_count when (discharged(ossel) or saultWarden(ossel) and saultHoldsNote(ossel)) and held(ossel) > 0 { Set held(ossel) to 0. }
  Rule settlement_heard at ranks when discharged(ossel) and not spread(held_woke)
    says "All down the Ranks the sleepers open their eyes, together, as if a drum had beaten the stand-down. They look at their hands. They look at each other. Somebody laughs. Somebody starts to cry. Then, without anyone giving the order, they turn, all of them, and begin to walk back across the white floor toward the Door, in step, because they do not know how not to." { Assert spread(held_woke). }
  Rule settlement_seen when discharged(ossel) and not at(party, ranks) and not spread(held_woke)
    and inTessary() says "At two in the morning, all over the Withies, people wake for no reason and go out onto the boardwalks. The basin is out, lower than anyone has ever seen it. And out in the drowned city, very small, coming up the steps of the Hall of Oaths and across the Forum in the starlight, barefoot and in their shirts and in step, a hundred and sixty soldiers of the Long Muster are walking home." { Assert spread(held_woke). }
  Discovery held_woke "At the Settlement the note was discharged, and the called of the Long Muster woke and walked home.".
  Rule muster_called when saultHoldsNote(ossel) and not saultWarden(ossel) and not spread(muster_called_known)
    says "At two in the morning, all over Tessary, the soldiers of the Long Muster get up out of their beds, the old ones and the young ones and the one-armed ones, and dress, and go out into the streets, and walk in step through the dark to Panhythe, where Factor Sault is waiting for them on the steps of her countinghouse with a lantern. Her voice carries a long way in the quiet. 'Good morning, lads,' she says. 'You're paid from today.'" { Assert spread(muster_called_known). }
  Discovery muster_called_known "At the Settlement Factor Sault took up the War Note and called the Long Muster to Panhythe.".
  Rule muster_warden when saultHoldsNote(ossel) and saultWarden(ossel) and not spread(muster_called_known)
    says "At two in the morning the soldiers of the Long Muster wake in their beds all over the city, every one of them, for no reason, and lie listening. Nothing calls them. Out in the drowned city, in the starlight, a hundred and sixty more are walking home across the Forum, and at the head of them, in a wet sea-cloak with a lantern, the Factor of the Salt Moiety is picking her way over the weed and swearing." { Assert spread(muster_called_known). }
  Rule foreclosure_told when foreclosed(ossel) and not spread(foreclosed_known)
    and inTessary() says "At two in the morning nothing happens. The basin is out, lower than anyone remembers; the Tidewall bonfires have burned down to red; the last contracts of the year are ash. Nobody walks into the sea. Nobody walks out of it. Only, a long way out past the Hall of Oaths, where the outer bar meets the open water, the sea for a moment shows a sky full of stars that are not the stars over Tessary, bright and close, and then is the sea again." { Assert spread(foreclosed_known). }
  Discovery foreclosed_known "At the Settlement the War Note fell in and nobody took it up. The called stay where they are, and the ledger is uneven at Tessary.".

  // ── What became of them ───────────────────────────────────────────────────────────────────────────────────────────
  // Told in the morning after the Settlement, before the book closes.
  Query morning() means night(ossel) >= 15 and hour(clock) >= 7.
  Relation toldFates(place).
  Rule fate_tally_reformer when morning() and noteVoid(ossel) and not tallyFreed(ossel) and not told_tally(ossel) says "The Ninth Valuer sits now at the Comptroller's desk, which they have had moved into the Hall of Clerks where everyone can see it. They have begun to go through the ledger from the first page, with the old city's hole in it, and to write in the margin, for each entry, whether it was honest. It will take them, they estimate, four hundred years. They seem, as far as anyone can tell with a Scruple, happy." { Assert told_tally(ossel). }
  Rule fate_tally_freed when morning() and tallyFreed(ossel) and not told_tally(ossel) says "There is a new stall on Scriveners' Row: CONTRACTS READ, DISPUTES WEIGHED, NO LIES TOLD (NONE). The scrivener behind it has a grey coat and ruled hands and a name nobody in Tessary has heard before, which by the end of the winter nobody finds strange. Pounce says it is unfair competition. Brother Ancel says it is the saint come home. Wick brings them an eel every Fourth-day, and they eat it." { Assert told_tally(ossel). }
  Rule fate_tally_unravelled when morning() and tallyUnravelled(ossel) and not told_tally(ossel) says "Wick Teazle sits on the Watersteps every evening at the ebb, with an eel in a paper cone, and watches the doorways of Lowtide where the hollow men stand, looking for one in a grey coat. He has not seen it yet. He does not know what he would do if he did. He thinks he would give it the eel." { Assert told_tally(ossel). }
  Rule fate_tally_plain when morning() and not tallyFreed(ossel) and not tallyUnravelled(ossel) and not noteVoid(ossel) and not told_tally(ossel) says "The Ninth Valuer went below at the Settlement with the inventory complete. The children of the Withies still call the stair at the end of the boardwalk Docket's Step, though none of them can say why." { Assert told_tally(ossel). }
  Relation told_tally(place). Relation told_durrance(place). Relation told_quire(place). Relation told_sault(place).
  Rule fate_durrance_release when morning() and released(ossel) and not told_durrance(ossel) says "Thomasin Durrance never takes a penny of the pension she released. She runs the Muffled Drum with Hannelore now, and the Third Company's drum hangs over the bar with its head bare, and on the night of every spring ebb she beats the stand-down on it, at two in the morning, for anyone who might be listening." { Assert told_durrance(ossel). }
  Rule fate_durrance_sault when morning() and serves(durrance, sault) and not told_durrance(ossel) says "Sergeant Durrance sergeants the Factor's Muster, in a good coat, and is fair to them, and is paid, and does not go into the Muffled Drum any more." { Assert told_durrance(ossel). }
  Rule fate_durrance_held when morning() and heldNow(durrance) and not told_durrance(ossel) says "Sergeant Durrance is still standing in the Ranks of the Holding, asleep, with her hands at her sides. At the Muffled Drum her boots stand on the bar under the covered drum, and nobody touches them." { Assert told_durrance(ossel). }
  Rule fate_durrance_home when morning() and not heldNow(durrance) and not serves(durrance, sault) and not released(ossel) and not told_durrance(ossel) says "Sergeant Durrance goes back to the Muffled Drum and drinks one pot, standing, and then goes down to the Watersteps to meet the ones coming home, and calls the roll for them on the top step, every name, in order, until her voice goes." { Assert told_durrance(ossel). }
  Rule fate_quire_confessed when morning() and quireConfessed(ossel) and not told_quire(ossel) says "Josiah Quire is put out of the Exchequer by the Board in a vote of seven to nothing, and goes to live in two rooms in the Lettered Quarter, and writes letters for people who cannot, at Pounce's old rates, which annoys Pounce. He is sleeping again." { Assert told_quire(ossel). }
  Rule fate_quire_dead when morning() and quireDrowned(ossel) and not told_quire(ossel) says "Brother Ancel hangs a weight in Saint Evenhand's for Josiah Quire: lead, for a debt. It is the only one in the chapel nobody paid for." { Assert told_quire(ossel). }
  Rule fate_sault_exposed when morning() and saultExposed(ossel) and not saultHoldsNote(ossel) and not told_sault(ossel) says "Factor Sault keeps her pans and her ships and loses her chair on the Board, and is seen every evening on the Tidewall eating eels out of a paper cone, as cheerful as ever, and doing sums." { Assert told_sault(ossel). }
  Rule fate_sault_warden when morning() and saultWarden(ossel) and saultHoldsNote(ossel) and not told_sault(ossel) says "Factor Sault holds the War Note in a frame on the wall of her countinghouse, and never calls on it, and works the salt springs of Hethra by treaty with a king who finds her very amusing. The city owes her everything. She reminds it daily." { Assert told_sault(ossel). }
  Rule fate_sault_foreclosed when morning() and foreclosed(ossel) and not saultHoldsNote(ossel) and not told_sault(ossel) says "Factor Sault came up the Long Stair on the morning of the Settlement with nothing in her hands, and has not said a word about it since, to anyone. In the spring she pays, out of her own purse, for another course of stone along the Tidewall, a foot higher than the Moieties' and the Aenean ones under it, and has nothing cut on it at all." { Assert told_sault(ossel). }
  Rule fate_sault_thwarted when morning() and not foreclosed(ossel) and not saultExposed(ossel) and not saultHoldsNote(ossel) and not told_sault(ossel) says "Factor Sault's bid was never opened: at the Settlement there was nothing owing to bid for. She keeps her chair and her pans and her ships. One by one, over the winter, the coats she gave the Muster's men come back to her hiring hall, folded, and she has them hung on pegs along the wall, in rows, and does not give them out again." { Assert told_sault(ossel). }
  Relation told_comptroller(place).
  Rule fate_comptroller_foreclosed when morning() and foreclosed(ossel) and not told_comptroller(ossel) says "Under the sea the Comptroller has his eight thousand oaths, and the hole in his ledger is filled, to the last line, as he drew it. The Copyist says he has not been seen to write since." { Assert told_comptroller(ossel). }
  Rule fate_comptroller_outbid when morning() and saultHoldsNote(ossel) and not told_comptroller(ossel) says "Under the sea the Comptroller enters the War Note transferred to a woman of the Salt Moiety, in his own hand, which does not shake. The hole in the Room of Defaults is eleven hundred years wide and stays so. He has the Copyist read the entry back to him twice." { Assert told_comptroller(ossel). }
  Rule fate_comptroller_discharged when morning() and (keptPromise(ossel) or released(ossel) or noteTorn(ossel)) and not told_comptroller(ossel) says "Under the sea the Comptroller enters the War Note discharged and closes the ledger. The hole in the Room of Defaults is still there. The Copyist says he has taken to sitting in that room in the evenings, with the door open, which the Scruples find more frightening than anything he has done in eleven hundred years." { Assert told_comptroller(ossel). }

  // ── Endings ───────────────────────────────────────────────────────────────────────────────────────────────────────
  Ending kept "The Kept Promise" when morning() and keptPromise(ossel) "In the spring the old estates of the Moieties along the Ossel are surveyed into strips, and eight thousand soldiers and their families go upriver with ploughs bought on the city's credit, which is now bad, because the city has nothing; but the city kept its word, and the Balance under the sea is level, and the Scruples go back to writing down the small promises of fishwives. The Board meets in a Council House with boarded windows. On the twelfth of Haying there is no procession for the Kneeling. Instead, in the Withies, somebody's mother puts a recruiting bill in the fire, and everyone stands round and watches it burn.".
  Ending release "The Release" when morning() and released(ossel) "The Muster saved the city twice. The second time it paid for the privilege with every penny the city had promised it, and the city knows it, and does not know what to do with the knowledge. The Board votes the Muster a medal. The Muster does not come to collect it. Instead, the veterans of Tessary go to work, on the pans and the boats and in the Lettered Quarter, owing nobody anything, and when the Board next wants a war it finds that nobody in the Withies will answer a drum, and has to think of something else.".
  Ending void "The Void Note" when morning() and noteVoid(ossel) "The note is void and the Muster is home, and the city owes nothing to the Balance and its soldiers everything, as before; the Board will hear the question of the Settlement again in the spring, and this time the public bench will be full. Under the sea the Scruples have a new Comptroller who keeps a hole in the ledger the size of a city in plain sight, and on certain nights, far out past the bar, the sea at Tessary shows other stars. The fishermen have stopped being frightened of it. They say it is good for the eels.".
  Ending torn "The Broken Note" when morning() and noteTorn(ossel) "The note is broken, and the Muster is home, and nobody in Tessary but you knows exactly how. The Scruples enter it as a default by an officer of the Balance, and say nothing more; the Board says nothing at all. In Lowtide the mudlarks say there is a new hollow man in the doorways of the bath-house, in a grey coat, who stands very still and does not come out, and who once, at the turn of the tide, held out a hand ruled like paper to a child, palm up, as if to show it was empty.".
  Ending warden "The Warden of the Settlement" when morning() and saultHoldsNote(ossel) and saultWarden(ossel) "The called come home, and the Muster belongs to Factor Sault, who will never call it; the city's debt has become a debt to one woman, who can count, and does, out loud, at every meeting of the Board. The veterans go upriver to land that is theirs in all but law, under the Warden of the Settlement, who visits every autumn with seed-corn and a ledger. It is not justice. It is something people can live in, which in Tessary is often the best on offer.".
  Ending factor "The Factor's Tessary" when morning() and saultHoldsNote(ossel) and not saultWarden(ossel) "The Muster belongs to Factor Sault. Within the week the Board, which has no army and no money and no more chairs than it has frightened councillors, gives her the Great Seal and the title of Warden of the City. Tessary is better run than it has been in a century. The soldiers are fed and paid and housed, and stand on the Tidewall in her coats, and nobody in the city is sure any more what they would do if they were told to do something terrible, and the soldiers least of all.".
  Ending foreclosure "Foreclosure" when morning() and foreclosed(ossel) "Nothing happens, which is the worst of it. The called stay where they are. The Board says nothing; there is no money to say anything with. The rest of the Muster goes back to the boardwalks and the pans and waits for the next spring ebb, which does not come, because there is nothing left owing, only something forfeit. In the Withies they hang the boots from the eaves of the stilt-houses, pair by pair. And out past the bar, on more nights every month, the sea shows stars that are not Tessary's, very close, and once in the winter something comes up the Swatch on the flood and is found dead on the Pans in the morning, pale and many-jointed and the size of a calf, and not one book in the Lettered Quarter has a word for it; and the Scruples, who might have, have closed the black wall and do not answer.".

  // ── Objectives ────────────────────────────────────────────────────────────────────────────────────────────────────
  Objective find_davy when knows(party, notice_read) and not knows(party, davy_went) and heldNow(davy) "Nan Teazle of the Withies wants to know where her son Davy went when he walked into the sea.".
  Objective follow_davy when knows(party, davy_went) and not knows(party, held_alive) and heldNow(davy) "Davy Teazle walked into the sea at the spring ebb. Where did he go, and why do the soldiers keep step as they go?".
  Objective why_held when knows(party, held_alive) and not knows(party, collateral) and not matured(ossel) "The soldiers who walk into the sea are held, not dead. Who is holding them, and for what?".
  Objective what_owed when knows(party, collateral) and not knows(party, promise_weight) and not matured(ossel) "The city pledged its soldiers' oaths against a debt. What does it owe, and how can it be paid?".
  Objective pay_it when knows(party, promise_weight) and not voted(ossel) and not matured(ossel) "The War Note is paid if the city keeps its promise of land and a pension to every soldier who came home. The Board votes on the thirteenth day, and has no money.".
  Objective save_durrance when knows(party, durrance_next) and night(ossel) < 8 and not durranceSafe() and not heldNow(durrance) "Sergeant Durrance is on the next page of the roll, and will walk into the sea at the eighth night's spring ebb.".
  Objective carry_deeds when knows(party, deeds_for_held) and not deedsDelivered(ossel) and not matured(ossel) "The deeds of the called must be put into their hands in the Holding before the note falls due at two in the morning after the Feast.".
  Objective feast_release when releaseCalled(ossel) and not released(ossel) and not releaseBroken(ossel) and not matured(ossel) "Durrance will call the Muster to the Oath Stone on the night of the Feast, to release the city. The Factor's lightermen will come.".
  Objective feast_assembly when indictmentFiled(ossel) and not noteVoid(ossel) and not matured(ossel) "The Assembly of the Scruples sits in the Weighing Chamber from midnight on the night of the Feast. The Valuer asked you to be there.".
  Objective sault_bid_known when knows(party, sault_bid) and not matured(ossel) and not saultWarden(ossel) and not saultStopped(ossel) "Factor Sault means to take up the War Note when it falls in, and govern Tessary with the Muster.".

  // The module is seen through when the note is discharged, or held by a Warden sworn to send the Muster home.
  Goal discharged(ossel) or saultWarden(ossel) and saultHoldsNote(ossel).
}

data/adventures/what-tessary-owes/histor:
Module tessary "What Tessary Owes" {
  // ── What the city remembers, and what it has forgotten ────────────────────────────────────────────────────────────
  // Tessary counts its years from the Drowning: it is the year 1144 of the Drowning. Four hundred years of mud-huts on
  // the ridge before anyone dared build a wall on the old one; the Oath Stone hauled up out of the basin in the 942nd
  // year; and forty years ago the Salt War, against the fen-reeves of Carrabay, for which the city raised its First
  // Muster and promised it land on the south bank of the Ossel. It gave the First Muster a plaque, and the right to
  // rake the pans in perpetuity. Factor Sault's father raked salt.

  Observe tidewall_datestone at tidewall when not visitedBefore(tidewall) "Where the city's courses begin on the Aenean ones, the parapet is painted with a ladder of white bars, each with a year of the Drowning beside it: the Grey Water of 711, the Long Spring of 902, the Salt Flood of 1104, each bar higher than the one before. The fishermen touch the top bar for luck going out. Below the lowest, where the old city's stone begins, there is a bar in another paint, very faded, older than all of them, with no year.".
  Observe tidewall_stars at tidewall when dark() "Lanterns along the parapet, and fishermen under them, talking low. One of them says, not to you, that the stars past the bar were wrong again last night, the whole sky of them, close as lamps. The man next to him tells him to shut his mouth and mind his line.".
  Observe terraces_plaque at terraces when not visitedBefore(terraces) "By the Council House steps a bronze plaque, green with salt, is set into the wall at knee height, where nobody reads it: TO THE FIRST MUSTER OF THE SALT WAR, WHO KEPT THE CITY. THE CITY WILL NEVER FORGET. IN THE 1104th YEAR OF THE DROWNING.".
  Observe terraces_plaque_again at terraces when visitedBefore(terraces) and knows(party, first_muster) "The First Muster's plaque by the Council House steps, at knee height, green with salt.".
  Observe pans_rakers at pans when not dark() "The rakers are old, most of them, and stoop the same way. One has a soldier's cap badge pinned to his hat, so green you can hardly see the crossed keys on it: the badge of a regiment nobody under fifty remembers.".
  Discovery first_muster "Forty years ago, for the Salt War against the fen-reeves of Carrabay, Tessary raised a First Muster and promised it land on the south bank of the Ossel. It gave the First Muster a bronze plaque and the right to rake the city's salt-pans in perpetuity. Factor Sault's father was one of them." {
    Known by sault, tolley.
  }
  Topic tolley_first with tolley "Ask Brother Ancel about the old rakers on the Pans" when true once {
    Says "'The First Muster,' says Ancel. 'What is left of it. The Salt War, forty years back. They were promised land on the south bank, and the Board voted them a plaque instead, and the rakes, and called it generous.' He looks up at the hanging weights. 'Half the brass up there is theirs. Their wives hung them. Factor Sault's mother hung one, I'm told, the year Imma was born. It is still there. Nobody has ever taken it down, because nobody has ever been able to say it was kept.'".
    On discuss { Assert knows(actor, first_muster). }
  }

  // The saint's sayings: the oldest thing in the chapel, and the first word anyone in Tessary spoke of a default.
  Discovery evenhand_saying "Saint Evenhand used to say that the sea did not drown the old city: a promise did. Asked whose, he wept, which is the only time his book says he wept." {
    Known by tolley.
  }
  Topic tolley_saying with tolley "Ask Brother Ancel what the saint said about the Drowning" when knows(actor, evenhand_tale) once {
    Says "Ancel takes a small book from the altar, so old the boards have gone soft as cloth. 'His sayings,' he says. 'Taken down by the first brothers. Most of them are about weights and measures.' He turns to a page he does not have to look for. 'Not the sea. A promise drowned the old city.' He closes the book. 'They asked him whose promise, and he wept. It is the only time the book says he wept. Seven hundred years of brothers have argued about what he meant. I think he meant exactly what he said. He could not do otherwise.'".
    On discuss { Assert knows(actor, evenhand_saying). }
  }
  // The worn letters on the Watersteps, which are the beginning of the formula on the Hall's wall.
  Discovery steps_letters "The worn letters on the Watersteps are Aenean: WHO COMES TO THE LEDGER, and the rest worn away. The Steps were an instrument of the Balance once, like the Oath Stone, and a little of them still is: what is sworn on them is held.".
  Topic tally_steps with tally "Ask the Valuer what the letters on the Steps say" when at(tally, tideline_steps) or travelsWith(tally, actor) and at(actor, tideline_steps) once {
    Says "The Valuer does not need to bend. 'Who comes to the ledger,' they say. 'The rest is worn away by feet. These steps were an instrument once, as the Stone in your Yard was. They are a very old one, and very tired, but they still hold a little.' They look down at the water. 'It is why the called come this way. The calling goes by the old roads. And it is why, when a ferryman swears on these steps that he will not drink, we write it down.'".
    On discuss { Assert knows(actor, steps_letters). }
  }

  // ── The city under the city ───────────────────────────────────────────────────────────────────────────────────────
  // New Tessary was built on the old one's plan, street over street, because the old walls were the only stone on the
  // ridge to build on. From Lowtide, looking up, you see it.
  Observe forum_under at forum when lowWater() and not dark() and not visitedBefore(forum) "You know this square. It takes a moment to see why: it is the Landgate's square, its three corners, its slope, exactly, laid out down here in stone eleven hundred years older, with the sky where the bill-board should be. Up over the Tidewall's edge you can see the Landgate's own roofs, standing where these roofs stood.".
  Observe forum_pool at forum when lowWater() and not dark() "In the fountain's broken basin a sheet of standing water holds the sky, and in it, upside down and perfectly still, the Tidewall and the roofs of Tessary. The mudlark children walk round it, never across. The city in the pool, they say, has people of its own, who walk with their feet on the sky and keep every promise they make, and want you to come down and live with them.".
  Observe scales_under at scales_street when not visitedBefore(scales_street) "It runs where Scriveners' Row runs above, and bends where the Row bends, by the width of a cart. Scales here, on every counter; seals there, on every desk.".
  Observe court_hollow at oath_court when not benighted(party) "In the end wall, at the height of a man, there is a hollow cut into the black stone: square-edged and clean, a slab's breadth and a man's height and a hand deep, the shape of something that was cut out of this wall and taken away. You have seen that shape. It stands on a plinth in the Legion Yard, directly over your head, with eleven thousand handprints worn into it.".
  Topic pounce_copies with pounce "Ask Pounce why every contract in Tessary is drawn twice" when true once {
    Says "'Two parties, two copies,' says Pounce. 'One each. Every child knows that.' He sands a line. 'The old people said the ledger under the sea keeps a third, which is why a Tessarine will swear on his mother's grave and then look at the floor.' He sets the pen down. 'This whole city is a second copy, you know. Drawn on the old one, street for street. The original is filed under four fathoms of water at the bottom of the basin.' He snorts. 'And we still argue about the boundaries.'".
  }

  // ── The bell of the old city ──────────────────────────────────────────────────────────────────────────────────────
  // The mudlarks have looked for the drowned city's bell for a thousand years. It is not in Lowtide. On storm nights
  // the Withies hear it under the basin. It is on the white floor, with a tag.
  Observe forum_tower at forum when not visitedBefore(forum) "At the Forum's east side stands the stump of a bell-tower, roofless, its bell-frame empty. Every mudlark in Tessary has dug under it at one time or another. There is nothing there.".
  Thing old_bell "the bell of the old city" at far_edge {
    State hanging "On a frame of black timber at the very edge of the floor hangs a bell taller than a man, green with the sea that never touched it, with a tag on its rope the size of a shield: the bell of the Aenean city, pledged by its magistrates as surety for the compact, forfeit in the year of the Drowning.".
    State humming "The old city's bell is still humming on its frame at the edge of the floor.".
    Change ring "Haul on the bell-rope" from hanging to humming.
  }
  Relation bellHeard(place).
  Event bell_rings at far_edge when state(old_bell, humming) "The bell swings, slowly, and speaks: a note so low it is more a pressure than a sound, and it goes out across the white floor and past the edge into the dark where the nine lights hang, and does not come back. Far behind you, through the Door, faintly, you think you hear water move." then {
    Assert bellHeard(ossel). }
  Rule bell_heard_above when bellHeard(ossel) and inTessary() and not spread(bell_news)
    says "They are talking about it in the Withies: the bell under the basin rang last night, with no storm and no wind, and every dog on the boardwalks howled. Wick is unbearable about it." { Assert spread(bell_news). }
  Entity bell_news: fact "the bell under the basin".
  Rule bell_resets when state(old_bell, humming) and not at(party, far_edge) { Assert state(old_bell, hanging). }
}

data/adventures/what-tessary-owes/holdin:
Module tessary "What Tessary Owes" {
  // ── The Holding ───────────────────────────────────────────────────────────────────────────────────────────────────
  // Where pledged things are kept against their promises, and forfeit things for ever: beyond the Balance, a white
  // floor under no sky. Everything here has a tag. (A contribution to Imbar's cosmology for canon review: the Kept's
  // tradition, not a narrator's fact. See doc/adventures/what-tessary-owes/03-revised-design.md.)
  Place holding_plane "the Holding" is plane.
  Place white_floor "the white floor" is region within holding_plane.
  Place holding "the Holding" is site within white_floor at 0, 0.
  Place threshold "the threshold of the Holding" is room within holding at 0, 0 outdoors.
  Place sheaves "the field of sheaves" is room within holding at 1, 0 outdoors.
  Place folded_lake "the folded lake" is room within holding at 2, 0 outdoors.
  Place notary_desk "the Notary's desk" is room within holding at 0, 1 outdoors.
  Place tags "the avenue of tags" is room within holding at 1, 1 outdoors.
  Place ranks "the Ranks" is room within holding at 1, 2 outdoors.
  Place far_edge "the far edge" is room within holding at 2, 2 outdoors.

  // The Door stands open on the night of the Settlement; at other times only to the Valuer and whoever goes with
  // them, or to whomever the Comptroller admits.
  Relation holdingAdmits(group).
  Query doorOpen() means feastEve() and hour(clock) >= 18 or night(ossel) >= 15 or travelsWith(tally, party) or holdingAdmits(party).
  Passage holding_door "the Door of the Holding" is passage between weighing_chamber and threshold
    opening when doorOpen() "The Door of the Holding stands at the end of the nave with the white floor showing through it, and when you walk toward it you do not come any nearer.".
  Passage floor_n "the white floor" is passage between threshold and sheaves taking 10 minutes.
  Passage floor_lake "the white floor" is passage between sheaves and folded_lake taking 10 minutes.
  Passage floor_desk "the white floor" is passage between threshold and notary_desk taking 10 minutes.
  Passage floor_tags "the white floor" is passage between notary_desk and tags taking 10 minutes.
  Passage floor_sheaves_tags "the white floor" is passage between sheaves and tags taking 10 minutes.
  Passage floor_ranks "the white floor" is passage between tags and ranks taking 10 minutes.
  Passage floor_edge "the white floor" is passage between ranks and far_edge taking 30 minutes.
  Passage floor_lake_edge "the white floor" is passage between folded_lake and far_edge taking 30 minutes.

  Observe threshold_scene at threshold when true "You step through and there is no sky. There is a floor, white, faintly ruled, going on in every direction until it is too far to see, and there is a light that comes from nowhere and casts no shadows. Behind you the Door stands on its own, with the nave of the Weighing Chamber dim inside it like a room seen through a window at night. Ahead, in rows that go on past seeing, things stand on the floor with tags tied to them.".
  Observe sheaves_scene at sheaves when true "A field of sheaves, standing in stooks on the white floor, gold and dry and smelling of August: a harvest, a whole country's harvest, acres of it. The tag on the nearest stook is old leather, and the writing on it says, in a script like the Scruples', a king's word that his people would not starve, given in a year of famine, and broken.".
  Observe lake_scene at folded_lake when true "A lake, folded. That is the only way to say it: a lake has been folded like linen, in squares, and laid on the floor in a stack higher than a house, and you can see through the folds the reeds and the fish and a little boat, very small and perfectly still, caught between two layers of water. Its tag is the size of a door.".
  Observe tags_scene at tags when true "An avenue of tags with nothing tied to them: little white tags on cords, hanging from a rail at the height of your eyes, thousands of them, stirring though there is no wind. Each has a name on it in the ruled script. These are the names of the Scruples, pledged at their births. Some are very old. Some are new, and the ink still wet.".
  Observe ranks_scene at ranks when true "The Ranks. Soldiers of the Long Muster, standing in files on the white floor as if on parade, barefoot, in their shirts, their eyes closed, their hands at their sides. They are breathing, very slowly, all together. There are a hundred and fifty of them, and more; there are faces you have seen on the boardwalks of the Withies, and faces you have seen only on the Valuer's pages. Nobody has tied tags to them. Their tags are in the Weighing Chamber, in the pan.".
  Observe desk_scene at notary_desk when true "A white desk stands on the white floor with nothing round it for a long way in any direction: a clerk's desk, sloped, with an inkwell, and a rail behind it hung with keys that have no doors. There is no chair. Whoever works here does not sit.".
  Observe durrance_held near durrance when heldNow(durrance) and at(durrance, ranks) and asleep(durrance) "At the end of the Third Company's file, a little apart, as a sergeant stands, Thomasin Durrance is asleep on her feet, barefoot, with her chin up as if on parade.".
  Observe davy_held near davy when heldNow(davy) and asleep(davy) "In the Third Company's file, between a big man with a burned hand and a boy who cannot be more than seventeen, Davy Teazle is asleep in his shirt. His feet are bare and very white. He looks cold.".
  Observe edge_scene at far_edge when true "The floor ends. It does not drop away; it stops, and beyond it is dark that is not night, and in the dark, very far off, there are nine points of black light, arranged in no shape you know, perfectly still. They do not twinkle. The cold comes off them the way cold comes off a cellar door, and it smells of iron. You find you have counted them three times.".
  Observe ranks_count at ranks when held(ossel) > 150 "The files are longer than they were. New faces at the ends of them, in their shirts, with their eyes closed.".

  // The Notary: the Balance's own clerk, who keeps the Holding and sits with the Assembly at a Settlement.
  Person notary "the Notary" at notary_desk {
    Role "a figure at a white desk, made of fine ruled lines of light, as a drawing of a clerk is made of lines". Ancestry human. Peaceable. Pronouns it. Manner stoic.
    Greets "The figure at the desk looks up. It has no face, only the lines where a face would be drawn, very close together, and when it speaks the lines move. 'Weighed,' it says, in a voice like a page turning. 'Come in. Everything here is accounted for.'".
  }
  Topic notary_place with notary "Ask the Notary what this place is" when true once {
    Says "'The Holding,' says the Notary. 'Where what is pledged is kept against the promise it was pledged for, until the promise is kept or released, and where what is forfeit is kept for ever.' Its lines move. 'A harvest. A lake. A singer's voice, in a jar, over there; she pledged it against her lover's return, and he came home, and she has never come for it. I do not know why. People are not always in a hurry for what is theirs.'".
  }
  Topic notary_lights with notary "Ask the Notary about the nine black lights at the far edge" when true once {
    Says "The Notary is quiet for a long time. 'Security,' it says at last. 'For the oldest promise this floor holds. The Scruples call it the Fastening; your priests have other words. The nine jewels your songs remember are the tallies of it, and what they tally is held there.' Its lines grow very close together. 'I do not discuss the terms. I will say that they are being kept. I will say that at one place in Imbar the ledger is uneven, and the fastening there is slack, and it is the place you came from.'".
  }
  Topic notary_redeem with notary "Ask the Notary how the called may be redeemed" when true once {
    Says "'Three ways,' says the Notary. 'The debt is paid, and all that was pledged for it goes home. The debt is released, by the one it is owed to, and all goes home. Or a single thing is redeemed by another pledge of its weight, laid on this desk.' It turns a page that is not there. 'A soldier's oath weighs about what a person's name weighs, and everything they carry of worth. I make that observation to everyone who asks. Very few people ask twice.'".
    On discuss { Assert knows(actor, redeem_by_pledge). }
  }
  Discovery redeem_by_pledge "In the Holding a single held thing may be redeemed by laying another pledge of its weight on the Notary's desk: a soldier's oath weighs about what a person's name weighs, and everything they carry of worth.".
  Topic notary_comptroller with notary "Ask the Notary about the Comptroller's default" when knows(actor, note_designed) once {
    Says "'Entered in his hand eleven hundred years ago,' says the Notary. 'An honest entry.' The lines of its face do not move at all. 'The note he drew for your city was not honest. I hold what I am given. I do not choose what I am given. If the Assembly sits at the Settlement and finds the note drawn to be broken, I will hold that too.' A pause. 'He has been very unhappy. I make that observation as well.'".
  }
  // A goose, pledged in a wager three hundred years ago and forfeit, who has views.
  Person old_goose "a goose" at sheaves {
    Role "a grey goose with a tag round its neck, three hundred years forfeit". Species goose_kind. Peaceable. Pronouns she.
  }
  Observe old_goose_scene near old_goose when at(old_goose, sheaves) "Among the sheaves a grey goose is eating a king's harvest, one grain at a time, with the air of someone who has been doing it for a very long while and intends to go on. The tag round her neck says she was wagered on a horse-race in the Ossel country three hundred and four years ago, by a miller, who lost. When she sees you she hisses, on principle.".
  Topic notary_goose with notary "Ask the Notary about the goose" when true once {
    Says "'Forfeit,' says the Notary. 'A miller wagered her on a horse and the horse lost. She is the property of the Balance. She has eaten approximately a third of the harvest of Old Ennelmark.' Its lines move in a way that might be a sigh. 'Nothing forfeit to the Holding ages. Nothing in the Holding can be made to leave it. I have tried.'".
  }

  // ── The called ──────────────────────────────────────────────────────────────────────────────────────────────────────
  Person held_files "the called of the Long Muster" at ranks {
    Role "soldiers asleep on their feet, in files". Ancestry human. Numbers 1. Peaceable. Pronouns they.
  }
  Initially Assert asleep(held_files).
  Person davy "Davy Teazle" at ranks {
    Role "a private of the Long Muster, nineteen, the youngest of the Third". Ancestry human. Calling warrior. Level 1. Peaceable. Pronouns he. Manner stoic.
    Greets "Davy Teazle looks at you as if you might be someone he dreamed.".
  }
  Initially Assert asleep(davy). Initially Assert heldNow(davy).
  Relation davyWoke(place).
  Action wake_davy(actor: group, site: place) "Lay Davy's coat over his shoulders" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(davy, site) and carries(actor, davy_coat)
      and heldNow(davy) and not davyWoke(ossel).
    On success { Assert davyWoke(ossel). Retract asleep(davy). }
    Result "You put the red coat round his shoulders, the darned elbow and all, and he shivers once, the whole length of him, and opens his eyes. 'Mam?' he says. Then he sees you, and the white floor, and the files of sleepers going away on either side of him, and his face does the thing a face does when a dream turns out not to be one. 'I put my boots together,' he says. 'Didn't I? She'll never believe it.'".
  }
  Topic davy_talk with davy "Ask Davy what it is like here" when davyWoke(ossel) and heldNow(davy) once {
    Says "'Like standing guard,' says Davy. 'Only nobody comes to relieve you.' He pulls the coat round himself. 'I can't move my feet. I've tried. I can hear the others breathing. Sometimes somebody talks in his sleep, the Lucey twins mostly, they always did.' He looks at you. 'Are we coming home? Tell me straight. The army never told anyone anything straight.'".
  }
  Rule davy_sleeps_again when davyWoke(ossel) and heldNow(davy) and not at(party, ranks) { Assert asleep(davy). }
  Rule davy_wakes_again when davyWoke(ossel) and heldNow(davy) and at(party, ranks) and asleep(davy) { Retract asleep(davy). }

  // Durrance, if she was taken: her own oath, said to her to its last words, wakes her.
  Relation durranceWoke(place).
  Action wake_durrance(actor: group, site: place) "Say the Muster's oath to Durrance, to the very end: 'until it release me'" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(durrance, site) and heldNow(durrance)
      and knows(actor, oath_words) and not durranceWoke(ossel).
    On success { Assert durranceWoke(ossel). Retract asleep(durrance). }
    Result "You say it into her face, the way she said it to you in the Drum: I swear to keep the city of Tessary, its walls and its people, while I live or until it release me. At release her eyes open. She looks at you for a long moment without knowing you, and then knowing you. 'Until it release me,' she says. 'Nobody ever listens to that part.' She tries to move her feet, and cannot. 'Well,' she says. 'Here I am, then. Where's the one doing the calling? I said I'd like to look at them.'".
  }
  Rule durrance_sleeps_again when durranceWoke(ossel) and heldNow(durrance) and not at(party, ranks) { Assert asleep(durrance). }
  Rule durrance_wakes_again when durranceWoke(ossel) and heldNow(durrance) and at(party, ranks) and asleep(durrance) { Retract asleep(durrance). }

  // The deeds of the called, put into their hands before the Settlement: the city's promise, kept to every soldier.
  Action deliver_deeds(actor: group, site: place) "Go down the files putting a sealed deed into every hand" {
    Description "A hundred and sixty-odd deeds, name by name. It will take a while.".
    Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ranks) and carries(actor, held_deeds)
      and not deedsDelivered(ossel) and not matured(ossel).
    On success { Assert deedsDelivered(ossel). }
    Result "You go down the files with the casket open, reading the names off the deeds, finding the faces. Pargeter. Haskett. Moll Bryer. The Lucey twins, side by side. Teazle, D. Every hand takes the paper as you put it there, the way a sleeping hand will close on whatever is put in it, and holds it. When you come to the end of the last file the casket is empty, and all down the Ranks, very faintly, there is a sound like a great many people breathing out.".
  }

  // ── The pledge ────────────────────────────────────────────────────────────────────────────────────────────────────
  // One pledge to a person, for there is one name to a person: laid on the Notary's desk, it redeems one held thing.
  Relation pledgedSelf(group). Relation redeemedBy(group, group). Relation tallyFreed(place). Relation tallyNameFound(group).
  Observe tally_tag at tags when knows(party, tally_name_known) and not tallyFreed(ossel) "In the ninth row, near the end, a tag hangs whose ink is twenty-nine years old. You know it is the Valuer's before you read it. It is a short name. It would sound strange in Tessary, and then, after a while, it would not.".
  Discovery tally_name_known "The Valuer's name hangs in the avenue of tags in the Holding, pledged at their birth.".
  Topic tally_name with tally "Ask the Valuer what their name is" when tallySawDefaults(ossel) and not knows(actor, tally_name_known) once {
    Says "The Valuer looks at you for a long time. 'It is held,' they say. 'In the ninth row of the avenue of tags. I have never seen it. One is not shown one's name.' A pause. 'I find, since the Room of Defaults, that I would like to know what it is. I note that. I do not know what to do with it.'".
    On discuss { Assert knows(actor, tally_name_known). }
  }
  Action pledge_for_davy(actor: group, site: place) "Lay your name and everything you carry of worth on the Notary's desk, to redeem Davy Teazle" {
    Speaker notary. Time 1 minute.
    Grave "A name pledged to the Holding is held. It is not given back.".
    Requires able(actor) and company(actor) and at(actor, site) and at(notary, site) and knows(actor, redeem_by_pledge)
      and heldNow(davy) and not pledgedSelf(actor) and not discharged(ossel).
    On success { Assert pledgedSelf(actor). Assert redeemedBy(davy, actor). Set quantity(actor, gold) to 0. Assert registered(actor). }
    Result "You say your name, the whole of it, and the Notary writes it on a tag, and ties the tag to the rail with the others, and it hangs there stirring. 'Held,' it says. 'Teazle, D., redeemed.' Your purse is empty; you did not see it go. When you try to think of your own name it is there, still, but at a distance, like a word in a language you used to speak. 'You will be called something,' says the Notary. 'People always are.'".
  }
  Action pledge_for_durrance(actor: group, site: place) "Lay your name and everything you carry of worth on the Notary's desk, to redeem Thomasin Durrance" {
    Speaker notary. Time 1 minute.
    Grave "A name pledged to the Holding is held. It is not given back.".
    Requires able(actor) and company(actor) and at(actor, site) and at(notary, site) and knows(actor, redeem_by_pledge)
      and heldNow(durrance) and not pledgedSelf(actor) and not discharged(ossel).
    On success { Assert pledgedSelf(actor). Assert redeemedBy(durrance, actor). Set quantity(actor, gold) to 0. Assert registered(actor). }
    Result "You say your name, the whole of it, and the Notary writes it on a tag and ties it to the rail. 'Held,' it says. 'Durrance, A., redeemed.' Your purse is empty. Your own name, when you reach for it, is there, but at a distance, like the name of a town you passed through once.".
  }
  Action pledge_for_tally(actor: group, site: place) "Lay your name and everything you carry of worth on the Notary's desk, to redeem the Valuer's name" {
    Speaker notary. Time 1 minute.
    Grave "A name pledged to the Holding is held. It is not given back. The Valuer's, redeemed, is theirs.".
    Requires able(actor) and company(actor) and at(actor, site) and at(notary, site) and knows(actor, redeem_by_pledge)
      and knows(actor, tally_name_known) and not tallyFreed(ossel) and not pledgedSelf(actor) and not tallyUnravelled(ossel).
    On success { Assert pledgedSelf(actor). Assert tallyFreed(ossel). Set quantity(actor, gold) to 0. Assert registered(actor). }
    Result "The Notary goes down the avenue of tags without seeming to walk, and comes back with one small white tag in the lines of its hand, and lays it on the desk, and ties yours in its place. 'A Scruple's name, redeemed,' it says. 'That has not happened before.' Its lines move. 'They will not be able to lie any more easily than they could. But they will be able to leave.'".
  }
  Relation tallyUnravelled(place).
  Rule redeemed_go_home when redeemedBy(?s, ?c) and heldNow(?s) {
    Retract heldNow(?s). Retract asleep(?s). Assert cameHome(?s). Assert wokeHome(?s). }
  Relation wokeHome(group).
  Rule davy_home when wokeHome(davy) and at(davy, ranks) { Retract at(davy, ranks). Assert at(davy, teazle_room). }
  Rule durrance_home when wokeHome(durrance) and at(durrance, ranks) { Retract at(durrance, ranks). Assert at(durrance, drum_taproom). }
  Rule comptroller_redeems when redeemedByComptroller(davy) and heldNow(davy) and lowWater() and dark() {
    Retract heldNow(davy). Retract asleep(davy). Assert cameHome(davy). Assert wokeHome(davy). }
  Rule davy_back_told when wokeHome(davy) and not knows(party, davy_back) and inTessary()
    says "Word runs along the Withies faster than the tide: Davy Teazle woke up on the Watersteps in his shirt with his boots beside him, and walked home, and put his boots on the mat inside his mother's door, side by side." teaches davy_back { }
  Discovery davy_back "Davy Teazle has come home to the Withies.".
  Event nan_pays near nan when knows(party, davy_back) and nanOffer(party) and not nanPaid(party) "Nan Teazle puts a tin in your hands without a word. Nine coin in it. Davy is asleep in the cupboard bed behind her, in his coat, with his boots on." then {
    Increase quantity(party, gold) by 9. Assert nanPaid(party). }
  Event nan_pays_knowing near nan when toldNan(party) and nanOffer(party) and heldNow(davy) "Before you go, Nan Teazle puts a tin in your hands. 'Nine coin,' she says. 'You told me where he is. That was the bargain.'" then {
    Increase quantity(party, gold) by 9. Assert nanPaid(party). }
  Relation nanPaid(group).
}

data/adventures/what-tessary-owes/lowtid:
Module tessary "What Tessary Owes" {
  // ── Lowtide ───────────────────────────────────────────────────────────────────────────────────────────────────────
  // Eleven hundred years ago the sea came over the Aenean city in a night and kept it. Its streets lie in the outer
  // basin under four fathoms at high water; at low water they drain through the Swatch and stand out for a few hours,
  // weeded, wet, picked over by mudlarks, used by smugglers, and haunted. The Hall of Oaths, the old city's court, is
  // at the bottom of the basin, and the wall at the back of it is the way down to the Strongrooms.
  Place throat_foot "the foot of the Swatch Stair" is room within lowtide at 0, 0 outdoors.
  Place colonnade "the Weed Colonnade" is room within lowtide at 1, 0 outdoors.
  Place forum "the Drowned Forum" is room within lowtide at 1, 1 outdoors.
  Place scales_street "the Street of Scales" is room within lowtide at 2, 1 outdoors.
  Place aqueduct_foot "the foot of the Aqueduct" is room within lowtide at 0, 1 outdoors.
  Place aqueduct_top "the top of the Aqueduct" is room within lowtide at 0, 2 outdoors.
  Place landing "the ebb-runners' landing" is room within lowtide at 3, 1 outdoors.
  Place bath_house "the bath-house" is building within lowtide.
  Place bath_hall "the bath-house hall" is room within bath_house at 2, 2.
  Place plunge "the plunge-room" is room within bath_house at 3, 2.
  Place bath_dome "the top of the bath-house dome" is room within lowtide at 2, 3 outdoors.
  Place oath_house "the Hall of Oaths" is building within lowtide.
  Place oath_court "the Hall of Oaths" is room within oath_house at 1, 2.

  Passage throat_stair "the Swatch Stair" is steps between throat_head and throat_foot
    opening when lowWater() "The Swatch Stair goes down into green water and does not come up. The basin is full.".
  Passage colonnade_way "the colonnade" is arch between throat_foot and colonnade.
  Passage forum_steps "the forum steps" is steps between colonnade and forum.
  Passage scales_way "the Street of Scales" is path between forum and scales_street taking 5 minutes.
  Passage aqueduct_way "the lane to the aqueduct" is path between forum and aqueduct_foot taking 5 minutes.
  Passage pier "the broken pier" is passage between aqueduct_foot and aqueduct_top needing climbing or rope
    opening when lowWater() "The broken pier stands up out of the sea. The water is over everything below it.".
  Passage landing_way "the quay steps" is steps between scales_street and landing.
  Passage bath_door "the bath-house door" is doorway between scales_street and bath_hall.
  Passage plunge_arch "the plunge-room arch" is arch between bath_hall and plunge.
  Passage dome_stair "the dome stair" is passage between bath_hall and bath_dome
    opening when lowWater() "The dome stair goes down into black water.".
  Passage hall_steps "the Hall steps" is steps between forum and oath_court.
  Passage runners_tunnel "the ebb-runners' tunnel" is tunnel between landing and cistern taking 20 minutes.
  Initially Assert unlit(plunge). Initially Assert unlit(oath_court).

  // What floods, and what does not: the landing is a raised quay at the tunnel's mouth; the aqueduct and the dome
  // stand above the highest water.
  Relation floods(place).
  Initially Assert floods(throat_foot). Initially Assert floods(colonnade). Initially Assert floods(forum).
  Initially Assert floods(scales_street). Initially Assert floods(aqueduct_foot). Initially Assert floods(bath_hall).
  Initially Assert floods(plunge). Initially Assert floods(oath_court).
  Relation lowtideRoom(place).
  Initially Assert lowtideRoom(throat_foot). Initially Assert lowtideRoom(colonnade). Initially Assert lowtideRoom(forum).
  Initially Assert lowtideRoom(scales_street). Initially Assert lowtideRoom(aqueduct_foot). Initially Assert lowtideRoom(aqueduct_top).
  Initially Assert lowtideRoom(landing). Initially Assert lowtideRoom(bath_hall). Initially Assert lowtideRoom(plunge).
  Initially Assert lowtideRoom(bath_dome). Initially Assert lowtideRoom(oath_court).

  // ── The water ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe water_low near party when at(party, ?p) and floods(?p) and lowWater() and not turning() "Water stands in the low places and runs in the gutters, going out. Somewhere far off, toward the Swatch, the sea is a long way away.".
  Observe water_turning near party when at(party, ?p) and floods(?p) and turning() "The water in the gutters has stopped running out. Now it is running back. A wet line is creeping up the steps of the nearest house, and from the direction of the Swatch comes a sound like a mill-race opening.".
  Observe table_says near party when at(party, ?p) and floods(?p) and turning() and carries(party, ?t) and itemKind(?t, tide_table) "By Wick's table the basin fills on the hour. The drawing of the wave with teeth is underlined twice.".
  Observe refuge_high near party when at(party, ?p) and lowtideRoom(?p) and not floods(?p) and not lowWater() "The sea is in. Green water lies over Lowtide from the Tidewall to the outer bar, with the tops of colonnades standing up out of it, and gulls on them. You are above it, and will be until the ebb.".
  Hazard drowning "Rolled through the Swatch by the flood" means "Deal (2d4) physical damage to ally unless constitution save against (12).".
  Rule swept when at(party, ?p) and floods(?p) and not lowWater()
    says "The flood comes back through the Swatch all at once, a brown wall of it shouldering down the streets. It takes your feet. It takes everything. You are rolled, and dragged, and something hits you, and there is no up; and then there is, and air, and you are being carried out along the pan-dykes with the weed and the timber, and you crawl out at last onto the salt crust east of the city and lie there, coughing up the sea. Your purse is lighter." {
    Retract at(party, ?p). Assert at(party, pans). Assert strikes(drowning, party). Decrease quantity(party, gold) by 3. Assert sweptOnce(party). }
  Relation sweptOnce(group).

  // ── The places ────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe throat_foot_scene at throat_foot when not visitedBefore(throat_foot) "The stair comes down the face of the Tidewall into a gully of wet stone and kelp. The noise of the Swatch fills the gully: the basin draining past you through the one deep channel, brown and quick. Ahead, through a gap in the old sea-wall, a street begins.".
  Observe throat_foot_scene_again at throat_foot when visitedBefore(throat_foot) "The foot of the Swatch Stair, loud with the channel.".
  Observe colonnade_scene at colonnade when not visitedBefore(colonnade) "A street of columns, their tops lost, their shafts furred with weed that lies flat in the direction the water went. Between the columns, doorways, full of sand to the lintel. Anemones the colour of raw meat have opened in the wet, and close if you go near.".
  Observe colonnade_scene_again at colonnade when visitedBefore(colonnade) "The Weed Colonnade, its columns furred with weed, anemones in the doorways.".
  Observe forum_scene at forum when not visitedBefore(forum) "The old city's market square, a hundred paces across, paved in great slabs, most of them still there. The fountain in the middle is a heap of stone with a crab on it. On every side the fronts of buildings stand roofless, their windows full of sky. At the south end, broad steps go down to a building with no windows at all.".
  Observe forum_scene_again at forum when visitedBefore(forum) "The Drowned Forum, wide and wet, with the windowless Hall at the bottom of its south steps.".
  Observe forum_larks at forum when lowWater() and not dark() "Mudlarks are working the square with buckets and rakes, children mostly, and a few old men who have been children here for sixty years. They lift their heads to look at you, and go back to work.".
  Observe forum_dark at forum when dark() "In the dark the square is a pale floor, and the buildings round it are holes. Things move in the wet places. There is no sound but the Swatch.".
  Observe scales_scene at scales_street when not visitedBefore(scales_street) "A street of shops, by the look of it: every doorway has a stone counter, and every counter a pair of carved scales. Eleven hundred years have not worn the scales off. At the far end, a quay stands up out of the sand, higher than the street, with steps.".
  Observe scales_scene_again at scales_street when visitedBefore(scales_street) "The Street of Scales, a pair of carved scales on every counter, and the quay at the far end.".
  Observe aqueduct_foot_scene at aqueduct_foot when true "The aqueduct comes in over the basin on three arches from somewhere that is now open sea, and stops in mid-air above a heap of its own fallen stones. One pier still stands to the top. Its stones are stepped and broken; there is a rusted ring set in it, high up, where somebody has knotted rope before.".
  Observe aqueduct_top_scene at aqueduct_top when true "The water-channel along the aqueduct's top is a yard wide and dry, and you can lie in it out of the wind. From here the whole of Lowtide is laid out like a plan: the colonnade, the forum, the dome of the bath-house, the windowless Hall at the bottom of everything, and beyond it all the outer bar, and the sea.".
  Observe bath_hall_scene at bath_hall when true "A hall of benches round a dry basin, under a dome that has kept its roof. Light comes down through the hole at the top of the dome in a white post. Against one wall, a stair winds up inside the dome's thickness. On the other side an arch opens on darkness, and the air that comes out of it is cold and smells of nothing at all.".
  Observe plunge_scene at plunge when true "The plunge-room: a deep square pool, dry, its floor a bed of silt. Round its edge, against the walls, things are standing that look at first like coats hung on pegs, and then do not.".
  Observe dome_scene at bath_dome when true "The dome's top is a broad shallow cap of stone with the light-hole in the middle of it, crusted with gull-lime. It stands above the highest water. People have sat out tides here before: there are names scratched in the stone, and a tally of days.".
  Observe court_scene at oath_court when true "The Hall of Oaths has no windows. It is a long room of black stone, the same black as the Oath Stone in the Legion Yard, dry, except for the sea's tidemark half way up the walls, as if the water had come in and thought better of it. The walls are carved from floor to tidemark with ruled lines, ledger on ledger, and on the end wall, where a judge's seat would be, there is no seat, only an inscription in Aenean letters a foot high, and under it a plain black wall.".

  // ── The ebb-runners ───────────────────────────────────────────────────────────────────────────────────────────────
  // Factor Sault's people in Lowtide. They work the old city for bronze and dressed stone, run untaxed salt through the
  // cistern, and for ten years carried the city's interest silver down to the Hall of Oaths. They take prisoners:
  // whoever they beat wakes on the Pans.
  Person slake "Bettany Slake" at landing {
    Role "who runs the ebb-runners, in a fisherman's smock with a cutlass through the belt". Ancestry human. Calling thief. Level 3. Pronouns she. Manner acerbic.
    Temperament territorial.
    Warns "A woman in a smock stands up off a crate with a cutlass in her hand and puts her other hand up, palm out. 'That's far enough,' she says. 'This is a working quay. Five coin for the use of it, or back up the street the way you came, and don't stand there thinking about it.'".
    Comes "'Right,' says Bettany Slake, almost sorry, and the ebb-runners come off the crates.".
    Pleads "Bettany Slake puts her cutlass down on the stones. 'All right,' she says. 'All right. You've made your point.'".
  }
  Person runners "the ebb-runners" at landing {
    Role "three of Bettany Slake's people, with hooks and short clubs". Ancestry human. Calling warrior. Level 1. Numbers 3. Pronouns they.
    Temperament territorial.
  }
  Initially Assert takesPrisoners(slake). Initially Assert takesPrisoners(runners).
  Initially Assert serves(runners, slake). Initially Assert serves(slake, sault).
  Observe landing_scene at landing when true "A stone quay at the end of the Street of Scales, high enough that the flood laps its top and goes no further. Crates, coils of rope, a brazier, a long boat drawn up on rollers. A low tunnel goes back into the quay wall, toward the city, with lamps on hooks along it. On a post by the tunnel mouth hangs a board scored with notches.".
  Rule runners_captured when captured(slake, party) or captured(runners, party)
    says "You come round on the salt crust east of the city at the edge of a pan, with a headache and an empty feeling at your belt. Someone has carried you up the tunnel and dumped you here. Someone has also been through your purse." {
    Retract captured(slake, party). Retract captured(runners, party). Retract at(party, landing). Assert at(party, pans).
    Decrease quantity(party, gold) by 5. }
  Topic slake_quay with slake "Ask Bettany Slake what the ebb-runners do" when true once {
    Says "'Salvage,' says Bettany. 'Bronze, dressed stone, whatever the sea's been keeping. All above board, in the Factor's name.' She spits over the edge of the quay. 'And what goes up and down that tunnel is the Factor's business and mine, and not a thing a stranger wants to be curious about, if the stranger likes the shape of his head.'".
  }
  Topic slake_silver with slake "Ask Bettany Slake what she carried to the Hall of Oaths" when knows(actor, collateral) or knows(actor, note_terms) once {
    Says "Bettany looks at you a long moment. 'Silver,' she says. 'Every month for ten years. The city's, in the Factor's boats, down the tunnel and across at the ebb and into the Hall, and left in the niche by the wall, and the next ebb it was gone.' She shrugs. 'Then in the summer there wasn't any silver, and we stopped. And at the next spring ebb the first of them walked past us across the Forum with their eyes open.' She looks away. 'I don't carry anything to that Hall any more. Only the Factor's letters.'".
    On discuss { Assert knows(actor, sault_courier). }
  }
  Discovery sault_courier "For ten years the ebb-runners carried the city's interest silver, in Factor Sault's boats, down to the Hall of Oaths. The slate on the post is chalked with a month to a stroke, twelve to a row, ten rows, the oldest rubbed nearly away and chalked over again; across the top someone has painted the crossed rakes of the Salt Moiety and the words HALL. NICHE. BY THE MONTH. The Factor has known the whole arrangement from the beginning." {
    Source runners_board "the chalked slate on the post by the tunnel" at landing readable by party.
  }
  Relation slakeLetsPass(group).
  Action pay_slake(actor: group, site: place) "Pay Bettany Slake five coin for the use of her quay" {
    Speaker slake. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(slake, site) and able(slake)
      and not tolerates(slake, actor) and not hostile(slake, actor) and quantity(actor, gold) >= 5.
    On success { Decrease quantity(actor, gold) by 5. Increase quantity(slake, gold) by 5. Assert tolerates(slake, actor). Assert tolerates(runners, actor). Assert slakeLetsPass(actor). }
    Result "Bettany weighs the coins in her palm, and bites one, and pockets them. 'Quay's yours,' she says. 'Don't touch the crates.'".
  }
  Topic slake_factor with slake "Tell Bettany Slake you work for the Factor" when hiredBySault(actor) and not tolerates(slake, actor) once {
    Says "'Do you,' says Bettany. She looks you up and down. 'She said she'd hired someone to go asking. All right. Mind yourself on the quay.' She sits back down on her crate.".
    On discuss { Assert tolerates(slake, actor). Assert tolerates(runners, actor). Assert slakeLetsPass(actor). }
  }
  Thing runners_box "the ebb-runners' lockbox" at landing {
    Holds.
    State locked closed "An iron-bound lockbox is chained to the boat's thwart.".
    State open "The lockbox stands open.".
    Change pick "Pick the lockbox" from locked to open needing lockwork.
    Change smash "Smash the lockbox open" from locked to open needing brawn.
  }
  Item sault_letter "a letter in the Factor's hand" is letter_kind in runners_box.
  Kind letter_kind "a sealed letter" is gear worth 0 weighing 0
    described "A letter folded small and sealed with salt-white wax, stamped with a pair of crossed rakes.".
  // What is seen taken, by those who keep the quay.
  Rule box_watched when state(runners_box, open) and perceives(slake, party) and able(slake) and not hostile(slake, party) and not slakeGaveLetter(ossel)
    says "'Oi,' says Bettany Slake, and her cutlass comes out." { Assert hostile(slake, party). Assert assails(runners, party). }
  Discovery sault_bid "Factor Sault has written to a broker of the Scruples offering to bid for the War Note at its foreclosure, and to pledge her own house to the Balance as surety: 'The Board will not pay. When the Feast passes, I will take up the note, and with it the Muster, and Tessary will be governed by someone who can count.'".
  Action read_letter(actor: group, site: place) "Break the wax and read the Factor's letter" {
    Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and carries(actor, sault_letter) and not benighted(actor)
      and not knows(actor, sault_bid).
    On success { Assert knows(actor, sault_bid). }
    Result "It is addressed to the Broker of the Fourth Pan, the Strongrooms, by hand of B. Slake. 'Sir. You will have had my earlier. I repeat my offer: when the city's note falls in at the Feast and is offered at foreclosure, I bid for it, and I will pledge House Sault entire as surety, which your Comptroller will find to weigh what it needs to. The Board will not pay; I have seen to that, and if I had not, the treasury would. I will take up the note and with it the Muster. They will be fed and paid and housed. Tessary will be governed by someone who can count. Burn this. I. Sault, Factor.'".
  }

  // Councillor Haverick's goose, taken off the Terraces by the ebb-runners for their Feast.
  Species goose_kind "a goose" like hen tame described "A big white goose with an orange bill and an opinion of everyone.".
  Person plum "Mistress Plum" at landing {
    Role "a large white goose of the old Paper strain, very much offended". Species goose_kind. Peaceable. Pronouns she.
  }
  Observe plum_crate near plum when at(plum, landing) and not plumLoose(ossel) "In a crate by the brazier a big white goose is hissing steadily at the ebb-runners, who are ignoring it. A ribbon round its neck says PLUM in gold thread.".
  Relation plumLoose(place). Measure distractedUntil(place).
  Action release_plum(actor: group, site: place) "Knock the peg out of the goose's crate" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, landing) and at(plum, landing) and not plumLoose(ossel).
    On success { Assert plumLoose(ossel). Assert acceptsEscort(plum, actor). Assert unseen(actor, slake). Assert unseen(actor, runners).
      Assert tolerates(slake, actor). Assert tolerates(runners, actor). Retract assails(slake, actor). Retract assails(runners, actor).
      Set distractedUntil(ossel) to watch(clock) + 3. }
    Result "The peg comes out and the crate door falls open and Mistress Plum comes out of it like a cannonball, wings out, neck out, screaming, and goes straight for the nearest ebb-runner's ankles. In a moment the whole quay is chasing a goose round the brazier and the goose is winning. Nobody is looking at you at all.".
  }
  Rule distraction_ends when plumLoose(ossel) and watch(clock) >= distractedUntil(ossel) and unseen(party, slake) {
    Retract unseen(party, slake). Retract unseen(party, runners). }
  Rule distraction_over when plumLoose(ossel) and watch(clock) >= distractedUntil(ossel) and tolerates(slake, party) and not slakeLetsPass(party) and not hostile(slake, party) {
    Retract tolerates(slake, party). Retract tolerates(runners, party). }
  Observe plum_loose near plum when plumLoose(ossel) and not following(plum, party) and not plumHome(ossel) "Mistress Plum stands on a bollard with her wings half open, daring anyone to try it.".

  // ── The Forsworn ──────────────────────────────────────────────────────────────────────────────────────────────────
  // Aenean oath-breakers whose bindings unravelled when they broke a promise the Balance held. What is left of them
  // stands in the plunge-room and comes to the sound of swearing, and to whoever has broken a promise held below.
  Species forsworn_kind "a Forsworn" like revenant temperament savage
    described "A thing like a person-shaped hollow, wearing the rags of an Aenean robe. Where its face should be there is a darkness with the texture of torn paper.".
  Person forsworn "the Forsworn" at plunge {
    Role "hollow people in the rags of Aenean robes". Species forsworn_kind. Level 3. Numbers 3. Pronouns they.
    Temperament territorial.
    Warns "All round the dry pool the things like coats on pegs turn toward your light, without any sound, and hold out their hands, palm up, as if they wanted to be given something. They do not come any nearer. Not yet.".
    Comes "The coats on the pegs come off the walls. They come round the dry pool toward you without any sound at all, with their hands out, as if they wanted to be given something.".
    Lair plunge.
  }
  // A company that has broken a promise held below is followed through Lowtide by the Forsworn, as the tide turns.
  Relation forswornParty(group).
  Rule forsworn_follow when forswornParty(party) and at(party, ?p) and floods(?p) and turning() and able(forsworn) and not at(forsworn, ?p) and not dark()
    says "Something is standing in the nearest doorway that was not there a moment ago: a coat with nobody in it, turned toward you." {
    Retract at(forsworn, plunge). Assert at(forsworn, ?p). Assert assails(forsworn, party). }

  // ── The Hall of Oaths ─────────────────────────────────────────────────────────────────────────────────────────────
  Discovery compact_read "The inscription in the Hall of Oaths is the drowned city's compact with the keepers of the Balance: 'THE SEA SHALL NOT HAVE THIS CITY WHILE THE LEDGER KEEPS. WHO COMES TO THE LEDGER COMES TO BE WEIGHED.' The sea had the city all the same.".
  Action read_compact(actor: group, site: place) "Puzzle out the Aenean inscription on the end wall" {
    Time 3.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, oath_court) and not benighted(actor)
      and not knows(actor, compact_read) and not travelsWith(tally, actor).
    Resolve check(actor, lore, dc_fair).
    On success { Assert knows(actor, compact_read). }
    Result "Letter by letter, with the ruled walls watching. The Aenean is formal, legal, very old, and plain once you have the first word: THE SEA SHALL NOT HAVE THIS CITY WHILE THE LEDGER KEEPS. And under it, smaller, over the black wall: WHO COMES TO THE LEDGER COMES TO BE WEIGHED. You look up at the tidemark half way up the walls, and think about the sea, and what it had.".
    Otherwise "You can make out a word here and there, CITY and SEA and something that might be LEDGER or might be SCALES, but the sense of it slides away from you in the dark.".
  }
  Observe tally_reads at oath_court when travelsWith(tally, party) and not knows(party, compact_read) and not benighted(party) "The Valuer stops in front of the end wall and reads it aloud, in a flat clear voice, as a clerk reads a clause. 'The sea shall not have this city while the ledger keeps. Who comes to the ledger comes to be weighed.' They are quiet a moment. 'That is the compact of the old city with the Balance. It is a famous text. I have never seen it.' Another pause. 'The sea had the city. I had not thought about that before.'" teaches compact_read.
  // The black wall: open to the Scruples, to the called, and to whoever says the words on it and means them.
  Relation weighedAt(group, place).
  Action say_words(actor: group, site: place) "Put your hand on the black wall and say 'I come to the ledger to be weighed'" {
    Grave "The words are written on a wall that hears them. Below, what you say is held to.".
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, oath_court) and knows(actor, compact_read)
      and not weighedAt(actor, oath_court) and not barredBelow(actor).
    On success { Assert weighedAt(actor, oath_court). Assert registered(actor). }
    Result "The stone is warm under your hand, warm as a sleeping animal. You say the words, and for a moment you feel it: a weighing, as if you were standing in one pan of a scale with something enormous in the other, and the beam lifting, considering. Then the wall under your hand is not there.".
  }
  Relation registered(group).
  Passage black_wall "the black wall" is passage between oath_court and long_stair
    opening when (travelsWith(tally, party) or weighedAt(party, oath_court) or registered(party)) and not barredBelow(party) "A plain wall of black stone, warm to the touch, with no door in it.".
}

data/adventures/what-tessary-owes/people:
Module tessary "What Tessary Owes" {
  // ── What can be known ─────────────────────────────────────────────────────────────────────────────────────────────
  // The facts of the adventure, in the order a company is likely to come by them. Each is a step in what the
  // vanishings turn out to be.
  Discovery notice_read "Nan Teazle of the Withies will give her savings for news of her son, who walked into the sea. The notice is in a careful, laboured hand, pressed hard into cheap paper: 'MY SON PRIVATE DAVY TEAZLE OF THE LONG MUSTER WENT DOWN THE TIDELINE STEPS INTO THE SEA AT THE LAST SPRING EBB. HE SET HIS BOOTS ON THE TOP STEP. WHO CAN TELL ME WHERE HE WENT I WILL GIVE MY SAVINGS. NOT A BODY. WHERE HE WENT. NAN TEAZLE, THE WITHIES, BY THE DRUM.'" {
    Source notice "a notice on the Landgate board" at landgate readable by party.
  }
  Discovery enlist_promise "Eleven years ago, raising the Long Muster, the city of Tessary promised land and a pension to every soldier who came home. It was cried in every square and printed on every bill." {
    Known by nan, durrance, marrable, quire, sault.
  }
  Discovery hall_of_oaths_way "The called walk out across the drained basin to the Hall of Oaths in Lowtide and go in at a wall where there is no door." {
    Known by wick.
  }
  Discovery roll_order "The called go in the order of the Long Muster's roll, Third Company first, a dozen at each spring ebb." {
    Known by durrance, tally.
  }
  Discovery durrance_next "Sergeant Thomasin Durrance is on the next page of the roll. Unless something changes she will be called at the eighth night's spring ebb." {
    Known by durrance, tally.
  }
  Discovery council_knows "Treasurer Quire keeps a list, in his own hand, of every veteran called since the summer, a hundred and thirty-eight names, each with an address in the Withies or the Eel quarter, and against each a column of sums: four marks, four marks, four marks, every month since the summer. Nobody sends money to the mothers of deserters." {
    Source quire_list "a list in the Treasurer's hand, under a paperweight" at exchequer_room readable by party.
  }
  Discovery collateral "The Muster's oaths, sworn on the Oath Stone, were pledged as security on a debt the city owes to the keepers of an engine under the sea. At each spring ebb a dozen are taken as interest." {
    Known by tally, quire, sault, comptroller.
  }
  Discovery note_terms "The War Note: ten years ago, when the war was a year old, Tessary borrowed, from the Scruples who keep the Balance under the sea, the right to call an oath King Amaury's ancestor swore to the Aenean emperors at Aen-Vessaly. The Long Muster's oaths were pledged as collateral; interest was paid in silver each month; the principal falls due at the Feast of Settlement in the twelfth year, and may be paid only in a kept promise of equal weight." {
    Known by tally, quire, sault, comptroller.
  }
  Discovery promise_weight "In the Scruples' reckoning only a promise of a whole people to a whole people weighs as much as the War Note, and Tessary has made one such promise: land and a pension for every soldier who came home. If the city keeps it, the debt is paid." {
    Known by tally, comptroller.
  }
  Discovery held_alive "The called are not dead. They are held in the Holding, beyond the Balance, standing asleep, until their oaths are redeemed." {
    Known by tally, comptroller.
  }
  Discovery kneeling_felt "King Amaury did not kneel at Sedge Ford of his own will. He felt a hand on the back of his neck, he says, nine hundred years old, and his knees went into the river." {
    Known by amaury.
  }
  Discovery kneeling_bought "The Kneeling at Sedge Ford was bought: Tessary called in an oath Amaury's ancestor swore to the Aenean emperors, borrowed from under the sea, and the king's body kept his ancestor's word.".
  Discovery oath_words "The Muster's oath, sworn hand on the Oath Stone: 'I swear to keep the city of Tessary, its walls and its people, while I live or until it release me.'" {
    Known by durrance, marrable, fisk.
  }
  Discovery evenhand_tale "Saint Evenhand, say the brothers of his chapel, was a clerk who came up out of the sea when the old city drowned, with ruled lines on his skin, and lived among the people of the new city weighing their quarrels, and never once told a lie.".

  // What a company that knows two things comes to see for itself.
  Observe kneeling_seen near party when knows(party, kneeling_felt) and knows(party, note_terms) and not knows(party, kneeling_bought) "You put them side by side: the old oath of Amaury's line in the War Note, and the hand Amaury felt on his neck at the ford. The miracle the city keeps a saint's day for was paid for, by the month, in silver and then in soldiers." teaches kneeling_bought.

  // ── The Landgate ──────────────────────────────────────────────────────────────────────────────────────────────────
  Person tolley "Brother Ancel" at chapel {
    Role "the brother who keeps Saint Evenhand's". Ancestry human. Profession priest. Peaceable. Pronouns he. Manner compassionate.
    Offers healing "a dressing, a prayer and a weight hung for you" for 2 coin.
  }
  Topic tolley_weights with tolley "Ask Brother Ancel about the hanging weights" when true once {
    Says "'Promises,' says Brother Ancel, and touches one so that it turns on its cord. 'A man who wants a thing kept hangs its weight here. Brass for a marriage. Lead for a debt. This one, a stone off the beach, a girl hung for her sweetheart in the Muster.' He looks up at them, hundreds, turning. 'Eleven years of war, and the cords are getting thin. The saint holds the scales, you see. He doesn't put his thumb on them.'".
  }
  Topic tolley_saint with tolley "Ask Brother Ancel who Saint Evenhand was" when true once {
    Says "'A clerk of the drowned city,' says Ancel, 'who came up out of the sea the night it went down. That is the old story. He had lines on his skin like a ledger, and he could not tell a lie, and he lived among the first people of Tessary weighing their quarrels for them, and they trusted him because he could not be bought or frightened or flattered. He never went back.' He smiles. 'The scholars say he is a story about a set of scales. I say a set of scales is a story about a man like that.'".
    On discuss { Assert knows(actor, evenhand_tale). }
  }
  Topic tolley_calling with tolley "Ask Brother Ancel about the soldiers walking into the sea" when knows(actor, notice_read) or knows(actor, calling_witnessed) once {
    Says "Ancel's hand finds the nearest weight and holds it still. 'Nan Teazle's boy was the first I buried with no body,' he says. 'I have said the office over eleven pairs of boots since. The Board says they are deserters. A deserter takes his boots.' He lets the weight go. 'Talk to the clerk in grey, if you can make him answer. He was in here yesterday, reading the cords. He said they were all of them accurate.'".
  }

  Person pitch "Lemuel Pitch" at chandlery {
    Role "a ship's chandler". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "Lemuel Pitch looks up from a line he is splicing, and goes on splicing it. 'If it's rope, it's on the left,' he says. 'If it's the tides, everyone asks. Ask.'".
    Sells rations for 2 coin from 8.
    Sells rope for 1 coin from 4.
    Sells torch for 1 coin from 6.
    Sells lantern for 3 coin from 2.
    Sells lamp_oil for 1 coin from 6.
    Sells oilskin for 2 coin from 3.
    Sells bandages for 1 coin from 4.
    Sells chapbook for 1 coin from 2.
  }
  Kind chapbook "a chapbook of ballads" is gear worth 1 weighing 0
    described "Twenty pages of cheap reed-paper, badly printed: 'The Drowned Bell', 'Sally of the Withies', 'The Soldier's Return' and nine more, with a woodcut of a ship on the cover.".
  Kind oilskin "an oilskin" like cloak worth 2 weighing 2
    described "A fisherman's coat of oiled canvas, stiff as a board and smelling of linseed. Water runs off it.".
  Topic pitch_tide with pitch "Ask Lemuel Pitch about the tides" when true once {
    Says "'Twice a day it goes out and twice it comes back, same as anywhere,' says Pitch, 'only here when it goes out it goes out properly. The basin's out from ten in the morning till two, and from ten at night till two, give or take a little: four hours of streets, and then it turns. Then it turns. And when it turns in the basin it doesn't come in, it comes back, all at once through the Swatch like it's been sent for.' He taps the counter. 'Rope. Anyone going down into Lowtide wants rope, and something to stand on.' And then, lower, because it is not the kind of thing a chandler says to strangers: 'And don't take a boat out past the bar at night. Some nights the stars out there are wrong. My father saw it, and I've seen it twice, and I don't care who laughs.'".
  }

  // ── The Withies: Nan and Wick Teazle ──────────────────────────────────────────────────────────────────────────────
  Person nan "Nan Teazle" at teazle_room {
    Role "an eel-wife of the Withies". Ancestry human. Peaceable. Pronouns she. Manner grim.
    Greets "Nan Teazle looks up from the trap she is mending and does not get up.".
  }
  Person wick "Wick Teazle" at withies {
    Role "a mudlark, about ten, with a tray on a string". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Sells tide_table for 1 coin from 3.
    Sells aenean_coin for 1 coin from 9.
  }
  Kind tide_table "a tide-table" is gear worth 1 weighing 0
    described "A square of reed-paper ruled in a child's careful hand: the hours of low water for the fortnight, the turn marked each time with a drawing of a wave with teeth.".
  Kind aenean_coin "a genuine Aenean coin" is treasure worth 0 weighing 0
    described "A disc of greenish metal with a face on it, stamped, rather recently, by someone who had seen an Aenean coin once and liked it.".
  Discovery davy_went "Davy Teazle came home with the Muster, sat on his mother's step for a week without saying much, and at the last spring ebb got up in his sleep, went down the Watersteps barefoot and walked into the sea." {
    Known by nan, wick.
  }
  Topic nan_davy with nan "Ask Nan about Davy" when not cameHome(davy) once {
    Says "'He came home on the Tuesday with the rest of them,' says Nan, 'and he sat on that step out there for a week. Didn't say much. Ate what I put down. Then the spring ebb, the night after the new moon, I wake up and he's going down the ladder in his shirt. I called him. He didn't turn round.' Her needle goes in and out of the net. 'He set his boots on the top step. Side by side. I had to tell him every night of his life to put his boots together and he never once did it, and he set them on the step like a gentleman's valet. They taught him that.' She bites the cord. 'Then he walked into the sea.'".
    On discuss { Assert knows(actor, davy_went). }
  }
  Relation nanOffer(group).
  Topic nan_reward with nan "Ask Nan what she is offering" when not cameHome(davy) and not nanOffer(actor) once {
    Says "'Nine coin,' says Nan. 'It's in a tin. And all the eels you can eat for a twelvemonth, which you'll be sick of in a week.' She looks at you properly for the first time. 'I don't need him back. I'm not a fool. I need to know where he went. If he's down there drowned, I need to know where, so I can say so to the brother at the chapel and have him say the office over something that isn't a pair of boots.'".
    On discuss { Assert nanOffer(actor). }
  }
  Topic nan_bill with nan "Ask Nan about the recruiting bill on her shelf" when true once {
    Says "'LAND AND A PENSION FOR EVERY MAN WHO COMES HOME,' says Nan, without looking at it. 'They cried that in the Withies with a drum. Davy was seventeen. He came home Tuesday with a red coat and a paper that says he's owed eleven years' pay, and the Exchequer has no money to pay it with, and the Board's to hear the question of the land on the thirteenth day. The question.' She snorts. 'They've had eleven years to think of the answer.'".
    On discuss { Assert knows(actor, enlist_promise). }
  }
  Topic nan_alive with nan "Tell Nan that Davy is alive" when knows(actor, held_alive) and knows(actor, davy_went) and not toldNan(actor) once {
    Says "Nan Teazle puts the net down. She sits very still for a long time with her hands in her lap. 'Asleep,' she says at last. 'Standing up. Under the sea.' She gets up and takes Davy's red coat off its peg and holds it, and then holds it out to you. 'If you're going where he is, take him this. He'll be cold. He was always cold.' Her voice does not change at all. 'And tell him to put his boots on.'".
    On discuss { Assert toldNan(actor). }
  }
  Relation toldNan(group).
  Item davy_coat "Davy Teazle's red coat" is soldier_coat at teazle_room hidden until coat_given.
  Kind soldier_coat "a red coat of the Long Muster" like cloak worth 0 weighing 2
    described "A soldier's coat, red gone brown at the shoulders, with the Muster's brass buttons and a darn at the elbow in someone's careful wool.".
  Discovery coat_given "Nan Teazle has given you Davy's coat to take to him.".
  Action take_coat(actor: group, recipient: member, site: place) "Take Davy's coat from Nan" {
    Speaker nan. Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(nan, site) and toldNan(actor)
      and memberOf(recipient, actor) and awake(recipient) and not knows(actor, coat_given).
    Resolve acquire(davy_coat, soldier_coat, recipient).
    On success { Assert knows(actor, coat_given). Retract at(davy_coat, teazle_room). }
    Result "Nan lays the coat over your arm, and smooths the darn at the elbow once with her thumb, and lets go.".
  }
  Initially Assert lends(nan, davy_coat, party).

  Topic wick_night with wick "Ask Wick about the night Davy went" when not cameHome(davy) once {
    Says "'I followed him,' says Wick, fast, as if he has been waiting to be asked. 'All the way down the Steps and out on the sand, it was a spring ebb, you can walk right out. There were twelve of them and they kept step and nobody was calling it. Out past the colonnade, across the Forum. Into the Hall of Oaths.' He lowers his voice. 'There's no door in the Hall of Oaths. It's a wall at the back. I've felt it. They walked into the wall and it let them, and then it was a wall again.' He considers. 'I'll show you, if you like. A coin. Two if you want the tide-table too, which you do.'".
    On discuss { Assert knows(actor, hall_of_oaths_way). }
  }
  Topic wick_lowtide with wick "Ask Wick about Lowtide" when true once {
    Says "'It's the old city,' says Wick. 'You go down the Swatch Stair at low water and it's all streets, with weed in, and you can find things. Coins.' He rattles his tray. 'You've got five hours, about. When the tide turns you get up high, the aqueduct or the top of the bath-house dome, and you sit there till it goes out again, and you don't go in the bath-house, not ever, because the hollow men are in the bath-house.' He thinks. 'And keep out of the way of the ebb-runners at the landing. They don't like being looked at.'".
  }
  Topic wick_hollow with wick "Ask Wick about the hollow men" when true once {
    Says "Wick stops grinning. 'They were people,' he says. 'Old ones, from when the city was up. Mudlarks see them sometimes in the doorways when the water's coming. They're like coats with nobody in. They come if you swear. My nan says they come for anyone who's broke a promise, so I never promise anything.' He holds out a coin. 'Genuine Aenean. One coin. I'm not promising it's genuine.'".
  }
  Topic wick_grey with wick "Ask Wick about the clerk in grey" when true once {
    Says "'That's Docket,' says Wick. 'I called him that because he's always counting. He asked me my name and wrote it down and asked was I sure. He knows everyone's name in the Withies now. He knows Davy's. He said Davy was on page four.' Wick scuffs the boards. 'He doesn't eat anything. I gave him an eel and he thanked me and wrote it down and put it in his pocket.'".
  }

  // ── The Muffled Drum: Sergeant Durrance and the Muster ────────────────────────────────────────────────────────────
  Person sedge "Hannelore Rackham" at drum_taproom {
    Role "who keeps the Muffled Drum". Ancestry human. Profession innkeeper. Peaceable. Pronouns she. Manner jovial.
    Greets "Hannelore Rackham looks at you over the bar, and up at the drum over it, and back at you, the way she has looked at everyone who comes in since the summer.".
    Sells rations for 2 coin from 6.
  }
  Topic sedge_drum with sedge "Ask Hannelore Rackham about the drum over the bar" when true once {
    Says "'The Third Company's,' says Hannelore. 'Thomasin brought it home. She tied the cloth over it herself. Nobody plays it till the last of the Third comes home, she says, and since the summer that's been looking like never.' She wipes the bar. 'Don't touch it. I mean that kindly.'".
  }
  Person durrance "Thomasin Durrance" at drum_taproom {
    Role "a sergeant of the Long Muster, out of uniform". Ancestry human. Calling warrior. Level 4. Trait brave. Peaceable. Pronouns she. Manner acerbic.
    Greets "Sergeant Durrance looks at you over her pot the way she has looked at nineteen years of recruits.".
    Joins "Durrance finishes her pot and stands, and is suddenly a sergeant again. 'Right,' she says. 'Let's go and look at where I'm going.'".
    Leaves "'I'll be at the Drum,' says Durrance. 'Where else.'".
  }
  Topic durrance_vanished with durrance "Ask Durrance about the soldiers who have gone into the sea" when true once {
    Says "'Third Company,' says Durrance. 'All of them. Pargeter, Haskett, Moll Bryer, the Lucey twins, Davy Teazle. And in order. You know what order? Roll order. Alphabet by platoon, the way the paymaster calls it.' She drinks. 'I've had nineteen years of roll calls. Somebody is calling the roll, and it isn't anybody in this city. Next spring ebb it's Ruddock, Saye, Tamsett, Oddie, Amsel. And then it's a page turn, and the top of the next page is me.'".
    On discuss { Assert knows(actor, roll_order). Assert knows(actor, durrance_next). }
  }
  Topic durrance_will with durrance "Ask Durrance what she means to do when it is her turn" when knows(actor, durrance_next) and not heldNow(durrance) once {
    Says "'Go,' says Durrance. 'What do you think?' She puts her hand flat on the table. 'I put this hand on the Stone in the Yard nineteen years ago and swore. Nobody made me. I swore to keep the city, and I've kept it, through two sieges and Sedge Ford and the winter at Galt. If the city's calling me in, I go in.' She looks at her hand. 'I'd like to know who's doing the calling, mind. That's all. I'd like to look at them.'".
  }
  Topic durrance_oath with durrance "Ask Durrance what the oath on the Stone says" when true once {
    Says "Durrance doesn't have to think. ''I swear to keep the city of Tessary, its walls and its people, while I live or until it release me.'' She shrugs. 'Hand on the Stone, say it once, the recruiting sergeant slaps your back and you're the city's. Nobody listens to the words. I listened. I was that kind of recruit.' A short laugh. 'Until it release me. It never has. I've never heard of anyone it did.'".
    On discuss { Assert knows(actor, oath_words). }
  }
  Topic durrance_ford with durrance "Ask Durrance about Sedge Ford" when true once {
    Says "'I was ten yards off,' says Durrance. 'Their king came down the bank on a grey horse with his whole household round him. We were finished. We knew it, they knew it. And in the middle of the river he gets off his horse, and goes down on his knees in the water, and holds out his sword to Captain Ancrum hilt first.' She turns her pot. 'People say he looked like a man praying. He didn't. He looked like a man being pushed down by a hand on the back of his neck. And there wasn't anybody behind him.'".
  }
  Topic durrance_join with durrance "Ask Durrance whether she would come with you into Lowtide" when knows(actor, hall_of_oaths_way) and knows(actor, durrance_next) and not willing(durrance, actor) and not travelsWith(durrance, actor) and not heldNow(durrance) once {
    Says "Durrance looks at you a long moment. 'To the Hall of Oaths,' she says. 'Where they go in.' She pushes her pot away. 'Yes. I'd like to see the door before I walk through it. And you'll want someone who can hold a line when the tide comes, and that's me. Say the word and I'll get my coat.'".
    On discuss { Assert willing(durrance, actor). }
  }
  Initially Set hire(durrance) to 0.

  Person fisk "Benno Fisk" at drum_taproom {
    Role "a corporal of the Long Muster". Ancestry human. Calling warrior. Level 2. Peaceable. Pronouns he. Manner cheerful.
    Greets "Benno Fisk lifts his pot to you with one hand and smooths the front of a new grey coat with a salt-white collar with the other.".
  }
  Initially Assert serves(fisk, sault).
  Topic fisk_work with fisk "Ask Fisk where he got the new coat" when true once {
    Says "'Factor Sault,' says Fisk, and smooths it. 'Best employer in Tessary. Day's pay for a day's work, and she knows your name. She knew my name before I knew hers.' He winks. 'Night work too, for them as don't ask questions. Carrying. Down Panhythe way, under the warehouse. Pays double.' He drinks. 'I don't ask questions.'".
  }
  Topic fisk_board with fisk "Ask Fisk what the Muster thinks of the Board" when true once {
    Says "'The Board?' says Fisk. 'The Board sent us to Hethra for eleven years and now it's going to hold a meeting about whether it owes us. A meeting.' He laughs, not pleasantly. 'There's lads at the Muster hall say if the Board votes no, they'll go up the Terraces and ask again, louder. The Factor says not to. The Factor says leave it to her.'".
  }

  // ── Panhythe: Factor Sault ────────────────────────────────────────────────────────────────────────────────────────
  Person sault "Imma Sault" at sault_office {
    Role "Factor of the Salt Moiety". Ancestry human. Calling warrior. Level 5. Peaceable. Pronouns she. Manner acerbic.
    Greets "Factor Sault looks up from her ledgers and wipes her fingers on a cloth and holds out her hand, salt and all.".
  }
  Relation hiredBySault(group).
  Topic sault_work with sault "Ask the Factor about the veterans who have gone into the sea" when not hiredBySault(actor) once {
    Says "'My lads,' says Factor Sault. 'Forty of them on my books at the Muster hall, and six of the forty gone into the water since the summer, and the Board says deserters.' She snorts. 'Deserters. Men who'd come to me for work at dawn every day for a month. You're a stranger here, which is useful: nobody's paying you to see nothing. Find out who's taking them, and how, and bring it to me. Twenty coin.' She holds your eye. 'And if the grey clerk who goes about writing down their names is any part of it, I want to know what he writes.'".
    On discuss { Assert hiredBySault(actor). }
  }
  Topic sault_board with sault "Ask the Factor what she thinks of the Board" when true once {
    Says "'The furniture?' Factor Sault laughs. 'Eight chairs, five of them inherited. They started a war over salt springs they could have bought for a tenth of what it cost, borrowed to fight it, and now the bill's come in, they want to send it to the men who did the fighting.' She spreads her hands, salt-cracked. 'I came up off the pans. I could tell you the name of every rake in my yards. Half of them were soldiers once, before your time, and the city promised them something too.' She does not say what. 'Somebody in this city has to be able to count.'".
  }
  Topic sault_muster with sault "Ask the Factor about her hiring hall" when true once {
    Says "'No man turned away who wore the coat,' says Sault. 'It costs me. The Board was supposed to look after them and didn't, so I do.' She shrugs. 'And they work, and they're grateful, and in a city that's about to have eight thousand angry soldiers in it, I would rather they were grateful to me than to anyone else. I don't pretend it's charity.'".
  }
  // What she pays for: what is taking her lads, told; or the grey clerk's inventory, copied. Either brings her plans on.
  Topic sault_report with sault "Tell the Factor what is taking her lads" when hiredBySault(actor) and knows(actor, collateral) and not saultInformed(sault) once {
    Says "Factor Sault listens with her chin on her fist and does not interrupt once. When you have done she counts twenty coin onto the ledger and pushes them across. 'Pledged,' she says. 'Their oaths. As collateral.' She is not surprised, you notice; she is checking it against something. 'Well. You've earned it.' She looks out of the window toward the Muster hall. 'Ten years I've carried—' She stops. 'Never mind what I've carried. Go and have your supper.'".
    On discuss { Assert saultInformed(sault). Decrease quantity(sault, gold) by 20. Increase quantity(actor, gold) by 20. }
  }
  Topic sault_confronted with sault "Tell the Factor you have read her letter to the Broker of the Fourth Pan" when knows(actor, sault_bid) and not saultExposed(ossel) and not voted(ossel) once {
    Says "Factor Sault puts her pen down. 'Bettany,' she says, not as a question. 'Well. Every word of it's true.' She leans back. 'So what will you do with it? Take it to the Board, and they'll read it, and be frightened of me, and vote no anyway because there's no money, and I'll have the note at the Feast and you'll have been right. Or take it under the sea to the old man, and he'll stop my broker, and I'll go down and bid in person.' She shrugs. 'Or put me terms, if you can find anything I want more than the Muster. Nobody has yet.' She picks up the pen. 'I'm not your enemy. I'm the only one in this city who's been paying attention.'".
  }
  // The grey clerk's inventory, copied.
  Item inventory_copy "a copy of the Valuer's inventory" is ledger_copy at tideline_steps hidden until inventory_copied.
  Kind ledger_copy "a copied page of an inventory" is gear worth 1 weighing 0
    described "Names in a careful hand you made yourself from someone else's careful hand, in roll order, with a column of marks no one in Tessary could read.".
  Discovery inventory_copied "You have copied pages of the Valuer's inventory: the Muster's names in roll order, those called and those to come.".
  Relation saultInformed(group). Relation caughtCopying(group).
  // By night the Valuer stands on the Watersteps watching the water, with the ledger open on the step beside them.
  Action copy_inventory(actor: group, site: place) "Copy the pages of the Valuer's ledger, open on the step behind them" {
    Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, tideline_steps) and at(tally, tideline_steps)
      and dark() and not travelsWith(tally, actor) and not knows(actor, inventory_copied) and not caughtCopying(actor).
    Resolve check(actor, stealth, dc_fair).
    On success { Assert knows(actor, inventory_copied). Assert knows(actor, roll_order). Assert knows(actor, durrance_next). }
    On failure { Assert caughtCopying(actor). }
    Result "The Valuer stands at the water's edge with their back to you, quite still, and the ledger lies open on the step in the lamplight. You copy two pages by its light, names in roll order and columns of marks you cannot read, and the Valuer does not turn round. Third Company. Page four: Teazle, D. Page five, near the top: Durrance, A.".
    Otherwise "You have copied half a page when the Valuer says, without turning round, 'That is the property of the Balance.' They come and close the ledger, and take it up, and look at you with no expression at all. 'I note it,' they say.".
  }
  Event sault_paid near sault when keeps(sault, inventory_copy) "Factor Sault reads the pages through twice, running a salt-cracked finger down the names, stopping at some. 'Roll order,' she says. 'Well, well.' She counts twenty coin onto the ledger without looking at them. 'You've earned it. I'll not forget it.' She folds the pages away into her coat." then {
    Assert saultInformed(sault). Decrease quantity(sault, gold) by 20. Increase quantity(party, gold) by 20. }
  Initially Set quantity(sault, gold) to 60.

  // ── The Lettered Quarter ──────────────────────────────────────────────────────────────────────────────────────────
  Person quire "Josiah Quire" at exchequer_room {
    Role "Treasurer of Tessary". Ancestry human. Peaceable. Pronouns he. Manner compassionate.
    Greets "The Treasurer looks up as if he had been expecting someone else, or everyone, and blinks.".
  }
  Topic quire_vanished with quire "Ask the Treasurer about the soldiers who have gone into the sea" when not knows(actor, council_knows) once {
    Says "'Deserters,' says Quire, too quickly. 'That is the Board's finding. Men who have been away eleven years do not always want to come home to what they left.' He moves a paperweight on his desk from one stack to another and back. 'I'm sorry. I am very tired. Is there anything else?'".
  }
  Relation quireConfided(group).
  Topic quire_list_asked with quire "Ask the Treasurer about his list of names" when knows(actor, council_knows) and not quireConfided(actor) once {
    Says "Quire looks at the list for a long time. 'A hundred and thirty-eight,' he says. 'I send their mothers something every month. Out of my own salary, which the city also does not pay.' He takes off his spectacles. 'I signed it. Ten years ago. We went down under the sea, six of us, and they showed us a thing like a ledger the size of a ship, and an old man who could not lie read us the terms, and we signed, because we were going to lose the war, and we won.' His hands are shaking. 'The Muster's oaths. As collateral. I put my name to eight thousand men like a farmer putting up his cows.'".
    On discuss { Assert quireConfided(actor). Assert knows(actor, collateral). }
  }
  Topic quire_terms with quire "Ask the Treasurer what the city must do to pay" when quireConfided(actor) and not knows(actor, promise_weight) once {
    Says "'Keep a promise,' says Quire. 'Of equal weight. Their words.' He laughs, horribly. 'Do you know what weighs as much as a king's ancestral oath, in their scales? A promise of a whole people to a whole people. And there is exactly one of those in the city's books, and I have it by heart: land and a pension for every man who comes home. It would cost two hundred thousand marks. The treasury has nothing. The Board will vote no on the thirteenth day, because there is no money, and on the fifteenth the note falls due, and then...' He doesn't finish.".
    On discuss { Assert knows(actor, promise_weight). Assert knows(actor, enlist_promise). }
  }

  Person pounce "Hesketh Pounce" at pounce_stall {
    Role "a scrivener of the Row". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
  }
  Topic pounce_trade with pounce "Ask Pounce about his trade" when true once {
    Says "'Contracts drawn, contracts read, contracts explained,' says Pounce. 'The first is easy, the second is a skill, the third is extra because nobody likes what I tell them.' He sands a page. 'Tessary is a city where a fishwife will sue a gull. I have made a good living out of it for thirty years. I keep every draft I ever wrote, you know. A scrivener who burns his drafts is a scrivener who gets sued.'".
  }
  Topic pounce_council with pounce "Ask Pounce whether he has ever drawn a contract for the Board" when true once {
    Says "Pounce's pen stops. 'Once,' he says. 'Ten years ago. A fair copy of an instrument, done at night in the Council House with a councillor at my elbow and sworn to silence after. Strangest thing I ever copied. Half of it was in a hand I had never seen and had to copy by shape.' He looks at you sideways. 'I kept my draft. Of course I kept my draft. I am sworn to silence, mind. But a scrivener's drafts are his own property, and his property is for sale, and it is no breach of silence to sell a man a piece of paper he will read for himself.' He names the price: 'Six coin.'".
    On discuss { Assert pounceOffered(actor). }
  }
  Relation pounceOffered(group).
  Item pounce_draft "Pounce's draft of the War Note" is draft_kind at pounce_stall hidden until draft_bought.
  Kind draft_kind "a scrivener's draft" is gear worth 1 weighing 0
    described "Six closely written pages of reed-paper, foxed and folded, the draft of a fair copy: a contract between the city of Tessary and a party named only as the Ledger Below.".
  Discovery draft_bought "Pounce has sold you his twelve-year-old draft of the Board's secret instrument.".
  Action buy_draft(actor: group, recipient: member, site: place) "Pay Pounce six coin for his old draft" {
    Speaker pounce. Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(pounce, site) and pounceOffered(actor)
      and memberOf(recipient, actor) and awake(recipient)
      and not knows(actor, draft_bought) and quantity(actor, gold) >= 6.
    Resolve acquire(pounce_draft, draft_kind, recipient).
    On success { Decrease quantity(actor, gold) by 6. Increase quantity(pounce, gold) by 6. Assert knows(actor, draft_bought). Retract at(pounce_draft, pounce_stall). }
    Result "Pounce goes to a chest and comes back with six pages folded small, and counts your coins before he lets go of them. 'You did not get these from me,' he says. 'You got them from a man you met in a tavern who resembled me.'".
  }
  Action read_draft(actor: group, site: place) "Read Pounce's draft of the War Note" {
    Time 2.
    Requires able(actor) and company(actor) and at(actor, site) and carries(actor, pounce_draft) and not benighted(actor)
      and not knows(actor, note_terms).
    On success { Assert knows(actor, note_terms). }
    Result "You read it through twice. The city's half is plain Tessarine legal hand: the city of Tessary, as heir to the Aenean emperors in the matter of oaths, borrows the calling of an oath sworn by the house of Hethra, &c. The other half is in a script Pounce copied by shape, ruled like a ledger; but the terms are restated in the city's hand at the foot, as terms are. The Long Muster's oaths as surety. Silver monthly. And at the Feast of Settlement in the twelfth year, the principal, to be paid in a kept promise of equal weight. The Treasurer's signature. Five councillors'. And a sixth mark that is not a signature at all, only a set of ruled lines.".
  }
  Action explain_draft(actor: group, site: place) "Pay Pounce two coin to explain the clause about equal weight" {
    Speaker pounce. Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(pounce, site) and carries(actor, pounce_draft)
      and knows(actor, note_terms) and not knows(actor, promise_weight) and quantity(actor, gold) >= 2.
    On success { Decrease quantity(actor, gold) by 2. Increase quantity(pounce, gold) by 2. Assert knows(actor, promise_weight). Assert knows(actor, enlist_promise). }
    Result "Pounce puts on a second pair of spectacles over the first. 'Equal weight,' he says. 'Weight of what? Not silver, or it would say silver. A promise of equal weight to an oath that bound a royal house for nine hundred years.' He taps the page. 'A people's promise, then, to a people. Has this city ever made one?' He answers himself before you can. 'Land and a pension for every man who comes home. I drew the recruiting bills. So if the city keeps that, it pays this.' He takes off both pairs of spectacles. 'And if it doesn't, it doesn't. That will be two coin. I did say nobody likes what I tell them.'".
  }

  // The Office of Seals: the queue, and the Keeper of the Seal.
  Person queue "the queue" at seals_hall {
    Role "who have been waiting since breakfast, or Tuesday, or longer, each with a document". Ancestry human. Numbers 1. Peaceable. Pronouns they.
    Greets "Every face in the queue turns to see whether you mean to push in, and, satisfied, turns back.".
  }
  Topic queue_asked with queue "Ask the queue how long they have been waiting" when true once {
    Says "Several people answer at once. A man with a deed: 'Since breakfast.' A woman with a marriage contract: 'Since Tuesday.' An old man near the front, without turning round: 'My father held this place in the queue before me. I am sealing the lease he came to seal. It has run out, but it is the principle.'".
  }
  Person deckle "Ulric Deckle" at seals_inner {
    Role "Keeper of the Great Seal". Ancestry human. Peaceable. Pronouns he. Manner proud.
    Wants seal_kind.
  }
  Relation reachedKeeper(group).
  Action wait_in_queue(actor: group, site: place) "Take your place in the queue" {
    Description "It moves. Slowly, but it moves.".
    Time 18.
    Requires able(actor) and company(actor) and at(actor, site) and at(queue, site) and not reachedKeeper(actor)
      and hour(clock) >= 8 and hour(clock) < 15.
    On success { Assert reachedKeeper(actor). }
    Interrupted when threatened(actor).
    Result "Three hours later, having learned the life history of a rope-maker's widow and the full grounds of a dispute about a fence, you reach the grille. A clerk looks at you over it. 'Business?' And, since you have none he recognises: 'The Keeper will see you. The Keeper sees everyone who reaches the grille. It is the law.' He opens the door.".
  }
  Thing grille "the grille" on seals_grille {
    State shut blocking "A clerk behind the grille admits whoever reaches the head of the queue, and nobody else.".
    State open "The clerk has opened the grille for you.".
  }
  Query keeperSends() means deedsSealed(ossel) or sealStolen(ossel) or votePassed(ossel) and night(ossel) == 13 and hour(clock) >= 15.
  Rule grille_opens when (reachedKeeper(party) or keeperSends()) and state(grille, shut) { Assert state(grille, open). }
  Rule grille_shuts when state(grille, open) and not reachedKeeper(party) and not keeperSends() { Assert state(grille, shut). }
  Rule grille_closes_at_night when dark() and reachedKeeper(party) and not at(party, seals_inner) and not keeperSends() { Retract reachedKeeper(party). }
  Topic deckle_seal with deckle "Ask the Keeper about the Great Seal" when true once {
    Says "'The Seal of Tessary,' says Deckle, and lifts the glass bell an inch as if letting it breathe. 'What it seals, the city has done. A deed sealed here is land given. A treaty sealed here is peace made. If the Board were to vote the Veterans' Settlement' (he says it the way one says the name of a disease) 'every one of eight thousand deeds would have to pass under this hand. My clerks could do it in a night and a day, if they did nothing else.' He lowers the bell. 'Nobody has asked them to.'".
  }

  // ── The Terraces ──────────────────────────────────────────────────────────────────────────────────────────────────
  Person marrable "Ysbel Marrable" at marrable_room {
    Role "who sits for the Eel Moiety on the Board, a veteran with one sleeve pinned up". Ancestry human. Calling warrior. Level 3. Peaceable. Pronouns she. Manner stoic.
  }
  Topic marrable_vote with marrable "Ask Councillor Marrable how the vote will go" when not voted(ossel) once {
    Says "'Badly,' says Marrable. 'Eight chairs. Mine is yes. Old Hallam has buried two sons in Hethra; he's yes, if he's awake. Salt is Sault's and Sault says no, there's no money, which is true. Rope is Dauntry and Dauntry votes the way Sault tells him. Greaves and Vantage are the furniture and will not give an inch of their land. Paper is Haverick, who cares about nothing but his goose, and Ship is Orme, who will vote for whatever he thinks will be paid for.' She counts on one hand, which takes no time. 'I need five. I have two.'".
  }
  Topic marrable_sway with marrable "Ask Councillor Marrable what would change their minds" when not voted(ossel) once {
    Says "'Proof,' says Marrable. 'They call the vanished deserters because if they're not deserters, something worse is happening and somebody on the Board knows what. Show them the Treasurer knows. Show them why. Bring them someone they can't call a liar.' She looks at the pinned sleeve. 'And keep the Muster off the Terraces. If soldiers come up that hill shouting the night before, Orme and Hallam will vote no out of fright and I won't blame them.' She looks at you. 'We sit on the thirteenth day, from ten in the morning till the bell at two. The public bench is open. Anyone with something to say can stand up and say it, until two. After two it's a count.'".
  }
  Person amaury "Amaury of Hethra" at kings_rooms {
    Role "King of Hethra, a hostage in Tessary". Ancestry human. Calling warrior. Level 6. Peaceable. Pronouns he. Manner acerbic.
    Greets "The King of Hethra looks up from his draughts board. 'A visitor,' he says. 'How unusual. Sit, sit. I am allowed visitors. I am allowed everything except the door.'".
  }
  Topic amaury_kneeling with amaury "Ask the King about the Kneeling at Sedge Ford" when true once {
    Says "'Ah,' says the King. 'The famous kneeling.' He moves a draught. 'I had won. You understand that? I had your city's Muster pinned against the river and I rode down to accept its surrender. And in the middle of the ford I felt a hand. Here.' He touches the back of his neck. 'Old. Patient. Quite certain of its rights. Nine hundred years old, I would say, if a hand can be old. And my knees went into the water and my sword went out hilt first and I heard my own voice yielding the kingdom.' He looks at the board. 'Your saint's day for it is the twelfth of Haying. I watch the procession from this window. It is the only day of the year I drink before noon.'".
    On discuss { Assert knows(actor, kneeling_felt). }
  }
  Relation amauryPlayed(group).
  Action play_amaury(actor: group, site: place) "Play the King a game of Hethran draughts" {
    Speaker amaury. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(amaury, site) and not amauryPlayed(actor).
    Resolve check(actor, insight, dc_fair).
    On success { Assert amauryPlayed(actor). Assert amauryWon(actor). }
    On failure { Assert amauryPlayed(actor). }
    Result "It is a long game, and the King talks all through it, about his horses, the weather in the hills, the absurdity of a city that keeps its prisoner in better rooms than its Treasurer. Somewhere in the second hour you see the trap he has been building on the left side of the board, and walk round it, and he sits back. 'You see what's in front of you,' he says. 'That is rarer than it should be. Come again.'".
    Otherwise "It is a long game, and the King talks all through it, and in the second hour springs a trap on the left side of the board that he has been building since the first move. 'Hethran draughts,' he says kindly, sweeping up your pieces, 'is a game for people who expect to lose a war. Come again.'".
  }
  Relation amauryWon(group).
  Relation amauryWillTestify(group).
  Topic amaury_told with amaury "Tell the King how Sedge Ford was won" when knows(actor, note_terms) and not amauryWillTestify(actor) once {
    Says "The King hears you out without moving a piece. When you have done, he laughs, quite quietly, for a long time. 'An oath of my house,' he says, 'to the Aenean emperors. Bought back off a shelf under the sea by a city of paper-makers, for silver, on the never-never.' He wipes his eyes. 'And then paid for in their own soldiers when the silver ran out. Oh, that is good. That is the best thing I have heard in a year.' He stops laughing. 'If you want this told to the Board in a voice they cannot dismiss as a stranger's, I will tell it. They will have to let me out of these rooms to hear it, and I should like to see the inside of their chamber, and the painting.' He moves a draught at last. 'I should like very much to see their faces.'".
    On discuss { Assert amauryWillTestify(actor). Assert knows(actor, kneeling_felt). }
  }
  Topic amaury_wants with amaury "Ask the King what he wants" when true once {
    Says "'To go home,' says the King. 'My ransom is a sum your Board cannot ask for and my people cannot pay, which suits both of them. And to know what happened to me in that river.' He sets a piece down very precisely. 'A man can lose a kingdom and live. I find it is harder to have been made to give it away.'".
  }

  // ── The Ninth Valuer ────────────────────────────────────────────────────────────────────────────────────────────
  // A clerk of the Scruples, sent up to inventory the collateral before the note falls due. Exact; unable to lie;
  // answers what it is asked and nothing it is not.
  Person tally "the Ninth Valuer" at withies {
    Role "a clerk in a grey coat with a ledger, whose skin is faintly ruled like paper". Ancestry human. Calling cleric. Level 3. Peaceable. Pronouns they. Manner stoic.
    Called "Docket".
    Seen when not tallyUnravelled(ossel).
    Greets "The clerk in grey looks up from the ledger. Close to, the skin of their face and hands is very faintly ruled, like a page, in lines as fine as hairs. 'Good day,' they say. 'You are not on my inventory.'".
    Joins "'Our inquiries coincide,' says the Valuer, and closes the ledger on a ribbon. 'I will accompany you. I will note anything you do that bears on the collateral.'".
    Leaves "The Valuer inclines their head, very exactly, and closes the ledger on its ribbon, and goes.".
  }
  Initially Set hire(tally) to 0.
  Topic tally_who with tally "Ask the clerk in grey who they are" when true once {
    Says "'I am the Ninth Valuer of the Scruples,' says the clerk. 'I am taking an inventory.' A pause, which seems to be for you to say something, and when you do not: 'The children call me Docket. It is not my name. My name is held. Docket is accurate as a description, and I do not object to it.'".
  }
  Topic tally_counting with tally "Ask the Valuer what they are counting" when true once {
    Says "'The Long Muster,' says the Valuer, 'page by page, in the order of its roll.' They make a small mark. 'I am not at liberty to say why. The affairs of a debtor are not discussed with a third party. You are a third party.' A pause, quite friendly. 'You may ask me anything. I will not lie to you. I will decline a great deal.'".
    On discuss { Assert knows(actor, roll_order). }
  }
  Topic tally_where with tally "Ask the Valuer where the soldiers you saw walk into the sea have gone" when knows(actor, calling_witnessed) and not knows(actor, held_alive) once {
    Says "The Valuer considers whether this is the affair of a debtor, and decides, visibly, that what you saw with your own eyes is your own affair. 'Into the Holding,' they say, 'where pledged things are kept. They are not harmed. They are held. They stand asleep with the rest of what has been pledged and forfeit, and they do not age.' A pause. 'You are distressed. I am sorry. It is a lawful collection.'".
    On discuss { Assert knows(actor, held_alive). }
  }
  Topic tally_discharge with tally "Ask the Valuer what would bring the called home" when knows(actor, held_alive) and not knows(actor, release_law) once {
    Says "'The discharge of the debt they stand surety for,' says the Valuer, as if reading it. 'A debt is discharged in two ways. It is kept, or it is released: if the one to whom a promise was made says freely to the one who made it, I hold you quit, that weighs in the Balance exactly as the keeping does.' A pause. 'People forget the second. Nobody releases anybody. I have often wondered why.'".
    On discuss { Assert knows(actor, release_law). }
  }
  Topic tally_confirm with tally "Ask the Valuer whether the city pledged its soldiers' oaths" when (knows(actor, council_knows) or quireConfided(actor)) and not knows(actor, collateral) once {
    Says "'You have seen the Treasurer's list,' says the Valuer. 'Then you have it from the debtor's own officer, and I may confirm what he has let you see.' They open the ledger flat. 'The oaths of the Long Muster, sworn on the instrument the city calls the Oath Stone, are pledged as security on a debt the city owes to the Balance. Since the silver stopped in the summer, interest has been taken in oaths at each spring ebb, in the order of the roll.' They close it. 'Some of the collateral has died since it was pledged, of wounds and of drink. I am noting that.'".
    On discuss { Assert knows(actor, collateral). }
  }
  Topic tally_debt with tally "Ask the Valuer what the city borrowed" when knows(actor, collateral) and not knows(actor, note_terms) once {
    Says "'The terms are the debtor's affair,' says the Valuer. And then, with great exactness: 'The city made a fair copy of the instrument in its own hand, as a debtor must. Its Board had it made at night by a scrivener of the Row, under an oath of silence.' They look at you. 'In my experience of this city, a scrivener keeps his drafts. I say so as an observation about scriveners.'".
  }
  Topic tally_how with tally "Ask the Valuer what promise would weigh as much as the War Note" when knows(actor, note_terms) and not knows(actor, promise_weight) once {
    Says "'I am not permitted to advise the debtor,' says the Valuer. 'You are not the debtor.' They consider this for some time. 'A promise is weighed by who makes it and to whom, and what it binds. An oath of a royal house to an empire is very heavy. Only a promise of a whole people to a whole people would balance it. I have read the city's books. It has made one.' They look, for the first time, faintly uncomfortable. 'I cannot tell you which. I can tell you that it is printed on a bill on the shelf of a house in this ward, and that I have read it there.'".
    On discuss { Assert knows(actor, promise_weight). }
  }
  Topic tally_next with tally "Ask the Valuer whose names are on the next page" when knows(actor, roll_order) and night(ossel) < 8 once {
    Says "The Valuer opens the ledger at a ribbon. 'Ruddock, J., private. Saye, W., private. Tamsett, M., private. Oddie, F., drummer. Amsel, K., private. Then the page turns. Durrance, A., sergeant, Third Company, nineteen years' service.' They look up. 'Then Elcock, Fane, Garrow, Hobb, Ince and Jessup. Twelve.'".
    On discuss { Assert knows(actor, durrance_next). }
  }
  Topic tally_join with tally "Ask the Valuer to come with you to the Hall of Oaths" when knows(actor, hall_of_oaths_way) and knows(actor, held_alive) and not willing(tally, actor) and not travelsWith(tally, actor) once {
    Says "'The Hall of Oaths,' says the Valuer. 'The way down.' They are quiet, and you have the impression of a calculation being done. 'I am to return below before the Feast in any case, to report. If you are going that way, I will take you through the wall, and note what you do on the other side of it.' They hold out a hand, ruled like a page. 'I must ask you to promise not to lie to me. It is a small thing, for you. You will find it is not small below.'".
    On discuss { Assert willing(tally, actor). Assert promisedTally(actor). }
  }
  Relation promisedTally(group).
}

data/adventures/what-tessary-owes/placed:
Module tessary "What Tessary Owes" {
  // The Ossel delta as a country beyond a march: the company that comes in along the Causeway is the world's own.
  Entity party: group "Your company".
}

data/adventures/what-tessary-owes/plot.k:
Module tessary "What Tessary Owes" {
  // ── The state of the city's affairs ──────────────────────────────────────────────────────────────────────────────
  // Relations shared by every movement: who is held, whether the Board has voted, how the note stands.
  Relation heldNow(group). Relation voted(place). Relation votePassed(place).
  // At the Settlement the note is discharged (kept, released or voided), or it falls in: foreclosed, or taken up.
  Relation discharged(place). Relation foreclosed(place). Relation saultHoldsNote(place).
  Relation keptPromise(place). Relation released(place). Relation noteVoid(place). Relation noteTorn(place).
  Relation matured(place).

  // ── Factor Sault's undertakings ───────────────────────────────────────────────────────────────────────────────────
  // What she does whether or not anyone interferes: makes the vanished out to be deserters; buys what she can of the
  // Muster; leans on the Treasurer; keeps the Board from voting the Settlement by whatever it takes; and, when the
  // Feast passes, takes up the note. Her lightermen do the heavy work and take prisoners rather than kill.
  Person lightermen "Sault's lightermen" at warehouse_floor {
    Role "three big men in salt-stiff jerkins, with cudgels". Ancestry human. Calling warrior. Level 2. Numbers 3. Pronouns they.
    Temperament territorial.
    Warns "Three big men in salt-stiff jerkins step out from between the stacks. 'Warehouse is shut,' says the biggest.".
    Comes "Sault's lightermen come at you with their cudgels up, not hurrying, the way men do who have done this before.".
    Pleads "The last of the lightermen backs off with his hands open. 'Not paid enough,' he says. 'Not for this.'".
  }
  Initially Assert takesPrisoners(lightermen). Initially Assert serves(lightermen, sault).
  Rule lightermen_captured when captured(lightermen, party) and at(party, ?p)
    says "You wake on the salt crust out on the Pans, at dawn, with a split lip and your purse lighter. Somebody has left you a cup of water, which is the Factor all over." {
    Retract captured(lightermen, party). Retract at(party, ?p). Assert at(party, pans). Decrease quantity(party, gold) by 4. }

  // What the Factor says, seeing her letter in a stranger's hand: nothing.
  Event sault_sees_letter near sault when carries(party, sault_letter) "The Factor's eyes go to the letter in your hand, with her own wax on it, and come back to your face. She says nothing about it at all. She goes on talking about the price of peat.".
  Discovery sault_saw_letter "Factor Sault has seen her letter in your hands.".

  // What the city shows a company that comes back to it, of what was done while it was away.
  Event drum_boots at drum_taproom when durranceCalled(ossel) and heldNow(durrance) "Thomasin Durrance's boots stand on the bar of the Muffled Drum, side by side, toes to the door, under the drum with the cloth over it. Nobody drinks at that end of the bar.".
  Observe exchequer_shut at exchequer_room when quireDrowned(ossel) "The Treasurer's room has been shut up. The cot is stripped, the ledgers stacked, and someone has tied a black ribbon round the empty bottle and left it on the desk.".
  Observe terraces_riot at terraces when riotHappened(ossel) and not matured(ossel) "Glass glitters in the gutters of the Terraces. The Council House windows are boarded, and men of the Watch stand on its portico with pikes, looking anxious.".
  Observe marrable_abed at marrable_room when marrableHurt(ossel) "Ysbel Marrable is sitting up in a chair by the window with her head bandaged and one eye closed. 'They didn't take the other arm,' she says. 'Considerate of them.'".
  Observe landgate_lost at landgate when voted(ossel) and not votePassed(ossel) and not matured(ossel) "On the board, the Speaker's notice: the question of the Veterans' Settlement is lost, the city having no money. Pasted over half of it, the old recruiting bill: LAND AND A PENSION FOR EVERY MAN WHO COMES HOME.".
  Observe landgate_carried at landgate when votePassed(ossel) and not matured(ossel) "On the board, in fresh print: THE VETERANS' SETTLEMENT IS CARRIED. Someone has drawn a pair of scales on it in charcoal, and someone else a goose.".

  // 1. The whisper: from the second day, bills on the Landgate board and talk in the Withies.
  Relation whispered(place).
  Rule whisper_starts when night(ossel) >= 2 and not whispered(ossel) { Assert whispered(ossel). }
  Observe whisper_bill at landgate when whispered(ossel) and not voted(ossel) "A new bill on the board, printed, not handwritten, on good paper: DESERTERS. Those who have left their homes by night since the summer are absconders from the city's service and from their just debts. Information to the Watch. Beneath it, in pencil, someone has written: MY BOY NEVER OWED ANYONE A PENNY.".
  Observe whisper_withies at withies when whispered(ossel) and not dark() and not voted(ossel) "Two women on the boardwalk stop talking as you pass. You catch the word deserter, and the other one saying, quite loudly, that she'd like to see the man who printed it come and say it here.".

  // 2. The Sergeant's silver: on the fifth day she offers to pay the next spring ebb's interest herself, in silver, if
  // Durrance will sergeant her Muster. Durrance takes it only if she has learned what the city did with her oath and
  // nothing yet of what Sault means to do with it.
  Relation durranceKnowsSold(group). Relation durranceKnowsFraud(group). Relation durranceKnowsRelease(group).
  Relation durranceKnowsSault(group). Relation saultOffered(place). Relation durranceSaults(place).
  Rule silver_offered when night(ossel) >= 5 and hour(clock) == 12 and not saultOffered(ossel) and not heldNow(durrance) {
    Assert saultOffered(ossel). }
  Rule silver_taken when saultOffered(ossel) and durranceKnowsSold(durrance) and not durranceKnowsSault(durrance)
    and not durranceSaults(ossel) and not heldNow(durrance) and night(ossel) < 8 {
    Assert durranceSaults(ossel). Assert interestPaid(ossel). Assert serves(durrance, sault). }
  Observe durrance_refused near durrance when saultOffered(ossel) and not durranceSaults(ossel) and not heldNow(durrance) and night(ossel) < 8 "'The Factor sent for me,' says Durrance. 'Offered to pay the silver for the next ebb out of her own pocket, all twelve of us, if I'd sergeant her Muster after.' She turns her pot. 'I told her I'd sworn already. Once is enough for anyone.'".
  Event durrance_took near durrance when durranceSaults(ossel) "Durrance has a new coat on, a good one, and does not meet your eye. 'The Factor's paying the next ebb's silver,' she says. 'All twelve. Out of her own pocket. And I'm her sergeant after.' She drinks. 'The city sold my oath. The Factor bought it back. I don't see the difference, and nor will Ruddock's mother.'".
  Discovery sault_offer_known "Factor Sault offered to pay the next spring ebb's interest in silver from her own purse if Sergeant Durrance would sergeant her Muster.".
  Topic tell_durrance_sold with durrance "Tell Durrance what the city did with the Muster's oaths" when knows(actor, collateral) and not durranceKnowsSold(durrance) and not heldNow(durrance) once {
    Says "Durrance hears you out. Then she sits for a long time looking at the drum over the bar with the cloth on it. 'Collateral,' she says at last. 'Like a cow.' She laughs, once. 'Nineteen years. I buried the whole of the Second Platoon at Galt in one trench. And the Board had us in a pawnshop the whole time.' She finishes her pot. 'Well. It's still my oath. They sold it. I didn't.'".
    On discuss { Assert durranceKnowsSold(durrance). }
  }
  Topic tell_durrance_sault with durrance "Tell Durrance what the Factor means to do with the note" when knows(actor, sault_bid) and not durranceKnowsSault(durrance) and not heldNow(durrance) once {
    Says "'Govern,' says Durrance. 'With us.' She is very still. 'Not pay us. Own us. Call us out of wherever we are and stand us on the Tidewall in her coats.' Her face does not change. 'She'd feed us. She'd be better than the Board. I'd still be a cow.'".
    On discuss { Assert durranceKnowsSault(durrance). }
  }
  Rule durrance_quits_sault when durranceSaults(ossel) and durranceKnowsSault(durrance) and serves(durrance, sault)
    says "Durrance takes off the Factor's coat and folds it and leaves it on the bench." { Retract serves(durrance, sault). }
  Topic tell_durrance_fraud with durrance "Tell Durrance that the note was drawn to fail" when knows(actor, note_designed) and not durranceKnowsFraud(durrance) and not heldNow(durrance) once {
    Says "Durrance listens with her hands at her sides. When you have finished she is quiet so long that you think she has not heard. 'A promise made to be broken,' she says. 'By them. The ones who keep the books.' She looks at her right hand, the one she laid on the Stone. 'Then what did I swear to? A trap?' She stands up. 'An oath sworn into a fraud is no oath. My grandmother could have told them that. I'm not going in when the drum goes. And I'm not going to let anyone else go either.'".
    On discuss { Assert durranceKnowsFraud(durrance). }
  }
  Topic tell_durrance_release with durrance "Tell Durrance that a promise can be discharged by release" when knows(actor, release_law) and not durranceKnowsRelease(durrance) and not heldNow(durrance) once {
    Says "'Released,' says Durrance slowly. 'If the one it was made to says, I hold you quit.' She is looking at the drum. 'The city promised us land and pension. That's the promise in their scales. And it's ours. It was made to us.' Her hand closes. 'So if we let them off it. If the Muster stood on the Stone and said, we hold you quit, keep your land...' She stops. 'Then the debt's paid. With our pensions. And the lads come home.' She laughs, not happily. 'Eleven years, and we save the city twice, and the second time we pay for it. Let me think. Don't ask me today. Let me think.'".
    On discuss { Assert durranceKnowsRelease(durrance). }
  }

  // 3. The eighth night: Durrance walks. A company with her an hour before the ebb can hold her back; the drum over
  // the Drum's bar, uncovered and beaten to the stand-down, breaks the step of any soldier of the Third who hears it.
  Relation durranceWalking(place). Relation heldBack(group). Relation drumBeaten(place). Relation elcockTaken(place).
  Relation durranceCalled(place).
  Query durranceSafe() means durranceSpared(ossel) or interestPaid(ossel) or heldBack(durrance) or durranceKnowsFraud(durrance).
  Rule durrance_walks when night(ossel) == 7 and hour(clock) == 1 and not durranceWalking(ossel) and not heldNow(durrance)
    and not durranceSafe() { Assert durranceWalking(ossel). }
  Event durrance_walks_seen near durrance when durranceWalking(ossel) and not heldBack(durrance) and not heldNow(durrance) and hour(clock) == 1
    "Durrance stops. She goes still all at once, the way a soldier comes to attention when an officer walks in, and what she had in her hand falls and she does not look at it. Her eyes are open. She is listening to something. Then she bends and begins, very neatly, to unlace her boots.".
  Action hold_durrance(actor: group, site: place) "Get hold of Durrance and keep her from the Steps" {
    Description "She is a sergeant of nineteen years and she is not awake.".
    Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and (at(durrance, site) or travelsWith(durrance, actor))
      and durranceWalking(ossel) and not heldBack(durrance) and not triedHolding(actor) and hour(clock) == 1.
    Resolve check(actor, brawn, dc_hard).
    On success { Assert heldBack(durrance). }
    On failure { Assert triedHolding(actor). }
    Result "You get your arms round her from behind and she throws you off as if you were a coat, and you get them round her again, and this time you hang on, and go down with her, and lie on her on the boards while she fights in perfect silence with her eyes open. It goes on a long time. Then, all at once, she goes slack, and blinks, and says in her own voice, 'Get off me, you great lump.'".
    Otherwise "You get hold of her and she simply walks on, and takes you with her a step, and puts you down against the wall with one hand, quite gently, as if you were in her way. Then she goes out barefoot into the night.".
  }
  Relation triedHolding(group).
  Thing third_drum "the Third Company's drum" at drum_taproom {
    State muffled "Over the bar hangs a regimental drum with a black cloth tied over its head.".
    State bare "The Third Company's drum hangs over the bar with its head bare.".
    Change uncover "Pull the cloth off the Third Company's drum and beat the stand-down" from muffled to bare.
  }
  Rule drum_breaks when state(third_drum, bare) and durranceWalking(ossel) and not heldBack(durrance) and hour(clock) == 1
    says "The drum fills the low room. Rap, rap, and the long roll, and rap: the stand-down, that every soldier of the Muster has heard at the end of every day for eleven years. Durrance stops with one boot off. All over the Withies, in the stilt-houses, you hear other things stop: a door, a ladder, someone on the boardwalk. Durrance sits down, hard, on the floor, and looks at the boot in her hand as if she has never seen it." {
    Assert heldBack(durrance). Assert drumBeaten(ossel). }
  Rule drum_offends when state(third_drum, bare) and not drumBeaten(ossel) and at(party, drum_taproom)
    says "Hannelore Rackham comes round the bar and puts the cloth back over the drum's head, and ties it, and looks at you. 'I said don't,' she says. 'I said it kindly.'" {
    Assert state(third_drum, muffled). }
  Rule durrance_goes when night(ossel) == 8 and callings(ossel) == 8 and not durranceCalled(ossel) and not heldNow(durrance)
    and not durranceSafe() {
    Assert durranceCalled(ossel). Assert heldNow(durrance). Assert asleep(durrance). Retract travelsWith(durrance, party).
    Retract willing(durrance, party). Assert at(durrance, ranks). Retract serves(durrance, sault). }
  Relation heldRoom(place). Initially Assert heldRoom(ranks).
  Rule durrance_leaves_place when heldNow(durrance) and at(durrance, ?p) and not heldRoom(?p) { Retract at(durrance, ?p). }
  Rule durrance_gone_told when durranceCalled(ossel) and not spread(durrance_gone)
    and inTessary() says "In the morning Hannelore Rackham stands Thomasin Durrance's boots on the bar of the Muffled Drum, side by side, toes to the door, under the drum with the cloth over it. Nobody drinks there all day." { Assert spread(durrance_gone). }
  Discovery durrance_gone "Sergeant Durrance answered the drum at the eighth night's spring ebb, and walked into the sea.".
  // Whoever is passed over, the weight is the weight: another goes in their place.
  Rule elcock_goes when night(ossel) == 8 and callings(ossel) == 8 and not elcockTaken(ossel) and not interestPaid(ossel)
    and (durranceSpared(ossel) or heldBack(durrance) or durranceKnowsFraud(durrance)) and not heldNow(durrance) {
    Assert elcockTaken(ossel). }
  Rule elcock_told when elcockTaken(ossel) and not knows(party, elcock_known)
    and inTessary() says "In the morning there are twelve pairs of boots on the Watersteps. The eleventh pair is small, and very new, and belongs to Robin Elcock, who was a drummer, and was nineteen." teaches elcock_known { }
  Discovery elcock_known "Durrance was not taken at the eighth night's ebb. Robin Elcock, a drummer of nineteen, was taken in her place.".
  Topic durrance_elcock with durrance "Tell Durrance who went in her place" when knows(actor, elcock_known) and not heldNow(durrance) once {
    Says "'Elcock,' says Durrance. 'Robin Elcock. He couldn't keep time. I used to make him march at the back so the step wouldn't go to pieces.' She looks at her hands. 'He went in my place.' A long silence. 'Right. Then I owe him. And I pay what I owe, which is more than this city does.'".
    On discuss { Assert durranceOwes(durrance). }
  }
  Relation durranceOwes(group).

  // 4. The Treasurer: on the ninth day the Factor goes to see him. Unless someone has given him a reason to live, on
  // the tenth night he walks down the Swatch Stair into the full basin.
  Relation quirePressed(place). Relation quireHope(group). Relation quireDrowned(place). Relation quireWillConfess(group).
  Rule quire_pressed when night(ossel) >= 9 and hour(clock) == 11 and not quirePressed(ossel) { Assert quirePressed(ossel). }
  Observe quire_after at exchequer_room when quirePressed(ossel) and not quireDrowned(ossel) and not quireHope(quire) "Quire has not slept. The bottle is empty. 'The Factor came,' he says to you, or to the room. 'She sat in that chair and told me what would happen to me when the Board learns what I signed. Very kindly. She brought eels.'".
  Topic quire_hope with quire "Tell the Treasurer that the called are alive, and that the debt can still be paid" when knows(actor, held_alive) and knows(actor, promise_weight) and quireConfided(actor) and not quireHope(quire) and not quireDrowned(ossel) once {
    Says "Quire stares at you. 'Alive,' he says. 'Asleep. All of them.' He takes his spectacles off, and puts them on, and takes them off. 'And if the Board keeps the promise, they come home.' He stands up, too fast, and holds the desk. 'Then somebody has to tell the Board why. And it has to be the man who signed.' He looks at the empty strongboxes along the wall. 'I'll do it. On the thirteenth day, in front of all of them. It will finish me. Good.'".
    On discuss { Assert quireHope(quire). Assert quireWillConfess(quire). }
  }
  Rule quire_walks when night(ossel) == 10 and hour(clock) == 4 and quirePressed(ossel) and not quireHope(quire) and not quireDrowned(ossel) {
    Assert quireDrowned(ossel). Retract at(quire, exchequer_room). }
  Rule quire_found when quireDrowned(ossel) and not spread(quire_dead)
    and inTessary() says "Word goes along the Tidewall in the morning: the Treasurer went down the Swatch Stair before dawn, into the full basin, with his coat buttoned. The fishermen brought him up at the ebb. In his coat was a list of a hundred and thirty-eight names." { Assert spread(quire_dead). }
  Discovery quire_dead "Treasurer Quire drowned himself at the Swatch on the tenth night, with the list of the called in his coat.".

  // 5. the chairs: the Board as it stands, and what can move it on the thirteenth day.
  // 6. The attempt on Marrable, the night before the eleventh ebb, if the vote looks as if it might pass.
  Measure support(place). Relation marrableHurt(place). Relation marrableGuarded(place). Relation attemptMade(place).
  Query looksLikely() means quireWillConfess(quire) or amauryWillTestify(party) or carries(party, sault_letter) or at(plum, terraces) or plumHome(ossel).
  Rule attempt_on_marrable when night(ossel) == 10 and hour(clock) == 23 and looksLikely() and not attemptMade(ossel) and at(lightermen, ?p) {
    Assert attemptMade(ossel). Retract at(lightermen, ?p). Assert at(lightermen, marrable_room). }
  Rule attempt_succeeds when attemptMade(ossel) and at(lightermen, marrable_room) and hour(clock) == 0 and not at(party, marrable_room)
    and not marrableGuarded(ossel) and not marrableHurt(ossel) and able(lightermen) {
    Assert marrableHurt(ossel). Retract at(lightermen, marrable_room). Assert at(lightermen, warehouse_floor). }
  Rule attempt_guarded when attemptMade(ossel) and at(lightermen, marrable_room) and hour(clock) == 0 and marrableGuarded(ossel) and not at(party, marrable_room) {
    Retract at(lightermen, marrable_room). Assert at(lightermen, warehouse_floor). Assert attemptFoiled(ossel). }
  Relation attemptFoiled(place).
  Rule attempt_foiled_told when attemptFoiled(ossel) and inTessary() and not spread(attempt_foiled_known)
    says "Word in the morning: three men came to Councillor Marrable's door in the night, and found four veterans of the Third on her step, and went away again." { Assert spread(attempt_foiled_known). }
  Discovery attempt_foiled_known "The Factor's lightermen came for Councillor Marrable in the night and found her step guarded.".
  Rule attempt_met at marrable_room when attemptMade(ossel) and at(lightermen, marrable_room) and at(party, marrable_room) and not assails(lightermen, party) and able(lightermen)
    says "Boots on the step, and the door goes in. Three big men in salt-stiff jerkins, with cudgels, who stop when they see that Marrable is not alone." {
    Assert assails(lightermen, party). }
  Rule marrable_hurt_told when marrableHurt(ossel) and not knows(party, marrable_beaten)
    and inTessary() says "Word comes up from the Terraces in the morning: Councillor Marrable was beaten in her own house in the night, by men nobody saw the faces of. She is alive. She will not be at the Board on the thirteenth day." teaches marrable_beaten { }
  Discovery marrable_beaten "Councillor Marrable was beaten in her house the night before the eleventh ebb, and will not be able to speak at the Board.".
  Topic ask_guard with durrance "Ask Durrance to put some of the Third on Councillor Marrable's step" when not heldNow(durrance) and not marrableGuarded(ossel) and night(ossel) < 11 and (knows(actor, sault_bid) or knows(actor, note_designed) or durranceKnowsSold(durrance)) once {
    Says "'Ysbel Marrable?' says Durrance. 'She carried me off the field at Galt with one arm.' She turns on the bench and whistles, and four of the Third look up from four pots. 'Councillor Marrable's step,' she says. 'Nights. Till the Board sits. Nobody goes in that isn't asked.' They go.".
    On discuss { Assert marrableGuarded(ossel). }
  }

  // 7. The riot: the night before the vote, the Factor's men among the veterans at the Exchequer and up the Terrace
  // Steps, unless Fisk will not lead them, or someone the Muster listens to stands them down.
  Relation fiskTurned(group). Relation riotHappened(place). Relation riotCalmed(place). Relation riotGathering(place).
  Topic turn_fisk with fisk "Tell Fisk what the Factor means to do with the Muster" when knows(actor, sault_bid) and not fiskTurned(fisk) once {
    Says "Fisk's grin goes. He reads it twice in your face. 'Own us,' he says. 'With a note. Like a debt.' He takes the new coat off and looks at it. 'She knew my name before I knew hers.' He drops the coat on the floor. 'There's a thing she wants done the night before the Board sits. Lads up the Terrace Steps with torches, shouting. She said it'd show the Board what eight thousand angry soldiers look like.' He shakes his head. 'Not me. Not now. And I'll tell the others why.'".
    On discuss { Assert fiskTurned(fisk). Retract serves(fisk, sault). }
  }
  Rule riot_gathers when night(ossel) == 12 and hour(clock) == 20 and not fiskTurned(fisk) and not riotGathering(ossel) and not voted(ossel) and at(fisk, ?p) {
    Assert riotGathering(ossel). Retract at(fisk, ?p). Assert at(fisk, scriveners_row). }
  Observe riot_scene at scriveners_row when riotGathering(ossel) and not riotHappened(ossel) and not riotCalmed(ossel) "The Row is full of soldiers. Two hundred of them, more, in red coats, with torches, and more coming up from the Withies. Fisk is on a scrivener's desk shouting about the Board. The crowd is not quite a mob yet. It is waiting for something to make it one.".
  Action calm_riot(actor: group, site: place) "Get up on a desk beside Fisk and talk the Muster down" {
    Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, scriveners_row) and riotGathering(ossel)
      and not riotHappened(ossel) and not riotCalmed(ossel) and not triedCalming(actor).
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert riotCalmed(ossel). }
    On failure { Assert triedCalming(actor). }
    Result "You tell them what is true: that the Board will vote tomorrow, and that if soldiers go up the Terraces tonight with torches, Orme and old Hallam will vote no out of fright, and the Factor knows it, and that is why they are here. It takes a long time, and some of them shout you down, and then one of them says, 'That's right,' and then a lot of them say it. By midnight the Row is empty, and the torches are going home through the Withies in twos and threes.".
    Otherwise "You get up on the desk and they shout you off it.".
  }
  Relation triedCalming(group).
  Action durrance_stands_down(actor: group, site: place) "Ask Durrance to stand the Muster down" {
    Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, scriveners_row) and riotGathering(ossel)
      and not riotHappened(ossel) and not riotCalmed(ossel) and travelsWith(durrance, actor) and not serves(durrance, sault).
    On success { Assert riotCalmed(ossel). }
    Result "Durrance does not get up on anything. She walks into the middle of the Row and says, not very loudly, 'Third Company. Fall in.' And they do, the ones who were Third, from all over the crowd, and the ones who were not stop to watch. She looks at them for a long time. 'Go home,' she says. 'The Board sits tomorrow. Let them do their own dirty work.' And they go.".
  }
  Rule riot_breaks when riotGathering(ossel) and hour(clock) == 23 and not riotCalmed(ossel) and not riotHappened(ossel) {
    Assert riotHappened(ossel). }
  Rule riot_told when riotHappened(ossel) and not knows(party, riot_known)
    and inTessary() says "In the night the soldiers went up the Terrace Steps with torches, two hundred of them, shouting for the Board. Somebody threw a stone through the Council House window. Nobody was killed. By morning the Terraces are full of the Watch, and the Board is frightened, which is what somebody wanted." teaches riot_known { }
  Discovery riot_known "On the night before the vote soldiers went up the Terrace Steps with torches and broke the Council House windows. The Board is frightened.".
  Rule riot_ends when riotCalmed(ossel) and at(fisk, scriveners_row) { Retract at(fisk, scriveners_row). Assert at(fisk, drum_taproom). }
  Rule riot_over when riotHappened(ossel) and at(fisk, scriveners_row) and night(ossel) >= 13 { Retract at(fisk, scriveners_row). Assert at(fisk, muster_hall). }

  // ── The Board sits ────────────────────────────────────────────────────────────────────────────────────────────────
  // On the thirteenth day, from ten in the morning to two in the afternoon, the Board of Moieties hears the question of
  // the Veterans' Settlement. Whoever is in the chamber may lay before it what they have.
  Person board "the Board of Moieties" at council_chamber {
    Role "the councillors in their carved seats". Ancestry human. Numbers 1. Peaceable. Pronouns they.
    Seen when inSession().
  }
  Query inSession() means night(ossel) == 13 and hour(clock) >= 10 and hour(clock) < 14 and not voted(ossel).
  Rule sault_sits when inSession() and at(sault, sault_office) { Retract at(sault, sault_office). Assert at(sault, council_chamber). }
  Rule sault_leaves when not inSession() and at(sault, council_chamber) { Retract at(sault, council_chamber). Assert at(sault, sault_office). }
  Rule marrable_sits when inSession() and at(marrable, marrable_room) and not marrableHurt(ossel) { Retract at(marrable, marrable_room). Assert at(marrable, council_chamber). }
  Rule marrable_home when not inSession() and at(marrable, council_chamber) { Retract at(marrable, council_chamber). Assert at(marrable, marrable_room). }
  Observe session_scene at council_chamber when inSession() "The Board of Moieties is sitting. Seven of the eight carved seats are full; the Salt chair is Factor Sault's, and she sits in it with her arms folded, eating nothing for once. Councillors Greaves and Vantage, the furniture, in velvet. Old Hallam asleep or nearly. Haverick of Paper, red-eyed. Orme of Ship, doing sums on his cuff. Dauntry of Rope, looking at Sault. The public bench is full of red coats. The Speaker is reading the question aloud, slowly, as if hoping it will go away.".
  Observe session_marrable at council_chamber when inSession() and at(marrable, council_chamber) "Ysbel Marrable stands at the Eel chair with her pinned sleeve, waiting her turn to speak, and when it comes she speaks for a quarter of an hour without notes, and does not raise her voice once.".
  Observe session_empty_eel at council_chamber when inSession() and marrableHurt(ossel) "The Eel chair is empty. Everybody looks at it and nobody mentions it.".
  Relation boardSawList(place). Relation boardSawTerms(place). Relation boardSawBid(place). Relation amauryTestified(place).
  Relation quireConfessed(place). Relation plumHome(place). Relation saultExposed(place).
  Action lay_list(actor: group, site: place) "Tell the Board what is on the Treasurer's list" {
    Time 1. Speaker board.
    Requires able(actor) and company(actor) and at(actor, site) and at(board, site) and inSession() and knows(actor, council_knows)
      and not boardSawList(ossel).
    On success { Assert boardSawList(ossel). }
    Result "You tell them: a hundred and thirty-eight names, in the Treasurer's own hand, each with an address and a sum of money sent to the family every month since the summer. Nobody sends money to the mothers of deserters. Orme stops doing sums on his cuff. Haverick looks at Greaves. Greaves looks at the ceiling.".
  }
  Action lay_terms(actor: group, site: place) "Read the Board the terms of the War Note" {
    Time 1. Speaker board.
    Requires able(actor) and company(actor) and at(actor, site) and at(board, site) and inSession() and knows(actor, note_terms)
      and not boardSawTerms(ossel).
    On success { Assert boardSawTerms(ossel). }
    Result "You read them the terms. The calling of the oath of Hethra. The Muster as surety. Silver monthly. The principal at the Feast, in a kept promise of equal weight. When you come to the signatures, three of the councillors in the room are on it, and they know it, and the public bench knows it by the time you have finished the sentence. The noise from the red coats is like surf.".
  }
  Action lay_bid(actor: group, site: place) "Show the Board the Factor's letter" {
    Time 1. Speaker board.
    Requires able(actor) and company(actor) and at(actor, site) and at(board, site) and inSession() and carries(actor, sault_letter)
      and not boardSawBid(ossel).
    On success { Assert boardSawBid(ossel). Assert saultExposed(ossel). }
    Result "You read them the Factor's letter: I will take up the note and with it the Muster, and Tessary will be governed by someone who can count. Factor Sault does not interrupt. When you have finished she stands up, quite unhurried, and looks round the chamber at each of them, and at the public bench. 'Every word,' she says. 'Somebody should.' And walks out. Dauntry of Rope sits for a moment, and then, very slowly, as if testing whether it is allowed, takes his eyes off her empty chair.".
  }
  // Someone they cannot call a liar: the Board is the debtor, and the Valuer may state a debtor's affairs to it.
  Relation boardHeardTally(place).
  Action lay_tally(actor: group, site: place) "Ask the Valuer to tell the Board what the city pledged" {
    Time 1. Speaker tally.
    Requires able(actor) and company(actor) and at(actor, site) and at(board, site) and inSession() and travelsWith(tally, actor)
      and not boardHeardTally(ossel) and not tallyUnravelled(ossel).
    On success { Assert boardHeardTally(ossel). }
    Result "The Valuer walks out into the middle of the floor, under the painting of the Kneeling, and opens the ledger. 'You are the debtor,' they say to the Board, 'so I may state your affairs to you. I am the Ninth Valuer of the Balance. I cannot lie; you may ask anyone below.' Then they read out, in the voice of someone reading a bill of lading, what the city pledged, and when, and how many have been taken, by name, in roll order. Somewhere about the fortieth name Councillor Greaves stops pretending to read his papers. Nobody calls the Valuer a liar. Nobody can think how.".
  }
  Event amaury_testifies at council_chamber when inSession() and amauryWillTestify(party) and not amauryTestified(ossel) "The doors open and the King of Hethra comes in between two guards, in a plain coat, and walks up to the painting of the Kneeling and stands under it. 'I am told,' he says to the Board, pleasantly, 'that this city has been paying for my knees.' And he tells them about the hand on the back of his neck, and the oath of his house, and the silver, and when he has done the Speaker has to call for order three times." then {
    Assert amauryTestified(ossel). }
  Event quire_confesses at council_chamber when inSession() and quireWillConfess(quire) and not quireConfessed(ossel) and not quireDrowned(ossel) "Treasurer Quire gets up from the officers' bench, where he is not supposed to speak, and speaks. 'I signed it,' he says. 'Ten years ago. So did you, Greaves, and you, Vantage, and Dauntry. We put the Muster up as surety for a miracle, and the miracle came, and the bill has come after it.' He puts his list on the Speaker's table. 'Those men are not deserters. They are asleep under the sea, and if this Board keeps its promise to them, they come home. If it does not, the rest follow them.' He sits down. He is shaking. Nobody looks at him." then {
    Assert quireConfessed(ossel). Assert boardSawList(ossel). }
  Rule quire_at_board when inSession() and quireWillConfess(quire) and at(quire, exchequer_room) { Retract at(quire, exchequer_room). Assert at(quire, council_chamber). }
  Rule quire_back when not inSession() and at(quire, council_chamber) { Retract at(quire, council_chamber). Assert at(quire, exchequer_room). }
  Rule amaury_comes when inSession() and amauryWillTestify(party) and at(amaury, kings_rooms) { Retract at(amaury, kings_rooms). Assert at(amaury, council_chamber). }
  Rule amaury_back when not inSession() and at(amaury, council_chamber) { Retract at(amaury, council_chamber). Assert at(amaury, kings_rooms). }

  // Haverick's goose, home.
  Person haverick "Lucius Haverick" at terraces {
    Role "who sits for the Paper Moiety on the Board". Ancestry human. Peaceable. Pronouns he. Manner compassionate.
    Greets "Councillor Haverick turns to you with red eyes and a printed bill in each hand, as if you might be about to tell him something.".
  }
  Topic haverick_goose with haverick "Ask Councillor Haverick what the matter is" when not plumHome(ossel) once {
    Says "'Plum,' says Councillor Haverick. 'Mistress Plum. A goose, sir, a white goose of the old Paper strain, the last of her line. Taken off my lawn on the night of the Muster's homecoming, by persons. I have posted a reward. I have posted three.' He wipes his eyes. 'People think it absurd. A goose. I have no children, sir. I have a goose.'".
  }
  Event plum_home near haverick when following(plum, party) and at(party, terraces) and at(haverick, terraces) and at(plum, ?p) "Mistress Plum sees Councillor Haverick across the Terraces and goes for him at a run, wings out, honking like a wagon with a bad axle, and he goes down on his knees in his good stockings and gathers her up, and she bites him on the ear, and he weeps. 'Anything,' he says to you, over her. 'Anything at all. Name it.' And then, before you can: 'The Settlement? The Paper chair will vote for it. Plum would want me to. She has a great respect for soldiers.' He presses a purse on you as well, without looking at it, and goes back to Plum." then {
    Increase quantity(party, gold) by 10.
    Assert plumHome(ossel). Retract following(plum, party). Retract at(plum, ?p). Assert at(plum, terraces). }

  // The count, at two in the afternoon, in one breath.
  Relation counting(place).
  Rule vote_begins when night(ossel) == 13 and hour(clock) == 14 and not voted(ossel) and not counting(ossel) {
    Assert counting(ossel). Set support(ossel) to 2. }
  Rule vote_marrable when counting(ossel) and marrableHurt(ossel) { Decrease support(ossel) by 1. Assert counted_marrable(ossel). }
  Rule vote_plum when counting(ossel) and plumHome(ossel) { Increase support(ossel) by 1. Assert counted_plum(ossel). }
  Rule vote_list when counting(ossel) and boardSawList(ossel) { Increase support(ossel) by 1. Assert counted_list(ossel). }
  Rule vote_terms when counting(ossel) and boardSawTerms(ossel) { Increase support(ossel) by 1. Assert counted_terms(ossel). }
  Rule vote_quire when counting(ossel) and quireConfessed(ossel) { Increase support(ossel) by 1. Assert counted_quire(ossel). }
  Rule vote_amaury when counting(ossel) and amauryTestified(ossel) { Increase support(ossel) by 1. Assert counted_amaury(ossel). }
  Rule vote_bid when counting(ossel) and boardSawBid(ossel) { Increase support(ossel) by 1. Assert counted_bid(ossel). }
  Rule vote_tally when counting(ossel) and boardHeardTally(ossel) { Increase support(ossel) by 1. Assert counted_tally(ossel). }
  Relation counted_tally(place).
  Rule vote_riot when counting(ossel) and riotHappened(ossel) { Decrease support(ossel) by 2. Assert counted_riot(ossel). }
  Relation counted_marrable(place). Relation counted_plum(place). Relation counted_list(place). Relation counted_terms(place).
  Relation counted_quire(place). Relation counted_amaury(place). Relation counted_bid(place). Relation counted_riot(place).
  Rule vote_carried when counting(ossel) and support(ossel) >= 5 {
    Retract counting(ossel). Assert voted(ossel). Assert votePassed(ossel). }
  Rule vote_lost when counting(ossel) and support(ossel) < 5 {
    Retract counting(ossel). Assert voted(ossel). }
  Rule vote_carried_told when votePassed(ossel) and inTessary() and not spread(vote_known)
    says "At two in the afternoon the Board of Moieties votes on the Veterans' Settlement. The bell on the Council House rings, and goes on ringing, and down in the Withies people come out onto the boardwalks to listen, and somebody shouts, and then everybody does. Land and a pension for every soldier who came home. Carried." { Assert spread(vote_known). }
  Rule vote_lost_told when voted(ossel) and not votePassed(ossel) and inTessary() and not spread(vote_known)
    says "At two in the afternoon the Board of Moieties votes on the Veterans' Settlement, and the Council House bell does not ring. The question is lost. There is no money, says the Speaker's notice on the Landgate board, and the city will not make promises it cannot keep. Under it, by evening, someone has pasted the old recruiting bill: LAND AND A PENSION FOR EVERY MAN WHO COMES HOME." { Assert spread(vote_known). }
  Discovery vote_known "The Board of Moieties has voted on the Veterans' Settlement.".

  // ── The Seal ──────────────────────────────────────────────────────────────────────────────────────────────────────
  // A Settlement voted is not a Settlement kept: eight thousand deeds must pass under the Great Seal. The night the
  // vote is carried, the Factor's men come for it.
  Relation sealStolen(place). Relation sealGuarded(place). Relation sealTried(place).
  Item great_seal "the Great Seal of Tessary" is seal_kind at seals_inner.
  Kind seal_kind "a disc of dark bronze the size of a plate" is treasure worth 0 weighing 4
    described "The Great Seal of Tessary: a pair of scales over a wave, and round the rim, in old letters, WHAT IS SEALED IS DONE.".
  Initially Assert owns(deckle, great_seal).
  Topic deckle_warned with deckle "Warn the Keeper that the Factor's men will come for the Seal tonight" when votePassed(ossel) and not sealGuarded(ossel) and not sealTried(ossel) and (knows(actor, sault_bid) or knows(actor, riot_known) or knows(actor, marrable_beaten)) once {
    Says "Deckle looks at you as if you had suggested the sea might come in. 'The Seal,' he says, 'has not left this room in three hundred years.' Then he looks at the bell glass, and at the door, which has a lock a child could open. 'The Watch is the Factor's,' he says slowly. 'Everybody knows that.' He sits down. 'I shall sit up with it. I shall sit up with it myself. And if you know anyone who would sit up with me, who carries something heavier than a pen...'".
    On discuss { Assert deckleWarned(deckle). }
  }
  Relation deckleWarned(group).
  Topic ask_guard_seal with durrance "Ask Durrance to put a guard on the Office of Seals tonight" when votePassed(ossel) and not heldNow(durrance) and not sealGuarded(ossel) and not sealTried(ossel) and not serves(durrance, sault) once {
    Says "'The Seal,' says Durrance. 'Of course. She'll not let a vote stop her.' She is already on her feet. 'Six of the Third, inside the Office, round the Keeper's table. They can sleep in the morning. They've slept in worse.'".
    On discuss { Assert sealGuarded(ossel). }
  }
  Topic fisk_guard_seal with fisk "Ask Fisk to get some of the lads round the Office of Seals tonight" when votePassed(ossel) and fiskTurned(fisk) and not sealGuarded(ossel) and not sealTried(ossel) once {
    Says "'The Seal,' says Fisk, and laughs. 'That's where she'll go, isn't it. Course it is. Eight thousand deeds and not one of them worth the paper without it.' He is already pulling on his old coat, the red one. 'I know every lad she's paying. I'll have the ones she isn't in the Keeper's room by dark, and the ones she is can come and try it.'".
    On discuss { Assert sealGuarded(ossel). }
  }
  Topic marrable_guard_seal with marrable "Ask Councillor Marrable to put a guard on the Seal tonight" when votePassed(ossel) and not marrableHurt(ossel) and not sealGuarded(ossel) and not sealTried(ossel) and (knows(actor, sault_bid) or knows(actor, riot_known) or knows(actor, marrable_beaten)) once {
    Says "Marrable looks at you for a moment, and then at her one hand. 'She'll go for it tonight,' she says. 'Of course she will.' She stands. 'The Eel Moiety has boatmen who have never once in their lives done what the Watch told them. I'll have six of them in the Keeper's room by dark, with oars.'".
    On discuss { Assert sealGuarded(ossel). }
  }
  Rule seal_raid when votePassed(ossel) and night(ossel) == 13 and hour(clock) == 23 and not sealTried(ossel) and able(lightermen) and at(lightermen, ?p) {
    Assert sealTried(ossel). Retract at(lightermen, ?p). Assert at(lightermen, seals_inner). }
  Rule seal_raid_met at seals_inner when sealTried(ossel) and at(lightermen, seals_inner) and at(party, seals_inner) and not assails(lightermen, party) and able(lightermen) and not sealStolen(ossel)
    says "The door of the Keeper's room is forced from the hall side. Three lightermen, cudgels out, who had expected an old man." {
    Assert assails(lightermen, party). }
  Rule seal_taken when sealTried(ossel) and at(lightermen, seals_inner) and hour(clock) == 0 and not at(party, seals_inner)
    and not sealGuarded(ossel) and not sealHidden(ossel) and able(lightermen) and at(great_seal, seals_inner) {
    Assert sealStolen(ossel). Retract at(great_seal, seals_inner). Assert inside(great_seal, sault_strongbox).
    Retract at(lightermen, seals_inner). Assert at(lightermen, warehouse_floor). }
  Rule seal_bed when sealTried(ossel) and at(lightermen, seals_inner) and hour(clock) == 0 and sealHidden(ossel) and not sealGuarded(ossel) and not at(party, seals_inner) {
    Retract at(lightermen, seals_inner). Assert at(lightermen, warehouse_floor). Assert sealRaidFoiled(ossel). }
  Rule seal_kept when sealTried(ossel) and at(lightermen, seals_inner) and hour(clock) == 0 and sealGuarded(ossel) and not at(party, seals_inner) {
    Retract at(lightermen, seals_inner). Assert at(lightermen, warehouse_floor). Assert sealRaidFoiled(ossel). }
  Relation sealRaidFoiled(place).
  Rule seal_kept_told when sealRaidFoiled(ossel) and inTessary() and not spread(seal_kept_known)
    says "In the night three lightermen broke into the Office of Seals and found the Keeper's room full of people who had been waiting up for them, and left faster than they came." { Assert spread(seal_kept_known). }
  Discovery seal_kept_known "The Factor's lightermen tried for the Great Seal in the night and were driven off.".
  Rule seal_stolen_told when sealStolen(ossel) and not spread(seal_gone)
    and inTessary() says "The Office of Seals does not open in the morning. The Keeper is sitting on the step in his nightshirt with his head in his hands: the Great Seal was taken in the night, and without it not one deed of the Settlement can be sealed." { Assert spread(seal_gone). }
  Discovery seal_gone "The Great Seal of Tessary was stolen the night after the vote. Without it the Settlement's deeds cannot be sealed.".
  Thing sault_strongbox "the Factor's strongbox" at sault_office {
    Holds.
    State locked closed "Behind the Factor's desk stands an iron strongbox the size of a dog kennel.".
    State open "The Factor's strongbox stands open.".
    Change pick "Pick the strongbox" from locked to open needing lockwork at sault_office.
  }
  // Picked in front of her: she lets you, and says what is in it, which is nothing yet.
  Event strongbox_seen near sault when state(sault_strongbox, open) and at(sault, sault_office) and at(party, sault_office) and not sealStolen(ossel)
    "Factor Sault watches you do it, with her chin on her fist. 'Empty,' she says, before the lid is up. 'I keep the money at the pans, where there are forty men who'd notice.' She reaches over and pushes the lid shut with one finger, and the lock goes home. 'Come back after the thirteenth day if you want to see something worth the trouble.'" then {
    Assert state(sault_strongbox, locked). }
  Rule seal_back when sealStolen(ossel) and (keeps(deckle, great_seal) or at(great_seal, seals_inner)) { Retract sealStolen(ossel). Retract inside(great_seal, sault_strongbox). }
  Event seal_returned near deckle when keeps(deckle, great_seal) "The Keeper takes the Seal from you in both hands and holds it against his chest like a child that was lost in a market. Then he puts it under its glass, and rings for his clerks, and they come running, all of them, with their sleeves rolled up." then {
    Retract keeps(deckle, great_seal). Assert at(great_seal, seals_inner). }

  // The deeds: sealed through the fourteenth day if the vote passed and the Seal is under its glass. The deeds for the
  // held cannot be put into their hands in Tessary.
  Relation deedsSealed(place). Relation deedsDelivered(place).
  Rule deeds_sealed when votePassed(ossel) and night(ossel) == 14 and hour(clock) == 16 and not sealStolen(ossel) and at(great_seal, seals_inner) and not deedsSealed(ossel) {
    Assert deedsSealed(ossel). }
  Rule deeds_sealed_told when deedsSealed(ossel) and inTessary() and not spread(deeds_sealed_known)
    says "All day the Office of Seals has worked with its doors shut and every clerk in the Lettered Quarter borrowed; by four in the afternoon the last deed has passed under the Seal, and they begin carrying them out to the Withies in baskets, with the Muster's own sergeants calling the names. Land and a pension. A deed to every hand." { Assert spread(deeds_sealed_known). }
  Discovery deeds_sealed_known "The deeds of the Settlement have been sealed and given out.".
  Item held_deeds "the deeds of the called" is deeds_kind at seals_inner hidden until deeds_for_held.
  Kind deeds_kind "a casket of sealed deeds" is gear worth 0 weighing 3
    described "A cedar casket with a hundred and sixty-odd deeds in it, each sealed with the scales and the wave: land and a pension, made out to soldiers of the Long Muster who are not in Tessary to receive them.".
  Discovery deeds_for_held "The deeds made out to the called cannot be put into their hands in Tessary. They wait in a casket at the Office of Seals for whoever will carry them down.".
  Rule deeds_casket at seals_inner when deedsSealed(ossel) and not knows(party, deeds_for_held)
    says "On the Keeper's table, apart from the rest, stands a cedar casket. 'The deeds of the ones who are not here,' says Deckle. 'The Settlement says every hand. I cannot put these into a hand.' He looks at you. 'I am told that somebody may know where those hands are.'" teaches deeds_for_held { }
  Initially Assert lends(deckle, held_deeds, party).
  Action take_deeds(actor: group, recipient: member, site: place) "Take the casket of the deeds of the called from the Keeper" {
    Speaker deckle. Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(deckle, site) and knows(actor, deeds_for_held)
      and memberOf(recipient, actor) and awake(recipient) and at(held_deeds, site).
    Resolve acquire(held_deeds, deeds_kind, recipient).
    On success { Retract at(held_deeds, site). }
    Result "Deckle puts the casket in your arms. It is heavier than paper should be. 'Every hand,' he says. 'That is what it says. Every hand.'".
  }
  Rule deeds_word when deedsSealed(ossel) and not spread(deeds_word_known) and not at(party, seals_inner)
    and inTessary() says "A boy from the Office of Seals finds you: the Keeper asks for you. There is a casket of deeds that nobody in Tessary can deliver." { Assert spread(deeds_word_known). }
  Discovery deeds_word_known "The Keeper of the Seal has a casket of deeds for the called, and asks for you.".
}

data/adventures/what-tessary-owes/strong:
Module tessary "What Tessary Owes" {
  // ── The Strongrooms ───────────────────────────────────────────────────────────────────────────────────────────────
  // Under the Hall of Oaths, cut in the bedrock of the delta by people of the Mathematical Age: white stone that hums,
  // rooms that weigh whoever stands in them, and at the bottom the Balance, which makes a sworn promise binding in the
  // prima materium. The Scruples keep it. They were the drowned city's clerks; a thousand years beside the Balance have
  // made them pale, long-lived, unable to lie, and ruled like paper. Each pledged their name to it at birth.
  Place strongrooms "the Strongrooms" is site within ossel at 2, 0.
  Place sr_head "the stair-head" is level within strongrooms.
  Place sr_halls "the halls of the Scruples" is level within strongrooms.
  Place sr_deep "the deep rooms" is level within strongrooms.
  Place long_stair "the head of the Long Stair" is room within sr_head at 1, 0 underground.
  Place antechamber "the Antechamber of Weights" is room within sr_halls at 1, 0 underground.
  Place clerks_hall "the Hall of Clerks" is room within sr_halls at 1, 1 underground.
  Place archive "the Archive of Instruments" is room within sr_halls at 0, 1 underground.
  Place defaults_room "the Room of Defaults" is room within sr_halls at 0, 2 underground.
  Place dormitory "the standing dormitory" is room within sr_halls at 2, 1 underground.
  Place comptroller_office "the Comptroller's office" is room within sr_halls at 1, 2 underground.
  Place gallery "the Gallery of Pans" is room within sr_deep at 1, 0 underground.
  Place weighing_chamber "the Weighing Chamber" is room within sr_deep at 1, 1 underground.

  Passage long_stair_way "the Long Stair" is stair between long_stair and antechamber taking 20 minutes.
  Passage ante_door "the inner door of the Antechamber" is doorway between antechamber and clerks_hall.
  Passage archive_arch "the archive arch" is arch between clerks_hall and archive.
  Passage defaults_door "the door of the Room of Defaults" is door between archive and defaults_room.
  Passage dorm_way "the dormitory passage" is doorway between clerks_hall and dormitory.
  Passage office_door "the Comptroller's door" is door between clerks_hall and comptroller_office.
  Passage counting_stair "the Counting Stair" is stair between clerks_hall and gallery.
  Passage chamber_door "the pan door" is door between gallery and weighing_chamber.

  Observe long_stair_scene at long_stair when true "Behind the black wall the dark is dry and smells of stone dust and, faintly, of hot metal. A stair goes down, straight and steep and very long, cut in white rock that gives back a little light of its own. You can hear a hum, below the edge of hearing, in your teeth. The steps are worn in the middle, but not by feet: by something that went up and down them on a groove for a very long time, before the Scruples, before the old city, when whoever cut this place was still here to need it.".
  Observe ante_scene at antechamber when true "A square white room with a floor of a single slab, smooth as a pond. When you step onto it the slab gives, very slightly, as a pan of a balance gives, and steadies. Around the walls ruled lines run at the height of a man's mouth, and as you speak they brighten along their length, and fade, as if writing down what was said. A notice in three scripts, one of them Tessarine: WHAT IS SAID HERE IS HELD.".
  Observe hall_scene at clerks_hall when true "A long white hall full of desks, and at the desks the Scruples, writing: forty or fifty of them in grey, pale as candles, the ruled lines on their hands and faces moving a little as they move. Nobody speaks above a murmur. The pens make a sound like rain. At the end of the hall a stair goes down; beside it, a door with the word COMPTROLLER cut over it, and nothing else.".
  Observe archive_scene at archive when true "Shelves to the ceiling, and the ceiling out of sight. On them, not books, but instruments: slabs, rolls, tablets, sheets of something like black glass, each with a tag. Every promise the Balance has ever held is here, the Scruples say, from the oath of a king to the bet of a fishwife. In the far wall, a door bound in iron with a single word on it in the ruled script, which you cannot read, and which nobody here looks at.".
  Observe defaults_scene at defaults_room when true "A small room, which is the surprise. After the archive's endless shelves, this is a cupboard: one table, one lamp that lights when you come in, one ledger. The ledger is thin. The Scruples do not record many defaults.".
  Observe dorm_scene at dormitory when true "The Scruples sleep standing. Rows of them along the walls in a dim room, eyes closed, hands folded, breathing very slowly and all together. Some have tags at their wrists, like the instruments in the archive. A very young Scruple at the end of a row has a book open under her folded hands.".
  Observe office_scene_c at comptroller_office when true "A white room with nothing in it but a desk, a chair that has never been sat in, and the Comptroller standing behind the desk. On the desk lies one sheet of black glass, ruled, which he has been reading for a very long time.".
  Observe gallery_scene at gallery when true "A gallery cut through the rock with the hum much louder here, a sound you feel in your breastbone. At the far end a door of white metal with no handle stands between two great pans hung on chains from the roof. One pan holds a block of lead cut with nine ruled lines. The other is empty, and the door does not open. Along the wall, on a rack, a set of brass weights, each with its number of lines. Over the door: NINE AGAINST NINE.".
  Observe chamber_scene_w at weighing_chamber when true "The Weighing Chamber is a nave cut so deep into the bedrock that the hum is the only sound left in it. The Balance hangs in it from a beam lost in the dark overhead: two pans each the size of a fishing boat, and a pointer as tall as a mast at rest against a dial of ruled lines. In one pan, very small at the bottom of it, lies a single sheet of black glass. In the other are oaths: not things but the shapes of things, eight thousand faint warm shapes like breath on a cold window, each the size of a hand laid flat. Beyond the Balance, at the end of the nave, is a door with no frame, standing on its own, through which you can see a white floor going on for ever.".
  Observe chamber_level at weighing_chamber when not discharged(ossel) "The pointer leans a hair's breadth toward the black glass, and the oaths in the other pan stir now and then, like sleepers.".

  // ── The Scruples ──────────────────────────────────────────────────────────────────────────────────────────────────
  Person scruples "the Scruples at their desks" at clerks_hall {
    Role "who keep the Balance's books". Ancestry human. Numbers 1. Peaceable. Pronouns they.
    Greets "The nearest of the clerks lifts their pen from the page and waits, without looking up, as if for dictation.".
  }
  Topic scruples_asked with scruples "Ask the clerks at the desks what they are writing" when true once {
    Says "The nearest clerk finishes the line before looking up. 'Promises,' she says. 'As they are kept. A fishwife in the Withies has paid her rent. A ferryman has sworn to his wife on the Watersteps that he will not drink, and has drunk, and it is a small thing and the Balance has noted it. A great deal of the city stands on the old instruments without knowing it, you see. We write what is kept and what is not.' She dips her pen. 'Mostly it is not.'".
  }
  Topic scruples_names with scruples "Ask the clerks what they are called" when true once {
    Says "Three or four of the nearest clerks look up at once, which they evidently find embarrassing. 'By our offices,' says one. 'I am the Third Copyist of Settlements. He is the Clerk of Small Wagers. She has been the Second Tare-Clerk for two hundred years and will be for two hundred more.' He touches his wrist, where there is a pale band like the mark of a ring long worn. 'Our names are on the white floor beyond the Balance. One gives it at birth, as surety for a lifetime's exactness. One does not miss it. One cannot miss what one has never had.' The others go back to their pens, a little too quickly.".
  }
  Topic scruples_defaults with scruples "Ask the clerks about the iron door in the archive" when true once {
    Says "The pens stop, all of them, all down the hall, and then start again a beat later, as if nothing had happened. The Clerk of Small Wagers does not look up. 'The Room of Defaults,' he says, very quietly. 'It is the Comptroller's room. Nobody else goes in.' He dips his pen. 'He goes in once a year, on the anniversary of the Drowning, and stays the night, and comes out in the morning, and nobody asks.' The Second Tare-Clerk says his office, not loudly, and he says nothing more.".
  }
  Topic scruples_surface with scruples "Ask the clerks what they think of the city above" when true once {
    Says "'Tessary?' The Clerk of Small Wagers puts down his pen. 'We write it down. We are very fond of it, in the way one is fond of weather.' He turns back a page. 'This morning a woman in the Withies swore on the Watersteps that she would never speak to her sister again, and at noon she spoke to her sister. The Balance holds the steps; we entered it.' He shakes his head. 'They do it all day. They do not know they are doing it. Sometimes I think the whole of the drowned city went down because nobody up there ever once meant what they said, and sometimes I think that is what I would like most to try.' The Second Tare-Clerk looks at him, and he picks up his pen.".
  }
  Topic scruples_sleep with scruples "Ask the clerks why they sleep standing" when true once {
    Says "'One sleeps as one stands before the Balance,' says the Second Tare-Clerk, without looking up. 'Upright, and ready to be weighed.' A pause. 'Also, there is not room for beds. The Mathematical people built for a thousand clerks and there are eleven thousand of us. The archive takes precedence.'".
  }
  Person copyist "the Fourteenth Copyist" at clerks_hall {
    Role "a very young Scruple with ink on her ruled fingers and a bad habit of looking at the stair". Ancestry human. Peaceable. Pronouns she. Manner cheerful.
    Wants chapbook.
  }
  Topic copyist_surface with copyist "Ask the Copyist about the surface" when true once {
    Says "The Copyist puts her pen down with enormous care. 'Is it true,' she says, very low, 'that up there people say things they do not mean? All the time? And nothing happens?' Before you can answer: 'Someone left a book in the Hall of Oaths with the silver once. Poems. In Tessarine. I have read it two hundred and eleven times.' She looks at the stair. 'There is one about a woman who promises to wait for a sailor and does not. And it is sad. And nobody unravels. I have never understood anything so well.'".
  }
  Relation copyistFriend(group).
  Event copyist_book near copyist when keeps(copyist, ?b) and itemKind(?b, chapbook) "The Copyist takes the chapbook in both hands and does not open it, as if it might go off. 'Twelve new ones,' she says. 'Twelve.' She puts it inside her coat, against her ruled skin. 'I am in your debt. I know exactly how much. If there is a door down here you need opened, I can file for it. I am very good at forms.'" then {
    Assert copyistFriend(party). }
  Discovery release_law "In the Scruples' law a promise is discharged in two ways: when it is kept, and when the one it was made to holds the promisor quit. A release freely given weighs as much as the keeping." {
    Known by copyist, comptroller, tally.
  }
  Topic copyist_release with copyist "Ask the Copyist how a promise can be discharged" when true once {
    Says "'Two ways,' says the Copyist promptly, as if reciting. 'Kept, or released. If I promise you a thing, and give it, it is kept. If I promise you a thing and you say to me, freely, I hold you quit of it, that is a release, and in the Balance it weighs the same as the keeping.' She frowns. 'People forget the second. It is in the first chapter. I think people stop reading after the first page.'".
    On discuss { Assert knows(actor, release_law). }
  }
  Discovery assembly_law "Any Scruple may indict another before the Assembly of the Scruples. The Assembly meets in the Weighing Chamber at the Settlement, and the Notary sits with it. It has happened twice in a thousand years.".
  Topic copyist_assembly with copyist "Ask the Copyist whether a Scruple can be called to account" when knows(actor, compact_read) once {
    Says "The Copyist goes quite still. 'An indictment,' she says. 'Before the Assembly. Any of us may bring one against any other, even the least against the greatest. It is in the second chapter.' She swallows. 'It has happened twice. The Assembly sits in the Weighing Chamber at a Settlement, and the Notary comes out of the Holding to sit with it, and what is found is found. Both times, the one indicted...' She stops, and makes a small gesture of something coming apart. 'Why do you ask?'".
    On discuss { Assert knows(actor, assembly_law). }
  }
  Action copyist_files(actor: group, site: place) "Ask the Copyist to file for the Room of Defaults to be opened to you" {
    Speaker copyist. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(copyist, site) and copyistFriend(actor)
      and state(defaults_lock, locked).
    On success { Assert state(defaults_lock, open). }
    Result "The Copyist fills out a form requesting the form for a request, and then the request, and takes them up the hall to a desk, and from that desk to another, and comes back an hour later with the iron key on a ribbon. 'An inspection of records in the course of an inventory,' she says. 'The Ninth Valuer's inventory. They will not mind. They are very thorough.' She looks at the key. 'Nobody has asked to see that room in my lifetime.'".
  }

  // ── The weighing floor ────────────────────────────────────────────────────────────────────────────────────────────
  // What is said on the Antechamber's floor is held. A company that comes down from Tessary, where people swear about
  // everything, may say something it will have to keep.
  Relation sworeToFind(group).
  Action swear_find(actor: group, site: place) "Say, 'I'll find Davy Teazle if it kills me'" {
    Description "It is the kind of thing anyone says.".
    Time 0.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, antechamber) and knows(actor, davy_went)
      and not sworeToFind(actor) and heldNow(davy).
    On success { Assert sworeToFind(actor). Assert registered(actor). }
    Result "The ruled lines round the walls brighten all along their length, and hold, and fade. The floor under you dips a hair, and steadies. Somewhere far below, something has written it down.".
  }
  Observe swore_noted at antechamber when sworeToFind(party) and travelsWith(tally, party) and at(party, antechamber) "'That was held,' says the Valuer, looking at the walls. 'I would not have said if it kills me.'".

  // ── Lies to the Valuer ──────────────────────────────────────────────────────────────────────────────────────────
  // The Valuer asked a promise of honesty at the Hall of Oaths; below, it is held.
  Relation askedEmployer(group). Relation keptFaith(group). Relation brokeFaith(group).
  Observe tally_asks at antechamber when travelsWith(tally, party) and at(party, antechamber) and hiredBySault(party) and not askedEmployer(party) "On the weighing floor the Valuer stops and turns to you. 'A question,' they say, 'which I should have asked above. Are you in anyone's employ in this matter?'".
  Action tell_tally_truth(actor: group, site: place) "Tell the Valuer that Factor Sault hired you to find out who takes the veterans" {
    Speaker tally. Time 0.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, antechamber) and travelsWith(tally, actor)
      and hiredBySault(actor) and not askedEmployer(actor).
    On success { Assert askedEmployer(actor). Assert keptFaith(actor). }
    Result "The lines on the walls brighten and fade. 'The Factor of the Salt Moiety,' says the Valuer. 'Who carried the silver.' They write it down. 'Thank you. That cannot have been comfortable to say. I will remember that you said it here.'".
  }
  Action lie_to_tally(actor: group, site: place) "Tell the Valuer that you are in no one's employ" {
    Speaker tally. Time 0.
    Grave "You promised the Valuer not to lie to them, and here what is said is held.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, antechamber) and travelsWith(tally, actor)
      and hiredBySault(actor) and not askedEmployer(actor).
    On success { Assert askedEmployer(actor). Assert brokeFaith(actor). Assert forswornParty(actor). }
    Result "The ruled lines round the walls go dark, all of them at once, and the floor under you drops a finger's breadth and does not come up. The Valuer looks at the walls, and at you. They do not say anything. They write something down, and close the ledger, and do not open it again for a long while.".
  }

  // ── The Room of Defaults ──────────────────────────────────────────────────────────────────────────────────────────
  Thing defaults_lock "the iron door" on defaults_door {
    State locked blocking "The door of the Room of Defaults is bound in iron and locked.".
    State open "The iron door of the Room of Defaults stands open.".
    Change pick "Pick the lock of the iron door" from locked to open needing lockwork at archive.
  }
  Action tally_opens(actor: group, site: place) "Ask the Valuer to open the Room of Defaults in the course of the inventory" {
    Speaker tally. Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, archive) and travelsWith(tally, actor)
      and knows(actor, compact_read) and state(defaults_lock, locked) and not brokeFaith(actor).
    On success { Assert state(defaults_lock, open). }
    Result "The Valuer looks at the iron door for some time. 'The compact of the old city is not on my inventory,' they say. 'But the city of Tessary claims the old city's oaths as its heir, and so its defaults are the city's defaults, and so they bear on the collateral.' They lay a ruled hand flat on the iron, and the lock turns over inside the door with a sound like a slow bell. 'I find that I want to see it,' they say. 'I note that I want to.'".
  }
  Discovery default_record "The Room of Defaults records the drowned city's compact as broken eleven hundred years ago, in the Comptroller's own hand: 'The sea had the city. The ledger did not keep. Default entered by the clerk who swore it.' Beside the entry, in the same hand, a reckoning runs down the margin for a thousand years, and ends in fresh ink: 'Tessary, heir. War note drawn. Repayment at the weight of a people's promise. At foreclosure, eight thousand oaths.' And under it, a single word: 'Balanced.'" {
    Source defaults_ledger "the thin ledger on the table" at defaults_room readable by party.
  }
  Discovery note_designed "The War Note was drawn to fail. The Comptroller swore the drowned city's compact eleven hundred years ago and could not keep it; his default left a hole in the Balance's ledger. He set Tessary's repayment at a weight its heir could never meet, so that at foreclosure the Muster's oaths would fall into the Holding and fill the hole he made.".
  Observe designed_seen near party when knows(party, default_record) and knows(party, note_terms) and knows(party, promise_weight) and not knows(party, note_designed) "You read the margin again with the War Note's terms in your head. The weight of a people's promise, and a city with exactly one such promise in its books and no money to keep it. Eight thousand oaths at foreclosure. Balanced. The repayment was never meant to be made." teaches note_designed.
  Relation tallySawDefaults(place).
  Event tally_reads_defaults at defaults_room when travelsWith(tally, party) and knows(party, default_record) "The Valuer reads the ledger over your shoulder, and then reads it again, alone, with their finger on the lines, the way a child reads. When they straighten, the ruled lines on their face have gone faint, as if something had rubbed at them. 'He swore the compact,' they say. 'He did not keep it. And he has drawn the city's note so that it cannot be paid, so that the Muster will fall in and cover it.' A long pause. 'A promise made in order to be broken is not a promise. It is the first thing we are taught. It is the gravest thing one of us can do.' They close the ledger very gently. 'I do not know what I am going to do.'" then {
    Assert tallySawDefaults(ossel). }

  // ── The Gallery of Pans ─────────────────────────────────────────────────────────────────────────────────────
  // The door to the Weighing Chamber opens when the empty pan is made to balance the nine-line lead: a test every
  // Scruple passes as a child. The brass on the rack is two, three, four and five.
  Thing door_pan "the empty pan" at gallery {
    Holds.
    State hanging "The empty pan hangs high on its chains, the lead's pan low.".
  }
  Initially Assert receptacle(door_pan).
  Kind brass_two "a brass weight of two lines" is gear worth 1 weighing 2 described "A flat brass weight with two ruled lines cut across it.".
  Kind brass_three "a brass weight of three lines" is gear worth 1 weighing 3 described "A flat brass weight with three ruled lines cut across it.".
  Kind brass_four "a brass weight of four lines" is gear worth 1 weighing 4 described "A flat brass weight with four ruled lines cut across it.".
  Kind brass_five "a brass weight of five lines" is gear worth 1 weighing 5 described "A flat brass weight with five ruled lines cut across it.".
  Item w_two "a brass weight of two lines" is brass_two at gallery.
  Item w_three "a brass weight of three lines" is brass_three at gallery.
  Item w_four "a brass weight of four lines" is brass_four at gallery.
  Item w_five "a brass weight of five lines" is brass_five at gallery.
  Query panBalanced() means (inside(w_four, door_pan) and inside(w_five, door_pan) and not inside(w_two, door_pan) and not inside(w_three, door_pan))
    or (inside(w_two, door_pan) and inside(w_three, door_pan) and inside(w_four, door_pan) and not inside(w_five, door_pan)).
  Thing counter_door "the white door" on chamber_door {
    State shut blocking "The white door between the pans has no handle, and does not open.".
    State open "The white door stands open, the pans level on their chains.".
  }
  Rule door_balances at gallery when panBalanced() and state(counter_door, shut)
    says "The empty pan sinks, slowly, and the lead rises to meet it, and the two hang level. The pointer between them settles on its mark. Without any sound, the white door opens." { Assert state(counter_door, open). }
  Rule door_unbalances when not panBalanced() and state(counter_door, open) and not chamberOpened(ossel) { Assert state(counter_door, shut). }
  Relation chamberOpened(place).
  Observe pan_wrong at gallery when not panBalanced() and inside(?w, door_pan) "The pan has something in it, and has moved, but the pointer between the pans has not come to its mark.".

  // The Weights: bailiffs of stone and bronze, who seize the forsworn and those in default.
  Species weight_kind "a Weight" like bronze_construct temperament obedient
    described "A figure of bronze and white stone twice the height of a man, with a pair of scales cast into its chest where a heart would be. It does not move unless something is owed.".
  Person weights "the Weights" at gallery {
    Role "two bailiffs of bronze and white stone, standing either side of the door". Species weight_kind. Level 8. Numbers 2. Pronouns they.
    Comes "The Weights come down the gallery toward you, not fast, with their bronze hands open: not to strike, to take hold.".
  }
  // Bailiffs seize; they do not kill. Whoever they take is carried up the Long Stair and put out through the black wall,
  // which does not open to them again.
  Initially Assert takesPrisoners(weights).
  Relation barredBelow(group).

  Initially Assert tolerates(weights, party).
  Initially Assert peaceable(weights).
  // The Weights do not fight. They take hold, the way the tide does, and nobody has ever made them let go.
  Rule weights_seize when forswornParty(party) and at(party, ?p) and at(weights, ?p) and not barredBelow(party)
    says "The Weights turn their heads, both together, with a grinding of bronze. The scales in their chests have tipped. They come down the gallery toward you, not fast, with their bronze hands open, and there is nothing to be done about it at all: you might as well fight the sea. The hands close on you very gently, the way a careful man picks up something that might break. You are carried, a long way, up the Long Stair in the dark, and set down on the floor of the Hall of Oaths, and when you turn round there is only the black wall, and it is cold." {
    Retract at(party, ?p). Assert at(party, oath_court). Assert barredBelow(party). }

  // ── The Comptroller ───────────────────────────────────────────────────────────────────────────────────────────────
  // Eldest of the Scruples. He swore the drowned city's compact, and has kept the ledger for eleven hundred years
  // since he failed to keep his word. He cannot lie. He can choose what to say.
  Person comptroller "the Comptroller" at comptroller_office {
    Role "eldest of the Scruples, tall and thin as a rule, the ruled lines on his face so close they look like shading". Ancestry human. Calling mage. Level 9. Peaceable. Pronouns he. Manner proud.
    Greets "The Comptroller looks up from the black glass. His eyes are the colour of old paper. 'You have come down,' he says, 'from the debtor's city. Very well. You may ask.'".
  }
  Topic comptroller_note with comptroller "Ask the Comptroller about the War Note" when true once {
    Says "'A loan,' says the Comptroller. 'The city wished to call an oath its predecessors were owed, and could not pay for the calling. We lent it, against security, as is our office.' He touches the black glass. 'When an oath is called, the ledger is drawn down by its weight, and the weight must be restored. That is all the Balance is: a thing that must come level.' He looks at the glass a while longer than the sentence needs. 'It has not been level for some time. I am not concerned with your city's poverty. I am concerned with that.'".
    On discuss { Assert knows(actor, note_terms). }
  }
  Relation comptrollerAlly(group). Relation brokerSuspended(place).
  Topic comptroller_bid with comptroller "Tell the Comptroller that the Factor means to buy the note" when knows(actor, sault_bid) and not comptrollerAlly(actor) once {
    Says "For the first time the Comptroller looks at you directly. 'Buy it,' he says. 'At foreclosure.' The ruled lines on his face tighten. 'It is lawful. A note in default may be taken up by whoever pledges its weight. And then the holder may call the collateral out, to service as sworn, and the oaths leave the Holding, and the weight with them.' He is silent a while. 'That must not happen. Bring me what she has written, in her hand, and I will suspend the broker she has suborned. Whatever else she does, she will have to do in person, in this chamber, on the night.' He bows very slightly. 'In this, we want the same thing.'".
    On discuss { Assert comptrollerAlly(actor). }
  }
  Event broker_suspended near comptroller when keeps(comptroller, sault_letter) "The Comptroller reads the Factor's letter once, and lays it on the black glass, and the glass takes it, the way still water takes a dropped page. 'The Broker of the Fourth Pan is suspended,' he says. 'If the Factor wants the note, she will come to the Weighing Chamber on the night of the Settlement and pledge in person.' He looks at you. 'Thank you. The ledger is in your debt. I do not say that often.'" then {
    Assert brokerSuspended(ossel). }
  Relation durranceSpared(place). Relation promisedLetter(group).
  Topic comptroller_spare with comptroller "Ask the Comptroller to strike Sergeant Durrance from the next page" when knows(actor, durrance_next) and night(ossel) < 8 and not durranceSpared(ossel) and not heldNow(durrance) once {
    Says "'The page will be read,' says the Comptroller. 'Twelve oaths. The weight is the weight.' He considers you. 'But the order of the roll is a convenience, not a term. I can have the sergeant passed over. Elcock, who is next, will go in her place, and the one after Jessup in his.' He lets that sit. 'I will do it for a promise, made here, where it is held: that you will bring me, before the Settlement, the Factor's bid in her own hand.'".
  }
  Action promise_comptroller(actor: group, site: place) "Promise the Comptroller the Factor's letter before the Settlement, so that Durrance is passed over" {
    Speaker comptroller. Time 1 minute.
    Grave "A promise made to the Comptroller is held by the Balance. If it is not kept by the Feast, it is broken; and Elcock goes into the sea in Durrance's place.".
    Requires able(actor) and company(actor) and at(actor, site) and at(comptroller, site) and knows(actor, durrance_next)
      and night(ossel) < 8 and not durranceSpared(ossel) and not heldNow(durrance) and not keeps(comptroller, sault_letter).
    On success { Assert durranceSpared(ossel). Assert promisedLetter(actor). Assert registered(actor). }
    Result "The Comptroller takes a pen and writes one line on the black glass, and the glass takes the ink. 'Durrance, A., passed over,' he says. 'Elcock, R., to be called in her place.' He does not look up. 'Elcock is nineteen. He was a drummer. I mention it because you will want to know what you have done, and I do not say things that are not so.'".
  }
  Rule letter_promise_kept when promisedLetter(party) and keeps(comptroller, sault_letter) { Retract promisedLetter(party). Assert keptFaith(party). }
  Rule letter_promise_broken when promisedLetter(party) and feastEve() and hour(clock) >= 18
    says "Somewhere under the sea a line is drawn through a promise you made, and you feel it, exactly as if a cold hand had been laid flat between your shoulders and then taken away. The Comptroller's letter was not brought." {
    Retract promisedLetter(party). Assert forswornParty(party). }
  Topic comptroller_drowned with comptroller "Ask the Comptroller about the drowned city's compact" when knows(actor, compact_read) and not knows(actor, note_designed) once {
    Says "The Comptroller does not move at all. 'That is not a matter of the note,' he says. 'You will not find me willing to discuss it.' And then, because he cannot leave a false impression standing, and you see him know it: 'I do not say that there is nothing to discuss. I say that I will not discuss it.' He looks back down at the black glass. 'You may go.'".
  }
  Relation comptrollerConfronted(group). Relation silenceOffered(group). Relation swornSilence(group).
  Topic comptroller_confronted with comptroller "Put the reckoning in the Room of Defaults to the Comptroller" when knows(actor, note_designed) and not comptrollerConfronted(actor) once {
    Says "The Comptroller listens to the end. He cannot say it is not so, and he does not try. 'I swore the compact,' he says. 'I was younger than your Valuer. The sea came over the old city in one night and the ledger did not keep, and I wrote the default in my own hand, as one must.' He lays his hand on the black glass. 'Since then there has been a hole in the ledger the shape of a city. Your fishermen have seen what shows through it, on the nights the stars past the bar are wrong.' He lays his ruled hand flat on the glass, as if keeping something down. 'I have tried to fill it honestly for eleven hundred years. One cannot. Nobody owes that much.' He looks up. 'Then your city came down the stair, poor, at war, frightened, with six signatures and no silver. I drew the note so that it would fail. Eight thousand sleepers, unharmed, against a hole I made.' A pause, exact. 'I am not proud of it. I would draw it again. I should like you to hold both of those at once, as I do.'".
    On discuss { Assert comptrollerConfronted(actor). Assert silenceOffered(actor). }
  }
  Action swear_silence(actor: group, site: place) "Promise the Comptroller your silence, and take Davy Teazle out of the Holding for it" {
    Speaker comptroller. Time 1 minute.
    Grave "A promise of silence made here is held. If you speak of the reckoning to anyone after, you are forsworn.".
    Requires able(actor) and company(actor) and at(actor, site) and at(comptroller, site) and silenceOffered(actor)
      and not swornSilence(actor) and heldNow(davy) and not indictmentFiled(ossel).
    On success { Assert swornSilence(actor). Assert registered(actor). Assert redeemedByComptroller(davy). }
    Result "'Then it is held,' says the Comptroller, and writes on the black glass. 'Teazle, D., private, redeemed from the Holding by order of the Comptroller.' He does not look up. 'He will wake on the Watersteps at the night ebb, with his boots beside him. Go home. You have done a good thing for one family, and nothing at all for the rest, and you knew that when you chose.'".
  }
  Relation redeemedByComptroller(group). Relation indictmentFiled(place).

}

data/adventures/what-tessary-owes/voices:
Module tessary "What Tessary Owes" {
  // ── Where people are in the day ───────────────────────────────────────────────────────────────────────────────────
  // The Factor eats her supper on the Tidewall every evening, from a paper cone, standing up; Wick works Lowtide at the
  // day's ebb with the other mudlarks.
  Rule sault_to_wall when hour(clock) >= 18 and hour(clock) < 21 and at(sault, sault_office) and not inSession() and not feastEve() {
    Retract at(sault, sault_office). Assert at(sault, tidewall). }
  Rule sault_from_wall when (hour(clock) >= 21 or hour(clock) < 18) and at(sault, tidewall) {
    Retract at(sault, tidewall). Assert at(sault, sault_office). }
  Event sault_eels near sault when at(sault, tidewall) "Factor Sault is leaning on the parapet with a paper cone of hot eels, watching her ships come in on the evening tide, and nodding to every second person who passes. Most of them nod back.".
  Rule wick_to_forum when hour(clock) >= 10 and hour(clock) < 14 and at(wick, withies) { Retract at(wick, withies). Assert at(wick, forum). }
  Rule wick_from_forum when (hour(clock) >= 14 or hour(clock) < 10) and at(wick, forum) { Retract at(wick, forum). Assert at(wick, withies). }
  Observe wick_digging near wick when at(wick, forum) "Wick is up to his knees in a drain at the edge of the square with a rake, a bucket and an expression of total professional absorption.".
  Observe wick_swept near wick when sweptOnce(party) "Wick looks you up and down. 'You got rolled,' he says, delighted. 'Didn't you. Out through the Swatch. Everybody does once.' He considers. 'Most people only once.'".
  Discovery wick_teased "Wick knows you were caught by the flood.".

  // ── Sergeant Durrance, on the way ─────────────────────────────────────────────────────────────────────────────────
  Event durrance_forum at forum when travelsWith(durrance, party) "Durrance stands at the edge of the Forum and looks across it, the way she would look at a field before crossing it under fire. 'Out past the colonnade,' she says, 'across the Forum, into the Hall. Wick's route.' She sets off across the slabs in a straight line, not hurrying, as if she were walking it for someone.".
  Event durrance_hall at oath_court when travelsWith(durrance, party) and not benighted(party) "Durrance goes to the end wall and puts her hand flat on the black stone, the way she put it on the Stone in the Yard nineteen years ago, and takes it away again quickly, as if it were hot. 'Same stone,' she says. 'Same as the Yard.' She wipes her hand on her coat. 'Well. Now I know what I swore on.'".
  Event durrance_landing at landing when travelsWith(durrance, party) and at(slake, landing) "Durrance and Bettany Slake look at each other across the quay, two people who have each run something hard for a long time, and something like respect passes between them without either of them saying anything.".
  Event durrance_floor at antechamber when travelsWith(durrance, party) "Durrance looks at the ruled lines round the walls, and at the notice, and closes her mouth with a snap. 'Not a word,' she says under her breath, and the lines brighten along their length at every syllable of it. She glares at them. After that she doesn't speak at all until you are off the floor.".
  Event durrance_chamber at weighing_chamber when travelsWith(durrance, party) "Durrance stands a long time looking up into the second pan, at the faint warm shapes of the oaths. 'That's us,' she says at last. 'Eight thousand.' She shakes her head. 'You'd think we'd weigh more.'".
  Event durrance_ranks at ranks when travelsWith(durrance, party) "Durrance walks slowly down the Third Company's file, saying the names under her breath as she passes each face. Pargeter. Haskett. Moll Bryer. The Lucey twins. She stops in front of a boy at the end, and straightens his collar, and goes on.".
  Event durrance_ranks_elcock at ranks when travelsWith(durrance, party) and elcockTaken(ossel) "At the end of the file Durrance stops in front of a thin boy with a drummer's calluses on his hands. 'Elcock,' she says. 'You never could keep time.' She stands there a while. Then she comes back, and does not say anything for some time.".
  Event durrance_yard at legion_yard when travelsWith(durrance, party) and not feastEve() "Durrance stops at the Yard gate and does not go any further. She looks at the Oath Stone across the empty parade ground for a long moment. 'Nineteen years,' she says. 'Come on. I don't like it here.'".

  // ── The Valuer, on the way ──────────────────────────────────────────────────────────────────────────────────────
  Event tally_drum at drum_taproom when (travelsWith(tally, party) or at(tally, drum_taproom)) and not durranceCalled(ossel) and not heldBack(durrance) "The Valuer stands looking up at the drum over the bar with the black cloth tied over its head. 'That drum beat the Third Company's muster on the day it swore,' they say. 'The calling speaks to what an oath was sworn by: the stone, and the drum. I note that a cloth does not stop it.' A pause. 'I would not be surprised if it answered to the drum in other ways. I make no recommendation.'".
  Event tally_forum at forum when travelsWith(tally, party) "The Valuer stands in the middle of the Forum and turns slowly round, looking at everything. 'It is smaller than in the records,' they say. 'Everything is.' They bend and touch a paving slab with one ruled finger, very gently, as if it might mind.".
  Event tally_landing at landing when travelsWith(tally, party) "The Valuer looks at the ebb-runners' boat for a long time. 'The niche by the black wall,' they say. 'Where the silver was left. Every month for ten years I took it out and weighed it and entered it. I did not think about who carried it.' They write something down.".
  Event tally_stone at legion_yard when travelsWith(tally, party) "The Valuer goes straight to the Oath Stone and lays a hand on it, and the fine ruled lines cut in its face brighten for a moment under their palm, and fade. 'An instrument of the Balance,' they say. 'Salvaged. The city does not know what it has. It swears its soldiers on it the way a child plays with a sword.'".
  Event tally_chapel at chapel when travelsWith(tally, party) "The Valuer walks slowly under the hanging weights, reading them. 'All accurate,' they say. Then they look up at the saint over the altar, holding his scales level, and stand quite still. 'There was a clerk who went up,' they say at last, 'when the old city drowned. We are told about him in the nursery. As a warning.' They look at the scales a while longer. 'I had not known he was a saint.'".
  Event tally_tags at tags when travelsWith(tally, party) "The Valuer walks down the avenue of tags with their eyes fixed straight ahead. 'I will not look for mine,' they say, before you can ask. 'One is not shown one's name.' They walk a little faster.".
  Event tally_ranks at ranks when travelsWith(tally, party) "The Valuer goes along the files with the ledger open, checking the faces against the names, as they have done in the Withies every day. Every one is there. When they reach the end they close the ledger and stand for a moment with their hand on it, and their face does something you have not seen it do before.".
  // "Wait here a minute."
  Relation tallyWaiting(place). Measure tallyWaitFrom(place). Measure tallyWaited(place).
  Action tally_wait(actor: group, site: place) "Ask the Valuer to wait here a minute" {
    Speaker tally. Time 0.
    Requires able(actor) and company(actor) and at(actor, site) and travelsWith(tally, actor) and not tallyWaiting(ossel).
    On success { Retract travelsWith(tally, actor). Assert at(tally, site). Assert willing(tally, actor). Assert tallyWaiting(ossel).
      Set tallyWaitFrom(ossel) to watch(clock) * 10. }
    Result "'A minute,' says the Valuer, and opens the ledger.".
  }
  Rule tally_rejoined when tallyWaiting(ossel) and travelsWith(tally, party) { Retract tallyWaiting(ossel). }
  Rule tally_counts when tallyWaiting(ossel) and perceives(party, tally) and watch(clock) * 10 - tallyWaitFrom(ossel) > 30 and tallyWaited(ossel) == 0 {
    Set tallyWaited(ossel) to watch(clock) * 10 - tallyWaitFrom(ossel). }
  Rule tally_says_minutes near tally when tallyWaiting(ossel) and tallyWaited(ossel) > 0
    says "'You said a minute,' says the Valuer, closing the ledger on their finger. 'It has been {tallyWaited(ossel)} minutes. I have noted it.' A pause. 'I do not mind. I note it because it is so.'" {
    Retract tallyWaiting(ossel). Set tallyWaited(ossel) to 0. }
  Rule tally_waits_quietly when tallyWaiting(ossel) and perceives(party, tally) and watch(clock) * 10 - tallyWaitFrom(ossel) <= 30 and tallyWaited(ossel) == 0 { Retract tallyWaiting(ossel). }

  // ── What the careless swear on the weighing floor costs ───────────────────────────────────────────────────────────
  Relation foundDavy(group).
  Rule found_davy when sworeToFind(party) and at(party, ranks) and not foundDavy(party) { Assert foundDavy(party). Assert keptFaith(party). }
  Rule swear_unkept when sworeToFind(party) and matured(ossel) and not foundDavy(party) and heldNow(davy) and not forswornParty(party)
    says "Somewhere under the sea a line is drawn through something you said once on a white floor without thinking: I'll find Davy Teazle if it kills me. You did not find him. It did not kill you. The Balance does not care which part you meant." {
    Assert forswornParty(party). }

  // ── What the Factor does with what she is given ───────────────────────────────────────────────────────────────────
  // With the Valuer's pages she knows the roll order, and goes to Durrance two days sooner.
  Rule silver_offered_early when saultInformed(sault) and night(ossel) >= 3 and hour(clock) == 12 and not saultOffered(ossel) and not heldNow(durrance) {
    Assert saultOffered(ossel). }
  // A Keeper warned takes the Seal to bed with him.
  Relation sealHidden(place).
  Rule seal_hidden when deckleWarned(deckle) and votePassed(ossel) and night(ossel) == 13 and hour(clock) == 22 and not sealHidden(ossel) and not sealGuarded(ossel) {
    Assert sealHidden(ossel). }

  // ── What the King knows of the war ────────────────────────────────────────────────────────────────────────────────
  Discovery salt_springs "What the war was fought for: the salt springs of Hethra on the upper Ossel, which make a white salt finer than anything from the Pans. Nobody in Tessary knows how to work them except, the King says, one person who has asked him about them twice.".
  Topic amaury_springs with amaury "Ask the King what the war was really for" when amauryPlayed(actor) or amauryWillTestify(actor) once {
    Says "'Salt,' says the King, as if it were obvious. 'The springs at Hethra-under-Fell. White salt, fine as flour; your Pans make grey. Your Board wanted them because they are worth more than the Pans. Your Factor wanted them because she understood that.' He moves a piece. 'She has written to me. Twice. Very civil letters, about the working of brine. She is the only person in this city who has asked me a sensible question in a year.' He smiles. 'If I were your Board I would be frightened of her. I am not your Board. I find her rather good company.'".
    On discuss { Assert knows(actor, salt_springs). }
  }

  // ── Quiet ─────────────────────────────────────────────────────────────────────────────────────────────────────────
  // Supper at the Teazles', once, of an evening: eels, and the peg with the coat on it.
  Relation suppedWithTeazles(group).
  Action sup_with_teazles(actor: group, site: place) "Stay for supper with the Teazles" {
    Speaker nan. Time 6.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, teazle_room) and at(nan, teazle_room)
      and hour(clock) >= 18 and hour(clock) < 22 and knows(actor, davy_went) and not suppedWithTeazles(actor).
    On success { Assert suppedWithTeazles(actor). Increase quantity(actor, rations) by 1. }
    Result "Nan does not ask you to stay; she puts a third bowl on the table and that is that. Eels, stewed with onions, and bread, and a jug of something brown. Wick talks the whole time, about the bell that rings under the basin on stormy nights (he has heard it; his nan has heard it; nobody believes either of them), about a coin he nearly found, about the clerk in grey, who he has decided is lonely. Nan says almost nothing. Once, without seeming to notice she is doing it, she reaches out and straightens the red coat on its peg. When you go she gives you the end of the loaf wrapped in a cloth, for tomorrow.".
  }
  // Dawn at the Oath Stone, with Durrance, before the Feast.
  Event durrance_dawn at legion_yard when travelsWith(durrance, party) and hour(clock) >= 5 and hour(clock) < 8 and not feastEve() "In the first grey light the Yard is empty and the shell is wet. Durrance walks out to the Oath Stone and stands in front of it with her hands behind her back, the way she would stand in front of an officer. 'I was sixteen,' she says. 'I lied about it. The sergeant knew; he slapped my back anyway. My mother cried all the way home and then made me a cake.' She looks at the ruled lines on the Stone. 'I'd do it again. That's the trouble with me. Come on, before somebody sees us and thinks I'm sentimental.'".
  // In the Holding, a singer's voice in a jar: pledged against her sweetheart's coming home, and never collected.
  Thing voice_jar "a stoppered jar with a tag" at folded_lake {
    State stoppered "On the white floor by the folded lake stands a plain stoppered jar of brown glaze with a tag on its neck: a voice, pledged by a woman of the Withies a hundred and ninety years ago against her sweetheart's return from the sea. He came home. The tag says she never came for it.".
    State unstoppered "The jar by the folded lake stands unstoppered, and very faintly, if you bend close, someone is still singing in it.".
    Change listen "Take the stopper out of the jar and listen" from stoppered to unstoppered.
  }
  Event jar_sings at folded_lake when state(voice_jar, unstoppered) "Out of the jar comes a woman's voice, small and clear and far away, singing to nobody in particular, the way people sing over washing. It is 'Sally of the Withies', the old ballad of the girl who waited for a sailor, that Pitch sells in a penny chapbook and that the Copyist under the sea has read two hundred and eleven times. In the jar she has got to the third verse, where he comes home. She sings it twice. Then she starts again from the beginning.".
}

data/adventures/what-tessary-owes/ways.k:
Module tessary "What Tessary Owes" {
  // ── The Factor at dusk ────────────────────────────────────────────────────────────────────────────────────────────
  // She seeks out whoever she has hired, once, on the Tidewall, with eels; and if she has not hired them, she looks
  // them over anyway. What she says depends on what they have done to her.
  Event sault_dusk near sault when at(sault, tidewall) and night(ossel) >= 2 and hiredBySault(party) and not saultExposed(ossel) and not voted(ossel) "Factor Sault sees you before you see her, and holds out the paper cone. 'Eel,' she says. 'Go on. You look like someone who's been under the sea.' She watches her ships come in for a while. 'I know what you've found, roughly. I know what the Board did ten years ago, exactly; I carried the silver. I'll tell you what I think, and then you can tell me I'm a monster.' She eats an eel. 'The Board will vote no. Not because they're wicked. Because they've never once had to pay for anything. And when they vote no, those lads go under the sea, all of them, and stay there, unless someone with the weight to do it takes up the note.' She licks salt off her thumb. 'When the Feast's done I'll need someone who's been down there and isn't afraid of clerks. Think about it. I'll be here every evening. I like the light.'".
  Event sault_dusk_letter near sault when at(sault, tidewall) and carries(party, sault_letter) and not saultExposed(ossel) and not voted(ossel) "Factor Sault looks at the letter in your hand, with her own wax on it, broken. 'Ah,' she says. 'Bettany never could keep a box shut.' She doesn't ask for it back. 'Well, you've read it. Every word's true, which is more than the Board can say for anything it ever signed.' She offers you the cone of eels. 'Keep it. Show it to whoever you like. I'd rather be hated for what I mean than liked for what I don't.'".
  Relation saultShaken(place).
  Topic sault_father with sault "Ask the Factor about the First Muster's plaque" when knows(actor, first_muster) and not saultShaken(ossel) once {
    Says "For the first time the Factor doesn't answer straight away. 'My father,' she says. 'Third rank, First Muster, the Salt War. They promised them the south bank. Good land, the south bank. They gave them that plaque, at knee height so you'd have to kneel to read it, and the right to rake salt for the Board at the Board's price, for ever.' She turns the paper cone in her hands. 'He raked for twenty-two years and died owing the company store four marks. I was fourteen. I raked it off. Then I bought the store. Then I bought the pans.' She looks out at the Pans steaming in the dusk. 'So when you tell me the city will keep its promise to the Long Muster, I'll laugh, and you'll forgive me. I've seen this city keep a promise. It's green, and it's at knee height.'".
  }
  Topic sault_designed with sault "Tell the Factor that the War Note was drawn to fail" when knows(actor, note_designed) and not saultShaken(ossel) once {
    Says "Factor Sault hears you out without eating anything. Then she laughs, once, a short bark that makes the fishermen along the parapet look round. 'Rigged,' she says. 'From the start. The Board too stupid to see it, and me too clever by half.' She is quiet a long time. 'Ten years I carried that silver down a tunnel and never once asked what the other side wanted with it.' She turns to you. 'It changes nothing. A rigged game is still the only game in town, and I'll still be at the table when the note falls in.' And then, much lower: 'It changes what I'd be buying. Tell me what you'd have me do instead, and I'll listen. Once.'".
    On discuss { Assert saultShaken(ossel). }
  }

  // ── The drowned city's own way down ───────────────────────────────────────────────────────────────────────────────
  // Under the plunge-pool a drain runs down through the bedrock into the cistern the Scruples draw their water from,
  // behind the standing dormitory: the old city's clerks went down to the Balance by it before the black wall was
  // sealed. The Forsworn stand over it. There are three ways past them: through them; round them, quietly; or by
  // giving them what they hold out their hands for, which is the weight of a promise that was kept.
  Place scruples_cistern "the Scruples' cistern" is room within sr_halls at 3, 1 underground.
  Passage plunge_drain "the drain under the plunge-pool" is crawl between plunge and scruples_cistern taking 20 minutes.
  Passage cistern_way "the cistern steps" is steps between scruples_cistern and dormitory.
  Observe scruples_cistern_scene at scruples_cistern when true "A round cistern of white stone, half full of black water so still that the lamp-light lies on it like a coin. A crawl comes in high up on one side, from the dark, cut by hands much older than the Scruples'; steps on the other side go up toward the sound of very slow breathing.".
  Observe plunge_drain_seen at plunge when not benighted(party) "In the floor of the dry pool, under the silt the Forsworn stand in, there is a square drain-mouth, cut with ruled lines like everything the old city's clerks made, and a draught comes up out of it that smells of stone dust and, faintly, of hot metal.".
  Relation forswornAppeased(place).
  Thing forsworn_watch "the Forsworn over the drain" on plunge_drain is scenery {
    State standing blocking "The Forsworn stand over the drain-mouth, close as reeds, with their hands out.".
    State parted "The Forsworn have drawn back from the drain-mouth, against the walls.".
  }
  Rule forsworn_part when (forswornAppeased(ossel) or not able(forsworn)) and state(forsworn_watch, standing) { Assert state(forsworn_watch, parted). }
  Rule forsworn_close when able(forsworn) and not forswornAppeased(ossel) and state(forsworn_watch, parted) and not at(party, plunge) and not at(party, scruples_cistern) { Assert state(forsworn_watch, standing). }
  // A weight of a kept promise, from Saint Evenhand's.
  Kind votive_weight "a votive weight of a kept promise" is gear worth 0 weighing 1
    described "A small lead weight on a cord, rubbed smooth, from the chapel ceiling: hung forty years ago by a woman whose husband promised to come home from the sea, and did. Brother Ancel says it has been kept a long time, and can be spared.".
  Item kept_weight "a votive weight of a kept promise" is votive_weight at chapel hidden until weight_given.
  Discovery weight_given "Brother Ancel has given you the weight of a kept promise.".
  Topic tolley_hollow with tolley "Ask Brother Ancel what the hollow men in Lowtide want" when true once {
    Says "Ancel does not laugh. 'The forsworn,' he says. 'The old city's oath-breakers, the book calls them. The saint pitied them. He said they hold out their hands because they want to be given back what they broke, and there is no giving it.' He looks up at the weights. 'He used to take a weight down from here, one of the old ones, a promise that had been kept, and go down at the ebb and give it to one. The book says it stood aside for him, and let him go where he was going. I have never tried it. I am a coward, and they are not mine to pity.'".
    On discuss { Assert knows(actor, hollow_want). }
  }
  Discovery hollow_want "Saint Evenhand used to give the Forsworn the weight of a kept promise from his chapel, and they would stand aside for him.".
  Action ask_weight(actor: group, recipient: member, site: place) "Ask Brother Ancel for the weight of a kept promise" {
    Speaker tolley. Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(tolley, site) and knows(actor, hollow_want)
      and memberOf(recipient, actor) and awake(recipient) and at(kept_weight, chapel).
    Resolve acquire(kept_weight, votive_weight, recipient).
    On success { Assert knows(actor, weight_given). Retract at(kept_weight, chapel). }
    Result "Ancel stands on the altar-step and reaches up among the weights for a long time, reading the little paper tags, and comes down with a lead one rubbed smooth as a pebble. 'Forty years,' he says. 'A sailor's wife. He came home. She died last winter, and he the winter before, and it has hung here kept all that while.' He puts it in your hand and closes your fingers over it. 'Bring the cord back, if you can. I like to know where they go.'".
  }
  Action give_weight(actor: group, giver: member, site: place) "Hold out the weight of a kept promise to the Forsworn" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, plunge) and at(forsworn, plunge) and able(forsworn)
      and memberOf(giver, actor) and carries(actor, kept_weight) and not forswornAppeased(ossel) and not benighted(actor).
    Resolve drop(kept_weight, giver).
    On success { Assert forswornAppeased(ossel). Retract assails(forsworn, actor). Assert tolerates(forsworn, actor). Retract at(kept_weight, plunge). }
    Result "You hold it out on its cord, and they stop. All of them, all at once, the way the soldiers stopped on the Steps. The nearest puts out a hand that is not quite a hand and takes the weight, and holds it, and for a moment, in the torn dark where its face should be, something is almost there: a mouth, an old man's mouth, about to say a name. Then it is gone. They draw back against the walls of the plunge-room, all of them, with the weight passed from hand to hand among them like something warm, and leave the drain-mouth clear.".
  }
  Action slip_forsworn(actor: group, site: place) "Slip along the pool's edge to the drain while the Forsworn face the arch" {
    Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, plunge) and at(forsworn, plunge) and able(forsworn)
      and not forswornAppeased(ossel) and not triedSlipping(actor) and state(forsworn_watch, standing).
    Resolve check(actor, stealth, dc_hard).
    On success { Assert state(forsworn_watch, parted). Assert unseen(actor, forsworn). }
    On failure { Assert triedSlipping(actor). Assert assails(forsworn, actor). }
    Result "You go along the very edge of the dry pool with your back to the wall and your light shaded in your hand, so close to the nearest of them that you could touch its sleeve. It does not turn. Nothing turns. The drain-mouth is at your feet, and then you are in it.".
    Otherwise "Your foot finds a loose tile at the pool's edge, and every empty face in the room turns to you at once.".
  }
  Relation triedSlipping(group).
  Rule slip_done when unseen(party, forsworn) and not at(party, plunge) { Retract unseen(party, forsworn). }

  // ── Other keys ────────────────────────────────────────────────────────────────────────────────────────────────────
  // A Scruple balances the weighing pans as a child of seven does.
  Action tally_balances(actor: group, site: place) "Ask the Valuer to balance the pans" {
    Speaker tally. Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gallery) and travelsWith(tally, actor)
      and state(counter_door, shut) and not brokeFaith(actor).
    On success { Assert state(counter_door, open). Assert chamberOpened(ossel). }
    Result "The Valuer does not look at the brass on the rack. They step into the empty pan themselves, and stand quite still, and the pan sinks under them, a little, and stops a hair short; and they take a pen out of their coat and hold it out at arm's length, and the pointer creeps to its mark, and the white door opens. 'Every one of us does that at seven years old,' they say, stepping out. 'It is how we are taught what we weigh. A pen is about the weight of an untold lie.'".
  }
  // Bettany Slake carries the Factor's letters. Shown what they are for, she will not carry another.
  Topic slake_letters with slake "Tell Bettany Slake what the Factor's letters to the Hall are for" when knows(actor, collateral) and knows(actor, sault_courier) and tolerates(slake, actor) and not state(runners_box, open) once {
    Says "Bettany listens with her arms folded, and when you get to the soldiers walking past the quay with their eyes open she unfolds them. 'Buying them,' she says. 'The Factor. With a letter in my box.' She spits over the edge of the quay, a long way. 'I run untaxed salt. I've run worse. I never yet carried a man.' She takes a key off her belt and opens the lockbox and holds out the letter on two fingers, as if it were wet. 'Take it. Tell her Bettany Slake said so. And then don't come back to my quay, because I'll have to say you robbed me.'".
    On discuss { Assert state(runners_box, open). Assert slakeGaveLetter(ossel). }
  }
  Relation slakeGaveLetter(place).
  Rule slake_lets_box when slakeGaveLetter(ossel) and not tolerates(slake, party) { Assert tolerates(slake, party). }
  // The Factor's lightermen let anyone on the Factor's books go about her warehouse, until she has reason not to.
  Rule lightermen_know_you when hiredBySault(party) and not saultExposed(ossel) and not tolerates(lightermen, party) and not hostile(sault, party) {
    Assert tolerates(lightermen, party). }
  Rule lightermen_forget_you when saultExposed(ossel) and tolerates(lightermen, party) { Retract tolerates(lightermen, party). }
  Action bribe_lightermen(actor: group, site: place) "Give the lightermen two coin each to finish their game somewhere else" {
    Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(lightermen, site) and able(lightermen)
      and not tolerates(lightermen, actor) and not assails(lightermen, actor) and quantity(actor, gold) >= 6.
    On success { Decrease quantity(actor, gold) by 6. Increase quantity(lightermen, gold) by 6. Assert tolerates(lightermen, actor). }
    Result "The biggest of them looks at the coins, and at his mates, and at the door to Panhythe, where the Factor is not. 'Never saw you,' he says, and they go and sit on the salt-sacks by the far wall with their backs to the trap-door.".
  }

  // ── The Treasurer and the Comptroller ─────────────────────────────────────────────────────────────────────────────
  // Two men who put their names to a promise they knew could not be kept.
  Topic quire_designed with quire "Tell the Treasurer that the War Note was drawn to fail" when knows(actor, note_designed) and quireConfided(actor) and not quireDrowned(ossel) once {
    Says "Quire takes his spectacles off. 'Drawn to fail,' he says. 'Then we were cheated.' He sits with that for a moment, and you watch him want it, the relief of it, and then watch him put it down. 'No,' he says. 'We read it. We knew the treasury. We knew what land and a pension for eight thousand would cost, and we signed it anyway, because the other side wanted it signed and we wanted to win.' He puts the spectacles back on. 'A man who signs a promise he cannot keep, because the man across the table would like it broken, is still the man who signed it. Your clerk under the sea and I are the same kind of fool. He has only been one longer.'".
  }
  // ── The Teazles, after ────────────────────────────────────────────────────────────────────────────────────────────
  Observe teazles_home at teazle_room when cameHome(davy) and at(davy, teazle_room) "The red coat is not on its peg. Davy Teazle is asleep in the cupboard bed in it, with his boots on, which his mother has not mentioned. Nan is mending a net by the brazier and has stopped pretending she is not looking at him. The recruiting bill is gone from the shelf; there is a pale square where it was.".
  Topic davy_home_talk with davy "Ask Davy what he remembers" when cameHome(davy) and at(davy, teazle_room) and not asleep(davy) once {
    Says "'Standing,' says Davy. 'In a line. White, everywhere, like snow with no cold in it.' He looks at his hands. 'And a voice somewhere singing the Sally song over and over, a woman, very far off. I kept trying to remember the last verse and I couldn't.' He looks up at his mother. 'He comes home,' he says. 'In the last verse. I remember now.'".
  }
  Rule davy_wakes_home when cameHome(davy) and at(davy, teazle_room) and asleep(davy) and hour(clock) >= 8 and hour(clock) < 20 { Retract asleep(davy). }

  // ── The eel-mother ────────────────────────────────────────────────────────────────────────────────────────────────
  // A conger as long as a boat that comes up the Swatch at the night ebb to hunt the drained streets, and lies at the
  // foot of the stair. By day she is out in the deep channel. Ways past her: by day; by the Factor's cistern; quietly,
  // while she is turned to the channel; or with what the Withies always give her, hot eels with vinegar, which she
  // likes better than anyone has ever been able to explain.
  Species conger_kind "a great conger" like great_snake temperament territorial
    described "An eel as long as a boat and as thick as a horse, grey-black, with a head like a ram and a mouth full of back-curved teeth. The Withies call her the eel-mother and say she was old when their grandmothers were girls.".
  Person eelmother "the eel-mother" at throat_foot {
    Role "a conger as long as a boat, lying in the channel at the stair-foot". Species conger_kind. Level 5. Pronouns she.
    Seen when dark() and lowWater().
    Warns "The black water at the foot of the stair humps up, and a head as big as a ram's comes out of it on a neck that keeps coming, and turns, slowly, toward your light. Her mouth is open. She does not want you on her stair.".
    Comes "The eel-mother comes up out of the channel all at once, the whole grey length of her, faster than anything that size should move.".
  }
  Kind hot_eels "a paper cone of hot eels" is gear worth 1 weighing 0
    described "Eels, stewed and sliced, hot, in a cone of the city's own paper, with too much vinegar. The paper is going soft.".
  Person eel_seller "Old Gudrun" at tidewall {
    Role "who sells hot eels in paper cones on the Tidewall, from a brazier on a barrow". Ancestry human. Peaceable. Pronouns she. Manner jovial.
    Greets "Old Gudrun holds up a paper cone before you have asked for one. 'Hot,' she says. 'One coin. Mind the vinegar.'".
    Sells hot_eels for 1 coin from 6.
    Seen when not dark().
  }
  Topic gudrun_eelmother with eel_seller "Ask Old Gudrun about the eel-mother" when true once {
    Says "'Her?' Old Gudrun laughs, and stirs the pot. 'She's been coming up the Swatch at the night ebb since my gran was a girl. Takes a dog now and then. Took a mudlark in my mother's time, and they say the mudlark had it coming.' She fills a cone and holds it out to you, steaming. 'You want to go down there of a night, you take her a cone of these. Vinegar. Lots. Throw it in the channel and she'll stop to eat it, and while she's eating you go by. She's been eating my eels sixty years. She knows the smell of my pot better than my husband does.'".
    On discuss { Assert knows(actor, eelmother_known). }
  }
  Discovery eelmother_known "A great conger, the eel-mother, comes up the Swatch at the night ebb and lies at the foot of the stair; a cone of hot eels thrown into the channel stops her long enough to get past.".
  Topic wick_night_ebb with wick "Ask Wick about going down at the night ebb" when true once {
    Says "'Don't,' says Wick at once. 'Not at the night ebb. The eel-mother comes up.' He holds his hands as far apart as they go, and then looks at them as if they were not nearly far enough. 'She lies at the bottom of the stair with her head out. You take her Gudrun's eels, from the barrow on the Wall. Everybody knows that.' He considers. 'Or you go round by the Factor's tunnel, but they'll break your head. Or you don't go.'".
    On discuss { Assert knows(actor, eelmother_known). }
  }
  Relation eelmotherFed(place).
  Action feed_eelmother(actor: group, giver: member, cone: item, site: place) "Throw {cone} into the channel" {
    Time 1 minute.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, throat_foot) and at(eelmother, throat_foot)
      and able(eelmother) and dark() and lowWater() and memberOf(giver, actor) and ownedItem(cone, giver) and itemKind(cone, hot_eels)
      and not eelmotherFed(ossel).
    Resolve drop(cone, giver).
    On success { Assert eelmotherFed(ossel). Assert tolerates(eelmother, actor). Retract assails(eelmother, actor). }
    Result "The cone hits the black water and opens, and the smell of vinegar goes up, and the great head turns away from you toward it with something you would swear was pleasure. She takes the whole thing, paper and all, in one movement, and slides back down into the channel to see if there is any more. You go past the end of her while she looks.".
  }
  Rule eelmother_full when eelmotherFed(ossel) and not dark() { Retract eelmotherFed(ossel). Retract tolerates(eelmother, party). }
  Action slip_eelmother(actor: group, site: place) "Wait for her to turn to the channel, and go by along the wall" {
    Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, throat_foot) and at(eelmother, throat_foot)
      and able(eelmother) and dark() and lowWater() and not tolerates(eelmother, actor) and not triedEel(actor).
    Resolve check(actor, stealth, dc_hard).
    On success { Assert tolerates(eelmother, actor). }
    On failure { Assert triedEel(actor). Assert assails(eelmother, actor). }
    Result "You stand pressed against the wet wall of the stair-foot for a long time, while the great head swings slowly back and forth over the channel, and when it is turned away you go, along the wall, one step and then another, close enough to smell her. She does not turn.".
    Otherwise "A stone turns under your boot. The head comes round.".
  }
  Relation triedEel(group).
  Rule eel_forgets when tolerates(eelmother, party) and not dark() and not eelmotherFed(ossel) { Retract tolerates(eelmother, party). }
}

data/adventures/what-tessary-owes/week.k:
Module tessary "What Tessary Owes" {
  // ── The middle of the fortnight ───────────────────────────────────────────────────────────────────────────────────
  // What happens between the first week's findings and the Feast happens somewhere, at an hour, whether or not anyone
  // is there: Durrance's night, the Treasurer at the Swatch, the lightermen at Marrable's door, the Muster on the Row,
  // the Board, the Seal. The Muffled Drum hears of each a day or two before, and Hannelore says what it hears.
  Topic gossip_deserters with sedge "Ask Hannelore what they are saying in the Drum" when night(ossel) >= 2 and night(ossel) <= 4 once {
    Says "'Deserters,' says Hannelore, and empties a pot into the slop-bucket as if it had said it. 'That bill on the Landgate. Printed, on good paper. The Board hasn't paper like that; it came off the Factor's press, and the whole Withies knows it.' She wipes the bar. 'And Benno Fisk is buying rounds, which he never did in his life. And nobody says a word to Thomasin about her page, so she sits there and says it to herself.'".
  }
  Topic gossip_coats with sedge "Ask Hannelore what they are saying in the Drum" when night(ossel) >= 5 and night(ossel) <= 6 once {
    Says "'Coats,' says Hannelore. 'Lads go down to the Factor's hall in the morning in red and come back in grey with a salt-white collar. And they say she's offered to pay the next ebb's silver herself, all twelve, if the right sergeant asks her nicely.' She looks up at the drum. 'The spring ebb's the night after next. Two in the morning. If you've anything to do for Thomasin, do it before then.'".
  }
  Topic gossip_tonight with sedge "Ask Hannelore what they are saying in the Drum" when night(ossel) == 7 and not heldNow(durrance) once {
    Says "'Nothing,' says Hannelore. 'Nobody's saying anything tonight.' She is polishing the same pot she was polishing when you came in. 'Spring ebb's at two. Thomasin's at the top of the page. She's said she'll sit up here with her boots on, like a soldier.' She puts the pot down. 'Rap, rap, and the long roll. My husband used to beat it. I've not touched it since.'".
  }
  Topic gossip_treasurer with sedge "Ask Hannelore what they are saying in the Drum" when night(ossel) >= 8 and night(ossel) <= 10 and not quireDrowned(ossel) once {
    Says "'The Treasurer,' says Hannelore. 'Twice now the eel-men have seen him at the head of the Swatch Stair before dawn, in his good coat, buttoned up, looking down at the water. Not doing anything. Just looking.' She frowns. 'Somebody ought to say something to him. Somebody he'd listen to.' And then, lower: 'And the Factor's lightermen were in the Eel quarter yesterday asking which door is Councillor Marrable's. Asking nicely.'".
  }
  Topic gossip_terraces with sedge "Ask Hannelore what they are saying in the Drum" when night(ossel) >= 11 and night(ossel) <= 12 and not fiskTurned(fisk) and not riotHappened(ossel) and not riotCalmed(ossel) once {
    Says "'Torches,' says Hannelore. 'The lads at the Factor's hall say if the Board's going to vote no, they'll go up the Terraces the night before and ask it again, louder. Fisk's getting them together on Scriveners' Row after dark, the night before the sitting.' She shakes her head. 'And the Factor says leave it to her, and pays for the torches. Work that out.'".
  }
  Topic gossip_coats_back with sedge "Ask Hannelore what they are saying in the Drum" when night(ossel) >= 11 and night(ossel) <= 12 and fiskTurned(fisk) once {
    Says "'There's grey coats in the canal,' says Hannelore, and almost smiles. 'Fisk's been telling the lads at the Factor's hall what she wants them for, and some of them believed him. Half the Withies went fishing for coats this morning.' She looks at you. 'The Board sits the day after tomorrow. Ten in the morning. I've never been on the public bench in my life. I might go.'".
  }
  Topic gossip_board with sedge "Ask Hannelore what they are saying in the Drum" when night(ossel) == 13 and not voted(ossel) once {
    Says "'The Board's sitting,' says Hannelore. 'Ten till two, and then the count. Public bench is open to anyone who'll stand, and anyone with anything to say can stand up and say it, before two.' She unties her apron. 'Half the Withies is going. Mind, if the Board votes yes, the Factor's lost, and she doesn't like losing. I'd watch the Office of Seals tonight, if I were the Keeper. He sleeps in there with it.'".
  }
  Topic gossip_carried with sedge "Ask Hannelore what they are saying in the Drum" when votePassed(ossel) and night(ossel) == 13 and not sealTried(ossel) once {
    Says "'Carried!' says Hannelore, and kisses you on both cheeks before you can stop her. Then she sobers. 'It's not done till the Seal's on the deeds tomorrow, mind. The Factor's lightermen were on Scriveners' Row this afternoon looking at the Keeper's windows. Somebody ought to sit up with him tonight.'".
  }
  Topic gossip_feast with sedge "Ask Hannelore what they are saying in the Drum" when night(ossel) == 14 once {
    Says "'Feast tomorrow,' says Hannelore. 'Feast of Settlement, and the spring ebb with it. Fifteenth night.' She looks at the drum for a long time. 'There's people in the Withies hanging their sons' boots on the door. I don't know if it's for luck or the other thing.'".
  }

  // The tenth night: an hour before he goes down the stair, the Treasurer goes to the head of it and stands there.
  // Anyone at the head of the Swatch Stair can speak to him. Who knows what to tell him can give him a reason; anyone
  // can try to give him a smaller one.
  Rule quire_to_throat when night(ossel) == 10 and hour(clock) == 3 and quirePressed(ossel) and not quireHope(quire)
    and not quireDrowned(ossel) and at(quire, exchequer_room) {
    Retract at(quire, exchequer_room). Assert at(quire, throat_head). }
  Rule quire_off_throat when quireDrowned(ossel) and at(quire, throat_head) { Retract at(quire, throat_head). }
  Rule quire_back_home when quireHope(quire) and at(quire, throat_head) and hour(clock) != 3 {
    Retract at(quire, throat_head). Assert at(quire, exchequer_room). }
  Observe quire_at_throat near quire when at(quire, throat_head) and not quireHope(quire) "At the head of the Swatch Stair, in the dark, a man is standing with his coat buttoned to the neck, looking down at the full basin. It is the Treasurer. He has taken his spectacles off and holds them folded in one hand, as if he did not expect to need them again.".
  Relation triedQuire(group).
  Action stay_quire(actor: group, site: place) "Ask the Treasurer who will send the money to the mothers on the first of the month" {
    Time 1.
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, throat_head) and at(quire, throat_head)
      and not quireHope(quire) and not quireDrowned(ossel) and not triedQuire(actor).
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert quireHope(quire). }
    On failure { Assert triedQuire(actor). }
    Result "He looks at you as if you had asked him the time. 'Four marks,' he says. 'Each. A hundred and thirty-eight of them, and twelve more after the Feast.' He thinks about it. 'Nobody,' he says. 'Nobody would. The Board would stop it in a week.' He puts his spectacles back on, and stands there a while longer, and then he turns round and walks back up toward the Lettered Quarter, slowly, like a man who has remembered an appointment.".
    Otherwise "He hears you out politely, and thanks you, and says you should go home to bed. He does not move from the top step.".
  }
  Rule quire_saved_told when quireHope(quire) and night(ossel) == 10 and not quireDrowned(ossel) and not spread(quire_lived)
    and inTessary() and not at(party, throat_head) says "Word goes along the Tidewall in the morning that the Treasurer was seen at the head of the Swatch Stair before dawn, and that he went home." { Assert spread(quire_lived). }
  Discovery quire_lived "The Treasurer stood at the head of the Swatch Stair on the tenth night, and went home.".

  // The thirteenth day: the Council House bell.
  Discovery board_sits "The Board of Moieties sits on the thirteenth day, from ten in the morning until the count at two in the afternoon. The public bench is open, and anyone with something to say may stand up and say it before two.".
  Rule board_bell when night(ossel) == 13 and hour(clock) >= 8 and hour(clock) < 10 and inTessary() and not spread(board_sits)
    says "The Council House bell rings over the city, nine strokes and then nine more: the Board of Moieties sits at ten to hear the question of the Veterans' Settlement, and the public bench is open." teaches board_sits {
    Assert spread(board_sits). }
}

data/adventures/wrayford/aftermath.kyr:
Module wrayford "The Third Night" {
  // ── After the verdict ─────────────────────────────────────────────────────────────────────────────────────────────
  // In a world that goes on, Wrayford is still there after its story, and shows what became of it.
  Rule captain_leaves when verdictGiven(wray) and hour(clock) >= 12 and not captainGone(wray) and fourthDay() {
    Assert captainGone(wray). Assert at(sefton, limbo). Assert at(troop, limbo). Assert at(gault, limbo). Assert at(riders, limbo). }
  Relation captainGone(place).
  Rule captain_gone_told when captainGone(wray) and inWrayford() and not spread(gone_fact) says "At noon the captain rides out over the drawbridge with her riders and Gault's four behind her, and the lord's toll money in a strongbox on a led horse, and does not look back at the gatehouse, and Wrayford watches her all the way up the south road until the hedges have her." { Assert spread(gone_fact). }
  Entity gone_fact: fact "The captain gone".
  // Whatever of the dead is not in the ground at the verdict goes to the lord's lime.
  Rule unburied_to_lime when verdictGiven(wray) and deadBody(?b) and not buried(?b) and not at(?b, limbo) { Assert at(?b, limbo). }
  Rule maudie_after when maudieHanged(maudie) and not at(maudie, limbo) { Assert at(maudie, limbo). }
  Rule maudie_home_after when verdictGiven(wray) and not maudieHanged(maudie) and maudieTaken(maudie) and not at(maudie, pardoe_kitchen) { Assert at(maudie, pardoe_kitchen). }

  Observe after_gate_fire at gate_road when verdictRebellion(wray) and not dark() "The gatehouse rail is crowded now. Nobody in the Bridge End looks up. Nobody stands about. People cross the bridge with their eyes on their feet and do not pay the farthing and nobody asks them to.".
  Observe after_gate_maudie at gate_road when verdictGiven(wray) and maudieHanged(maudie) and not verdictRebellion(wray) and not dark() "Four cut ends of rope hang from the hooks on the gatehouse rail. Somebody has tied a twist of black wool round the fourth, and nobody has taken it off.".
  Observe after_gate_mothers at gate_road when verdictGiven(wray) and mothersWalked(wray) and not dark() "On the coping of the gatehouse rail, where the hooks were, there are flowers: field scabious and corn-cockle and a bunch of mint, tied with carters' twine, renewed every morning by somebody nobody sees.".
  Observe after_gate_down at gate_road when verdictGiven(wray) and buried(wat_dead) and not mothersWalked(wray) and not maudieHanged(maudie) and not verdictRebellion(wray) and not dark() "The hooks on the gatehouse rail are empty, and the cut ends of rope have been taken down by someone, and people do not look up as they pass, or they do, briefly, the way you look at a place where a tooth was.".
  Observe after_gate_lime at gate_road when verdictGiven(wray) and not buried(wat_dead) and not verdictRebellion(wray) and not dark() "The hooks on the gatehouse rail are empty. The drovers say there is a new place at the crossroads on the south road where the lime has burned the grass white, and they take their beasts round it.".
  Observe after_row_fire at wain_row when verdictRebellion(wray) "Wain Row is gone: a lane of black chimneys and fallen roofs, cart-sheds open to the sky, the painted doors burned down to their hinges. The red one too.".
  Observe after_kitchen_empty at pardoe_kitchen when maudieHanged(maudie) and not verdictRebellion(wray) "The kitchen is cold. On every surface the loaves she made are going stale under their cloths, and nobody has the heart to throw them out, and nobody can eat them.".
  Observe after_kitchen at pardoe_kitchen when verdictGiven(wray) and not maudieHanged(maudie) and buried(wat_dead) "The kitchen smells of bread. There is one loaf on the table, not twenty. Somebody has wound the clock on the dresser.".
  Observe after_kitchen_lime at pardoe_kitchen when verdictGiven(wray) and not maudieHanged(maudie) and not buried(wat_dead) and not verdictRebellion(wray) "Maudie Pardoe sits at the table with her hands flat on it. She is not baking. The coat is gone from the hook by the door.".
  Observe after_hobday at hobday_room when verdictGiven(wray) and nedBuried(jennet) "The shutters are open. The bed is made. On the windowsill, in a jar, a boy's fishing line wound round a cork.".
  Observe after_hall_reeve at guild_hall when verdictGiven(wray) and (hulmeResigned(hulme) or reeveRelease(wray) or tooLate(wray)) "At the end of the long hall the reeve's chair stands empty, with his chain of office laid across its arms, and nobody has sat in it.".
  Rule hulme_dismissed when verdictGiven(wray) and (reeveRelease(wray) or tooLate(wray)) and not hulmeResigned(hulme) { Assert hulmeResigned(hulme). }
  Rule hulme_retires when hulmeResigned(hulme) and not at(hulme, hulme_study) { Assert hulmeAway(hulme). Assert at(hulme, hulme_study). }
  Observe after_acre at wades_acre when verdictGiven(wray) and reconciled(wray) and evening() "At dusk Dorcas Mudd rows across to the Acre steps, and Corbin comes down the steps to meet her, and they sit in the boat together not talking, and then they start to quarrel, comfortably, the way people do who have all the time in the world.".

  // ── What is given ───────────────────────────────────────────────────────────────────────────────────────────────
  // The Bench, entering its charity in the minutes, enters its benefactor too: the freedom of the bridge.
  Relation tokenGiven(group). Relation ferryTokenGiven(group).
  Rule bench_token when verdictGiven(wray) and releasedBy(wray, by_charity) and inWrayford() and not tokenGiven(party) and at(party, ?p) says "Lancelot Inchbold finds you in the crowd with a brass token on a ribbon and a paper to sign. 'The freedom of the bridge,' he says. 'By the Bench's resolution of this morning, in recognition of your services to the Company's charity.' He does not smile. 'It is entered in the minutes. Everything is.'" {
    Assert tokenGiven(party). Assert at(bridge_token, ?p). }
  // Dorcas, for a crossing the bridge never saw: her own token, a penny with a hole in it, good at any hour.
  Kind ferry_token_kind "Dorcas Mudd's penny" is gear worth 0 weighing 0
    described "A penny with a hole bored through it, on a twist of tarred twine, and MUDD scratched on the back: good for the ferry at any hour, for life, with no questions and no farthings.".
  Item ferry_token "Dorcas Mudd's penny" is ferry_token_kind at limbo.
  Rule dorcas_token when verdictGiven(wray) and (boatCrossed(wray) or reconciled(wray)) and inWrayford() and not ferryTokenGiven(party) and at(party, ?p) says "A boy from the Wharf finds you with something wrapped in a bit of sacking: a penny with a hole bored through it, on tarred twine. 'From Mistress Mudd,' he says. 'She says it's good for the ferry any hour, and she says don't thank her, and she says she means it.'" {
    Assert ferryTokenGiven(party). Assert at(ferry_token, ?p). }

  // ── The Bridge Feast ──────────────────────────────────────────────────────────────────────────────────────────────
  // On the fifth day at eleven the Company processes over the bridge in its blue gowns, and at the gatehouse the Abbess
  // receives the bridge penny that the city has paid the Liberty since the bridge was built.
  Relation feastHeld(place).
  Rule feast_none when fifthDay() and hour(clock) == 11 and verdictRebellion(wray) and not feastHeld(wray) and inWrayford() says "There is no Bridge Feast this year. The Company's blue gowns stay in their presses. At eleven, when the procession should have crossed, the bell of Saint Wade's rings once, by itself, someone says, though everyone knows the Abbess rang it." { Assert feastHeld(wray). }
  Rule feast_mothers when fifthDay() and hour(clock) == 11 and mothersWalked(wray) and not feastHeld(wray) and inWrayford() says "At eleven the Worshipful Company of the Bridge processes over the bridge in its blue gowns, with Gidley at the head and a band, and at the gatehouse the Abbess is waiting to receive the bridge penny, as the Liberty has since the bridge was built. Gidley holds it out. The Abbess looks at it, and at him, and at the flowers on the rail above, and does not take it. 'The city paid this year,' she says, loud enough for the Bridge End. 'Twice.' And goes back to Overbridge, and the procession does not know whether to go on, and does, very slowly, and the band stops." { Assert feastHeld(wray). }
  Rule feast_plain when fifthDay() and hour(clock) == 11 and not verdictRebellion(wray) and not mothersWalked(wray) and not feastHeld(wray) and inWrayford() says "At eleven the Worshipful Company of the Bridge processes over the bridge in its blue gowns, with a band, and at the gatehouse, from habit, Alderman Gidley stops under the empty rail and takes his hat off and weeps a little, beautifully, while the band waits. The Abbess takes the bridge penny from him at the drawbridge without a word, and bites it." { Assert feastHeld(wray). }
  Observe feast_portrait at guild_hall when fifthDay() and portraitHung(wray) "For the Feast the Guildhall is hung with blue, and at the end of the row of Masters the new portrait of the Bench is lit with candles, and every carter in Wrayford has found a reason to come in and stand in front of it.".
  Observe feast_banner at carters_yards when dayN(wray) >= 4 and portraitBanner(wray) "Against the yard wall, on its cart-shafts, Tom Lumley's portrait of the Bench, a little rained on, with somebody's pipe stuck in Gidley's mouth.".
}

data/adventures/wrayford/bridge.kyr:
Module wrayford "The Third Night" {
  // ── The Bridge End ────────────────────────────────────────────────────────────────────────────────────────────────
  // The lord's gatehouse spans the north end of the bridge. The toll is taken at a booth under its arch, where the
  // toll-house stood until four nights ago. Above, on the leads, the river rail; on the rail, the three.
  Measure crowd(place). Measure temper(place).
  Initially Set crowd(wray) to 1. Initially Set temper(wray) to 0.
  // The crowd grows every morning the dead are still up.
  Rule crowd_grows when hour(clock) == 7 and not crowdCounted(wray) and stillHanging() { Increase crowd(wray) by 1. Assert crowdCounted(wray). }
  Rule crowd_count_ends when hour(clock) == 8 and crowdCounted(wray) { Retract crowdCounted(wray). }
  Relation crowdCounted(place).
  Query stillHanging() means state(rail, hanging).

  Observe gate_scene at gate_road when not dark() and not visitedBefore(gate_road) "The road comes out of the Market into the shadow of the gatehouse, a square tower of red stone over the bridge's first arch, with the lord's arms over the arch and the lord's chain across it, new, the links still bright. Beside the arch, where a house stood, a heap of black timbers. In front of the chain, a booth of planks with a board nailed up beside it, very freshly painted. And up on the tower's river side, along the parapet of the leads, three shapes in sacking hang against the sky on short ropes, and turn a little when the wind comes up the river, and turn back.".
  Observe gate_scene_again at gate_road when not dark() and visitedBefore(gate_road) and stillHanging() "The Bridge End, under the gatehouse: the bright chain, the booth and its board, the black heap of the toll-house, and up on the leads the three in their sacking.".
  Observe gate_scene_down at gate_road when not dark() and not stillHanging() "The Bridge End, under the gatehouse: the chain, the booth and its board, the black heap of the toll-house. There is nothing on the rail now. People still look up as they pass, out of habit.".
  Observe gate_night at gate_road when dark() "The Bridge End at night. A lantern hangs under the gatehouse arch. Up on the leads the riders' brazier makes a red smudge, and against it, the three.".
  Observe crowd_small at gate_road when not dark() and stillHanging() and crowd(wray) <= 2 "A few people stand about at the Bridge End looking up, the way people stop to look at a fire, and then go on.".
  Observe crowd_large at gate_road when not dark() and stillHanging() and crowd(wray) >= 3 and temper(wray) < 2 "There is a crowd at the Bridge End now, fifty or sixty people, more at noon: drovers in for the market, apprentices, a man selling ballads, children on their fathers' shoulders. Someone has thrown a cabbage at the sacking. Someone else has said that's enough of that, and there was nearly a fight.".
  Observe crowd_quiet at gate_road when not dark() and stillHanging() and crowd(wray) >= 3 and temper(wray) >= 2 "There is a crowd at the Bridge End, a big one, and it is quiet. Nobody is selling anything. People come and stand and look up, and take their hats off, and go.".
  // The decree on the door.
  Observe decree_scene at gate_road when stillHanging() and not knows(party, decree_known) "A paper is nailed to the gate-ward's door in the tower, in a clerk's round hand with the reeve's seal at the foot.".

  // ── The toll ──────────────────────────────────────────────────────────────────────────────────────────────────────
  Discovery toll_schedule "The Bridge Company's new toll-board, by the booth: A CART, ONE PENNY. A BEAST, ONE PENNY THE HEAD. A CARCASS, THREE PENCE THE HUNDREDWEIGHT. GOODS OF A FELON: FORFEIT TO THE LORD, NOT TO PASS. A PILGRIM TO SAINT WADE'S ON HIS OWN FEET: FREE. THE ABBESS'S TITHE AND THE LIBERTY'S OFFAL TO THE TAN-YARDS: FREE, BY ANCIENT PRIVILEGE. A FOOT-PASSENGER: ONE FARTHING (SINCE THE RIOT). BY ORDER OF THE WORSHIPFUL COMPANY OF THE BRIDGE, FARMERS OF THE LORD'S TOLL." {
    Source toll_board "the Company's new toll-board" at gate_road readable by party.
    Known by pinch, gidley, inchbold.
  }
  Person pinch "Amos Pinch" at gate_road {
    Role "the Bridge Company's collector, in a new black coat". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "Amos Pinch looks up from his tally with the expression of a man who has been looked up from his tally all morning. 'A farthing, foot-passengers,' he says. 'Since the riot.'".
  }
  // The farthing, taken at the chain from everyone who goes on to the bridge while Pinch keeps the booth: once a day,
  // since he gives a tally-stick for it, and nobody but the Bench's freemen goes free.
  Measure tollDay(group). Initially Set tollDay(party) to 0.
  Relation owesToll(group).
  Rule toll_taken when at(party, bridge_street) and at(pinch, gate_road) and not asleep(pinch) and tollDay(party) < dayN(wray)
    and not carries(party, bridge_token) and quantity(party, gold) >= 1 says "At the chain Amos Pinch takes your farthing. There being no farthings left in Wrayford since the riot, he takes a penny, and writes you a tally-stick for the three farthings he owes you, which he says the Company will honour at Michaelmas." {
    Set tollDay(party) to dayN(wray). Decrease quantity(party, gold) by 1. }
  Rule toll_owed when at(party, bridge_street) and at(pinch, gate_road) and not asleep(pinch) and tollDay(party) < dayN(wray)
    and not carries(party, bridge_token) and quantity(party, gold) < 1 says "At the chain Amos Pinch holds out his hand, and looks at your empty one, and writes your name in the day-book as owing the Worshipful Company of the Bridge one farthing, and lets you by." {
    Set tollDay(party) to dayN(wray). Assert owesToll(party). }
  // The freedom of the bridge: a brass token, the Bench's, which the Bench gives to almost nobody.
  Kind bridge_token_kind "a bridge token" is gear worth 0 weighing 0
    described "A brass token stamped with the gold bridge and WE BEAR THE CROSSING: the freedom of the bridge at Wrayford, toll-free, by the Bench's leave, for life.".
  Item bridge_token "the freedom of the bridge" is bridge_token_kind at limbo.
  // He keeps the booth from eight until the curfew, and sleeps behind the counting-house.
  Rule pinch_opens when hour(clock) >= 8 and hour(clock) < 20 and not at(pinch, gate_road) and not pinchGone(pinch) { Assert at(pinch, gate_road). }
  Rule pinch_shuts when (hour(clock) >= 20 or hour(clock) < 8) and not at(pinch, pinch_room) and not pinchGone(pinch) { Assert at(pinch, pinch_room). }
  Rule pinch_sleeps when (hour(clock) >= 22 or hour(clock) < 6) and at(pinch, pinch_room) and not asleep(pinch) { Assert asleep(pinch). }
  Rule pinch_wakes when hour(clock) >= 6 and hour(clock) < 22 and asleep(pinch) { Retract asleep(pinch). }
  Relation pinchGone(group).
  // The rulings: how a dead man crosses the bridge, by the board.
  Relation ruling(entity). Relation pinchFlustered(group). Relation pinchCowed(group).
  Discovery ruled_felon "Pinch has ruled, in writing, at the chain, that the dead on the rail are goods of a felon: forfeit to the lord, not to pass. Whatever else they were, they are now a ruling.".
  Discovery ruled_carcass "Pinch rules that the dead may cross as carcasses, at three pence the hundredweight.".
  Discovery ruled_tithe "Pinch rules that the dead, claimed by the Abbess, cross free as her tithe.".
  Topic pinch_dead with pinch "Ask Pinch what it costs to carry a dead man over the bridge" when not pinchFlustered(pinch) once {
    Says "Pinch's pen stops. 'A dead man,' he says. 'A dead man is not on the board.' He looks at the board as if it might have changed while his back was turned. 'The board is complete. The Company drew it up with great care. Everything that crosses is on the board, and a dead man is not, and therefore,' and he stops, because he does not know what therefore. 'Read the board,' he says. 'What it is depends on what it is.'".
  }
  Topic pinch_felon with pinch "Put it to Pinch that the dead are goods of a felon" when knows(actor, toll_schedule) and not pinchFlustered(pinch) once {
    Says "'Goods of a felon,' says Pinch, with relief, as if you had handed him something he had dropped. 'Forfeit to the lord. Not to pass. Yes.' He writes it down. 'That is very clear. Thank you.' Then he looks up at the rail, and at you, and for the first time something crosses his face that is not arithmetic. 'Was that what you wanted?'".
    On discuss { Assert ruling(ruled_felon). Assert knows(actor, ruled_felon). Increase temper(wray) by 1. }
  }
  Topic pinch_carcass with pinch "Put it to Pinch that a dead man is a carcass, by the hundredweight" when knows(actor, toll_schedule) and not pinchFlustered(pinch) and not ruling(ruled_carcass) and not ruling(ruled_felon) once {
    Says "Pinch considers this with his whole face. 'A carcass,' he says. 'Three pence the hundredweight. A carcass is a dead beast. A man is not a beast. But the board does not say beast, it says carcass, and a dead man,' and he closes his eyes, and opens them, 'is a carcass. Wat Pardoe was a big man. Call it twelve stone, with the rope. One hundredweight and a half: four pence ha'penny. Dunstan Fenner, ten stone. Joss Wilder, a boy, nine.' He writes it all down in a small exact hand. 'One and a penny farthing for the three. In coin, at the chain.' The crowd has gone very quiet. Annis Pye, at her pitch, puts down the pie she was holding.".
    On discuss { Assert ruling(ruled_carcass). Assert knows(actor, ruled_carcass). }
  }
  Topic pinch_pilgrim with pinch "Put it to Pinch that Wat Pardoe is a pilgrim to Saint Wade's" when knows(actor, toll_schedule) and not pinchFlustered(pinch) once {
    Says "'On his own feet,' says Pinch at once. 'It says on his own feet. A pilgrim to Saint Wade's on his own feet: free. Wat Pardoe is not,' he looks up at the rail, and down again quickly, 'on his own feet. In the relevant sense.' Somebody in the crowd laughs, and then somebody else, and it is not a kind laugh, and it is not at the dead. Pinch goes red to the ears.".
    On discuss { Increase temper(wray) by 1. }
  }
  Topic pinch_tithe with pinch "Put it to Pinch that the dead are the Abbess's tithe, and she has claimed them" when knows(actor, toll_schedule) and abbessClaims(abbess) and not pinchFlustered(pinch) and not ruling(ruled_tithe) once {
    Says "Pinch reads the Abbess's letter twice, holding it at arm's length as if it might bite. 'The Abbess's tithe,' he says. 'Free. By ancient privilege.' He looks at the board, which says so, in his own paint. 'The Company has always respected the Liberty's privilege,' he says, in the voice of a man repeating something he was told to say, and writes it down, and does not look up at the rail at all.".
    On discuss { Assert ruling(ruled_tithe). Assert knows(actor, ruled_tithe). }
  }
  Action press_pinch(actor: group, site: place) "Press Pinch for a ruling, here, now, in front of the crowd" {
    Description "Loudly. He has been asked the same question all morning and has no answer.".
    Requires able(actor) and company(actor) and at(actor, site) and at(pinch, site) and at(actor, gate_road)
      and not pinchFlustered(pinch) and not dark().
    Time 1.
    On success { Assert pinchFlustered(pinch). Increase temper(wray) by 1. }
    Result "Pinch stands up in his booth. 'A cart, one penny,' he says. 'A beast, one penny the head. A carcass, three pence the hundredweight.' The crowd turns to listen. He goes faster. 'Goods of a felon, forfeit, not to pass. A pilgrim to Saint Wade's on his own feet, free. The Abbess's tithe and the Liberty's offal to the tan-yards, free by ancient privilege. A foot-passenger, one farthing, since the riot.' He takes a breath. 'Everything else is forbidden!' The crowd cheers him as if he had sung. He sits down, white, and pulls the shutter of the booth to, and will not open it again today.".
  }
  Rule pinch_recovers when hour(clock) == 8 and pinchFlustered(pinch) { Retract pinchFlustered(pinch). }

  // ── The leads, the rail and the three ─────────────────────────────────────────────────────────────────────────────
  Observe leads_scene at gate_leads when not dark() "The leads of the gatehouse: grey lead sheet, a parapet, a brazier, the riders' saddlebags. The river is a long way down, brown and quick, and the whole city is laid out from here: Northgate's smoke, the Hill's gardens, the bridge running out on its arches to Overbridge and the church tower on the far bank.".
  Observe leads_night at gate_leads when dark() "The leads at night: the brazier's red glow, the parapet a black line, the river loud below.".
  Thing rail "the river rail" at gate_leads {
    State hanging "Along the river parapet three men hang on short ropes from iron hooks driven into the coping, under sacking the reeve allowed. Their boots show below the sacking: a carter's big boots, a pair mended with wire, a boy's.".
    State cut "The iron hooks in the coping are empty. Three cut ends of rope hang from them.".
  }
  Initially Assert state(rail, hanging).
  // The three, once they are down: carried, laid down, buried. A body borne slows whoever bears it to half pace.
  Relation deadBody(entity). Relation bearing(member, entity). Relation buried(entity).
  Thing wat_dead "Wat Pardoe" at limbo is scenery {
    State lying "Wat Pardoe lies wrapped in his sacking, a big man, his boots showing.".
  }
  Thing dunstan_dead "Dunstan Fenner" at limbo is scenery {
    State lying "Dunstan Fenner lies wrapped in his sacking, his mended boots showing.".
  }
  Thing joss_dead "Joss Wilder" at limbo is scenery {
    State lying "Joss Wilder lies wrapped in his sacking. He was not very old.".
  }
  Place limbo "nowhere" is room within fells_edge at 9, 9.
  Initially Assert deadBody(wat_dead). Initially Assert deadBody(dunstan_dead). Initially Assert deadBody(joss_dead).
  Initially Assert state(wat_dead, lying). Initially Assert state(dunstan_dead, lying). Initially Assert state(joss_dead, lying).
  // Who bears a body takes it wherever they go, and goes at half pace.
  Rule body_carried when bearing(?m, ?b) and memberOf(?m, ?c) and at(?c, ?p) and not at(?b, ?p) { Assert at(?b, ?p). }
  Rule bearer_slowed when bearing(?m, ?b) and speed(?m) != 50 { Set speed(?m) to 50. }
  Rule bearer_eased when speed(?m) == 50 and not bearing(?m, ?b) and memberOf(?m, ?c) and company(?c) { Set speed(?m) to 0. }
  Query borne(b: entity) means bearing(?m, b).
  Query bearingAny(a: group) means memberOf(?m, a) and bearing(?m, ?b).

  // The watch: Sergeant Gault and four of the lord's riders, who keep the gatehouse until the captain comes.
  Person gault "Sergeant Gault" at gate_leads {
    Role "the riders' sergeant, a square man with a broken nose". Ancestry human. Calling warrior. Level 4. Peaceable. Pronouns he. Manner stoic.
    Greets "Sergeant Gault looks at you the way a dog looks at another dog, without much interest either way.".
  }
  Person riders "the lord's riders on the gate" at gate_leads {
    Role "four of the lord's riders, in buff coats, with the lord's badge". Ancestry human. Calling warrior. Level 2. Numbers 4. Peaceable. Pronouns they.
    Greets "One of the riders looks round, and says something to the others, and they laugh.".
  }
  Initially Assert takesPrisoners(gault). Initially Assert takesPrisoners(riders). Initially Assert serves(riders, gault).
  // They sleep in the small hours, on the nights before the captain comes; after, her own riders keep the bridge too,
  // and nobody sleeps.
  Rule riders_sleep when smallHours() and hour(clock) >= 1 and hour(clock) < 4 and not captainCome() and not asleep(riders) and not ridersRoused(riders) { Assert asleep(riders). }
  Rule riders_wake when (hour(clock) >= 4 or hour(clock) < 1 or captainCome()) and asleep(riders) { Retract asleep(riders). }
  Relation ridersRoused(group).
  Rule roused_ends when hour(clock) == 12 and ridersRoused(riders) { Retract ridersRoused(riders). }
  // Gault drinks at the Nine Wheels from seven until ten, because nobody else will serve him.
  Relation gaultAway(group).
  Rule gault_drinks when hour(clock) >= 19 and hour(clock) < 22 and not at(gault, wheels_taproom) and not gaultAway(gault) and able(gault) { Assert at(gault, wheels_taproom). }
  Rule gault_back when (hour(clock) >= 22 or hour(clock) < 19) and not at(gault, gate_leads) and not gaultAway(gault) and able(gault) { Assert at(gault, gate_leads). }
  Observe leads_asleep at gate_leads when asleep(riders) and at(riders, gate_leads) "The riders are asleep round the brazier, rolled in their cloaks with their boots to the coals, and one of them is snoring. Sergeant Gault sits against the parapet with his chin on his chest and his hand on his sword-hilt, asleep or near it.".
  Observe leads_turned at gate_leads when dark() and not asleep(riders) and riderPeaceBought(riders) and at(riders, gate_leads) "The riders sit round the brazier with their backs to the river parapet, all of them, very deliberately, eating bread and dicing, and none of them looks round.".
  Observe leads_awake at gate_leads when dark() and not asleep(riders) and not riderPeaceBought(riders) and at(riders, gate_leads) "The riders are awake round the brazier, dicing for farthings on a cloak, and every so often one of them looks along the parapet at the three.".
  Rule gault_sleeps when smallHours() and hour(clock) >= 1 and hour(clock) < 4 and not captainCome() and at(gault, gate_leads) and not asleep(gault) { Assert asleep(gault). }
  Rule gault_wakes when (hour(clock) >= 4 or hour(clock) < 1 or captainCome()) and asleep(gault) { Retract asleep(gault). }
  Topic gault_hanged with gault "Ask Sergeant Gault why he hanged them on the road" when true once {
    Says "'Warrant.' He holds his hands out to the brazier. 'Lord's warrant for the ringleaders of any rising against the lord's toll, to be taken and hanged where taken. We took them on the fell road with a dead lad in the back of the cart. Rising, a dead lad. That's the warrant.' He shrugs. 'The big one said he'd been driving. Said it twice. I don't hang a man twice.' He looks at the sacking, without anything in his face. 'Your reeve wanted them brought in for the court. I said: warrant. He went white. Clerks do.'".
  }
  Topic gault_road with gault "Ask Gault how he knew which road they'd take" when true once {
    Says "'Word came.' He does not look at you. 'Midnight, a lad with a letter. Back road to the fells, the cart with the red wheels, before light.' He shrugs. 'Somebody in this town wanted it done quiet. They all want it done quiet. Then they all come and stand at the gate and look.'".
    On discuss { Assert knows(actor, word_came). }
  }
  Discovery word_came "Someone in Wrayford sent Sergeant Gault a letter at midnight on the night of the rising, saying which road the carters would take to the fells, and that the cart had red wheels.".

  // Taking them down: the act the decree hangs a man for.
  Relation cutBy(group). Relation seenAtRail(group). Relation takenDown(place).
  Action cut_down(actor: group, site: place) "Cut the three down from the rail" {
    Grave "The decree is on the gatehouse door: whoever touches them shall hang beside them. Cut down, they cannot be put back.".
    Description "A knife to each rope, and a hand under each, so they do not fall.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gate_leads) and state(rail, hanging) and not benighted(actor).
    Time 1.
    On success { Assert state(rail, cut). Assert cutBy(actor). Assert takenDown(wray).
      Retract at(wat_dead, limbo). Assert at(wat_dead, gate_leads). Retract at(dunstan_dead, limbo). Assert at(dunstan_dead, gate_leads).
      Retract at(joss_dead, limbo). Assert at(joss_dead, gate_leads). }
    Result "You cut them down one by one, and take each one's weight as the rope goes, and lay them on the leads. They are lighter and heavier than you thought. Nobody in Wrayford will ever look at you the same way, if they know.".
  }
  // Whoever is seen at it by an awake rider is seized. The riders take prisoners.
  Rule seen_at_rail when cutBy(?c) and perceives(riders, ?c) and not seenAtRail(?c) and not riderPeace(riders) says "A rider is on his feet by the brazier. 'Sergeant! Sergeant, they're at the rail!' Then they are all up, and coming." {
    Assert seenAtRail(?c). Retract peaceable(riders). Retract peaceable(gault). Assert assails(riders, ?c). Assert ridersRoused(riders). }
  Rule seen_bearing when bearingAny(?c) and perceives(riders, ?c) and not seenAtRail(?c) and not riderPeace(riders) says "Someone on the leads shouts. A rider is looking straight at you, and at what you carry." {
    Assert seenAtRail(?c). Retract peaceable(riders). Retract peaceable(gault). Assert assails(riders, ?c). Assert ridersRoused(riders). }
  Relation riderPeace(group).
  // Taken: a night in the Guildhall cellar, and the dead back on the rail by morning.
  Relation heldInCellar(group).
  Rule taken_at_rail when (captured(riders, party) or captured(gault, party)) and not (fireFought(wray) and at(party, counting_room)) says "You come round in the dark on cold stone, with your hands tied. The Guildhall cellar. Up the stair, through the door, somebody is saying your name to the reeve." {
    Retract captured(riders, party). Retract captured(gault, party). Assert at(party, guild_cellar). Assert heldInCellar(party).
    Assert peaceable(riders). Assert peaceable(gault). }
  Rule cellar_unburdens when heldInCellar(party) and bearing(?m, ?b) { Retract bearing(?m, ?b). }
  Rule dead_put_back when heldInCellar(party) and state(rail, cut) and not buried(wat_dead) { Assert state(rail, hanging).
    Assert at(wat_dead, limbo). Assert at(dunstan_dead, limbo).
    Assert at(joss_dead, limbo). }

  // ── Bridge Street ─────────────────────────────────────────────────────────────────────────────────────────────────
  Observe street_scene at bridge_street when not dark() and not visitedBefore(bridge_street) "Bridge Street runs out over the river on the arches, three storeys of shops leaning toward each other across a lane so narrow the upper floors nearly meet: a glover, a cook-shop, a seller of spectacles, a seller of Saint Wade's badges, a tooth-drawer. Between the houses you see the river below through gaps, going by brown and fast. Halfway along, a chapel is built into the middle pier, and beyond it the drawbridge, and beyond that Overbridge and its church.".
  Observe street_again at bridge_street when not dark() and visitedBefore(bridge_street) "Bridge Street on the arches: the leaning shops, the gaps with the river in them, the chapel on the middle pier.".
  Observe street_night at bridge_street when dark() "Bridge Street at night: shutters, a cat, the sound of the river much louder than by day.".
  Observe hobday_outside at bridge_street when not jennetOpen(jennet) and not visitedBefore(bridge_street) "The first house past the gatehouse is the toll-keeper's, narrow, with a shut door. Its shutters are closed in the middle of the day.".

  // The bridge chapel, and under it, the starling: the cutwater ledge round the middle pier, reached by a ladder
  // through the undercroft, where boys fish.
  Observe chapel_scene at chapel when true "A small chapel of grey stone built into the pier, so that the river is loud through the floor. Candles. A trapdoor in the floor, propped open, with a ladder going down into the dark and the noise of water.".
  Observe starling_scene at starling when not dark() "The starling: a ledge of stone round the foot of the middle pier where it breaks the river, wet, green, wide enough for two to sit with their legs over. Under the arch the light is green and moving. On the stone someone, a long time ago, has cut two sets of initials with a knife.".
  Observe starling_night at starling when dark() "The starling at night: only the sound of the river, very close, and the arch overhead blacker than the sky.".

  // ── Jennet Hobday ─────────────────────────────────────────────────────────────────────────────────────────────────
  Person jennet "Jennet Hobday" at hobday_room {
    Role "the toll-keeper's widow". Ancestry human. Peaceable. Pronouns she. Manner proud.
    Greets "Jennet Hobday does not look up from the bed.".
  }
  Thing hobday_shut "Jennet Hobday's door" on hobday_door {
    State kept_shut blocking "The toll-keeper's door is shut. Knock, and a woman's voice inside says, 'Go away,' without anger, the way you would say it to the rain.".
    State on_latch "The toll-keeper's door is on the latch.".
  }
  Initially Assert state(hobday_shut, kept_shut).
  Measure jennetTrust(group). Initially Set jennetTrust(jennet) to 0.
  Relation jennetOpen(group). Relation jennetSat(group). Relation jennetIced(group).
  Rule jennet_opens when jennetOpen(jennet) and state(hobday_shut, kept_shut) { Assert state(hobday_shut, on_latch). }
  Observe hobday_scene at hobday_room when true "A front room with the shutters closed and a smell under the smell of lavender. On the bed, under a sheet, a boy. A woman sits by him on a hard chair, upright, with her hands in her lap. ".
  Observe hobday_hot at hobday_room when not jennetIced(jennet) "The room is very hot, and the shutters keep the heat in.".
  Observe hobday_iced at hobday_room when jennetIced(jennet) "Under the bed, in a tin bath, a block of ice wrapped in sacking is sweating into the tin. The room is a little cooler. The smell is a little less.".
  Kind ice_kind "a block of ice in sacking" is gear worth 1 weighing 6
    described "A block of grey ice the size of a loaf, wrapped in wet sacking, dripping. It will not keep long out of the dark.".
  Action bring_ice(actor: group, giver: member, cake: item, site: place) "Knock at Jennet Hobday's door, and say you have brought {cake}" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bridge_street) and state(hobday_shut, kept_shut)
      and memberOf(giver, actor) and ownedItem(cake, giver) and itemKind(cake, ice_kind).
    Time 2 minutes.
    Resolve drop(cake, giver).
    On success { Assert jennetOpen(jennet). Assert jennetIced(jennet). Increase jennetTrust(jennet) by 1. }
    Result "There is a long silence on the other side of the door. Then the bolt goes back. Jennet Hobday looks at the ice in your arms, and at you, and stands aside, and you carry it in and put it in the tin bath under the bed, where he is, and she watches you do it.".
  }
  Action sit_jennet(actor: group, site: place) "Sit with Jennet Hobday by the bed, and say nothing" {
    Description "An hour. She does not want talking to.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hobday_room) and at(jennet, hobday_room) and not jennetSat(actor).
    Time 6.
    On success { Assert jennetSat(actor). Increase jennetTrust(jennet) by 1. }
    Result "You sit. She does not tell you to go. After an hour she says, 'He took his father's place at the booth for the Company. A penny a day. He was proud of the penny.' That is all she says.".
  }
  Topic jennet_ned with jennet "Ask Jennet about Ned" when jennetTrust(jennet) >= 1 once {
    Says "'Fourteen.' She looks at the sheet. 'His father kept the lord's toll eleven years and died of his chest in the winter, and when the Company took the farm they said the boy could have the booth, a penny a day, since he knew the work. He'd stand at the chain in his father's hat.' Her hands stay still in her lap. 'He was at the chain when they came. He tried to keep it shut. A boy of fourteen, with his father's hat, holding the lord's chain against a hundred carters.' She looks at you for the first time. 'Wat Pardoe's cart. Everybody says so. And they've hung him for it, and I'm glad. I'm glad. Let the crows have him. Let the crows have him till the crows are sick.' She does not raise her voice at all.".
    On discuss { Assert knows(actor, jennet_hates). }
  }
  Discovery jennet_hates "Jennet Hobday believes Wat Pardoe's cart killed her son, and is glad he hangs, and wants him left to the crows.".
  Topic jennet_custom with jennet "Ask Jennet why Ned is not buried" when jennetTrust(jennet) >= 1 once {
    Says "'Corbin won't dig.' Flat. 'Old Corbin, at Wade's Acre. He's dug every grave in Wrayford forty years and he says he'll dig none while there's a Wrayford man on that rail, and he means the carters, not my boy. So my boy waits for Wat Pardoe.' Her mouth moves. 'The third day is tomorrow. The day after. I don't know what day it is. He'll go looking. That's what they say. I'd like to see him look. I'd like to see him get up.' And then, for the first time, her face goes, and she puts her hand over it, and keeps it there.".
    On discuss { Assert knows(actor, corbin_strike). }
  }
  Discovery corbin_strike "Corbin, sexton of Saint Wade's for forty years, will dig no grave in Wade's Acre while a Wrayford man hangs on the bridge. Nobody in the city can be buried until the carters come down: not the toll-keeper's boy, not Alderman Gidley's aunt.".
  // The truth, told by the one who drove, or by someone else.
  Relation kitToldJennet(group). Relation jennetTold(group). Relation jennetInformed(group).
  Action kit_tells_jennet(actor: group, site: place) "Stand by Kit while he tells Jennet Hobday who was driving" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hobday_room) and at(jennet, hobday_room)
      and travelsWith(kit, actor) and kitConfessed(actor) and not kitToldJennet(jennet).
    Time 3.
    On success { Assert kitToldJennet(jennet). Increase jennetTrust(jennet) by 2. Assert knows(actor, jennet_knows). }
    Result "Kit stands in the doorway with his cap in his hands, and tells her. All of it: the horse, the press, the wheel, his father lifting Ned into the cart like something precious, the bone-setter at Scar Top, the riders on the fell road. He does not cry until he gets to the part where his father said get away home. Jennet Hobday listens without moving. When he has finished she sits a long time. Then she says, 'You used to fish with him. Off the starling.' Kit nods. She looks at the sheet on the bed. 'He said you were the only one of the carters' lot who wasn't a lout.' She does not forgive him. She does not tell him to go, either.".
  }
  Discovery jennet_knows "Jennet Hobday knows who was driving, and why Wat Pardoe said he was.".
  Action tell_jennet(actor: group, site: place) "Tell Jennet Hobday that Kit Pardoe was driving, and Wat took the blame" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hobday_room) and at(jennet, hobday_room)
      and knows(actor, kit_driving) and not kitToldJennet(jennet) and not jennetTold(jennet).
    Time 2.
    On success { Assert jennetTold(jennet). Assert jennetInformed(jennet). }
    Result "She hears you out without moving. Then she gets up, and puts on her shawl, and goes past you out of the door without a word, and down Bridge Street toward the Guildhall, walking very fast.".
  }
}

data/adventures/wrayford/captain.kyr:
Module wrayford "The Third Night" {
  // ── The captain ───────────────────────────────────────────────────────────────────────────────────────────────────
  // Lys Sefton, the lord's captain, comes up the south road at dusk on the third day with her riders, sups with the
  // Bench in the Guildhall, and gives her verdict on the fourth morning: is Wrayford in rebellion?
  Person sefton "Captain Lys Sefton" at limbo {
    Role "the lord's captain, in a grey riding-coat with the lord's badge". Ancestry human. Calling warrior. Level 6. Peaceable. Pronouns she. Manner stoic.
    Greets "Captain Sefton looks at you as if you were a road she had to decide whether to take.".
  }
  Person troop "the captain's riders" at limbo {
    Role "a dozen of the lord's riders, dusty from the road". Ancestry human. Calling warrior. Level 3. Numbers 6. Peaceable. Pronouns they.
  }
  Initially Assert takesPrisoners(sefton). Initially Assert takesPrisoners(troop).
  Rule riders_sighted when thirdDay() and hour(clock) >= 12 and not spread(sighted_fact) and inWrayford() says "At noon a boy comes running over the drawbridge from Overbridge shouting that there are riders on the south road, a long way off, a dozen of them and a woman in grey, and the whole of the Bridge End turns to look south." { Assert spread(sighted_fact). }
  Entity sighted_fact: fact "Riders sighted".
  // On the south road in the late afternoon, ahead of her own arrival.
  Rule captain_on_road when thirdDay() and hour(clock) >= 15 and hour(clock) < 19 and at(sefton, limbo) { Assert at(sefton, south_road). Assert at(troop, south_road). }
  Rule captain_arrives when captainCome() and not captainHere(wray) { Assert captainHere(wray). Assert at(sefton, guild_hall). Assert at(troop, gate_road). }
  Relation captainHere(place).
  Rule captain_told when captainHere(wray) and inWrayford() and not spread(arrived_fact) says "At dusk the captain rides in over the drawbridge with her riders behind her, and does not look up at the gatehouse as she passes under it, and goes to the Guildhall, where the Bench has laid supper." { Assert spread(arrived_fact). }
  Entity arrived_fact: fact "The captain arrived".
  Rule captain_sups when captainHere(wray) and hour(clock) >= 19 and hour(clock) < 23 and not at(sefton, guild_hall) and not verdictGiven(wray) { Assert at(sefton, guild_hall). }
  Rule captain_retires when captainHere(wray) and (hour(clock) >= 23 or hour(clock) < 7) and not at(sefton, hulme_study) and not verdictGiven(wray) { Assert at(sefton, hulme_study). }
  Rule captain_court when fourthDay() and hour(clock) >= 7 and not at(sefton, guild_hall) and not verdictGiven(wray) { Assert at(sefton, guild_hall). }
  Observe supper_scene at guild_hall when captainHere(wray) and hour(clock) >= 19 and hour(clock) < 23 "The Bench's supper for the captain: candles down the long table, the aldermen in their best gowns, a swan nobody is eating, and at the head of the table a woman in a grey riding-coat with the road's dust still on it, eating bread and cheese and listening to Gidley with no expression at all. The reeve sits at her right hand and does not eat.".
  Measure captainView(group). Initially Set captainView(sefton) to 0.
  Relation captainMet(group). Relation captainPinch(group). Relation captainFuneral(group). Relation companyOffersKit(place).
  Discovery captain_question "Captain Sefton has one question for Wrayford: is it in rebellion? Ten hanged for every rider hurt, and the carters' row burned, if it is; the toll money taken and her riders home if it is not.".
  Topic sefton_road with sefton "Ask the captain what she means to do in Wrayford" when not verdictGiven(wray) once {
    Says "'Find out whether Wrayford is in rebellion.' She does not slow her horse, or her voice. 'If it is, I have a warrant for ten for every rider hurt and the carters' row burned to the stones, and I will do it. If it is not, I will take the lord's toll money and go home, and be glad.' She looks at you for the first time. 'I would rather go home. People think a captain likes a burning. Nobody likes a burning.'".
    On discuss { Assert knows(actor, captain_question). Assert captainMet(actor). }
  }
  Action meet_captain(actor: group, site: place) "Walk beside the captain's horse and tell her what Wrayford is, before the Bench does" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, south_road) and at(sefton, south_road) and captainMet(actor) and not triedCaptain(actor).
    Time 3.
    Resolve check(actor, persuasion, dc_fair).
    On success { Increase captainView(sefton) by 1. Assert triedCaptain(actor). }
    On failure { Assert triedCaptain(actor). }
    Result "You walk at her stirrup for a mile and tell her: the carters broke a chain and threw a board in the river; a boy died under a cart in the press; three men hanged on the road without a court; a widow who means to bury her husband; a city that would rather bury its dead than burn. She does not say anything. At the last milestone she says, 'Thank you. I'll see for myself,' and you understand that you have been listened to.".
    Otherwise "She listens to the first sentence and then says, 'I'll see for myself,' and touches her horse, and you are walking alone.".
  }
  Relation triedCaptain(group).
  Action tell_captain_fire(actor: group, site: place) "Tell the captain at supper that there was no rising: a riot, and a thief" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, guild_hall) and at(sefton, guild_hall) and knows(actor, fire_pinch)
      and (carries(actor, daybook) or pinchExposed(wray)) and not captainPinch(actor).
    Time 1.
    On success { Assert captainPinch(actor). Increase captainView(sefton) by 2. Assert pinchExposed(wray). }
    Result "You tell her about the flask in the ash, and the shirt, and the day-book, and what is in it, and when you have finished she turns, slowly, to look down the table at Alderman Gidley, who has gone the colour of the swan. 'So the carters broke a chain,' she says, 'and threw your board in the river, and your collector burned your toll-house to hide that he was robbing you.' She puts her bread down. 'That is not a rising, Alderman. That is a riot, and a thief.' Nobody at the table says anything at all.".
  }
  Action tell_captain_funeral(actor: group, site: place) "Tell the captain that Wrayford will bury its dead, not burn" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, guild_hall) and at(sefton, guild_hall) and not captainFuneral(actor)
      and (buried(wat_dead) or mothersMet(wray) or releaseUnderway(wray)).
    Time 1.
    On success { Assert captainFuneral(actor). Increase captainView(sefton) by 1. }
    Result "She hears you, and looks at the reeve, who nods without lifting his eyes. 'A funeral,' she says. 'Not a rising.' She seems to think about it. 'I've seen both. I know the difference.'".
  }
  // A drover who owes you something, and who has driven through every rising in the north, says so where it counts.
  Relation hamSpoke(group).
  Rule ham_speaks when captainHere(wray) and hamGrateful(party) and not hamSpoke(ham) and not verdictGiven(wray) says "At the Bridge End, as the captain's riders water their horses, Ham Ostler leans on his crook and tells the nearest of them, loud enough for the captain, that he has driven beasts through every rising in the north these thirty years, and this is not one, it is a city with a toothache. The captain looks at him from the saddle. Drovers, it seems, are people she listens to." {
    Assert hamSpoke(ham). Increase captainView(sefton) by 1. }
  // She asks the company one question, the first time it speaks to her in the city: the only one at the table she has
  // not been told what to think of. What it may answer depends on who it is.
  Relation captainAsked(group). Relation captainAnswered(group).
  Event captain_asks near sefton when captainHere(wray) and addressed(sefton, party) and not captainAsked(party) and not verdictGiven(wray) "Captain Sefton looks at you down the length of the table, past the aldermen. 'You,' she says. 'You are the only person in this hall I have not been told what to think of. Is Wrayford in rebellion?' The table goes quiet. Gidley opens his mouth, and she lifts one finger without looking at him, and he shuts it." then { Assert captainAsked(party). }
  Topic answer_captain_kin with sefton "Tell her: my father is on that rail, and I have not burned anything" when captainAsked(actor) and homecomer(actor) and not captainAnswered(actor) once {
    Says "She looks at you for a long moment. 'Pardoe,' she says. 'The big one, who sang.' She turns her cup round on the cloth. 'A rebel's child who comes to supper with the Bench instead of to the gate with a torch.' She does not say what she makes of it. But she does not look at Gidley again for the rest of the meal.".
    On discuss { Assert captainAnswered(actor). Increase captainView(sefton) by 1. }
  }
  Topic answer_captain_stranger with sefton "Tell her: I am a stranger here, with nobody on the rail; it is grief, not rebellion" when captainAsked(actor) and stranger(actor) and not captainAnswered(actor) once {
    Says "'A stranger.' She considers you as if you were a horse somebody else was selling. 'Then you've no reason to lie to me, and no reason to tell me the truth, which is the best a captain ever gets.' She nods, once. 'Grief. I have seen grief. It does not usually set fire to things.' She looks down the table at the aldermen. 'Usually.'".
    On discuss { Assert captainAnswered(actor). Increase captainView(sefton) by 1. }
  }
  Topic answer_captain_carters with sefton "Tell her to ask the carters, not the Bench" when captainAsked(actor) and not captainAnswered(actor) once {
    Says "'The carters.' She almost smiles. 'Yes. I'll go to the yards tonight, without my riders, and see what they are.' She does. Word comes back before midnight: she stood in the carters' yards for an hour with a pot of the Nine Wheels' ale, and they told her about the board in the river, and the chain, and nobody drew a knife.".
    On discuss { Assert captainAnswered(actor). Assert captainSawYards(sefton). }
  }
  Relation captainSawYards(group).
  // What she finds in the yards depends on what the carters did.
  Rule captain_yards_quiet when captainSawYards(sefton) and not fireTried(wray) and not countingBurned(wray) and not yardsCounted(sefton) { Assert yardsCounted(sefton). Increase captainView(sefton) by 1. }
  Rule captain_yards_laughing when captainSawYards(sefton) and boardSunk(wray) and not countingBurned(wray) and not yardsCounted(sefton) { Assert yardsCounted(sefton). Increase captainView(sefton) by 1. }
  Relation yardsCounted(group).
  // The Company, at supper, offers the captain a live ringleader for the lord's justice: the boy, if it knows of him.
  Rule company_offers when captainHere(wray) and hour(clock) >= 20 and (bargainMade(party) or kitExposed(wray)) and not companyOffersKit(wray) and not kitTaken(kit) and not travelsWith(kit, party) says "Word comes out of the Guildhall supper: Alderman Gidley has told the captain, with tears, that the true driver of the cart was Wat Pardoe's son, and that the Company would think it a great mercy to the city if the lord's justice took the boy alive. The riders go to the yards for Kit Pardoe." {
    Assert companyOffersKit(wray). Assert kitTaken(kit). Assert at(kit, guild_cellar). }
  // The Company keeps its word, such as it is: a live ringleader bought, it asks mercy for the dead, before the third night.
  Rule company_mercy when captainHere(wray) and hour(clock) >= 20 and kitSold(kit) and stillHanging() and not releaseUnderway(wray) says "Word comes out of the Guildhall supper: the Company, having given the lord's justice a live ringleader, has asked the captain's mercy for the dead, as a kindness to the city, and she has granted it, with a look at Alderman Gidley that goes on a little too long. The three come down from the rail by torchlight and are carried over the bridge to Wade's Acre, to wait for morning." {
    Assert releaseUnderway(wray). Assert releasedBy(wray, by_captain). }

  // ── The third night: the reeve, too late; the carters, rising ─────────────────────────────────────────────────────
  Relation reeveLate(place). Relation tooLate(place). Relation riseNight(place).
  Rule reeve_goes_late when hulmeMoved(hulme) >= 3 and captainCome() and stillHanging() and thirdDay() and hour(clock) >= 3 and hour(clock) < 6 and not reeveLate(wray) and not releaseUnderway(wray) {
    Assert reeveLate(wray). }
  Rule reeve_late_finds when reeveLate(wray) and maudieTaken(maudie) and not tooLate(wray) says "In the small hours Simon Hulme comes down the Cartway to the Bridge End alone, without a lantern, with a knife in his hand, to cut his cousin's husband down from the rail against the captain's word and answer for it. He is a quarter of an hour behind Maudie Pardoe. He stands under the gatehouse arch and looks at the empty step where the riders took her, and the riders look down at him from the leads, and nobody says anything at all." { Assert tooLate(wray). }
  Rule reeve_late_cuts when reeveLate(wray) and not maudieTaken(maudie) and stillHanging() says "In the small hours Simon Hulme comes down the Cartway to the Bridge End alone with a knife in his hand, and goes up the gate-ward's stair past the captain's riders, who do not stop the reeve, and cuts the three down himself, against the captain's word, and has them carried over the bridge at first light." {
    Assert releaseUnderway(wray). Assert reeveRelease(wray). Assert releasedBy(wray, by_reeve). }
  // With his mother in the cellar and his father on the rail, Kit takes the young carters to the gatehouse, unless he
  // is held, or with you, or has given his word.
  Rule carters_rise when maudieTaken(maudie) and stillHanging() and not kitTaken(kit) and not travelsWith(kit, party) and not kitStoodDown(kit) and thirdDay() and hour(clock) >= 4 and hour(clock) < 6 and not riseNight(wray) says "Before dawn the carters' yards empty. Kit Pardoe goes down the Cartway at the head of thirty men with cart-staves and torches, to the gatehouse where his mother was taken, and the captain's riders meet them at the Bridge End. By first light it is over, and Kit is in the Guildhall cellar with his arm broken, and two of the riders are being carried into the Bridge End inn." {
    Assert riseNight(wray). Assert kitTaken(kit). Assert at(kit, guild_cellar). }

  // ── The verdict ───────────────────────────────────────────────────────────────────────────────────────────────────
  // At nine on the fourth morning, in the Guildhall. Rebellion is fire raised, or riders beaten, or a rising at the gate.
  Relation verdictGiven(place). Relation verdictRebellion(place). Relation verdictOrder(place).
  Relation countingBurned(place). Relation ridersBeaten(place). Relation kitHanged(group). Relation maudieHanged(group).
  Rule riders_beaten when (routed(riders) or not able(riders) or not able(gault)) and not ridersBeaten(wray) { Assert ridersBeaten(wray). }
  Query rebellion() means countingBurned(wray) or ridersBeaten(wray) or riseNight(wray).
  Rule verdict_rebellion when fourthDay() and hour(clock) >= 9 and not verdictGiven(wray) and rebellion() {
    Assert verdictGiven(wray). Assert verdictRebellion(wray). }
  Rule verdict_order when fourthDay() and hour(clock) >= 9 and not verdictGiven(wray) and not rebellion() {
    Assert verdictGiven(wray). Assert verdictOrder(wray). }
  // An example: whoever she holds for the decree, she hangs; whoever she holds for the cart, she takes to the lord.
  Rule maudie_hanged when verdictGiven(wray) and maudieTaken(maudie) and not maudieHanged(maudie) and captainView(sefton) < 3 { Assert maudieHanged(maudie). }
  Rule kit_hanged when verdictGiven(wray) and kitTaken(kit) and (kitSold(kit) or companyOffersKit(wray) or verdictRebellion(wray) or fireTried(wray) and not kitStoodDown(kit) and not kitTurned(kit) and not boardSunk(wray) or kitBlamed(kit)) and not kitHanged(kit) { Assert kitHanged(kit). }
  // The company is let out of the cellar at the verdict, fined, and told to be gone by the south road; the captain
  // has what she came for.
  Rule cellar_released when verdictGiven(wray) and heldInCellar(party) says "At nine the cellar door opens and a rider takes you up into the long hall, where the captain is sitting in the reeve's chair. She looks at you for a long time. 'You did what you did,' she says. 'I have what I came for.' A fine is taken from your purse. 'Be on the south road by noon, and do not come back to the lord's bridge this year.' The riders walk you to the drawbridge." {
    Retract heldInCellar(party). Assert at(party, overbridge_street). Assert banished(party). }
  Relation banished(group).
  Rule cellar_fine when banished(party) and not fined(party) { Assert fined(party). Decrease quantity(party, gold) by 5. }
  Relation fined(group).
  Rule halt_banished when banished(party) and at(party, gate_road) says "The captain's rider at the Bridge End shakes his head. 'Not this year,' he says." { Assert at(party, bridge_street). }
}

data/adventures/wrayford/clock.kyr:
Module wrayford "The Third Night" {
  // ── The three days ────────────────────────────────────────────────────────────────────────────────────────────────
  // Wrayford's days are counted from the company's coming, at each dawn after the first hour it is here: the day it
  // comes is the first. The dead were hanged four nights before. The captain comes at dusk on the third day; the third
  // night is the night after it, and in the small hours of the fourth day Maudie Pardoe goes to the gatehouse.
  Measure dayN(place). Relation dawned(place).
  Initially Set dayN(wray) to 1.
  Rule dawn_counts when hour(clock) == 6 and not dawned(wray) and watch(clock) >= 6 { Increase dayN(wray) by 1. Assert dawned(wray). }
  Rule dawn_passes when hour(clock) != 6 and dawned(wray) { Retract dawned(wray). }
  Query dayIs(n: place) means dayN(wray) == dayN(n).
  // Days by name, for rules that read like the city's own talk.
  Query firstDay() means dayN(wray) == 1.
  Query secondDay() means dayN(wray) == 2.
  Query thirdDay() means dayN(wray) == 3.
  Query fourthDay() means dayN(wray) == 4.
  Query fifthDay() means dayN(wray) == 5.
  Query morning() means hour(clock) >= 6 and hour(clock) < 12.
  Query evening() means hour(clock) >= 18 and hour(clock) < 22.
  Query smallHours() means hour(clock) >= 0 and hour(clock) < 5.
  // The third night: after the captain's coming, until the fourth day's dawn.
  Query thirdNight() means thirdDay() and (hour(clock) >= 21 or hour(clock) < 6).
  Query captainCome() means thirdDay() and (hour(clock) >= 19 or hour(clock) < 6) or dayN(wray) >= 4.

  // ── The river ─────────────────────────────────────────────────────────────────────────────────────────────────────
  // The mills above the weir grind by day and pen the river by night: from one in the morning until five the Wray
  // runs low below the bridge, and the old ford-stones are under a foot of water instead of six.
  Query lowWater() means hour(clock) >= 1 and hour(clock) < 5.
  // Dorcas runs her ferry from six in the morning until the curfew bell, and at night for those she has agreed to.
  Relation ferriesAtNight(group).
  Query ferryRunning() means hour(clock) >= 6 and hour(clock) < 22 and at(dorcas, ferry_stage) or ferriesAtNight(party).

  // The drawbridge goes up at the curfew bell, for the night barges and against the night, and comes down at dawn.
  Thing drawbridge "the drawbridge" on drawbridge_span is scenery {
    State down "The drawbridge is down.".
    State raised blocking "The drawbridge stands up against the sky on its chains. Nobody crosses the river by it until it comes down at dawn.".
  }
  Initially Assert state(drawbridge, down).
  Rule curfew_raises when hour(clock) >= 22 and state(drawbridge, down) { Assert state(drawbridge, raised). }
  Rule small_hours_raised when hour(clock) < 5 and state(drawbridge, down) { Assert state(drawbridge, raised). }
  Rule dawn_lowers when hour(clock) >= 5 and hour(clock) < 22 and state(drawbridge, raised) { Assert state(drawbridge, down). }
  Rule curfew_bell at gate_road when hour(clock) == 22 and not knows(party, curfew_known) says "Saint Wade's rings the curfew across the water, and on the bridge the drawbridge chains begin to grind." teaches curfew_known { }
  Discovery curfew_known "At the curfew bell, ten at night, the drawbridge goes up, and nobody crosses the bridge until it comes down at dawn.".

  // ── Where word reaches the company ────────────────────────────────────────────────────────────────────────────────
  // News of the city is heard anywhere in Wrayford, on the bridge or in Overbridge; not out on the roads.
  Query inWrayford() means at(party, ?p) and not at(party, drove_road) and not at(party, south_road).
  // News already gone round, so it is not told twice.
  Relation spread(fact).
  // A place the company has left and come back to is told shortly.
  Relation visitedNow(place). Relation visitedBefore(place).
  Rule arrives_at when at(party, ?p) and not visitedNow(?p) { Assert visitedNow(?p). }
  Rule leaves_from when visitedNow(?p) and not at(party, ?p) { Retract visitedNow(?p). Assert visitedBefore(?p). }

  // ── Who the company is, here ──────────────────────────────────────────────────────────────────────────────────────
  // Wat Pardoe's elder child, come home (the campaign played alone: company.kyr); or a traveller, come down the drove
  // road with the world's own company. Everything said to kin is said only to kin.
  Relation homecomer(group).
  Query stranger(g: group) means not homecomer(g).
}

data/adventures/wrayford/company.kyr:
Module wrayford "The Third Night" {
  // The campaign played alone: Wat Pardoe's elder child, three years away with the droves on the far side of the fells,
  // coming home on their mother's letter, a week after it was written. (placed.kyr is the world's own company, come in
  // by the drove road with no kin here.)
  Company party "You" of 1 at drove_road.
  Initially Set quantity(party, gold) to 9. Initially Set quantity(party, rations) to 2.
  Initially Assert homecomer(party).
  Initially Assert kin(party, maudie). Initially Assert kin(party, kit).
  Initially Assert kinship(maudie, called_mother). Initially Assert kinship(kit, called_brother).
  Entity called_mother: fact "your mother". Entity called_brother: fact "your brother".
}

data/adventures/wrayford/day.kyr:
Module wrayford "The Third Night" {
  // ── The Remonstrance ──────────────────────────────────────────────────────────────────────────────────────────────
  // Noon to two on the second day, in the Guildhall: the Bench of the Bridge Company moves a Remonstrance to the lord
  // against the toll it farms, and any citizen may move a clause. The Bench passes whatever costs it nothing it can be
  // seen to lose. If nobody moves anything, the clerk's own clause passes.
  Query benchSitting() means secondDay() and hour(clock) >= 12 and hour(clock) < 14 and not benchRose(wray).
  Relation benchRose(place). Relation moved(entity).
  Relation clauseCharity(place). Relation clauseRelease(place). Relation clauseWorse(place). Relation clauseAudit(place).
  Entity motion_release: fact "that the dead be released".
  Entity motion_charity: fact "that the dead be commended to the Liberty's charity".
  Entity motion_toll: fact "that the toll be lifted".
  Entity motion_audit: fact "that the Company's accounts be laid open".
  Person bench "the Bench of the Bridge Company" at guild_hall {
    Role "five aldermen in blue gowns at the long table". Ancestry human. Numbers 1. Peaceable. Pronouns they.
    Seen when benchSitting().
  }
  Observe bench_scene at guild_hall when benchSitting() "The Bench is sitting: five aldermen in blue gowns along the dais, Gidley in the middle, the clerk Inchbold at a little desk below with the Remonstrance before him, and the public benches full of carters with their caps on their knees, and the Hill's wives in the gallery with their fans. Gidley is reading the Remonstrance aloud. It is very long, and it is against the toll in every particular, and it ends: the Company remaining, notwithstanding, the lord's loyal farmers of the same.".
  Query canMove(a: group) means benchSitting() and at(a, guild_hall).
  Action move_release(actor: group, site: place) "Rise, and move that the dead be released from the rail" {
    Requires able(actor) and company(actor) and at(actor, site) and canMove(actor) and not moved(motion_release).
    Time 1.
    On success { Assert moved(motion_release). }
    Result "There is a silence on the dais, and then a great deal of shuffling. Alderman Pocock says that it would be very unwise, at such a time, for the Company to be seen to dictate to the lord's officers. Alderman Dunch says the lord might take it amiss. Gidley says, with real tears, that his heart is with you, wholly, and the motion is put, and fails, four to one, the one being nobody: Gidley abstains, from emotion.".
  }
  // Or the Alderman has seen his own face that morning, painted as it is, and taken it for a portrait of his burden.
  Rule release_carried_portrait when moved(motion_release) and portraitHung(wray) and not honoriaLobbies(honoria) and not clauseRelease(wray) says "Gidley has been looking all the while past the speakers to the easel at the end of the hall, where Tom Lumley's Bench sits round its model bridge with his own face in the middle of it. Now he stands, and wipes his eyes, and says that a Company which bears the crossing can bear this, and that he votes for the motion; and Alderman Pocock, who owes him money, votes with him, and so does Alderman Dunch, who owes Pocock. It passes, three to two. At the easel, Tom Lumley puts his brushes away very carefully, so as not to be seen laughing." { Assert clauseRelease(wray). }
  Rule release_carried when moved(motion_release) and honoriaLobbies(honoria) and not clauseRelease(wray) says "And then, from the gallery, a woman's voice, quite clear: 'Prosper.' Alderman Gidley looks up at his wife among the fans. He looks for a long time. Then he stands, and says that on reflection he will vote, and that he votes for the motion, and Alderman Pocock, who owes him money, votes with him, and so does Alderman Dunch, who owes Pocock. It passes, three to two. The carters' benches do not cheer. They do not know what to do." { Assert clauseRelease(wray). }
  Action move_charity(actor: group, site: place) "Rise, and move that the dead be commended to the Liberty's charity, at the Liberty's charge, the Company's rights being reserved" {
    Requires able(actor) and company(actor) and at(actor, site) and canMove(actor) and knows(actor, bench_rule) and not moved(motion_charity).
    Time 1.
    On success { Assert moved(motion_charity). Assert clauseCharity(wray). }
    Result "You put it as Inchbold would: the dead commended to the Liberty's charity, at the Liberty's charge, the Company's rights in all things being reserved and its loyalty to the lord unquestioned. There is a pause while the Bench looks for what it costs. It costs nothing. Gidley's face lights up. 'Charity,' he says, 'at the Liberty's charge,' and the motion is carried by acclamation, and the Bench congratulates itself at some length on its humanity. Inchbold writes it in. He looks up at you once, with something like professional respect.".
  }
  Action move_toll(actor: group, site: place) "Rise, and move that the toll be lifted" {
    Requires able(actor) and company(actor) and at(actor, site) and canMove(actor) and not moved(motion_toll).
    Time 1.
    On success { Assert moved(motion_toll). }
    Result "The Bench laughs. Not unkindly: the way you laugh at a child who has asked why the sea is salt. Alderman Pocock wipes his eyes. 'The Company,' says Gidley, 'is the city's shield against the toll,' and the motion is not put. On the carters' benches a man says something very short, and is not hushed.".
  }
  Action move_audit(actor: group, site: place) "Rise, and move that the Company's accounts of the toll be laid open to the city" {
    Requires able(actor) and company(actor) and at(actor, site) and canMove(actor) and knows(actor, fire_pinch) and not moved(motion_audit).
    Time 1.
    On success { Assert moved(motion_audit). Assert clauseAudit(wray). Assert pinchExposed(wray). Increase temper(wray) by 1. }
    Result "You say why: the oil flask in the ash, the shirt, the day-book. The hall goes so quiet you can hear the clock. Gidley stands up, purple, and says that the Company has nothing to hide, nothing, and that if its servant has robbed it the Company will be the first to know, and the motion is carried, and only afterwards, in the arcade, does he seem to understand what he has voted for. The carters' benches empty into the Market shouting PINCH.".
  }
  // At two, the Bench rises; if nobody moved anything of use, the clerk's clause is read in.
  Rule bench_rises when secondDay() and hour(clock) >= 14 and not benchRose(wray) { Assert benchRose(wray). }
  Rule worse_clause when benchRose(wray) and stillHanging() and not clauseCharity(wray) and not clauseRelease(wray) and not clauseWorse(wray) and inWrayford() says "At two the Bench rises. The Remonstrance goes to the lord with one clause added at the end, which the clerk read in and nobody opposed: that the dead remain upon the rail until the Company's loss in the riot shall have been reckoned by the lord's captain, the Company's claims being thereby secured. The reeve, it is said, read it in his court with his face like a shut door." { Assert clauseWorse(wray). }
  // A measure cannot go below nothing: an effect that would take it there makes the whole rule impossible.
  Rule worse_clause_hardens when clauseWorse(wray) and hulmeMoved(hulme) >= 1 and not clauseHardened(wray) { Assert clauseHardened(wray). Decrease hulmeMoved(hulme) by 1. }
  Relation clauseHardened(place).

  // ── The Liberty's charity: the dead released lawfully, before the captain ────────────────────────────────────────
  Query crossingLawful() means ruling(ruled_tithe) or pinchExposed(wray) or pinchGone(pinch) or ruling(ruled_carcass).
  Query benchLeave() means clauseCharity(wray) or clauseRelease(wray).
  Relation releaseUnderway(place). Relation reeveRelease(place). Relation releasedBy(place, entity).
  Entity by_charity: fact "the Liberty's charity". Entity by_reeve: fact "the reeve's own word". Entity by_captain: fact "the captain's leave". Entity by_city: fact "the city itself".
  Action lay_before_reeve(actor: group, site: place) "Lay before the reeve the Bench's leave, the Abbess's claim, and the ruling at the chain" {
    Requires able(actor) and company(actor) and at(actor, site) and at(hulme, site) and stillHanging() and not captainCome()
      and benchLeave() and abbessClaims(abbess) and crossingLawful() and not releaseUnderway(wray).
    Time 1.
    On success { Assert releaseUnderway(wray). Assert lawfulRelease(wray). Assert releasedBy(wray, by_charity). }
    Result "He reads the Abbess's letter, and the Bench's clause in Inchbold's copperplate, and the line in Pinch's tally, slowly, all three, twice. Then he puts them square on the desk, edge to edge, the way a clerk does. 'Cover,' he says. 'There it is.' He does not look pleased. He looks like a man who has been let off something and knows it. He calls his constable. 'Cut them down,' he says. 'Give them to the Abbess's brothers at the chain. They cross as the Liberty's tithe, by the Bench's leave.' And then, to you, so low you barely hear it: 'Thank you.'".
  }
  // The reeve's own word, moved far enough by people and not by papers: he does it himself, by day, and will answer
  // for it to the captain.
  Rule reeve_relents when hulmeMoved(hulme) >= 3 and stillHanging() and not captainCome() and not releaseUnderway(wray)
    and hour(clock) >= 9 and hour(clock) < 18 and inWrayford() says "In the middle of the day Simon Hulme comes out of the Guildhall alone, without his chain of office, and walks down to the Bridge End, and the crowd parts for him. He goes up the gate-ward's stair. Gault meets him at the top and says something, and the reeve says something back, and Gault stands aside. And the reeve of Wrayford cuts the three down from the rail with his own knife, one by one, and hands them down to the carters below, and comes down after them, and goes back up the Cartway to the Guildhall, and shuts the door." {
    Assert releaseUnderway(wray). Assert reeveRelease(wray). Assert releasedBy(wray, by_reeve). }
  // Once released, by day: carried over, graves dug, buried.
  Rule release_takes_down when releaseUnderway(wray) and stillHanging() { Assert state(rail, cut). Assert takenDown(wray).
    Assert at(wat_dead, wades_acre). Assert at(dunstan_dead, wades_acre). Assert at(joss_dead, wades_acre). Assert corbinWillDig(wray). }
  Rule release_graves when releaseUnderway(wray) and state(graves, marked) and corbinResigned(corbin) { Assert state(graves, dug). }
  Rule release_buries when releaseUnderway(wray) and state(graves, dug) and not buried(wat_dead) says "In Wade's Acre, in the afternoon, the three are buried by the church door, with Wrayford standing round the wall and on the wall and on the roofs of the tan-yards. The Abbess says the office herself." {
    Assert buried(wat_dead). Assert buried(dunstan_dead). Assert buried(joss_dead). Assert buriedLawfully(wray).
    Assert at(wat_dead, limbo). Assert at(dunstan_dead, limbo). Assert at(joss_dead, limbo). }

  // ── The two mothers ───────────────────────────────────────────────────────────────────────────────────────────────
  Relation jennetKnowsTruth(group). Relation mothersMet(place). Relation mothersWalk(place). Relation mothersWalked(place).
  Relation mothersTurnedBack(place). Measure walkDay(place).
  Rule jennet_learns_from_kit when kitToldJennet(jennet) and not jennetKnowsTruth(jennet) { Assert jennetKnowsTruth(jennet). }
  // Told by someone she trusts, she keeps it; by someone she does not, she goes to the reeve.
  Rule jennet_keeps when jennetTold(jennet) and jennetTrust(jennet) >= 3 and not jennetKnowsTruth(jennet) and not kitInformedOn(kit) { Assert jennetKnowsTruth(jennet). }
  Rule jennet_goes_to_reeve when jennetTold(jennet) and jennetTrust(jennet) < 3 and not kitInformedOn(kit) and not jennetKnowsTruth(jennet) says "Jennet Hobday walks up the Cartway to the Guildhall and asks for the reeve, and is with him an hour. In the evening the riders take Kit Pardoe from the yards." {
    Assert kitInformedOn(kit). Assert kitTaken(kit). Assert at(kit, guild_cellar). Set kitTrust(kit) to 0. }
  Relation kitInformedOn(group).
  Observe jennet_after_tell at hobday_room when jennetTold(jennet) and jennetTrust(jennet) >= 3 and not kitToldJennet(jennet) "Jennet Hobday sits by the bed with her hands in her lap. 'He lifted him in,' she says, not to you. 'He lifted him in like something precious and drove for the bone-setter.' She says it again, as if learning it. 'You've sat with me,' she says. 'I'll not hang a boy for this. I've had enough of hanging.'".
  Action bring_jennet(actor: group, site: place) "Ask Jennet Hobday to come with you to Wain Row, and sit with Maudie Pardoe" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hobday_room) and at(jennet, hobday_room)
      and jennetKnowsTruth(jennet) and jennetTrust(jennet) >= 3 and stillHanging() and not mothersMet(wray) and not captainCome().
    Time 6.
    On success { Assert mothersMet(wray). Set walkDay(wray) to dayN(wray) + 1. Assert at(actor, wain_row). Assert at(jennet, pardoe_kitchen). }
    Result "She looks at the bed for a long time. Then she puts on her shawl. You walk with her the length of Bridge Street and up the Cartway and down Wain Row, and people stop in their doorways to watch the toll-keeper's widow go to the carter's widow's door. Maudie Pardoe opens it with flour on her hands. The two women look at each other. Then Maudie stands aside, and Jennet goes in, and the door shuts, and you are not asked in, and you do not ask. After an hour Maudie comes to the door and says to you, quite briskly, as if arranging a wash-day: 'In the morning. Both of them. Over the bridge, in the light, with the city behind us. And let them stop us.'".
  }
  // The morning after: if the city is behind them, nobody stops them.
  Rule mothers_set_out when mothersMet(wray) and dayN(wray) >= walkDay(wray) and hour(clock) >= 8 and stillHanging() and not mothersWalk(wray) and not captainCome() and temper(wray) >= 2 {
    Assert mothersWalk(wray). Assert releaseUnderway(wray). Assert releasedBy(wray, by_city). Assert mothersWalked(wray). Assert corbinWillDig(wray). }
  Rule mothers_turned when mothersMet(wray) and dayN(wray) >= walkDay(wray) and hour(clock) >= 8 and hour(clock) < 9 and stillHanging() and not mothersWalk(wray) and temper(wray) < 2 and not mothersTurnedBack(wray) says "In the morning the two widows walk down the Cartway together to the Bridge End with a handful of neighbours behind them, and at the gate-ward's door Sergeant Gault meets them and says, not unkindly, 'Not on my watch, mothers. Go home.' There are not enough of them. They go home. But by noon the whole of Wrayford has heard of it." {
    Assert mothersTurnedBack(wray). Increase temper(wray) by 1. Set walkDay(wray) to dayN(wray) + 1. }
  Rule mothers_walk_told when mothersWalk(wray) and inWrayford() and not spread(mothers_fact) says "In the morning Maudie Pardoe and Jennet Hobday walk down the Cartway together to the Bridge End, arm in arm, in black, and behind them comes Wrayford: Wain Row and Northgate, the yards, the Shambles, the fish-wives from the Wharf, Annis Pye with her fist shut, Win Fenner with four children, people from the Hill with their hats in their hands, so many that the Bridge End will not hold them and they stand back up the Cartway to the Cross. At the gate-ward's door Sergeant Gault looks at them for a long time. Then he takes his key off his belt and unlocks the door himself, and stands aside, and says to his riders, 'Let them be.' The toll-keeper's widow goes up first. When the three come down from the rail it is into the arms of the city, and they cross the bridge on carters' shoulders, and Amos Pinch, at the chain, lifts it without a word, and does not write anything down. Behind them, carried on a hurdle, comes Ned Hobday. Halfway over, by the chapel on the middle pier, somebody starts the carters' hymn, and then the whole bridge is singing it, badly, in the heat: carry me over, Wade, carry me over." { Assert spread(mothers_fact). }
  Entity mothers_fact: fact "The two mothers walked".
  Rule ned_buried when mothersWalked(wray) and buried(wat_dead) and not nedBuried(jennet) { Assert nedBuried(jennet). }
  Relation nedBuried(group).
  Rule ned_buried_lawful when buriedLawfully(wray) and not nedBuried(jennet) and corbinWillDig(wray) { Assert nedBuried(jennet). }
  Rule hulme_resigns when mothersWalked(wray) and buried(wat_dead) and not hulmeResigned(hulme) and hour(clock) >= 18 says "In the evening the reeve of Wrayford takes off his chain of office in the Guildhall before the Bench, and lays it on the long table, and goes home." { Assert hulmeResigned(hulme). }
  Relation hulmeResigned(group).
  Rule jennet_goes_home when mothersWalked(wray) and buried(wat_dead) and not at(jennet, hobday_room) { Assert at(jennet, hobday_room). }
}

data/adventures/wrayford/endings.kyr:
Module wrayford "The Third Night" {
  // ── Endings ───────────────────────────────────────────────────────────────────────────────────────────────────────
  // Reached at the captain's verdict on the fourth morning, by what the three days prepared. The first that holds is
  // the one told. None of them is a custom kept for ever after: each is the morning after, told plainly.
  Ending fire "The Fire" when verdictRebellion(wray) "The captain gives her verdict at nine in the Guildhall, and it takes one sentence. By noon the carters' row is burning, Wain Row and the yards behind it, and the captain's riders stand at the end of every lane to see that nobody puts it out. Ten men are hanged from the gatehouse rail beside the three, which is the lord's law for a rising, and the rail is not long enough, and they use the drawbridge chains, as her father did at the Michaelmas fair, and she watches it done from the same place at the Bridge End where she held his horses. In the evening the riders go home down the south road with the toll money and the lord's thanks, and Wrayford stands in its own smoke and does not speak to itself for a generation. The Company rebuilds its counting-house in stone.".
  Ending too_late "Too Late" when verdictGiven(wray) and tooLate(wray) "The captain hangs Maudie Pardoe from the gatehouse rail at nine in the morning, beside her husband, under the reeve's own decree, which is on the door in his son's best hand. Simon Hulme stands below with his hat in his hands and his knife still in his coat, where it was when he came down the Cartway a quarter of an hour behind her. He resigns that afternoon. In a week he is gone from Wrayford, nobody knows where. The three are taken down at noon and buried with her in Wade's Acre, four graves by the church door, and old Corbin digs them, and says nothing at all, and the reeve's house on the Hill stands empty, and nobody in the city will buy it.".
  Ending away "Away" when verdictGiven(wray) and maudieHanged(maudie) and not inWrayford() "You are not in Wrayford when it happens, and you hear it weeks later, in another country, from a drover in an inn, the way news of a place you have left always comes: badly told, by someone who does not know they are telling it to you. A carter's widow went up to the gatehouse in the night with her bread knife to cut her husband down, and the captain hanged her beside him in the morning, under the reeve's own decree. The drover shakes his head and says it was a hard thing, and drinks, and talks about the price of cattle.".
  Ending third_night "The Third Night" when verdictGiven(wray) and maudieHanged(maudie) "At nine in the morning Captain Sefton gives her verdict in the Guildhall: Wrayford is in order, its ringleaders on the rail, and one more, taken in the act against the lord's dead, under the reeve's decree. She hangs Maudie Pardoe from the gatehouse rail beside her husband before ten. The reeve watches from the Bridge End and does not look away, because he wrote it, or his son did. The captain takes the toll money and goes home down the south road, and at dusk on the fourth day the reeve has all four cut down and given to the Abbess, and Corbin digs, and Wrayford buries them by the church door; and every year after, on the third night, nobody in Northgate goes out of doors; and the eel-men on the night barges say that someone wades at Wade's Step, singing, with something heavy on her back.".
  Ending bargain "The Company's Bargain" when verdictGiven(wray) and kitSold(kit) "The captain takes Kit Pardoe south with her at noon, tied to a rider's saddle, for the lord's justice at Harbury, which is a rope. The Company, as it promised, asks the captain's mercy for the dead, justice having been done, and she grants it with a look at Alderman Gidley that he will not forget, and the three are buried that afternoon in Wade's Acre. Maudie Pardoe stands at the graveside and does not look at you once. You have forty crowns. The Company prints a ballad of the son who let his father die for him, at a penny, and it sells well.".
  Ending mothers "The Two Mothers" when verdictGiven(wray) and mothersWalked(wray) "When the captain comes up the south road at dusk on the third day there is nothing on the rail. There is a funeral: four new graves by the church door in Wade's Acre, the toll-keeper's boy among them, carried over the bridge on the city's shoulders, the way Wade carried the child, and the whole of Wrayford still standing about in the Liberty in its black, not going home. She looks at it a long time from her horse. In the morning she gives her verdict in one line: that the city is in order. She takes the toll money and goes home. The toll stands; the Company keeps its farm; Simon Hulme is not reeve any more. On Bridge Street, in the toll-keeper's house, Jennet Hobday has opened her shutters, and Maudie Pardoe comes on Sundays, with bread.".
  Ending charity "The Liberty's Charity" when verdictGiven(wray) and releasedBy(wray, by_charity) "The captain finds nothing on the rail but three cut ropes, and a letter from the Abbess claiming her dead, and the Bench's clause in Inchbold's copperplate, and the collector's ruling, and three new graves in Wade's Acre, dug square by old Corbin, who says it is the best work he has done in forty years. She reads the papers at supper with an expression nobody can read. In the morning she gives her verdict, that Wrayford is in order, and goes home with the toll money. The reeve keeps his office. The Company keeps its farm, and has its charity entered in its minutes, at the Liberty's charge. Everyone in Wrayford is a little ashamed, and the rail is empty, and on the whole it is a better morning than the city deserved.".
  Ending reeve "The Reeve's Release" when verdictGiven(wray) and reeveRelease(wray) "The captain hears at supper that the reeve of Wrayford cut the rebels down from the lord's rail with his own hands. In the morning she gives her verdict: that the city is in order, and its reeve is not. Simon Hulme hands her his chain of office on the Guildhall steps, and she takes it, not unkindly, and rides home with it and the toll money. He goes on living in the house on the Hill, and keeps a garden, and on the third night of every month walks down to the Bridge End and stands under the gatehouse for an hour, and nobody asks him why.".
  Ending earth "Earth on Him" when verdictGiven(wray) and buriedByNight(wray) "When the captain comes up the south road there is nothing on the rail but three cut ropes, and in Wade's Acre there are three graves nobody will admit to digging. The reeve has his answer for her, because he had to have one. She takes it, and the toll money, and gives her verdict that Wrayford is in order, and goes. They were carried over, the old way, in the dark, by someone's back. In Wain Row Maudie Pardoe bakes bread for three days and gives it all away. Nobody in the city ever says, out loud, who climbed the gatehouse in the small hours, and everybody knows.".
  Ending third_man "The Third Man" when verdictGiven(wray) and (buried(wat_dead) or buried(dunstan_dead) or buried(joss_dead)) and not buriedByNight(wray) and not buriedLawfully(wray) "When the captain comes up the south road there is nothing on the rail but three cut ropes, and in Wade's Acre there are new graves that nobody will admit to digging, and not enough of them. The one who could not be got over the water before the river rose was found by the reeve's men at first light, where he was left, and the captain has him put in the lord's lime at the crossroads on the south road, alone, which is the lord's law for a rebel's body. Then she gives her verdict that Wrayford is in order, and goes. Ever after, in the alehouses of Northgate, Wrayford argues about which of the three it was, and whether it matters; and it does.".
  Ending lime "The Lime" when verdictGiven(wray) and not buried(wat_dead) and not buried(dunstan_dead) and not buried(joss_dead) and not maudieHanged(maudie) "The captain gives her verdict that Wrayford is in order, and orders the ringleaders taken down and put in the lord's lime at the crossroads on the south road, which is the lord's law for rebels' bodies. It is done at noon. There is no grave, and nobody carried them over; the cart did, which is not the same. Maudie Pardoe stands in her doorway in Wain Row while the cart goes past to the south road with the three in it, and does not go in until it is out of sight, and does not speak to you, or to anyone, for a long time; and Corbin, at the Acre, picks up his spade and digs for Ned Hobday and for Gidley's aunt, very slowly, because there is no reason now not to.".

  // ── What became of them, told at the verdict ──────────────────────────────────────────────────────────────────────
  Rule fate_kit_hanged when verdictGiven(wray) and kitHanged(kit) and not kitSold(kit) and not spread(fate_kit) says "Kit Pardoe goes south with the captain, tied to a rider's saddle, for the lord's justice at Harbury. He looks back once, at the bridge." { Assert spread(fate_kit). }
  Entity fate_kit: fact "Kit's fate".
  Rule fate_maudie_fire when verdictGiven(wray) and verdictRebellion(wray) and maudieHanged(maudie) and not spread(fate_maudie) says "Maudie Pardoe is the first of the ten. She goes up the gate-ward's stair on her own feet, and does not look for anyone in the crowd." { Assert spread(fate_maudie). }
  Entity fate_maudie: fact "Maudie's fate".
  Rule fate_kit_free when verdictGiven(wray) and not kitTaken(kit) and not spread(fate_kit) and kitTrust(kit) >= 2 says "Kit Pardoe goes back to the yards, and to his father's place on the box, and the horse that went forward in the press, which he will not let anyone else drive." { Assert spread(fate_kit). }
  Rule fate_kit_cellar when verdictGiven(wray) and kitTaken(kit) and not kitHanged(kit) and not spread(fate_kit) says "The captain, having what she came for, has Kit Pardoe let out of the cellar with a cuff and a warning, and he walks home up the Cartway in the sun with his hands in his pockets." { Assert spread(fate_kit). Retract kitTaken(kit). Assert at(kit, carters_yards). }
  Rule fate_hal when verdictGiven(wray) and halTakesBlame(hal) and not spread(fate_hal) says "Hal Hulme comes out of the cellar when the captain has gone, and stands blinking in the Market, and his father is waiting for him at the Guildhall door, and they go home together up the Mercer Steps, very slowly, not talking." { Assert spread(fate_hal). }
  Entity fate_hal: fact "Hal's fate".
  Rule fate_hal_told_cut when verdictGiven(wray) and halToldFather(hal) and reeveRelease(wray) and not halTakesBlame(hal) and not spread(fate_hal) says "Hal Hulme, it is said, told his father what he did on the night of the rising, and his father sat with his head in his hands until dawn; and it was the next day that the reeve went down to the Bridge End with his knife." { Assert spread(fate_hal). }
  Rule fate_hal_told when verdictGiven(wray) and halToldFather(hal) and not reeveRelease(wray) and not halTakesBlame(hal) and not spread(fate_hal) says "Hal Hulme, it is said, told his father what he did on the night of the rising, before supper, and his father sat with his head in his hands until dawn, and in the morning went to his court as usual." { Assert spread(fate_hal). }
  Rule fate_corbin when verdictGiven(wray) and reconciled(wray) and not spread(fate_corbin) says "At the end of the week the banns are read at Saint Wade's for Corbin, sexton, of this parish, and Dorcas Mudd, ferry-woman, of the city, and the whole Liberty laughs, and so does the whole Wharf, and neither of them minds at all." { Assert spread(fate_corbin). }
  Entity fate_corbin: fact "Corbin and Dorcas".
  Rule fate_annis when verdictGiven(wray) and annisRing(annis) and not spread(fate_annis) says "Annis Pye wears Joss Wilder's ring on a string round her neck, and does not set up her pitch at the Bridge End again, but on the Wharf, where nobody ever hanged anybody." { Assert spread(fate_annis). }
  Entity fate_annis: fact "Annis".
  Rule fate_robin when verdictGiven(wray) and (robinHome(robin) or robinStays(robin)) and buried(wat_dead) and not spread(fate_robin) says "At the burying, somebody's boy beat a drum, slow, a bear-ward's drum with a bear painted on it: Robin Tull, who had nobody to bury, and came anyway." { Assert spread(fate_robin). }
  Entity fate_robin: fact "Robin".
  Rule fate_win when verdictGiven(wray) and winHelped(party) and buried(dunstan_dead) and not spread(fate_win) says "Win Fenner stood at Dunstan's grave with her four children in a row by height, and the chisels in the eldest's hands." { Assert spread(fate_win). }
  Entity fate_win: fact "Win".
  Rule fate_pinch when verdictGiven(wray) and (captainPinch(party) or pinchExposed(wray)) and not pinchGone(pinch) and not spread(fate_pinch) says "Amos Pinch goes south with the captain's baggage, for the lord's court at Harbury, on foot behind the led horse, with the day-book under his arm. He asked to carry it himself." { Assert spread(fate_pinch). Assert pinchGone(pinch). Assert at(pinch, limbo). }
  Entity fate_pinch: fact "Pinch".
}

data/adventures/wrayford/fire.kyr:
Module wrayford "The Third Night" {
  // ── Kit's night ───────────────────────────────────────────────────────────────────────────────────────────────────
  // At midnight on the second night Kit and the young carters go for the Company's counting-house with lamp-oil.
  // The Company's clerk hears everything at the Nine Wheels: Gault and two riders are waiting in the dark of the
  // arcade. Unless Kit has been talked down, or turned to sinking the board, or is held, or is walking with you.
  Query kitMeansFire() means not kitStoodDown(kit) and not kitTurned(kit) and not kitTaken(kit) and not travelsWith(kit, party).
  Query fireHour() means secondDay() and hour(clock) < 2.
  Person ambush "two of the lord's riders" at limbo {
    Role "two of Gault's riders, waiting in the dark of the arcade". Ancestry human. Calling warrior. Level 2. Numbers 2. Peaceable. Pronouns they.
  }
  Initially Assert takesPrisoners(ambush). Initially Assert serves(ambush, gault).
  Relation ambushLaid(place). Relation fireTried(place). Relation boardSunk(place). Relation fireFought(place).
  Rule ambush_laid when secondDay() and hour(clock) >= 23 and not ambushLaid(wray) and (kitMeansFire() or kitJoined(kit)) and not kitTurned(kit) and not kitStoodDown(kit) {
    Assert ambushLaid(wray). Assert gaultAway(gault). Assert at(gault, counting_room). Assert at(ambush, counting_room). }
  Observe ambush_seen at counting_room when ambushLaid(wray) and not fireTried(wray) and not fireFought(wray) "In the dark of the counting-house, behind the counter, something shifts: a buff coat, the gleam of a drawn blade. Sergeant Gault and two of his riders are waiting here in the dark.".
  // They come at midnight.
  Rule carters_go when fireHour() and (kitMeansFire() or kitJoined(kit)) and not kitTurned(kit) and not kitStoodDown(kit) and not cartersOut(carters) and not fireTried(wray) {
    Assert cartersOut(carters). Assert kitOut(kit). Assert at(carters, counting_room). Assert at(kit, counting_room). }
  // With the company there beside them: Gault comes out of the dark at them.
  Rule ambush_springs when cartersOut(carters) and at(party, counting_room) and ambushLaid(wray) and not fireFought(wray) says "The young carters come into the counting-house with the oil, and Kit with a lantern, and Sergeant Gault stands up from behind the counter. 'Evening,' he says, and two of the lord's riders step out of the dark either side of the door." {
    Assert fireFought(wray). Retract peaceable(gault). Retract peaceable(ambush). Assert assails(gault, party). Assert assails(ambush, party). }
  // Without the company: Gault takes them in the act.
  Rule ambush_takes when cartersOut(carters) and not at(party, counting_room) and ambushLaid(wray) and not fireTried(wray) and not fireFought(wray) says "Word comes before dawn, the way it comes in a city, from nowhere: the young carters went for the Company's counting-house at midnight with lamp-oil, and Sergeant Gault was waiting in the dark for them, and the fire was out before it was lit, and Kit Pardoe and two others are in the Guildhall cellar." {
    Assert fireTried(wray). Assert kitTaken(kit). Assert cartersTaken(carters). Assert at(kit, guild_cellar). Assert at(carters, guild_cellar).
    Retract cartersOut(carters). Retract kitOut(kit). Retract gaultAway(gault). Assert at(ambush, limbo). }
  // Won: the counting-house burns.
  Rule counting_burns when fireFought(wray) and (not able(gault) or routed(gault)) and (not able(ambush) or routed(ambush)) and not countingBurned(wray) says "The oil goes on the ledgers and the lantern after it, and the counting-house of the Worshipful Company of the Bridge goes up with a sound like a great breath. The gold bridge over the door melts and runs. By the time the Market is awake the whole of it is burning, and the bells are ringing, and nobody in Wrayford will ever again be able to say there was no rising." {
    Assert countingBurned(wray). Assert fireTried(wray). Retract cartersOut(carters). Retract kitOut(kit). Retract gaultAway(gault). }
  Rule fire_lost when fireFought(wray) and at(party, counting_room) and (captured(gault, party) or captured(ambush, party)) says "You come round in the Guildhall cellar on the straw, with Kit beside you with his face cut, and the young carters, and the smell of lamp-oil on your hands." {
    Retract captured(gault, party). Retract captured(ambush, party). Assert at(party, guild_cellar). Assert heldInCellar(party). Assert kitTaken(kit). Assert at(kit, guild_cellar).
    Assert cartersTaken(carters). Assert at(carters, guild_cellar). Assert fireTried(wray). Retract cartersOut(carters). Retract kitOut(kit). Retract gaultAway(gault).
    Assert peaceable(gault). Assert peaceable(ambush). Assert at(ambush, limbo). }
  // And the proof of the first fire goes in the second: Pinch's day-book, under his mattress behind the counter.
  Rule daybook_burns when countingBurned(wray) and at(daybook, pinch_room) { Retract at(daybook, pinch_room). }
  Observe counting_burned at counting_room when countingBurned(wray) "The counting-house is a shell: black walls, the counter charcoal, a smell that will be in the Market for a year. Over the doorway a lump of gold metal hangs where the bridge was.".
  // Turned: the new toll-board goes into the river instead, and nobody hangs for a board.
  Rule board_sinks when fireHour() and kitTurned(kit) and not boardSunk(wray) and not kitTaken(kit) {
    Assert boardSunk(wray). Increase temper(wray) by 2. }
  Rule board_told when boardSunk(wray) and inWrayford() and hour(clock) >= 6 and not spread(board_fact) says "All Wrayford is laughing by breakfast. In the night somebody unbolted the Company's new toll-board from beside the booth, all eight feet of it, freshly painted, and carried it down Bridge End and threw it in the Wray, for the second time in a week, and the sergeant and two riders sat in the dark of the counting-house all night waiting for a fire that never came. Amos Pinch stood at the booth this morning and ruled from memory, and got the price of a beast wrong, and the drovers cheered him." { Assert spread(board_fact). }
  Entity board_fact: fact "The board in the river".
  Rule ambush_stands_down when dayN(wray) >= 3 and ambushLaid(wray) and not fireTried(wray) and not fireFought(wray) { Retract gaultAway(gault). Assert at(ambush, limbo). Assert fireTried(wray). }
  Rule fire_carters_home when (fireTried(wray) or boardSunk(wray)) and cartersOut(carters) and not cartersTaken(carters) { Retract cartersOut(carters). Retract kitOut(kit). }
  // Standing in the door at the last moment, with a brother who trusts you.
  Action stand_in_door(actor: group, site: place) "Stand in the counting-house door, and tell Kit no" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, counting_room) and at(kit, counting_room) and cartersOut(carters)
      and kitTrusts(actor) and not fireFought(wray) and not kitStoodDown(kit).
    Time 1 minute.
    On success { Assert kitStoodDown(kit). Retract cartersOut(carters). Retract kitOut(kit). Assert at(kit, wheels_taproom). Assert at(carters, wheels_taproom). }
    Result "You stand in the door with your back to Gault's dark and say no, and Kit looks at you over the lantern, and at the oil in the others' hands, and something goes out of his face. 'Home,' he says to them. 'Home.' They go, and behind you in the dark of the counting-house someone lets out a long breath, and a blade goes back into its scabbard.".
  }
}

data/adventures/wrayford/hill.kyr:
Module wrayford "The Third Night" {
  // ── Mercer Hill ───────────────────────────────────────────────────────────────────────────────────────────────────
  Observe hill_scene at mercer_hill when not dark() and not visitedBefore(mercer_hill) "Mercer Hill: the houses of people who no longer have to live near what they sell. Gardens with walls, a view down over the roofs to the river and the bridge, a row of young limes. From up here you can see the gatehouse square and small at the end of the bridge, and what hangs from it, and somebody on this hill has planted the limes so that one day, when they are grown, nobody will have to.".
  Observe hill_again at mercer_hill when not dark() and visitedBefore(mercer_hill) "Mercer Hill: walled gardens, the young limes, the view of the bridge.".
  Observe hill_night at mercer_hill when dark() "Mercer Hill at night: lit windows behind garden walls, and the river below, and the brazier on the gatehouse leads, very small.".

  // ── The reeve ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe study_scene at hulme_study when true "The reeve's study: books of the city's statutes, a map of the bridge with every arch numbered, a fire, two chairs, and a desk with the reeve's seal on it in a dish, and a stack of papers in a round careful clerk's hand.".
  Person hulme "Simon Hulme" at guild_hall {
    Role "the Reeve of Wrayford, grey and careful". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "Simon Hulme looks up, and you watch him decide, in the space of a breath, to be the reeve and not anything else.".
  }
  Rule hulme_court when hour(clock) >= 9 and hour(clock) < 17 and not at(hulme, guild_hall) and not hulmeAway(hulme) { Assert at(hulme, guild_hall). }
  Rule hulme_home when (hour(clock) >= 17 or hour(clock) < 9) and not at(hulme, hulme_study) and not hulmeAway(hulme) { Assert at(hulme, hulme_study). }
  Relation hulmeAway(group).
  Measure hulmeMoved(group). Initially Set hulmeMoved(hulme) to 0.
  Relation hulmeAsked(group). Relation hulmeAnswered(group).
  Discovery hulme_reasons "The reeve keeps the dead on the rail because the captain comes at dusk on the third day to see whether Wrayford is in rebellion. If she finds the city in order, she takes the toll money and goes. If she finds it in rebellion, the lord's law is ten hangings and the carters' row burned.".
  Discovery charity_path "The reeve would release the dead before the captain comes, if he were given cover: the Bench's leave, which the Company will not give for nothing, and someone to take them who is beyond the reeve's writ, such as the Abbess of Overbridge, if she claimed them, and their crossing ruled lawful at the bridge.".
  Topic hulme_why with hulme "Ask the reeve why the dead must stay on the rail" when true once {
    Says "'Because the captain comes at dusk on the third day,' says Simon Hulme, 'and asks one question: is Wrayford in rebellion. If she finds the city quiet and its ringleaders on the rail, she takes the toll money and goes home. If she finds it in rebellion, the lord's law is ten hanged for every rider hurt and the carters' row burned to the stones.' He says it as if he had said it many times, to himself. 'Three men on a rail, or thirty. I have kept this city twenty years.' His hand is flat on the desk. 'I did not hang them. I would have brought them to the lord's court. The riders carried a warrant I was not shown.'".
    On discuss { Assert knows(actor, hulme_reasons). }
  }
  // Kin: he stood godfather to Kit. He asks his question once.
  Event hulme_question near hulme when homecomer(party) and knows(party, hulme_reasons) and addressed(hulme, party) and not hulmeAsked(party) "He looks at you for a long time. 'You were in my house every day of your childhood,' he says. 'You and Hal. Tell me, then. You've come home and found your father on the rail, and you're the only one in this city who can say anything to me I'd listen to.' His voice does not rise. 'What would you have me do?'" then { Assert hulmeAsked(party). }
  Topic answer_cut with hulme "Tell him: cut them down, and let the captain find a city that buries its dead" when hulmeAsked(actor) and not hulmeAnswered(actor) once {
    Says "He shuts his eyes. 'A city that buries its dead,' he says. 'That's a thing to say. That's a fine thing.' He opens them. 'And when she asks who cut them down against the lord's warrant?' He waits. You do not have an answer, and he sees it. 'No,' he says, gently. 'Neither have I.' But he does not look away from you.".
    On discuss { Assert hulmeAnswered(actor). Increase hulmeMoved(hulme) by 1. }
  }
  Topic answer_liberty with hulme "Tell him: give them to the Liberty, and let the Abbess's charity be the city's cover" when hulmeAsked(actor) and not hulmeAnswered(actor) once {
    Says "That makes him look up properly. 'The Liberty,' he says slowly. 'If the Abbess claimed them. If the Bench gave me leave, which they won't, for nothing. If the crossing were ruled lawful at the chain, so it's not a felon's goods going over the bridge.' He is counting on his fingers like a clerk. 'Then it's not the city releasing rebels. It's the Liberty taking up its dead, as it has the right, and the city standing aside, as it must.' He looks at you. 'Get me those three things, and I'll give them up before the captain's in sight.'".
    On discuss { Assert hulmeAnswered(actor). Assert knows(actor, charity_path). }
  }
  Topic answer_hang with hulme "Tell him: then hang me beside him" when hulmeAsked(actor) and not hulmeAnswered(actor) once {
    Says "He flinches. It is the first thing that has touched him, and he cannot hide it. 'Don't,' he says. 'Don't say that to me.' He gets up and goes to the window and stands with his back to you for a long time. 'Get out,' he says at last, quite gently. 'Go home to your mother.'".
    On discuss { Assert hulmeAnswered(actor). Increase hulmeMoved(hulme) by 1. }
  }
  // After the Bench's clause: its dead are now the Company's surety, and the reeve its bailiff. Anyone may say so.
  Topic hulme_clause with hulme "Put it to the reeve that the Bench has made his dead the Company's surety, and him its bailiff" when clauseWorse(wray) and stillHanging() once {
    Says "He has the Remonstrance on his desk; he has read it more than once. 'Its surety,' he says. 'Yes.' He turns it face down. 'I kept them on the rail for the city. Three men, so that it should not be thirty. And the Company has written under my seal that they stay there till its riot-money is counted.' He looks at the decree on the wall, in his son's hand. 'I did not hang men to be a debt-collector's pledge.' He does not say anything else, but he has not turned the paper back over.".
    On discuss { Increase hulmeMoved(hulme) by 1. }
  }
  Topic hulme_release with hulme "Ask the reeve what would let him release the dead" when stranger(actor) and knows(actor, hulme_reasons) once {
    Says "He considers you: a stranger, who has no stake, and is asking anyway. 'Cover,' he says. 'If the Abbess of Overbridge claimed them, they'd be the Liberty's, not the city's rebels. If the Bench gave me leave. If the crossing at the chain were ruled lawful, so it's not a felon's goods going over the bridge. Three things.' He shakes his head. 'The Bench will give nothing for nothing, and the Abbess gives nothing at all.'".
    On discuss { Assert knows(actor, charity_path). }
  }
  Topic hulme_kit with hulme "Tell the reeve what Kit Pardoe means to do tomorrow night" when knows(actor, kit_plan) and not kitStoodDown(kit) and not kitTurned(kit) and not kitTaken(kit) and not kitBetrayed(kit) once {
    Says "The reeve listens with his hand over his eyes. 'The counting-house,' he says. 'He'd hang. They'd hang him with his father.' He takes his hand away. 'I'll have him taken up tonight, before. The cellar's dry. It's better than the rope.' He looks at you. 'He'll not forgive you.'".
    On discuss { Assert kitBetrayed(kit). Assert kitTaken(kit). Set kitTrust(kit) to 0. }
  }
  Rule kit_taken_up when kitBetrayed(kit) and not at(kit, guild_cellar) and not travelsWith(kit, party) { Assert at(kit, guild_cellar). Assert kitTaken(kit). }

  // ── Hal ───────────────────────────────────────────────────────────────────────────────────────────────────────────
  Person hal "Hal Hulme" at guild_hall {
    Role "the reeve's son, who writes his father's papers". Ancestry human. Peaceable. Pronouns he. Manner compassionate.
    Greets "Hal Hulme looks up, and for a moment he is twelve years old, and then he is not.".
  }
  // His father's clerk by day; at dusk he goes down to the starling under the middle arch, where he always went; home.
  Relation halAway(group).
  Rule hal_clerk when hour(clock) >= 9 and hour(clock) < 18 and not at(hal, guild_hall) and not halAway(hal) { Assert at(hal, guild_hall). }
  Rule hal_starling when hour(clock) >= 18 and hour(clock) < 21 and not at(hal, starling) and not halAway(hal) { Assert at(hal, starling). }
  Rule hal_home when (hour(clock) >= 21 or hour(clock) < 9) and not at(hal, hulme_study) and not halAway(hal) { Assert at(hal, hulme_study). }
  Relation halSat(group). Relation halConfessed(group). Relation halKept(group). Relation halToldFather(group). Relation halTold(group).
  Topic hal_hello with hal "Ask Hal how he has been" when homecomer(actor) once {
    Says "'How I've been.' He looks at you as if you were a word he had been trying to remember for three years. 'I've been writing my father's letters,' he says. 'I've been writing his decrees.' He looks down at the paper under his hand. 'I wrote that one. On the gatehouse door. In my best hand.' His face does something, and stops. 'I'm glad you've come. I'm sorry it's now.'".
  }
  Observe starling_hal at starling when at(hal, starling) "Hal Hulme is sitting on the starling with his legs over the water and his back to the pier, where the two sets of initials are cut, as if he had been there every evening for three years.".
  Action sit_hal(actor: group, site: place) "Sit down by Hal on the starling, the way you used to" {
    Description "Half an hour, with the river under your feet.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, starling) and at(hal, starling) and homecomer(actor) and not halSat(actor).
    Time 3.
    On success { Assert halSat(actor). }
    Result "You sit. He moves over without looking, the way he always did, to give you the dry bit. After a while his shoulder is against yours, and neither of you moves it. 'You went away,' he says to the river. 'I know why. I'd have gone with you if I'd had any sense.' The river goes under you, brown and fast and loud. 'I haven't any sense,' he says. 'I've done something.' And then he does not say what.".
  }
  Discovery hand_match "The letter that sent the riders to the fell road is in the same round careful hand as the reeve's decree on the gatehouse door: Hal Hulme's, who writes his father's papers.".
  Rule hand_known when knows(party, letter_read) and knows(party, decree_known) and homecomer(party) and not knows(party, hand_match) says "You knew the hand the moment you saw it. You learned your letters beside it at the same bench. Hal's." teaches hand_match { }
  Action compare_hands(actor: group, site: place) "Hold the riders' letter in your mind against the decree on the gatehouse door" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gate_road) and knows(actor, letter_read) and stillHanging()
      and not knows(actor, hand_match) and not benighted(actor).
    Time 2 minutes.
    On success { Assert knows(actor, hand_match). }
    Result "You read the decree again, slowly, the shapes of the letters and not the words: the round careful clerk's hand, the long tail on the y, the way the d leans back. It is the same hand. The reeve's papers are written by his son.".
  }
  Topic hal_confess with hal "Tell Hal you have read his letter in Gault's coat" when knows(actor, hand_match) and not halConfessed(actor) once {
    Says "He goes white, and then he goes very still, the way his father does. 'Yes,' he says. 'I wrote it.' He does not look away. 'My father said the riders would take them for the lord's court. That's what he believed; he hadn't seen the warrant. The young ones were going to burn the counting-house, and the chain was already gone, and I thought: if the old ones are taken quietly on the road there'll be no more fire, and they'll be fined at the court, and that will be all.' His hands are shaking and he puts them flat on his knees. 'They hanged them on the road at sunrise. I have not slept. I have written the decree that keeps them there, in my best hand, because my father told me to and I had already done the other thing.' He looks at you. 'Do what you like with it. I'd tell Kit myself if I thought he'd let me finish.'".
    On discuss { Assert halConfessed(actor). Assert knows(actor, hal_wrote). }
  }
  Discovery hal_wrote "Hal Hulme, the reeve's son, wrote to the riders at midnight on the night of the rising, believing they would only take the old carters for the lord's court and spare the city another night of fire. They hanged them on the road. He has told no one.".
  Topic hal_tell_father with hal "Tell Hal he must tell his father" when halConfessed(actor) and not halToldFather(hal) and not halKept(hal) once {
    Says "He nods, slowly, as if you had told him the time. 'Yes.' He gets up. 'Tonight. When he comes in.' At the door he stops. 'He'll resign,' he says. 'Or he won't, and that'll be worse.'".
    On discuss { Assert halToldFather(hal). Increase hulmeMoved(hulme) by 2. }
  }
  Topic hal_keep with hal "Tell Hal you'll keep it between the two of you" when halConfessed(actor) and not halToldFather(hal) and not halKept(hal) once {
    Says "He looks at you for a long time. 'That's worse,' he says. 'You know that. That's worse than telling.' But he takes your hand, on the stone between you, where the initials are, and holds on to it as if the river might take one of you.".
    On discuss { Assert halKept(hal). }
  }
  Topic kit_told_hal with kit "Tell Kit who sent the riders to the fell road" when knows(actor, hal_wrote) and not halTold(kit) and not kitTaken(kit) once {
    Says "Kit hears you out without a sound. Then he stands up. 'Hal,' he says. 'Hal Hulme.' He looks at his hands as if they were somebody else's. 'He used to fish with us. Off the starling.' He goes, without another word, toward the bridge.".
    On discuss { Assert halTold(kit). Assert kitHunting(kit). }
  }
  Relation kitHunting(group). Relation halHurt(group).
  // Kit goes for Hal at the starling at dusk, unless someone is there to stop it.
  Rule kit_finds_hal when kitHunting(kit) and at(hal, starling) and not kitTaken(kit) and not halHurt(hal) and not at(party, starling) says "Word comes along Bridge Street at dusk: Kit Pardoe went down through the bridge chapel to the starling where Hal Hulme sits of an evening, and there was shouting under the arch, and Hal Hulme was pulled out of the river below the bridge by the fish-wives with his head cut open, alive, and Kit is in the Guildhall cellar." {
    Assert halHurt(hal). Assert kitTaken(kit). Retract kitHunting(kit). Assert at(kit, guild_cellar). Assert halAway(hal). Assert at(hal, hulme_study). }
  Action stop_kit_hal(actor: group, site: place) "Put yourself between Kit and Hal" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, starling) and kitHunting(kit) and at(hal, starling).
    Time 1 minute.
    On success { Retract kitHunting(kit). }
    Result "Kit comes down the ladder fast and stops on the last rung when he sees you between them. For a moment nobody moves. Then Hal says, 'Let him,' and Kit says, 'Get out of the way,' and you do not, and after a long time Kit sits down on the wet stone where he is and puts his head in his hands and Hal, very slowly, sits down too.".
  }
  Rule kit_finds_hal_watched at starling when kitHunting(kit) and at(hal, starling) and at(kit, starling) and at(party, starling) and not halHurt(hal) says "Kit comes down the ladder from the chapel with his face white and his fists shut." { }
  Rule kit_comes_down when kitHunting(kit) and at(hal, starling) and at(party, starling) and not at(kit, starling) and not kitTaken(kit) { Assert at(kit, starling). }

  // ── Alderman Gidley ───────────────────────────────────────────────────────────────────────────────────────────────
  Observe parlour_scene at gidley_parlour when true "A parlour of the best kind: a Turkey carpet, a harpsichord nobody plays, a view of the river through good glass, and over the fire a sampler: WE BEAR THE CROSSING. The blinds of the room above are drawn, for the aunt.".
  Person gidley "Alderman Prosper Gidley" at gidley_parlour {
    Role "the Master of the Worshipful Company of the Bridge, in a blue gown". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "Alderman Gidley takes your hand in both of his, which are warm and soft, and holds it. 'Terrible days,' he says. 'Terrible. Sit down.'".
  }
  // Breakfast at home; at nine to the gatehouse, where he weeps; the Guildhall; home to dine.
  Rule gidley_weeps when hour(clock) >= 9 and hour(clock) < 10 and stillHanging() and not at(gidley, gate_road) { Assert at(gidley, gate_road). }
  Rule gidley_hall when hour(clock) >= 10 and hour(clock) < 17 and not at(gidley, guild_hall) { Assert at(gidley, guild_hall). }
  Rule gidley_dines when (hour(clock) >= 17 or hour(clock) < 9) and not at(gidley, gidley_parlour) { Assert at(gidley, gidley_parlour). }
  Rule gidley_weeping at gate_road when hour(clock) == 9 and stillHanging() and at(gidley, gate_road) and not weptToday(gidley) says "Alderman Gidley arrives at the Bridge End in his blue gown, as he has every morning, and stands below the rail with his hat in his hand and weeps, beautifully, for some minutes, while the crowd watches. Then he wipes his eyes, and asks Pinch for the morning's takings, and goes up the Cartway to the Guildhall." { Assert weptToday(gidley). }
  Relation weptToday(group).
  Rule weeping_ends when hour(clock) == 10 and weptToday(gidley) { Retract weptToday(gidley). }
  Topic gidley_toll with gidley "Ask Alderman Gidley about the toll" when true once {
    Says "'A scandal.' He sits back. 'An imposition. The lord has no more right to tax that bridge than to tax the river.' He shakes his head. 'The Company opposed it with every fibre. And when it came, we took the farm of it ourselves, at great expense, so that it should at least be collected by Wrayford men, with Wrayford hearts, and not by some stranger.' He pats your hand. 'We are drawing up a Remonstrance. Tomorrow, at noon. You must come and speak, if you like. All are welcome. It costs nothing.'".
    On discuss { Assert knows(actor, remonstrance_called). }
  }
  Topic gidley_aunt with gidley "Ask the Alderman about his aunt" when knows(actor, corbin_strike) once {
    Says "Gidley's face falls into its folds. 'Aunt Letitia. Since Tuesday. In the blue room, with the blinds drawn and Mistress Gidley not able to go up.' He takes out his handkerchief. 'That old man at the Acre will not dig, because of the carters. The Company has offered him double fees. Treble.' He blows his nose. 'He laughed at the Company's clerk. Laughed.'".
  }
  // The bargain: forty crowns for the boy who drove.
  Relation bargainMade(group). Relation purseTaken(group).
  Topic gidley_bargain with gidley "Tell Alderman Gidley who was really driving Wat Pardoe's cart" when knows(actor, kit_driving) and not bargainMade(actor) once {
    Says "Gidley listens with his mouth a little open. Then he seizes your hand in both of his. 'The son,' he says. 'And the father died for him. Oh, that is beautiful. That is a ballad.' His eyes are wet. Then they are not. 'The captain will want a ringleader alive to take back to the lord. A live one is worth three on a rail. Give us the boy, and the Company will ask the captain to let the dead be buried, as a mercy, justice having been done.' He takes a purse from his desk and puts it on the table between you. 'Forty crowns, for your trouble. For the city's sake.'".
    On discuss { Assert bargainMade(actor). }
  }
  Action take_purse(actor: group, site: place) "Take the Company's forty crowns, and give them Kit" {
    Grave "Kit will be taken to the captain, alive, for the lord's justice.".
    Requires able(actor) and company(actor) and at(actor, site) and at(gidley, site) and bargainMade(actor) and not purseTaken(actor)
      and not kitTaken(kit).
    Time 2 minutes.
    On success { Increase quantity(actor, gold) by 40. Assert purseTaken(actor). Assert kitTaken(kit). Assert kitSold(kit). Set kitTrust(kit) to 0. }
    Result "The purse is heavy. Gidley sends a boy running for the reeve's men, and pours you a glass of something, and toasts the city. You do not drink it.".
  }
  Relation kitSold(group).
  Rule kit_sold_taken when kitSold(kit) and not at(kit, guild_cellar) { Assert at(kit, guild_cellar). Retract travelsWith(kit, party). }
  // The flask shown to the Alderman: the Company has been robbed, by its own collector.
  Relation audited(group).
  Topic gidley_flask with gidley "Show Alderman Gidley the Company's oil flask from the ash of the toll-house" when carries(actor, company_flask) and not audited(gidley) once {
    Says "Gidley turns the flask over in his soft hands and sees the gold bridge stamped on it, and goes slowly purple. 'Ours,' he says. 'Our oil. In the toll-house.' He stands up. 'Pinch.' He rings a bell. 'If that man has been at the Company's takings,' and his voice shakes with a grief more real than any you have heard from him, 'then the Company has been robbed. Robbed! By its own servant!' He sends for Pinch's room to be opened. When the clerk comes back he is carrying the toll day-book, and Gidley reads three pages and closes it and puts it on the fire, and watches it burn, and turns to you with tears in his eyes. 'For the Company's good name,' he says. 'Pinch leaves Wrayford at dawn. Not a word of this, I beg of you.'".
    On discuss { Assert audited(gidley). Assert pinchDismissed(pinch). Assert knows(actor, gidley_burned_book). }
  }
  Relation pinchDismissed(group).
  Discovery gidley_burned_book "Shown the Company's oil flask, Alderman Gidley had Pinch's room opened, read three pages of the toll day-book, burned it, and dismissed Pinch from the Company's service for robbing the Company; and begged that nothing be said, for the Company's good name.".
  Rule daybook_burned when audited(gidley) and not carries(party, daybook) { Retract at(daybook, pinch_room). }
  Rule pinch_leaves when pinchDismissed(pinch) and hour(clock) == 6 and not pinchGone(pinch) { Assert pinchGone(pinch). Assert at(pinch, limbo). }

  // Mistress Gidley, and the ice.
  Person honoria "Honoria Gidley" at gidley_parlour {
    Role "the Alderman's wife, in black for the aunt". Ancestry human. Peaceable. Pronouns she. Manner compassionate.
    Greets "Mistress Gidley looks up from a sampler with a needle in her mouth, takes it out, and says, 'Oh. Visitors.'".
  }
  Relation honoriaLobbies(group). Relation iceGiven(group).
  Topic honoria_aunt with honoria "Ask Mistress Gidley about her aunt" when true once {
    Says "'Aunt Letitia.' She puts the sampler down. 'Ninety-one. Upstairs, in the blue room, since Tuesday, with the ice-man going up and down the back stairs four times a day with blocks, and the whole house smelling of lilies, and I cannot go up.' She looks at the window, where the river is. 'Because an old man at the Acre will not dig while those poor men are on the bridge. And Prosper says the bridge is the lord's business and the Company cannot interfere.' She pricks herself, and does not notice. 'I do think a Company that can farm a toll could manage a funeral.'".
    On discuss { Assert knows(actor, corbin_strike). }
  }
  Topic honoria_ice with honoria "Ask Mistress Gidley for a block of ice for the toll-keeper's boy" when knows(actor, corbin_strike) and not iceGiven(actor) once {
    Says "'The Hobday boy.' Her hand goes to her mouth. 'In this heat. Oh, that poor woman.' She is already on her feet. 'Tobias! Tobias, a block for the toll-keeper's house, the biggest, and don't tell the Alderman.' To you, low: 'He'll say it's the Company's ice. It's my ice. I married it.'".
    On discuss { Assert iceGiven(actor). Assert at(ice_gift, ice_house). Assert knows(actor, ice_waiting). }
  }
  Discovery ice_waiting "Mistress Gidley has had a block of ice set out for you in the ice-house on the Hill, for the toll-keeper's boy.".
  Item ice_gift "a block of ice" is ice_kind at limbo.
  Topic honoria_lobby with honoria "Tell Mistress Gidley that if the carters come down, Corbin will dig for her aunt" when knows(actor, corbin_strike) and knows(actor, remonstrance_called) and not honoriaLobbies(honoria) once {
    Says "She sits very still. 'If the carters come down.' She looks at the ceiling, through which is the blue room. 'The Remonstrance is tomorrow at noon.' Her mouth goes thin. 'Prosper will do as I tell him, for once. He'll speak for whatever lets that old man dig. You tell me what to make him say, and he'll say it.'".
    On discuss { Assert honoriaLobbies(honoria). }
  }
  // The ice-house: Tobias Wren by day, who sells to the Hill and to nobody else; locked at night.
  Observe icehouse_scene at ice_house when true "Down a stair into the hill: a brick dome, cold enough to make your breath smoke, and straw, and under the straw, blocks of last winter's river, grey and sweating.".
  Person tobias "Tobias Wren" at ice_house {
    Role "the Alderman's ice-man, in a sacking cape". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "Tobias Wren straightens up from the straw with a pair of tongs. 'Hill houses only,' he says. 'Alderman's orders.'".
  }
  Rule tobias_day when hour(clock) >= 8 and hour(clock) < 18 and not at(tobias, ice_house) { Assert at(tobias, ice_house). }
  Rule tobias_night when (hour(clock) >= 18 or hour(clock) < 8) and at(tobias, ice_house) { Retract at(tobias, ice_house). Assert at(tobias, limbo). }
  Thing ice_lock "the ice-house door" on ice_door {
    State locked blocking "The ice-house door is padlocked for the night.".
    State open "The ice-house door is unlocked.".
    Change pick "Pick the padlock on the ice-house door" from locked to open needing lockwork.
    Change wrench "Wrench the padlock's hasp off the ice-house door" from locked to open needing brawn.
  }
  Initially Assert state(ice_lock, open).
  Rule ice_locked when (hour(clock) >= 18 or hour(clock) < 8) and state(ice_lock, open) and not iceForced(wray) { Assert state(ice_lock, locked). }
  Rule ice_unlocked when hour(clock) >= 8 and hour(clock) < 18 and state(ice_lock, locked) { Assert state(ice_lock, open). Retract iceForced(wray). }
  Relation iceForced(place).
  Rule ice_forced when state(ice_lock, open) and (hour(clock) >= 18 or hour(clock) < 8) and not iceForced(wray) { Assert iceForced(wray). }
  // Taken at night, unseen: anyone can lift a block, once in.
  Item ice_night "a block of ice" is ice_kind at ice_house hidden until ice_seen.
  Discovery ice_seen "In the straw of the ice-house lie blocks of grey river ice, and nobody watches them at night." { Found by searching ice_house. }
  Topic tobias_sell with tobias "Ask Tobias Wren to sell you a block of ice" when not iceGiven(actor) once {
    Says "'Hill houses only.' He looks at you. 'What for?' You tell him. He goes on looking. Then he takes a block out of the straw with his tongs and wraps it in sacking and puts it in your arms, and holds out his hand. 'Two coin,' he says. 'For the Hobday lad. And it fell off the cart.'".
    On discuss { Assert iceGiven(actor). Assert at(ice_gift, ice_house). Assert knows(actor, ice_waiting). Decrease quantity(actor, gold) by 2. }
  }
}

data/adventures/wrayford/liberty.kyr:
Module wrayford "The Third Night" {
  // ── Overbridge ────────────────────────────────────────────────────────────────────────────────────────────────────
  // The Liberty of Saint Wade's: the reeve's writ ends at the foot of the drawbridge.
  Observe over_scene at overbridge_street when not dark() and not visitedBefore(overbridge_street) "Overbridge Street comes off the drawbridge into another town: older, lower, poorer and louder, timber houses with their upper floors leaning on their neighbours, the tan-yards stinking at one end and the bear-garden roaring at the other, and in the middle Saint Wade's, a squat old church with a tower, and the Abbess's lodging behind a wall. A painted post at the bridge foot says THE LIBERTY OF SAINT WADE. The reeve's writ ends here, and everybody walks a little differently.".
  Observe over_again at overbridge_street when not dark() and visitedBefore(overbridge_street) "Overbridge Street: leaning houses, the church, the post that says THE LIBERTY OF SAINT WADE.".
  Observe over_night at overbridge_street when dark() "Overbridge at night: the Ferry Inn lit and loud, and every other door shut.".
  Observe stair_scene at south_stair when true "The south ferry-stair: worn steps going down into the river, a post for tying up, and the Acre wall above, with the tops of the gravestones showing over it.".
  Observe tanyards_scene at tanyards when not dark() "The tan-yards: pits of lime and bark and worse, hides on frames, men with their arms stained to the elbow, and a smell that takes the breath out of you. Nobody comes here who need not.".
  Observe tanyards_night at tanyards when dark() "The tan-yards at night: the pits black, the hides on their frames like people standing.".
  Observe ferry_inn_scene at ferry_taproom when true "The Ferry Inn: low, smoky, full of watermen and tanners and people who have business in the Liberty that they would not have in the city.".
  Observe south_road_scene at south_road when not dark() "The south road leaves Overbridge between hedges, toward the lord's country. A milestone: HARBURY XII.".

  // ── Saint Wade's and the Acre ─────────────────────────────────────────────────────────────────────────────────────
  Observe nave_again at nave when visitedBefore(nave) "Saint Wade's: whitewash, the cheerful saint, the carved wheels on the pews.".
  Observe nave_scene at nave when not visitedBefore(nave) "Saint Wade's: a low, old, whitewashed church, cold even in this heat, smelling of damp stone and tallow. Every pew has a carved wheel on its end, for the carters, and on the oldest pews the wheels have been touched smooth.".
  Observe acre_scene at wades_acre when not dark() "Wade's Acre: the burying ground of Wrayford since there was a Wrayford, between the church and the river, gravestones leaning every way like a crowd looking at something.".
  Observe acre_night at wades_acre when dark() "The Acre at night: the stones pale, the river loud beyond the wall, the tower black.".
  Person corbin "Corbin" at wades_acre {
    Role "the sexton of Saint Wade's, old as his spade". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "Corbin looks at you from his seat on the Acre wall without getting up. 'Not dead, are you,' he says. 'No business of mine, then.'".
  }
  Rule corbin_wall when hour(clock) >= 7 and hour(clock) < 21 and not at(corbin, wades_acre) { Assert at(corbin, wades_acre). }
  Rule corbin_bed when (hour(clock) >= 21 or hour(clock) < 7) and not at(corbin, nave) { Assert at(corbin, nave). }
  Rule corbin_sleeps when (hour(clock) >= 22 or hour(clock) < 6) and not asleep(corbin) { Assert asleep(corbin). }
  Rule corbin_wakes when hour(clock) >= 6 and hour(clock) < 22 and asleep(corbin) { Retract asleep(corbin). }
  Topic corbin_strike_talk with corbin "Ask Corbin why he will not dig" when true once {
    Says "'Forty years I've dug for Wrayford. Every one of them.' He points with his pipe at the stones. 'There's not a soul in this Acre I didn't put there, bar the old ones. Wat Pardoe's father. Dunstan Fenner's mother. Joss Wilder's sister, when she was three.' He puts the pipe back. 'I'll not dig a hole in this Acre while there's a Wrayford man hanging on that bridge for the crows. Not for the toll-keeper's boy, God rest him. Not for Gidley's aunt, God rest her, at treble fees.' He looks at you. 'Let them feel it. Let the Hill smell it.'".
    On discuss { Assert knows(actor, corbin_strike). }
  }
  Topic corbin_terms_talk with corbin "Ask Corbin what would make him dig" when knows(actor, corbin_strike) once {
    Says "'When they're down.' He considers. 'Or,' and his face does something sour, 'or when that woman over the water asks me. Dorcas Mudd.' He takes his pipe out and looks into the bowl. 'She's not asked me for anything in forty years. She'll not start now.'".
    On discuss { Assert corbinTerms(actor). }
  }
  Action tell_corbin_lie(actor: group, site: place) "Tell Corbin that Dorcas Mudd asked after him" {
    Description "She did not.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wades_acre) and at(corbin, wades_acre)
      and dorcasTerms(actor) and corbinTerms(actor) and not corbinLied(actor) and not reconciled(wray) and not triedCorbinLie(actor).
    Time 2 minutes.
    Resolve check(actor, deception, dc_fair).
    On success { Assert corbinLied(actor). }
    On failure { Assert triedCorbinLie(actor). }
    Result "'Asked after me.' He takes his pipe out. 'What did she ask?' You tell him something. He looks across the water at the ferry-stage for a long time, and puts the pipe back without lighting it. 'Did she,' he says.".
    Otherwise "Corbin laughs until he coughs. 'Dorcas Mudd,' he says, 'would ask after the Devil's health before mine. Go on with you.'".
  }
  // The graves: three, by the church door. Corbin digs them by the next morning once he has a reason; or anyone can.
  Thing graves "the three graves by the church door" at wades_acre {
    State marked "By the church door, three graves' worth of turf marked out with string and pegs, uncut.".
    State dug "By the church door, three graves, dug clean and square, with the earth heaped neatly beside each.".
  }
  Initially Assert state(graves, marked).
  Relation corbinWillDig(place). Relation corbinFinished(group).
  Rule corbin_reason when (corbinDigs(party) or takenDown(wray) and stillDownOrBuried()) and not corbinWillDig(wray) and not corbinResigned(corbin) { Assert corbinWillDig(wray). }
  Query stillDownOrBuried() means not stillHanging().
  Rule corbin_digs when corbinWillDig(wray) and state(graves, marked) and hour(clock) >= 5 and hour(clock) < 21 says "In Wade's Acre old Corbin has taken his coat off and is cutting turf by the church door, and the sound of the spade carries over the water." { Assert state(graves, dug). }
  Action dig_graves(actor: group, site: place) "Dig the three graves yourself" {
    Description "Three graves, square and deep, in heavy ground: half a day for a digger.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wades_acre) and state(graves, marked) and capable(actor, digging)
      and not dark().
    Time 18.
    On success { Assert state(graves, dug). Assert dugOwn(actor). }
    Result "You cut the turf back and stack it, and dig. It is heavy river clay under a foot of black earth, and the sun is on your back. Some time in the second grave Corbin gets down off the wall and stands over you with his pipe, and in the third he takes the spade out of your hands without a word and squares off the sides himself. 'Crooked,' he says. 'Every one.' But he does not stop.".
  }
  Relation dugOwn(group).
  Kind spade_kind "the sexton's spade" like crowbar worth 1 weighing 4
    described "A long-handled spade with a narrow blade worn bright and a T-handle black with forty years of one man's hands.".
  Item sexton_spade "the sexton's spade" is spade_kind at nave owned by corbin.
  Action dig_graves_spade(actor: group, digger: member, site: place) "Dig the three graves with the sexton's spade" {
    Description "Without a digger's knack it takes all night, and you will not do it well.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wades_acre) and state(graves, marked)
      and memberOf(digger, actor) and ownedItem(sexton_spade, digger) and not capable(actor, digging).
    Time 30.
    On success { Assert state(graves, dug). Assert dugOwn(actor). }
    Result "It takes five hours, and your hands are raw by the first, and the graves are not square and not quite deep enough. But they are graves.".
  }
  // The Abbess may order him to dig, and he will, and then he will put his spade down for good.
  Relation corbinOrdered(group). Relation corbinResigned(group).

  // ── The Abbess ────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe court_scene at abbess_court when true "The Abbess's court-room: a long room with a dais, a chair under a canopy, a table with a green cloth, and on the walls the charters of the Liberty, framed, all of them, from the oldest, which is a scrap of vellum with a seal like a biscuit, to the newest, which is a letter from the lord's steward that she has had framed upside down.".
  Person abbess "Dame Isobel Crane" at abbess_court {
    Role "the Lady Abbess of Saint Wade's, who holds the Liberty of Overbridge". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "The Abbess looks at you over a pair of spectacles. 'Sit,' she says. 'Or stand. Only be brief, and be accurate.'".
  }
  Measure abbessRegard(group). Initially Set abbessRegard(abbess) to 0.
  Relation abbessClaims(group). Relation sanctuary(group). Relation ritesOffered(group).
  Discovery abbess_terms "The Abbess holds that whatever of Wrayford's dead reaches the Liberty is the Liberty's to bury. She will not fetch the three across the city's bridge herself, since to do so would admit the bridge is the city's; but she will claim them, in writing, for someone she has cause to trust, so that they cross as the Liberty's tithe.".
  Topic abbess_dead with abbess "Ask the Abbess about the dead on the bridge" when true once {
    Says "'A question of jurisdiction,' says the Abbess, 'first, and of charity second, and I am honest enough to say so in that order.' She takes her spectacles off. 'Wrayford has buried its dead in Wade's Acre since before the bridge, and every one of them crossed the river to get here, and not one paid the lord a penny. If those three reach the Liberty, they are mine, and I will bury them, and the reeve can write to the lord.' She folds the spectacles. 'I will not fetch them. If I send my brothers over that bridge for them I have admitted that the bridge is the city's road and not the Liberty's, and my predecessors have not admitted it for three hundred years.' She looks at you. 'I might put my claim in writing. For someone I had cause to trust.'".
    On discuss { Assert knows(actor, abbess_terms). }
  }
  Topic abbess_bench with abbess "Ask the Abbess about the Bridge Company" when true once {
    Says "'The Worshipful Company of the Bridge.' Very dry. 'I have known Prosper Gidley since he sang in my predecessor's choir. He sang very sweetly, and he was the boy who carried the collection. He has not changed. He has only grown.' She turns a page. 'They will vote for anything that costs them nothing they can be seen to lose. Remember that, if you have business with them. It is the only thing about them worth knowing.'".
    On discuss { Assert knows(actor, bench_rule). }
  }
  Kind claim_kind "the Abbess's letter" is gear worth 0 weighing 0
    described "A folded sheet sealed in green wax with the Liberty's seal: THE LIBERTY OF SAINT WADE CLAIMS ITS DEAD, WAT PARDOE, DUNSTAN FENNER AND JOSS WILDER, TO BE BURIED IN WADE'S ACRE AS IT HAS ALWAYS BURIED WRAYFORD, AND THEY ARE TO CROSS AS THE LIBERTY'S TITHE. I. CRANE, ABBESS.".
  Item claim_letter "the Abbess's letter" is claim_kind at limbo.
  Action ask_claim(actor: group, recipient: member, site: place) "Ask the Abbess to put her claim to the dead in writing" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, abbess_court) and at(abbess, abbess_court)
      and knows(actor, abbess_terms) and abbessRegard(abbess) >= 1 and not abbessClaims(abbess) and memberOf(recipient, actor).
    Time 1.
    Resolve acquire(claim_letter, claim_kind, recipient).
    On success { Assert abbessClaims(abbess). }
    Result "She writes it herself, without a draft, in a hand like a row of pikes, and seals it in green, and gives it to you. 'If the city stands aside,' she says, 'they are mine. Show that to the collector. Show it to the reeve. Show it to the captain, if it comes to that. And then go away and let me get on.'".
  }
  Action argue_claim(actor: group, site: place) "Argue to the Abbess that charity cannot wait on jurisdiction" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, abbess_court) and at(abbess, abbess_court)
      and knows(actor, abbess_terms) and abbessRegard(abbess) < 1 and not triedAbbess(actor).
    Time 1.
    Resolve check(actor, persuasion, dc_hard).
    On success { Increase abbessRegard(abbess) by 1. }
    On failure { Assert triedAbbess(actor). }
    Result "She hears you out without interrupting, which you are given to understand is a compliment. 'You are quite wrong,' she says. 'Jurisdiction is charity, over three hundred years.' A pause. 'But you put it well, and you were brief.'".
    Otherwise "'Charity,' says the Abbess, 'is a word people use when they would like someone else to pay for something.' She returns to her papers.".
  }
  Relation triedAbbess(group).
  // A cleric's office for the dead: the thing she cannot do herself, since to say it on the bridge is to cross it.
  Action offer_rites(actor: group, site: place) "Offer to say the office of the dead for the three, on the bridge, as a priest of no parish" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, abbess_court) and at(abbess, abbess_court)
      and capable(actor, rites) and not ritesOffered(actor).
    Time 1.
    On success { Assert ritesOffered(actor). Increase abbessRegard(abbess) by 1. }
    Result "The Abbess takes off her spectacles. 'A priest of no parish,' she says. 'Who can stand on the lord's bridge and say the words over Wrayford's dead without it meaning that the Liberty crossed it.' For the first time she looks at you as if you were of use. 'Yes. Do. Tonight, at the curfew, under the rail. And come back to me after.'".
  }
  Rule rites_said at gate_road when ritesOffered(party) and hour(clock) == 22 and stillHanging() and at(party, gate_road) and not spread(rites_fact) says "At the curfew bell you stand under the rail and say the office of the dead for Wat Pardoe, Dunstan Fenner and Joss Wilder, aloud, in the old words. The riders on the leads stop talking. In the doorways of Bridge Street people come out and stand. When you have finished there is no sound at all but the river, and then, from somewhere behind the shutters, someone says Amen, and then a great many people do." { Assert spread(rites_fact). Increase temper(wray) by 1. }
  Entity rites_fact: fact "The office said under the rail".
  Topic abbess_after_rites with abbess "Tell the Abbess the office is said" when spread(rites_fact) once {
    Says "'I heard.' She does not look up. 'The whole of Overbridge heard. Half of it came out on to the drawbridge to listen, and the riders let them stand there, which they have not let anyone do in four days.' She writes something, and sands it. 'You did what I could not, and you did it properly. The old words, not the new ones.' She looks up. 'The Liberty is obliged to you. It does not say that often.'".
    On discuss { Increase abbessRegard(abbess) by 1. }
  }
  Topic abbess_sanctuary with abbess "Ask the Abbess whether the Liberty would shelter you, if it came to that" when abbessRegard(abbess) >= 2 and not sanctuary(actor) once {
    Says "'It has sheltered worse.' She does not look up. 'Whoever is in the Liberty is beyond the reeve's writ. If you have done something in the city you would rather not answer for to Simon Hulme, be on this side of the drawbridge at dawn, and he may send me a letter.' She signs something. 'I shall frame it.'".
    On discuss { Assert sanctuary(actor). }
  }
  Topic abbess_order with abbess "Ask the Abbess to order Corbin to dig" when knows(actor, corbin_strike) and abbessRegard(abbess) >= 1 and not corbinOrdered(actor) and not corbinWillDig(wray) once {
    Says "She considers. 'I can,' she says. 'He is my sexton. He will dig, because I tell him to.' She looks at you over the spectacles. 'And then he will put down his spade, after forty years, and never pick it up again, because I made him dig against his conscience. Shall I?' You do not answer, and she rings the bell anyway, and sends for him.".
    On discuss { Assert corbinOrdered(actor). Assert corbinResigned(corbin). Assert corbinWillDigOrdered(wray). }
  }
  Relation corbinWillDigOrdered(place).
  Rule corbin_digs_ordered when corbinWillDigOrdered(wray) and state(graves, marked) and hour(clock) >= 5 and hour(clock) < 21 says "In Wade's Acre old Corbin is digging three graves by the church door, very slowly and very well, and when he has finished he cleans his spade and lays it on the Abbess's step and walks away up the south road without his coat." { Assert state(graves, dug). Assert at(corbin, limbo). }
  Rule corbin_stays_gone when corbinResigned(corbin) and state(graves, dug) and not at(corbin, limbo) { Assert at(corbin, limbo). }

  // The hide: a case before the Liberty's court, which the Abbess hands to you on the morning of the second day.
  Relation courtSitting(place). Relation hideJudged(place). Relation hideFor(group). Relation hideSplit(place).
  Query courtHours() means secondDay() and hour(clock) >= 10 and hour(clock) < 12 and not hideJudged(wray).
  Person crouch "Barnaby Crouch" at tanyards {
    Role "a tanner, stained to the elbow". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "Barnaby Crouch wipes his hands, which makes them worse. 'If it's about the hide,' he says, 'it's mine.'".
  }
  Rule crouch_court when courtHours() and not at(crouch, abbess_court) { Assert at(crouch, abbess_court). }
  Rule kemp_court when courtHours() and not at(kemp, abbess_court) { Assert at(kemp, abbess_court). }
  Rule crouch_home when not courtHours() and at(crouch, abbess_court) { Retract at(crouch, abbess_court). Assert at(crouch, tanyards). }
  Rule kemp_home when not courtHours() and at(kemp, abbess_court) { Retract at(kemp, abbess_court). Assert at(kemp, shambles). }
  Thing hide "the disputed hide" at abbess_court {
    State disputed "On the green cloth, rolled and tied: a raw cowhide, red side out, with a ticket on it in the Abbess's hand: KEMP v. CROUCH.".
    State awarded "The hide has gone from the table.".
  }
  Initially Assert state(hide, disputed).
  Observe hide_court at abbess_court when courtHours() "The Abbess's court is sitting. Saul Kemp the butcher and Barnaby Crouch the tanner stand before the table, not looking at each other, and on the green cloth between them lies a rolled cowhide. The Abbess looks at you as you come in and says, 'You have a face like a juryman. I have a jurisdiction to defend this morning and no time for cows. Judge it.' And sits back.".
  Topic kemp_claim with kemp "Ask Saul Kemp why the hide is his" when courtHours() and at(kemp, abbess_court) once {
    Says "'Beast died in my pens, in the Shambles, in the city,' says Kemp. 'I skinned it. It's mine.'".
  }
  Topic crouch_claim with crouch "Ask Barnaby Crouch why the hide is his" when courtHours() and at(crouch, abbess_court) once {
    Says "'Came over in the offal cart,' says Crouch. 'Anything in the offal cart is the tan-yards' by the Liberty's privilege. It's mine.'".
  }
  Observe hide_brands near hide when tried(hide, looking) and (capable(party, woodcraft) or capable(party, lore)) and not knows(party, hide_brand) "Unrolled, the hide has two marks on the flank: a fresh nick in the ear, the Shambles' tally-mark for a beast sold, and under it, older, a drover's brand burned into the hair: H.O., and a little curlew. Ham Ostler's. The beast was never sold. It died in the pens and somebody skinned it." teaches hide_brand.
  Observe hide_brands_plain near hide when tried(hide, looking) and not capable(party, woodcraft) and not capable(party, lore) "Unrolled, the hide has a nick in the ear, and under the hair on the flank some older mark you cannot make out.".
  Discovery hide_brand "The disputed hide carries Ham Ostler's drover's brand, the curlew: the beast was his, never sold, and died in the Shambles pens before market. It is neither the butcher's nor the tanner's.".
  Action judge_kemp(actor: group, site: place) "Give the hide to the butcher" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, abbess_court) and courtHours().
    Time 2 minutes.
    On success { Assert hideJudged(wray). Assert hideFor(kemp). Assert state(hide, awarded). }
    Result "Kemp takes it under his arm with a grin. Crouch says something about the city that the Abbess pretends not to hear. 'So,' she says. 'The Liberty yields a hide to the Shambles.' She writes it down. She does not look pleased.".
  }
  Action judge_crouch(actor: group, site: place) "Give the hide to the tanner, by the Liberty's privilege" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, abbess_court) and courtHours().
    Time 2 minutes.
    On success { Assert hideJudged(wray). Assert hideFor(crouch). Assert state(hide, awarded). Increase abbessRegard(abbess) by 1. }
    Result "Crouch takes it as if it were a sword of state. 'The Liberty's privilege upheld,' says the Abbess, and writes it down with some satisfaction. Kemp goes out without a word, and the door bangs.".
  }
  Action judge_split(actor: group, site: place) "Cut the hide in two, and give each of them half" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, abbess_court) and courtHours().
    Time 2 minutes.
    On success { Assert hideJudged(wray). Assert hideSplit(wray). Assert state(hide, awarded). }
    Result "There is a knife on the table for the purpose, it seems. You cut the hide down the backbone and give each of them a half. Both look at their halves, which are now worth nothing to anybody, with the same expression. The Abbess laughs out loud, once, like a door slamming. 'Solomon,' she says, 'and nobody's baby. Very good. Get out, both of you.'".
  }
  Action judge_ham(actor: group, site: place) "Give the hide to neither: it is Ham Ostler's, by his brand" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, abbess_court) and courtHours() and knows(actor, hide_brand).
    Time 2 minutes.
    On success { Assert hideJudged(wray). Assert hideFor(ham). Assert state(hide, awarded). Increase abbessRegard(abbess) by 1. Assert hamGrateful(actor). }
    Result "You show her the curlew. The Abbess takes her spectacles off and looks at it for a long time, and then at the butcher, who is looking at the floor, and at the tanner, who is looking at the butcher. 'A beast that died in the pens before market,' she says, 'and was skinned, and sent over the bridge in the offal cart, and argued over by two men who both knew whose it was.' She puts her spectacles back on. 'The hide is Ham Ostler's, and the Liberty is obliged to whoever noticed.' She writes. 'That is the first sensible thing anyone has said to me this week.'".
  }
  Rule hide_regard_split when hideSplit(wray) and abbessRegard(abbess) < 1 { Increase abbessRegard(abbess) by 1. }

  // ── The bear-garden ───────────────────────────────────────────────────────────────────────────────────────────────
  Observe bear_scene at bear_garden when not dark() "The bear-garden: a ring of raised benches round a sanded pit, a post in the middle with a chain, and on the chain an old brown she-bear, sitting on her haunches with her forepaws in her lap like a farmer's wife. A boy of twelve or so is combing the burrs out of her coat, and she lets him.".
  Person robin "Robin Tull" at bear_garden {
    Role "a cutler's boy of twelve, with bear-hair on his sleeves". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "The boy looks up from the bear's coat. 'She's called Margery,' he says, before you can ask anything else.".
  }
  Person clout "Sim Clout" at bear_garden {
    Role "the bear-ward, with a strap at his belt". Ancestry human. Peaceable. Pronouns he. Manner grim.
    Greets "Sim Clout looks you over. 'Show's at four,' he says. 'Penny.'".
  }
  Person margery "Margery" at bear_garden {
    Role "an old brown she-bear on a chain". Species bear. Peaceable. Pronouns she.
  }
  Relation clouted(group). Relation margeryBought(group). Relation margerySettled(group).
  Topic robin_why with robin "Ask Robin Tull why he will not go home" when knows(actor, robin_gone) and not robinHome(robin) and not robinStays(robin) once {
    Says "'Because Margery won't dance for anyone else.' He goes on combing. 'Not for him. Only me. And if she won't dance he'll sell her to the baiting at Harbury at Michaelmas, he says so, and they'll set dogs on her.' He looks at the strap on Clout's belt, and away. 'So I can't go home. Can I.' He combs. 'I like knives,' he says, as if it were a confession. 'I do. I'd rather bears.'".
    On discuss { Assert knows(actor, margery_fate). }
  }
  Discovery margery_fate "The bear, Margery, dances only for Robin Tull. If she will not dance, Sim Clout will sell her to the baiting at Harbury at Michaelmas.".
  Action persuade_robin(actor: group, site: place) "Talk Robin Tull into going home to his mother" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bear_garden) and at(robin, bear_garden)
      and knows(actor, robin_gone) and not robinHome(robin) and not robinStays(robin) and not triedRobin(actor).
    Time 1.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert robinHome(robin). Retract at(robin, bear_garden). Assert at(robin, tull_shop). }
    On failure { Assert triedRobin(actor). }
    Result "It takes a while, and it is mostly about his mother, and how she grinds the cleavers when she is frightened. In the end he puts the comb down and says goodbye to Margery, which takes longer, and comes.".
    Otherwise "'No,' he says, and goes on combing, and the bear looks at you over his head.".
  }
  Relation triedRobin(group).
  Action buy_margery(actor: group, site: place) "Buy Margery from Sim Clout for ten coin, and give her to the Liberty" {
    Description "The Abbess has a walled garden. Nobody has told her yet.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bear_garden) and at(clout, bear_garden)
      and knows(actor, margery_fate) and not margeryBought(actor) and quantity(actor, gold) >= 10.
    Time 1.
    On success { Decrease quantity(actor, gold) by 10. Assert margeryBought(actor). Assert robinHome(robin). Increase abbessRegard(abbess) by 1.
      Retract at(robin, bear_garden). Assert at(robin, tull_shop). Retract at(margery, bear_garden). Assert at(margery, abbess_court). }
    Result "Clout counts the coins twice and unhooks the chain. You walk Margery down Overbridge Street on it with Robin at her other side, and all the Liberty comes to its doors to watch, and the Abbess comes to her gate, and looks at the bear, and at you, and says, 'I see,' and has the gate opened. Robin goes home to his mother after that without being asked, because he can come and visit on Sundays.".
  }
  Action settle_margery(actor: group, site: place) "Show Robin how a drover settles a beast with a low whistle, so anyone can work her" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bear_garden) and at(robin, bear_garden)
      and capable(actor, woodcraft) and knows(actor, margery_fate) and not margerySettled(actor) and not robinHome(robin).
    Time 2.
    On success { Assert margerySettled(actor). Assert robinHome(robin). Retract at(robin, bear_garden). Assert at(robin, tull_shop). }
    Result "It is the whistle a drover uses for a nervous cow, low and two notes, and the old bear lifts her head at it. You have Robin teach it to Sim Clout, who is bad at it, and then Clout does it, badly, and Margery gets up on her hind legs and turns round once, as if humouring him. Robin watches with his mouth open. 'She'll do it for him now,' he says. 'She'll do it for anyone.' He sounds, for a moment, bereft. Then he goes home.".
  }
  Action face_clout(actor: group, site: place) "Tell Sim Clout that if he lays that strap on the boy again, you will have his ears" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, bear_garden) and at(clout, bear_garden)
      and knows(actor, robin_gone) and not clouted(actor) and not robinHome(robin).
    Time 1.
    Resolve check(actor, intimidation, dc_fair).
    On success { Assert clouted(actor). Assert robinStays(robin). }
    Result "Clout looks at you, and at the strap, and takes it off his belt and hangs it on the post, and does not look at it again. Robin watches it all. 'I can stay, then,' he says. 'With Margery.' And then, carefully: 'Will you tell my mother I'm well. And that I'm sorry. And not where I am, because she knows.'".
    Otherwise "Clout puts his hand on the strap and smiles at you with very few teeth. 'Liberty,' he says. 'No reeve here. Go home.'".
  }
}

data/adventures/wrayford/market.kyr:
Module wrayford "The Third Night" {
  // ── The Market Cross ──────────────────────────────────────────────────────────────────────────────────────────────
  Observe cross_scene at market_cross when not dark() and not visitedBefore(market_cross) "The Market is a sloping square with a stone cross in the middle where the hiring is done, the Guildhall along the top side with its clock and its arcade, and the Bridge Company's counting-house next to it, newly painted blue, with a bridge in gold over the door. The Mercer Steps go up behind to the Hill. Down Shambles Lane you can hear cattle, and smell them. On the Cross itself, on every post of the arcade, and on the counting-house door, the same printed sheet is pasted.".
  Observe cross_again at market_cross when not dark() and visitedBefore(market_cross) "The Market Cross: the Guildhall clock, the blue counting-house, the sheets on every post.".
  Observe cross_night at market_cross when dark() "The Market at night: the Guildhall clock lit, and a watchman sitting on the steps of the Cross.".
  Observe cross_market_day at market_cross when not dark() and hour(clock) < 12 and (secondDay() or fifthDay()) "It is market day: farm carts, egg-women, a man selling eels live out of a barrel, and at the Cross the hiring, labourers standing with a tuft of wool or a whip in their hats for what they do.".
  // The broadside on every post.
  Discovery confession_read "Pasted on every post in the Market: THE TRUE AND LAST CONFESSION OF WAT PARDOE, CARTER, TAKEN ON THE FELL ROAD. 'I, Wat Pardoe, being led astray by Drink and the Devil and the Wicked Counsel of Others, did conspire against the Lord's Toll, which is a Just and Godly Toll, and did with my Cart run down an Innocent Youth, for which I am Heartily Sorry, and I Bless the Worshipful Company of the Bridge, who have been Ever Kind to Carters.' Printed by E. Quoin, Cutler's Lane. Price One Penny." {
    Source broadside "the printed sheet on the Market Cross" at market_cross readable by party.
  }
  Relation confessionDown(place).
  Observe sheets_down at market_cross when confessionDown(wray) and not dark() "The posts of the arcade are bare where the Confession was. Someone has scraped the last of it off the Cross with a knife.".

  // ── The Guildhall ─────────────────────────────────────────────────────────────────────────────────────────────────
  Observe hall_scene at guild_hall when not visitedBefore(guild_hall) "The Guildhall's long hall: a hammer-beam roof, the city's arms in plaster, a long table on a dais where the Bench sits, and at the far end the reeve's chair and his clerk's desk, where he keeps court. Along one wall hang the portraits of fifty years of the Bridge Company, Masters and Wardens, in blue gowns, each more prosperous than the last. An easel stands at the end of the row.".
  Observe hall_again at guild_hall when visitedBefore(guild_hall) "The Guildhall's long hall: the Bench's table, the reeve's chair, the row of blue-gowned portraits and the easel at the end.".
  Observe cellar_scene at guild_cellar when true "The Guildhall cellar, which is the city's lockup: stone, straw, a bucket, a grating at the top of the wall that lets in the feet of people crossing the Market.".

  // Tom Lumley's portrait of the present Bench, for the Bridge Feast.
  Person lumley "Tom Lumley" at guild_hall {
    Role "a painter, in a coat with paint on the elbows". Ancestry human. Peaceable. Pronouns he. Manner acerbic.
    Greets "Tom Lumley does not take his eyes off the canvas. 'If you're from the Company, I've not finished. If you're not, have you a shilling?'".
  }
  Rule lumley_drinks when hour(clock) >= 18 and hour(clock) < 23 and not at(lumley, wheels_taproom) { Assert at(lumley, wheels_taproom). }
  Rule lumley_paints when hour(clock) >= 9 and hour(clock) < 18 and not at(lumley, guild_hall) { Assert at(lumley, guild_hall). }
  Thing portrait "the Company's portrait" at guild_hall {
    State sketched "On the easel, the present Bench of the Bridge Company, five aldermen in blue gowns round a table with a model of the bridge on it, blocked in and half painted. It is extremely good. Alderman Gidley is in the middle, with one hand on the model bridge as if blessing it and the other, which the painter has not finished, very near the money-box.".
    State true_likeness "On the easel, the Bench of the Bridge Company, finished: five aldermen in blue gowns round the model bridge, each exactly himself, the soft hands, the good dinners, the small eyes and the large purses, and Gidley in the middle with one hand blessing the bridge and the other on the money-box, and on all their faces the same expression of men who have just been told something sad about other people.".
    State flattering "On the easel, the Bench of the Bridge Company, finished: five noble aldermen, rather thinner than life, gazing into the distance over the model bridge with the look of men contemplating Sacrifice. The money-box has been painted out. There is a dove.".
    State carried_off "The easel at the end of the row is empty.".
  }
  Initially Assert state(portrait, sketched).
  Relation lumleyPaid(group). Relation gidleySat(group). Relation portraitBanner(place). Relation portraitHung(place).
  Topic lumley_portrait with lumley "Ask Tom Lumley about the portrait" when state(portrait, sketched) once {
    Says "'The Worshipful Company of the Bridge, for their new hall.' He mixes something on a plate. 'Ten crowns, on delivery, if they like it, by the Feast.' He looks at the canvas with dislike. 'They won't sit. They sat once, all together, for an hour, and talked about the carters, and I got all I need.' He adds a touch of red to Gidley's nose. 'I'm painting what I saw. What I saw is not what they'll pay for. I have the rent to find.' He looks at you sidelong. 'They'll vote for anything that costs them nothing, you know. I've watched them do it for three weeks. You could get the Bench to pass a vote of thanks to the Devil if he waived the fee.'".
    On discuss { Assert knows(actor, bench_rule). }
  }
  Discovery bench_rule "The Bench of the Bridge Company will pass any motion that costs them nothing they can be seen to lose: not money, not face with the lord, not the toll. Phrased so, they will pass anything." {
    Known by lumley, inchbold, abbess, pell.
  }
  Action sit_gidley(actor: group, site: place) "Keep Alderman Gidley talking by the easel while Tom Lumley paints him" {
    Description "An hour of the Company's sacrifices, while the painter works.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, guild_hall) and at(gidley, guild_hall)
      and at(lumley, guild_hall) and state(portrait, sketched) and not gidleySat(actor).
    Time 6.
    On success { Assert gidleySat(actor). Assert state(portrait, true_likeness). }
    Result "You ask the Alderman about the Company's burdens, and he tells you, for an hour, standing by the easel, about the cost of the bridge's upkeep, the ingratitude of carters, the lord's unreasonable rent, and his own sleepless nights, with his hand on his heart. Behind him Tom Lumley paints like a man possessed. When Gidley at last goes off to his dinner, Lumley steps back from the canvas and looks at it and says, quite quietly, 'There. There he is.'".
  }
  Topic lumley_flatter with lumley "Tell Tom Lumley to paint them what they'll pay for" when state(portrait, sketched) once {
    Says "He looks at you a long time with his brush in the air. 'The rent,' he says. 'Yes.' He picks up a rag and wipes out the money-box, and Gidley's nose, and everyone's chins, with a long sigh, very carefully, the way a man takes out a splinter. 'I'll put a dove in,' he says. 'They like a dove.'".
    On discuss { Assert state(portrait, flattering). Assert lumleyPaid(lumley). }
  }
  Action carry_portrait(actor: group, site: place) "Carry the true portrait out to the carters' yards for a banner" {
    Description "Lumley says it's his to sell, and he'll sell it for a pint to anyone who'll carry it where it'll be looked at.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, guild_hall) and state(portrait, true_likeness)
      and not portraitHung(wray) and quantity(actor, gold) >= 1.
    Time 2.
    On success { Decrease quantity(actor, gold) by 1. Assert state(portrait, carried_off). Assert portraitBanner(wray). Increase temper(wray) by 1. }
    Result "Lumley takes your coin, and laughs, and helps you get it off the easel. You carry it down the Cartway with the paint still tacky and set it up against the wall of the carters' yards. Within the hour there is a crowd round it, and within two hours somebody has nailed it to a pair of cart-shafts so that it can be carried, and the carters are standing in front of it doing Gidley's face.".
  }
  // Gidley comes to see it before the Remonstrance, and weeps.
  Rule gidley_sees_true at guild_hall when secondDay() and hour(clock) == 11 and state(portrait, true_likeness) and not portraitHung(wray) says "Alderman Gidley comes in to see the portrait before the Bench sits. He stands in front of it for a long time with his hands behind his back, and then his face begins to work, and he takes out a handkerchief. 'He has caught it,' he says, thickly. 'Our burden. Look at us. Look at our faces.' He blows his nose. 'It shall hang in the Guildhall at the Feast, where every carter in Wrayford can see what the Company has given.' He pays Lumley on the spot. Lumley takes the money as if it might go off." { Assert portraitHung(wray). Assert lumleyPaid(lumley). Increase temper(wray) by 1. }
  Observe portrait_hung at guild_hall when portraitHung(wray) and state(portrait, true_likeness) "The true portrait of the Bench hangs at the end of the row now, framed in gilt, with a little brass plate: THE WORSHIPFUL COMPANY OF THE BRIDGE IN THE YEAR OF THE RIOT. Carters come into the hall on any excuse and stand in front of it with their caps off, very respectfully, shaking.".

  // ── The Guildhall yard: the impounded carts ───────────────────────────────────────────────────────────────────────
  Observe reeve_yard_scene at reeve_yard when not dark() "The Guildhall yard, behind the hall: the city's fire-cart, a stack of hurdles, and along the wall three carts drawn up with their shafts down and a chalked notice on each: IMPOUNDED. GOODS OF A FELON. Wilder's is a light cart. Fenner's is old.".
  Thing pardoe_cart "Wat Pardoe's cart" at reeve_yard {
    State impounded "A big four-wheeled carter's wagon with red wheels and PARDOE, WAIN ROW painted on the board, impounded.".
    State reclaimed "Wat Pardoe's cart, with the IMPOUNDED notice rubbed off.".
  }
  Initially Assert state(pardoe_cart, impounded).
  Observe tailboard_told near pardoe_cart when tried(pardoe_cart, looking) "You go over it: the wheels first, because that is what everyone says. The wheels are clean. A wheel that had gone over a boy would not be clean, and nobody has washed these; there is the fell road's red mud dried on every spoke. Then the tailboard, and the bed of the cart behind it. There is blood there, a good deal of it, dried brown into the boards, along the length of the bed, where something was laid down and lay a long while. Not where a wheel goes. Where a boy is lifted in, and held." teaches tailboard_seen.
  Discovery tailboard_seen "Wat Pardoe's cart was not washed, and its wheels are clean. The blood is in the bed of the cart, behind the tailboard: where a hurt boy was lifted in and laid down, not where a wheel went over one.".

  // ── The Bridge Company's counting-house ───────────────────────────────────────────────────────────────────────────
  Observe counting_scene at counting_room when true "A long counter, high desks, a smell of new paint and new ledgers, and over the inner door a painted board: WE BEAR THE CROSSING. The Company's motto. A strongbox with the bridge in gold on the lid. Behind the counter, a door to the collector's room.".
  Person inchbold "Lancelot Inchbold" at counting_room {
    Role "the Bridge Company's clerk, with ink to the second knuckle". Ancestry human. Peaceable. Pronouns he. Manner proud.
    Greets "Lancelot Inchbold finishes his line, sands it, and only then looks up, as if you were a sum he had been expecting.".
  }
  // The clerk keeps the Company's hours, and spends his evenings in the Nine Wheels, where he hears everything.
  Rule inchbold_works when hour(clock) >= 8 and hour(clock) < 18 and not countingBurned(wray) and not at(inchbold, counting_room) { Assert at(inchbold, counting_room). }
  Rule inchbold_works_burned when hour(clock) >= 8 and hour(clock) < 18 and countingBurned(wray) and not at(inchbold, guild_hall) { Assert at(inchbold, guild_hall). }
  Rule inchbold_drinks when hour(clock) >= 18 and hour(clock) < 23 and not at(inchbold, wheels_taproom) { Assert at(inchbold, wheels_taproom). }
  Rule inchbold_home when (hour(clock) >= 23 or hour(clock) < 8) and not at(inchbold, limbo) { Assert at(inchbold, limbo). }
  Topic inchbold_bench with inchbold "Ask the Company's clerk how the Bench decides things" when true once {
    Says "'Gracefully.' He dips his pen. 'The Bench is a body of gentlemen of the greatest goodwill, who will agree to any proposal that does not cost them anything. I draft the proposals.' He does not smile, quite. 'You would be surprised what does not cost anything, phrased well. The Remonstrance against the toll is being moved tomorrow at noon in the hall. It costs nothing: the lord will not read it.' He writes. 'I wrote it.'".
    On discuss { Assert knows(actor, bench_rule). Assert knows(actor, remonstrance_called). }
  }
  Discovery remonstrance_called "At noon on the second day the Bench of the Bridge Company meets in the Guildhall to move a Remonstrance to the lord against the bridge toll, which the Company itself farms. Citizens may attend, and move clauses." {
    Known by inchbold, gidley, lumley, hulme, hal, pell.
  }
  Topic inchbold_confession with inchbold "Ask the clerk who wrote Wat Pardoe's confession" when knows(actor, confession_read) and knows(actor, quoin_named) once {
    Says "Inchbold sands a line. 'A confession is a public document,' he says, 'and the public has a right to the consolation of it. Wat Pardoe was not in a position to write it himself.' He blots. 'I find the public is consoled by Drink and the Devil, and by gratitude to the Company. It is a penny. It has sold four hundred.' He looks up at last. 'It was not a lie. It was an improvement.'".
  }
  // The collector's room: Pinch's bed, and under the mattress what he could not bring himself to burn.
  Observe pinch_room_scene at pinch_room when true "A narrow room behind the counting-house: a bed made with corners like a box, a washstand, a candle-end in a saucer, a shelf with the toll schedule copied out fair and pinned up as if it were a prayer.".
  Thing pinch_lock "the lock on the collector's door" on pinch_door {
    State locked blocking "The door behind the counter is locked. Pinch keeps the key on a string round his neck.".
    State open "The door to the collector's room stands open.".
    Change pick "Pick the lock on the collector's door" from locked to open needing lockwork.
  }
  Initially Assert state(pinch_lock, locked).
  // The clerk sees everything, and writes it down, and that is all he does with it.
  Relation inchboldNoted(group).
  Rule inchbold_notes when state(pinch_lock, open) and at(inchbold, counting_room) and at(party, counting_room) and not pinchGone(pinch) and not inchboldNoted(party) says "Lancelot Inchbold watches you open the collector's door. He dips his pen, and writes something in the margin of his ledger, and blots it, and goes back to his figures. Whatever it is, it is minuted." {
    Assert inchboldNoted(party). }
  Rule pinch_locks when hour(clock) == 8 and state(pinch_lock, open) and not pinchGone(pinch) { Assert state(pinch_lock, locked). }
  Discovery daybook_found "Under Pinch's mattress, wrapped in a clean shirt: the toll day-book from the burned toll-house, its covers scorched and its pages whole." { Found by searching pinch_room. }
  Kind daybook_kind "the toll day-book" is gear worth 0 weighing 1
    described "A day-book bound in calf, scorched on the outside, every page within ruled and filled in a small exact hand: four months of the bridge toll, cart by cart, beast by beast, and a second column, very faint, in pencil.".
  Item daybook "the toll day-book" is daybook_kind at pinch_room hidden until daybook_found.
  Action read_daybook(actor: group, reader: member, site: place) "Read the toll day-book" {
    Requires able(actor) and memberOf(reader, actor) and ownedItem(daybook, reader) and not benighted(actor) and not knows(actor, daybook_read).
    Time 1.
    On success { Assert knows(actor, daybook_read). }
    Result "It is very clear, which is the terrible thing about it. Every cart, every beast, every farthing, entered in ink. And beside every fifth entry, in pencil, faint as a breath, a mark: a penny for the Company, and a penny for Amos Pinch. Four months of it. The last page is the night of the rising, the entries stopping at the hour the chain went, and under them, in pencil, as if he could not help it, a sum: what the fire would save him.".
  }
  Discovery daybook_read "Pinch's day-book shows that for four months he took a penny in five of the bridge toll for himself, marked in pencil. The last page is the night of the rising, and under it a sum: what a fire would save him.".
  Discovery fire_pinch "The carters broke the chain and threw the board in the river; they did not burn the toll-house. Amos Pinch, the Company's collector, set it alight in the confusion, to burn the tally of what he had been taking. Then he could not bring himself to burn the day-book, and kept it.".
  Rule fire_put_together when knows(party, daybook_read) and (knows(party, flask_found) or knows(party, pinch_shirt)) and not knows(party, fire_pinch) says "It goes together all at once: the Company's oil flask in the ash where no carter went, the collector's shirt stinking of lamp-oil the morning after, and the day-book under his mattress with the sum on the last page. The carters broke the chain. Amos Pinch burned the toll-house." teaches fire_pinch { }
  Topic pinch_cornered with pinch "Show Pinch the Company's flask from the ash of the toll-house" when knows(actor, flask_found) and carries(actor, company_flask) and not pinchCowed(pinch) once {
    Says "Pinch looks at the flask and his lips begin to move. 'A cart, one penny,' he whispers. 'A beast, one penny the head. A carcass,' and stops, and puts his face in his hands. 'I couldn't burn the book,' he says through his fingers. 'I had the oil on it and the light in my hand and I couldn't. Four months of figures. It's the best book I ever kept.' He looks up, grey. 'What do you want? I'll rule anything. Anything on the board. Only don't show the Alderman.'".
    On discuss { Assert pinchCowed(pinch). Assert knows(actor, fire_pinch). }
  }
  Topic pinch_rules_any with pinch "Tell Pinch he will rule that the dead cross free, as the Liberty's tithe" when pinchCowed(pinch) and not ruling(ruled_tithe) once {
    Says "'The Liberty's tithe.' He writes it in his tally with a hand that shakes. 'Free. By ancient privilege.' He does not look at you. He does not look at anyone, for the rest of the day.".
    On discuss { Assert ruling(ruled_tithe). Assert knows(actor, ruled_tithe). }
  }

  // ── Cutler's Lane: the printer, the pawnshop, the cutler ──────────────────────────────────────────────────────────
  Observe lane_scene at cutlers_lane when not dark() "Cutler's Lane: a narrow street of knife-grinders and small shops behind the Market, with the clatter of a press coming from one door and three gilt balls hanging over another.".
  Observe quoin_scene at quoin_shop when true "A print shop: the press like a great wooden mangle, cases of type, wet sheets pegged up on lines to dry like washing, and the smell of ink and lamp-black. On the lines: The True and Last Confession of Wat Pardoe, forty times over.".
  Person quoin "Ezra Quoin" at quoin_shop {
    Role "a printer, inky to the elbow". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "Ezra Quoin straightens up from the press with a sheet in each hand. 'Ballads, bills, confessions, almanacs, notices of sale,' he says. 'Three coin the hundred and I'll set it while you wait.'".
  }
  Discovery quoin_named "The Confession was printed by Ezra Quoin of Cutler's Lane, who prints anything paid for.".
  Rule confession_printer when knows(party, confession_read) and not knows(party, quoin_named) and at(party, quoin_shop) says "You know that black letter; you read it on every post in the Market." teaches quoin_named { }
  Topic quoin_who with quoin "Ask Quoin who brought him Wat Pardoe's confession to print" when knows(actor, confession_read) once {
    Says "'A gentleman of the Company,' says Quoin cheerfully. 'Mr Inchbold, the clerk. Brought it in fair copy, paid in advance, very generous.' He hangs up a sheet. 'I print what I'm brought. That's the trade. If you want to say something else, bring it me and three coin, and I'll print that too.' 'I'm a great believer in both sides.' He says it as if it were a creed, and perhaps it is.".
    On discuss { Assert knows(actor, quoin_named). Assert knows(actor, quoin_prints). }
  }
  Discovery quoin_prints "Ezra Quoin will print anything for three coin, set while you wait, and post it in the Market by evening.".
  Action buy_confessions(actor: group, site: place) "Buy up Quoin's whole stock of the Confession, and have the sheets in the Market taken down" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, quoin_shop) and at(quoin, quoin_shop)
      and knows(actor, confession_read) and not confessionDown(wray) and quantity(actor, gold) >= 5.
    Time 1.
    On success { Decrease quantity(actor, gold) by 5. Assert confessionDown(wray). Increase temper(wray) by 1. }
    Result "'The lot?' Quoin is delighted. 'Five coin, and my boy'll scrape the Market for nothing, he likes scraping.' He bundles the drying sheets off the lines and gives them to you to burn, which you do, in the alley, and his boy goes off with a bucket.".
  }
  Action smash_forme(actor: group, site: place) "Knock the type of the Confession out of Quoin's press" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, quoin_shop) and capable(actor, brawn)
      and not confessionDown(wray).
    Time 2 minutes.
    On success { Assert confessionDown(wray). Assert hostile(quoin, actor). }
    Result "You put your shoulder to the forme and it comes out of the bed of the press and goes over, and four hundred letters go across the floor like hail. Quoin stands looking at them. 'That,' he says, 'was three hours' work,' and then, quite calmly, 'Get out of my shop.'".
  }
  // A broadside of your own: what it says is what you know, and what you choose to say.
  Relation printed(entity).
  Entity sheet_trial: fact "THREE CARTERS HANGED ON THE ROAD WITHOUT A TRIAL".
  Entity sheet_fire: fact "WHO BURNED THE TOLL-HOUSE?".
  Entity sheet_elegy: fact "AN ELEGY FOR NED HOBDAY, AGED FOURTEEN".
  Entity sheet_kit: fact "THE TRUE ACCOUNT OF THE CART".
  Query printReady(a: group) means at(a, quoin_shop) and at(quoin, quoin_shop) and knows(a, quoin_prints) and not hostile(quoin, a) and quantity(a, gold) >= 3.
  Action print_trial(actor: group, site: place) "Pay Quoin to print: THREE CARTERS HANGED ON THE ROAD WITHOUT A TRIAL" {
    Requires able(actor) and company(actor) and at(actor, site) and printReady(actor) and not printed(sheet_trial).
    Time 2.
    On success { Decrease quantity(actor, gold) by 3. Assert printed(sheet_trial). Increase temper(wray) by 1. }
    Result "You write it at his bench in the plainest words you have: the warrant, the fell road, the rope before light, no court, no trial, a dead boy in the cart. Quoin sets it in the big black letter. By evening it is pasted on every post the Confession was on, and over half of them.".
  }
  Action print_fire(actor: group, site: place) "Pay Quoin to print: WHO BURNED THE TOLL-HOUSE?" {
    Requires able(actor) and company(actor) and at(actor, site) and printReady(actor) and knows(actor, fire_pinch) and not printed(sheet_fire).
    Time 2.
    On success { Decrease quantity(actor, gold) by 3. Assert printed(sheet_fire). Assert pinchExposed(wray). Increase temper(wray) by 1. }
    Result "You write it as a question, which is how Quoin says the best ones go: an oil flask of the Company's in the ash where no carter went, a collector's shirt sent to the wash stinking of lamp-oil, a day-book that did not burn. Quoin reads it over twice and whistles. 'Both sides,' he says. 'I did say.' By evening a crowd is reading it aloud at the Cross, and somebody has written PINCH under it in charcoal.".
  }
  Relation pinchExposed(place).
  Action print_elegy(actor: group, site: place) "Write an elegy for Ned Hobday, and pay Quoin to print it" {
    Description "Not about the carters. About the boy.".
    Requires able(actor) and company(actor) and at(actor, site) and printReady(actor) and knows(actor, jennet_hates) and not printed(sheet_elegy).
    Time 3.
    On success { Decrease quantity(actor, gold) by 3. Assert printed(sheet_elegy). Increase temper(wray) by 1. Increase jennetTrust(jennet) by 1. }
    Result "It takes you longer than you thought, at Quoin's bench, crossing out. In the end it is short: a boy of fourteen in his father's hat, a penny a day, holding the lord's chain because it was his to hold. Nothing about who drove. Quoin reads it, and does not make a joke, and sets it in a small plain letter with a black border, and does not charge for the border. By evening it is on the door of the toll-keeper's house, and somebody has put a flower under it.".
  }
  Action print_kit(actor: group, site: place) "Pay Quoin to print the true account of the cart: that Kit Pardoe was driving, and his father took the blame" {
    Grave "Printed, it cannot be unprinted. Every rider and constable in Wrayford can read.".
    Requires able(actor) and company(actor) and at(actor, site) and printReady(actor) and knows(actor, kit_driving) and not printed(sheet_kit).
    Time 2.
    On success { Decrease quantity(actor, gold) by 3. Assert printed(sheet_kit). Assert kitExposed(wray). }
    Result "Quoin sets it without a word, and pastes it up at dusk. It is true. Wat Pardoe did not run down the toll-keeper's boy; he lifted him into the cart and drove for the bone-setter, and said he had been driving so that his son would not hang. Everyone in the Market reads it. Sergeant Gault reads it at the Cross, slowly, moving his lips, and then goes off up the Cartway toward Northgate.".
  }
  Relation kitExposed(place).
  Rule kit_taken_exposed when kitExposed(wray) and not kitTaken(kit) and not travelsWith(kit, party) and hour(clock) >= 20 says "In the evening the riders go into the carters' yards and take Kit Pardoe, who does not fight them, and walk him to the Guildhall cellar through a crowd that does not know whether to cheer or curse." {
    Assert kitTaken(kit). Assert at(kit, guild_cellar). Set kitTrust(kit) to 0. }

  // The pawnshop, kept by Alderman Gidley's cousin.
  Observe pawn_scene at pawnshop when true "A dark shop full of other people's things: clocks, Sunday coats, a fiddle, a trayful of rings under glass, a cradle. Each has a ticket on a string.".
  Person pratt "Dorothea Pratt" at pawnshop {
    Role "who keeps the pawnshop, Alderman Gidley's cousin". Ancestry human. Peaceable. Pronouns she. Manner proud.
    Greets "Mistress Pratt looks at your hands before she looks at your face, to see what you have brought.".
  }
  Relation ringFreed(group). Relation chiselsBought(group).
  Topic pratt_ring with pratt "Ask Mistress Pratt about Joss Wilder's betrothal ring" when knows(actor, ring_missing) once {
    Says "'Wilder.' She turns a ledger and runs her finger down it. 'A gold ring, plain, a heart cut inside. Pawned for four shillings a fortnight ago, to pay the new toll on his cart.' She closes the ledger. 'It's not for sale. Mr Inchbold of the Company has been round. A felon's goods are forfeit to the lord, and the Company is making the inventory for the lord's steward. I'm to hold it.' She looks at you without much interest. 'Unless the redemption were paid twice over, for my trouble. Which I would have to account for. Eight coin.'".
    On discuss { Assert knows(actor, ring_pawned). }
  }
  Discovery ring_pawned "Joss Wilder pawned his betrothal ring a fortnight ago to pay the new toll on his cart. Mistress Pratt holds it for the Company's inventory of a felon's goods, and will sell it back for eight coin.".
  Kind ring_kind "Joss Wilder's ring" is treasure worth 0 weighing 0
    described "A plain gold ring, thin with being worn, with a heart cut on the inside.".
  Item joss_ring "Joss Wilder's ring" is ring_kind at limbo.
  Action buy_ring(actor: group, recipient: member, site: place) "Pay Mistress Pratt eight coin for Joss Wilder's ring" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pawnshop) and at(pratt, pawnshop)
      and knows(actor, ring_pawned) and not ringFreed(actor) and memberOf(recipient, actor) and quantity(actor, gold) >= 8.
    Time 2 minutes.
    Resolve acquire(joss_ring, ring_kind, recipient).
    On success { Decrease quantity(actor, gold) by 8. Assert ringFreed(actor). }
    Result "She counts the coins twice and puts the ring in your palm without a word, and writes something in the ledger, and you see that it is: lost.".
  }
  Action argue_ring(actor: group, recipient: member, site: place) "Tell Mistress Pratt that the ring was pawned before Joss was any felon, and is the pawn's, not the lord's" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pawnshop) and at(pratt, pawnshop)
      and knows(actor, ring_pawned) and not ringFreed(actor) and not triedPratt(actor) and not ruling(ruled_felon) and memberOf(recipient, actor)
      and quantity(actor, gold) >= 4.
    Time 2 minutes.
    Resolve check(actor, persuasion, dc_fair).
    On success { Decrease quantity(actor, gold) by 4. Assert ringFreed(actor). Assert acquireRing(recipient). }
    On failure { Assert triedPratt(actor). }
    Result "She opens her mouth, and shuts it, and looks at the ledger. 'A fortnight ago,' she says. 'He was a carter a fortnight ago.' She sniffs. 'The four shillings, then. And the Company can take it up with me.' She puts the ring in your hand.".
    Otherwise "'Mr Inchbold says otherwise,' she says. 'Eight coin, or good day.'".
  }
  Relation triedPratt(group). Relation acquireRing(member).
  Action take_ring(actor: group, recipient: member, site: place) "Take the ring that is owed" {
    Requires able(actor) and memberOf(recipient, actor) and acquireRing(recipient).
    Time 0.
    Resolve acquire(joss_ring, ring_kind, recipient).
    On success { Retract acquireRing(recipient). }
    Result "{recipient} takes Joss Wilder's ring.".
  }
  // What is pledged is hers until it is redeemed, and she says so.
  Entity pratt_objects: fact "'Those are pledged,' says Mistress Pratt, very loud, with her hand on the bell for the reeve's man. 'Pledged, and in my ledger, and not yours.'".
  Initially Assert objection(pratt, pratt_objects).
  Action redeem_chisels(actor: group, recipient: member, site: place) "Pay Mistress Pratt three coin for Dunstan Fenner's chisels" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pawnshop) and at(pratt, pawnshop)
      and knows(actor, tools_pawned) and not chiselsBought(actor) and memberOf(recipient, actor) and quantity(actor, gold) >= 3
      and at(fenner_chisels, pawnshop).
    Time 2 minutes.
    Resolve acquire(fenner_chisels, chisels_kind, recipient).
    On success { Retract owns(pratt, fenner_chisels). Decrease quantity(actor, gold) by 3. Assert chiselsBought(actor). }
    Result "'A boy's been bringing them one at a time,' she says. 'Six. Three coin.' She does not ask who you are.".
  }

  // Goodwife Tull, cutler, whose apprentice son has run off to the bears.
  Observe tull_scene at tull_shop when true "A cutler's shop: knives in rows on green baize, a grindstone, and a woman at a bench putting an edge on a cleaver with great violence.".
  Person tull "Goodwife Tull" at tull_shop {
    Role "a cutler's widow, who keeps the shop". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "Goodwife Tull does not stop grinding. 'If you've come to tell me where he is, I know where he is.'".
  }
  Topic tull_robin with tull "Ask Goodwife Tull who he is, and where" when not robinHome(robin) once {
    Says "'Robin. My boy. Apprenticed to me, articled, sealed, and run off four days ago across the bridge to the bear-garden in Overbridge to be a bear-ward's boy, because a bear is more interesting than knives.' The cleaver shrieks on the stone. 'I can't go and fetch him. It's the Liberty; the reeve's man won't go, and if I go myself I'll take the bear-ward's ears off and then where will I be.' She holds the cleaver up to the light. 'Fetch him home. I'll give you the best knife in the shop.'".
    On discuss { Assert knows(actor, robin_gone). }
  }
  Discovery robin_gone "Goodwife Tull's apprentice son Robin has run away across the bridge to the bear-garden in Overbridge. She wants him home, and will give the best knife in her shop for it.".
  Kind tull_knife "a Tull knife" like dagger worth 4 weighing 1
    described "A short heavy knife with a horn handle and the Tull mark, sharp enough to make you careful.".
  Item tull_reward "a Tull knife" is tull_knife at limbo.
  Relation robinHome(group). Relation robinStays(group). Relation tullPaid(group).
  Rule robin_home_told at tull_shop when robinHome(robin) and not tullPaid(tull) says "Robin Tull comes into the shop behind you with his hands in his pockets, smelling powerfully of bear. His mother looks at him for a long time. Then she hits him round the ear, not hard, and hugs him, very hard, and then holds out to you, handle first, the best knife in the shop." { Assert tullPaid(tull). Assert at(tull_reward, tull_shop). }
  Action take_tull_knife(actor: group, recipient: member, site: place) "Take the knife Goodwife Tull holds out" {
    Requires able(actor) and at(actor, site) and at(actor, tull_shop) and at(tull_reward, tull_shop) and memberOf(recipient, actor).
    Time 0.
    Resolve acquire(tull_reward, tull_knife, recipient).
    On success { Retract at(tull_reward, tull_shop). }
    Result "{recipient} takes the Tull knife.".
  }

  // ── The Shambles ──────────────────────────────────────────────────────────────────────────────────────────────────
  Observe shambles_scene at shambles when not dark() "The Shambles: a steep lane of butchers' shops with their shutters down for counters, blood in the gutters, flies, drovers' beasts in hurdle pens at the bottom, and at the top a cart waiting to take the day's leavings over the bridge to the tan-yards.".
  Observe shambles_night at shambles when dark() "The Shambles at night: shutters, a smell, cattle shifting in the pens.".
  Person kemp "Saul Kemp" at shambles {
    Role "a butcher, master of the Shambles". Ancestry human. Peaceable. Pronouns he. Manner jovial.
    Greets "Saul Kemp wipes a cleaver on his apron and looks you up and down, the way he looks at a beast in the pens, for the weight.".
  }
  Person jack_kemp "Jack Kemp" at shambles {
    Role "the butcher's boy, who drives the offal cart". Ancestry human. Peaceable. Pronouns he. Manner cheerful.
    Greets "The butcher's boy looks up from a pie. 'Seven and three,' he says. 'Tan-yards. Toll-free. Ask anybody.'".
  }
  Discovery offal_privilege "The Liberty's offal cart goes over the bridge from the Shambles to the tan-yards twice a day, at seven in the morning and three in the afternoon, toll-free by the Liberty's ancient privilege, and nobody at the chain has ever looked in it." {
    Known by kemp, jack_kemp, pinch, abbess.
  }
  Topic kemp_cart with kemp "Ask Saul Kemp about the offal cart" when true once {
    Says "'The Liberty's cart.' He grins. 'Older than the bridge, the privilege. The tan-yards have the Shambles' leavings free, and the cart goes over free, twice a day, my Jack driving. Nobody looks in it.' He sniffs. 'Nobody wants to.' He looks at you with sudden interest. 'Why?'".
    On discuss { Assert knows(actor, offal_privilege). }
  }
  Relation kempAgrees(group). Relation boyBribed(group).
  Topic kemp_ask with kemp "Ask Saul Kemp to carry three dead men over the bridge in tomorrow's offal" when knows(actor, offal_privilege) and (hideFor(kemp) or homecomer(actor)) and not kempAgrees(actor) once {
    Says "He puts the cleaver down. 'Wat Pardoe bought his Christmas goose off me thirty years,' he says. 'Under the offal, where nobody'll look, and I'll drive it myself, not the boy.' He picks the cleaver up again. 'Seven or three. Have them here before.'".
    On discuss { Assert kempAgrees(actor). }
  }
  Action bribe_jack(actor: group, site: place) "Pay the butcher's boy three coin to carry something to the tan-yards and not look at it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, shambles) and at(jack_kemp, shambles)
      and knows(actor, offal_privilege) and not boyBribed(actor) and not kempAgrees(actor) and quantity(actor, gold) >= 3.
    Time 2 minutes.
    On success { Decrease quantity(actor, gold) by 3. Assert boyBribed(actor). }
    Result "Jack Kemp takes the coins and bites one. 'Not look at what?' he says, and winks, which is not reassuring.".
  }
  // The cart: what is laid in it goes over with it, at seven and at three.
  Thing offal_cart "the offal cart" at shambles {
    Holds.
    State waiting "The Liberty's offal cart: a tumbril with high sides, loaded to the brim with the Shambles' leavings under a dripping tarpaulin.".
  }
  Initially Assert state(offal_cart, waiting).
  Relation inCart(entity). Relation cartFound(place).
  Action lay_in_cart(actor: group, bearer: member, body: entity, site: place) "Lay {body} in the offal cart, under the tarpaulin" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, shambles) and at(offal_cart, shambles)
      and memberOf(bearer, actor) and bearing(bearer, body) and (kempAgrees(actor) or boyBribed(actor)) and not dark().
    Time 3 minutes.
    On success { Retract bearing(bearer, body). Assert inCart(body). }
    Result "You lay {body} in the bottom of the tumbril, and the leavings of the Shambles go back over him, and the tarpaulin over that. It is the worst thing you have ever done, and the most necessary.".
  }
  Rule cart_goes when (hour(clock) == 7 or hour(clock) == 15) and at(offal_cart, shambles) and not cartGone(offal_cart) { Assert cartGone(offal_cart). Retract at(offal_cart, shambles). Assert at(offal_cart, tanyards). }
  Rule cart_back when (hour(clock) == 8 or hour(clock) == 16) and cartGone(offal_cart) { Retract cartGone(offal_cart). Retract at(offal_cart, tanyards). Assert at(offal_cart, shambles). }
  Relation cartGone(entity).
  // The boy, bribed but not his father's, talks: the riders look in the cart at the chain.
  Rule boy_talks when cartGone(offal_cart) and inCart(?b) and boyBribed(party) and not kempAgrees(party) and not cartFound(wray) says "Word comes back over the bridge: at the chain the riders stopped the offal cart, because the butcher's boy had told them in the Nine Wheels there was something in it, and pulled back the tarpaulin, and found the dead." {
    Assert cartFound(wray). Retract inCart(wat_dead). Retract inCart(dunstan_dead). Retract inCart(joss_dead). Assert state(rail, hanging).
    Assert at(wat_dead, limbo). Assert at(dunstan_dead, limbo).
    Assert at(joss_dead, limbo). }
  // Unloaded at the tan-yards, where the cart goes.
  Rule cart_unloads when cartGone(offal_cart) and inCart(?b) and not cartFound(wray) { Retract inCart(?b). Assert at(?b, tanyards). }

  // Ham Ostler's beasts, and the toll on them.
  Person ham "Ham Ostler" at shambles {
    Role "a drover from the fells, in a smock and a hat with a curlew feather". Ancestry human. Calling ranger. Level 2. Peaceable. Pronouns he. Manner cheerful.
    Greets "Ham Ostler leans on the hurdles with his chin on his crook. 'Sixty head,' he says. 'Sixty pennies. That's a cow.'".
  }
  Topic ham_toll with ham "Ask Ham Ostler about the toll on his beasts" when true once {
    Says "'A penny a head to put my beasts over a bridge they've been going over since before the Company's grandfathers were breeched.' He spits. 'Sixty head is five shillings. I sell them at the Liberty fair, Michaelmas, over the water, and the Company takes five shillings before I've sold a hoof.' He grins. 'So I'll not pay it. My leader knows the ford, and goes round the Step, where the Bargeman lies, the way her mother did. Small hours of the second night, when Dunch's mills up at Wrayholme have the river penned to fill their ponds, I'll take them down under the arches and over, and Pinch can rule on that.' He looks at you. 'You can come, if you like. It's a sight. Most folk have forgot the ford's there.'".
    On discuss { Assert knows(actor, ham_drive). Assert knows(actor, vigil_ford). }
  }
  Discovery ham_drive "Ham Ostler will drive his sixty head over the old ford under the bridge in the small hours of the second night, two in the morning, when the mills upstream have the river penned, and says anyone may come.".
}

data/adventures/wrayford/night.kyr:
Module wrayford "The Third Night" {
  // ── Up to the leads ───────────────────────────────────────────────────────────────────────────────────────────────
  // The gate-ward's stair is locked; Gault has the key on his belt. A thief picks it, or lifts the key at the Nine
  // Wheels; a climber goes up the pier face from the bank; by day Gault will let a mourner up to look.
  Thing gate_door "the gate-ward's door" on gate_stair {
    State locked blocking "The gate-ward's door into the tower is shut and locked.".
    State open "The gate-ward's door stands unlocked.".
    Change pick "Pick the lock of the gate-ward's door" from locked to open needing lockwork.
    Change unlock "Unlock the gate-ward's door with Gault's key" from locked to open needing gate_key.
  }
  Initially Assert state(gate_door, locked). Initially Assert keyholder(gault, gate_door).
  Kind gate_key_kind "the gate-ward's key" is gear worth 0 weighing 0
    described "A long iron key on a loop of leather, warm from a sergeant's belt.".
  Item gate_key "the gate-ward's key" is gate_key_kind at limbo owned by gault.
  Rule door_relocks when hour(clock) == 8 and state(gate_door, open) and not takenDown(wray) { Assert state(gate_door, locked). }
  Action lift_key(actor: group, recipient: member, site: place) "Lift the gate-ward's key off Gault's belt while he is at the jug" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wheels_taproom) and at(gault, wheels_taproom)
      and capable(actor, stealth) and memberOf(recipient, actor) and not keyLifted(actor) and not triedKey(actor) and gaultSat(actor).
    Time 1.
    Resolve check(actor, stealth, dc_hard).
    On success { Assert keyLifted(actor). }
    On failure { Assert triedKey(actor). Assert hostile(gault, actor). }
    Result "On his third jug Gault leans back to laugh at something, and the loop of leather comes off the buckle into your hand as easy as a ripe plum.".
    Otherwise "His hand drops onto yours on his belt and stays there. He does not even turn his head. 'No,' he says.".
  }
  Relation keyLifted(group). Relation triedKey(group).
  Rule key_given when keyLifted(party) and at(gate_key, limbo) and memberOf(?m, party) { Retract at(gate_key, limbo). Assert at(gate_key, wheels_taproom). Assert lends(gault, gate_key, party). }
  Rule key_missed when keyLifted(party) and hour(clock) == 8 and not spread(key_missed_fact) says "Word goes round in the morning that the sergeant lost his key in the Nine Wheels, and has had the lock of the gate-ward's door changed, and is in a filthy temper." { Assert spread(key_missed_fact). Retract lends(gault, gate_key, party). }
  Entity key_missed_fact: fact "Gault's key missed".
  // By day, a mourner may go up and look, with the sergeant's leave.
  Relation gaultLets(group).
  Action ask_up(actor: group, site: place) "Ask Sergeant Gault to let you up on the leads to look at them" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gate_road) and not dark() and stillHanging()
      and not gaultLets(actor) and not hostile(gault, actor).
    Time 2 minutes.
    On success { Assert gaultLets(actor). Retract at(actor, gate_road). Assert at(actor, gate_leads). }
    Result "Gault looks down at you over the parapet for a while. Then he comes down and unlocks the door himself. 'Look,' he says. 'Don't touch.' He stands at your shoulder the whole time.".
  }
  Rule gault_walks_down when gaultLets(party) and not at(party, gate_leads) { Retract gaultLets(party). }
  Action go_down_leads(actor: group, site: place) "Go back down the stair with the sergeant" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gate_leads) and gaultLets(actor).
    Time 2 minutes.
    On success { Retract gaultLets(actor). Retract at(actor, gate_leads). Assert at(actor, gate_road). }
    Result "Gault walks you down and locks the door behind you.".
  }
  // With the sergeant at your shoulder, the riders do not take it amiss that you stand at the rail.
  Rule leave_keeps_peace when gaultLets(party) and not riderPeace(riders) { Assert riderPeace(riders). }
  Rule leave_peace_ends when not gaultLets(party) and riderPeace(riders) and not riderPeaceBought(riders) { Retract riderPeace(riders). }
  Relation riderPeaceBought(group).
  Observe leads_sacking at gate_leads when stillHanging() and not dark() "Close to, the sacking is old grain sacks, stitched. The boots below it are a carter's big boots, a pair mended with wire, and a boy's with new laces. The boy's hands are tied in front of him with cord. There is nothing on them. No ring.".

  // ── The dead, borne ───────────────────────────────────────────────────────────────────────────────────────────────
  Action take_up(actor: group, bearer: member, body: entity, site: place) "Have {bearer} take up {body}" {
    Description "Over the shoulder. Whoever bears the dead goes at half pace.".
    Requires able(actor) and company(actor) and at(actor, site) and memberOf(bearer, actor) and awake(bearer)
      and deadBody(body) and at(body, site) and not borne(body) and not buried(body) and not bearing(bearer, ?o) and not inCart(body).
    Time 1 minute.
    On success { Assert bearing(bearer, body). }
    Result "{bearer} gets {body} up over one shoulder, and stands, and finds the weight.".
  }
  Action set_down(actor: group, bearer: member, body: entity, site: place) "Have {bearer} set {body} down" {
    Requires able(actor) and company(actor) and at(actor, site) and memberOf(bearer, actor) and bearing(bearer, body).
    Time 1 minute.
    On success { Retract bearing(bearer, body). }
    Result "{bearer} sets {body} down, carefully.".
  }
  // Lowered on a rope from the rail to the bank under the first arch: anyone with a rope can do it, and come down after
  // by the pier face.
  Action lower_to_bank(actor: group, site: place) "Lower the three on a rope from the rail to the bank under the first arch" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gate_leads) and holding(actor, rope)
      and at(wat_dead, gate_leads) and at(dunstan_dead, gate_leads) and at(joss_dead, gate_leads)
      and not borne(wat_dead) and not borne(dunstan_dead) and not borne(joss_dead).
    Time 2.
    On success { Retract at(wat_dead, gate_leads). Assert at(wat_dead, under_arches). Retract at(dunstan_dead, gate_leads). Assert at(dunstan_dead, under_arches).
      Retract at(joss_dead, gate_leads). Assert at(joss_dead, under_arches). Assert loweredBank(wray). }
    Result "A loop under each one's arms, and the rope over the coping, and down, slowly, with your feet braced against the parapet, the weight turning against the stone of the pier as it goes, until it goes slack on the bank below. Three times. Your hands are burnt raw by the third.".
  }
  Relation loweredBank(place).
  // Into Dorcas's boat under the arch, at the hour she named: the three, and the company after them on the rope, and
  // she pulls for the Acre steps.
  Action lower_to_boat(actor: group, site: place) "Lower the three into Dorcas Mudd's boat, go down after them, and let her pull for the Acre steps" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gate_leads) and boatArranged(actor) and lowWater()
      and not boatGone(actor) and at(wat_dead, gate_leads) and at(dunstan_dead, gate_leads) and at(joss_dead, gate_leads)
      and not borne(wat_dead) and not borne(dunstan_dead) and not borne(joss_dead).
    Time 3.
    On success { Assert boatGone(actor). Retract at(actor, gate_leads). Assert at(actor, south_stair).
      Retract at(wat_dead, gate_leads). Assert at(wat_dead, south_stair). Retract at(dunstan_dead, gate_leads). Assert at(dunstan_dead, south_stair).
      Retract at(joss_dead, gate_leads). Assert at(joss_dead, south_stair). Assert boatCrossed(wray). }
    Result "Dorcas has a rope ready, thrown up from the boat with a stone on the end, and you make it fast and lower them down to her one at a time, and she takes each one into the boat as if it were a sleeping child. Then you go down the rope after them, burning your hands, into the bottom of the boat among the three, and she pushes off the pier with an oar, and the river takes you. She does not row for some way. She lets the Wray carry you down under the arches in the dark, and then she pulls, long and slow, across to the Acre steps, and nobody on the bridge sees anything at all. 'Whatever's on the Wray between the stairs,' she says, very low, as the boat grounds, 'is mine.'".
  }
  Relation boatCrossed(place).

  // ── Burial ────────────────────────────────────────────────────────────────────────────────────────────────────────
  Relation buriedByNight(place). Relation buriedLawfully(place). Relation ritesAtGrave(place).
  Action bury(actor: group, body: entity, site: place) "Lay {body} in the earth, and fill the grave" {
    Description "Half an hour, with the spade, when the grave is dug.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wades_acre) and deadBody(body) and at(body, wades_acre)
      and not borne(body) and not buried(body) and state(graves, dug).
    Time 3.
    On success { Assert buried(body). Retract at(body, wades_acre). Assert at(body, limbo). }
    Result "You lay {body} in the grave by the church door, in his sacking, and fill it in, and tread it down, and lay the turf back. There is no stone. There will be.".
  }
  Rule all_buried when buried(wat_dead) and buried(dunstan_dead) and buried(joss_dead) and not buriedLawfully(wray) and not buriedByNight(wray) and takenDown(wray) { Assert buriedByNight(wray). }
  // Whoever is still lying by the church door at the end of his day, Corbin buries, without being asked: he said he would dig
  // when they were down.
  Rule corbin_buries when deadBody(?b) and at(?b, wades_acre) and not borne(?b) and not buried(?b) and state(graves, dug)
    and corbinWillDig(wray) and not corbinResigned(corbin) and not releaseUnderway(wray) and hour(clock) >= 19 and hour(clock) < 21
    and not at(party, wades_acre) and not bearingAny(party) says "Word comes over the water: at the end of the day old Corbin found {?b} lying by the church door in his sacking, and stood over him a while with his pipe, and then buried him, properly, without being asked." {
    Assert buried(?b). Assert at(?b, limbo). }
  // Whoever is left lying anywhere else, the reeve's men find in the morning.
  Rule dead_found when deadBody(?b) and not buried(?b) and not borne(?b) and not inCart(?b) and state(rail, cut) and not releaseUnderway(wray) and hour(clock) >= 8
    and hour(clock) < 20 and at(?b, ?p) and not inLiberty(?p) and not at(?b, limbo) and not at(?b, reeve_yard) says "Word goes round: the reeve's men found {?b} in the morning where he had been left, and carried him up to the Guildhall yard under a sheet, to wait for the captain." {
    Assert at(?b, reeve_yard). }
  Rule grave_rites at wades_acre when buriedByNight(wray) and capable(party, rites) and not ritesAtGrave(wray) says "Over the three new graves, in the dark, you say the office of the dead, the old words, all of them. It is the first time they have been said for these three, and the river says something under them." { Assert ritesAtGrave(wray). }
  Rule wat_coat_left when buriedByNight(wray) and homecomer(party) and not coatGiven(maudie) { Assert coatGiven(maudie). }
  Measure buriedOn(place). Relation burialDated(place).
  Rule burial_dated when buried(wat_dead) and buried(dunstan_dead) and buried(joss_dead) and not burialDated(wray) { Assert burialDated(wray). Set buriedOn(wray) to dayN(wray). }
  Observe acre_new_graves at wades_acre when burialDated(wray) and dayN(wray) == buriedOn(wray) and hour(clock) < 12 "By the church door, three new graves, the turf laid back and trodden, with no stones yet.".
  Observe acre_graves at wades_acre when burialDated(wray) and (dayN(wray) > buriedOn(wray) or hour(clock) >= 12) and not dark() "By the church door, three new graves, the turf laid back, with no stones yet. Someone has put a tuft of wool on one, and a carter's whip on another, and on the third a pie.".

  // ── The reckoning at dawn ─────────────────────────────────────────────────────────────────────────────────────────
  // Taken down without leave, the dead are missed at first light, and the reeve must have someone for it before the
  // captain does. Whoever was seen; or whoever gives themselves up; or Hal, who has his own reasons; or Kit Pardoe.
  Relation reckoned(place). Relation arrestedParty(group). Relation halTakesBlame(group). Relation kitBlamed(group).
  Relation gaveSelfUp(group). Relation fledToLiberty(group).
  // The whole city carrying its dead over the bridge in daylight is not a thing the reeve can answer by taking one man.
  Query unlawfulDown() means takenDown(wray) and not releaseUnderway(wray).
  Relation lawfulRelease(place).
  Action give_self_up(actor: group, site: place) "Tell the reeve it was you who cut them down" {
    Grave "He will have to take you for it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(hulme, site) and unlawfulDown() and not reckoned(wray) and not dark().
    Time 1.
    On success { Assert gaveSelfUp(actor). Assert arrestedParty(actor). Assert reckoned(wray). Assert at(actor, guild_cellar). Assert heldInCellar(actor). }
    Result "Simon Hulme hears you out with his eyes shut. 'I know,' he says at last. 'I knew when I heard. Who else.' He calls his constable. At the door of the cellar he puts his hand on your shoulder, once, and takes it away.".
  }
  // Kit taken for what you did: you may take his place.
  Action free_kit(actor: group, site: place) "Tell the reeve it was you who cut them down, not Kit, and that he is to let your brother go" {
    Grave "He will have to take you for it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(hulme, site) and kitBlamed(kit) and kitTaken(kit) and not gaveSelfUp(actor) and homecomer(actor) and not dark().
    Time 1.
    On success { Assert gaveSelfUp(actor). Assert arrestedParty(actor). Retract kitBlamed(kit). Retract kitTaken(kit). Assert at(kit, carters_yards). Assert kitStoodDown(kit). Increase kitTrust(kit) by 2.
      Assert at(actor, guild_cellar). Assert heldInCellar(actor). }
    Result "Simon Hulme looks at you for a long time across the desk. 'I know,' he says. 'I knew it was you before he said a word, and so did he, and he said nothing, which is your father all over.' He calls the constable. Kit passes you on the cellar stair coming up as you go down, and stops, and you do not let him say anything.".
  }
  Action free_kit_stranger(actor: group, site: place) "Tell the reeve it was you who cut them down, and that Kit Pardoe had nothing to do with it" {
    Grave "He will have to take you for it.".
    Requires able(actor) and company(actor) and at(actor, site) and at(hulme, site) and kitBlamed(kit) and kitTaken(kit) and not gaveSelfUp(actor) and stranger(actor) and not dark().
    Time 1.
    On success { Assert gaveSelfUp(actor). Assert arrestedParty(actor). Retract kitBlamed(kit). Retract kitTaken(kit). Assert at(kit, carters_yards). Assert kitStoodDown(kit). Increase kitTrust(kit) by 2.
      Assert at(actor, guild_cellar). Assert heldInCellar(actor). }
    Result "The reeve looks at you, a stranger, for a long time. 'Why?' he asks. You tell him. He writes it down in his own hand, not his son's. 'Wrayford will owe you for that,' he says, 'and will not know it,' and calls the constable.".
  }
  Rule dawn_reckoning when unlawfulDown() and hour(clock) >= 7 and hour(clock) < 9 and not reckoned(wray) {
    Assert reckoned(wray). Assert reckoningDue(wray). }
  Relation reckoningDue(place).
  // In the Liberty, with the Abbess's word, the reeve cannot reach the one he would take.
  Rule reckoned_sanctuary when reckoningDue(wray) and seenAtRail(party) and sanctuary(party) and at(party, ?p) and inLiberty(?p) says "The reeve's constable comes as far as the post at the foot of the drawbridge with a paper, and stops there, and reads it out to the Liberty at large, and goes back. Within the hour a letter crosses from the reeve to the Abbess. Within two, the Abbess has had it framed." {
    Retract reckoningDue(wray). Assert fledToLiberty(party). }
  Relation libertyPlace(place).
  Initially Assert libertyPlace(overbridge_street). Initially Assert libertyPlace(south_stair). Initially Assert libertyPlace(nave).
  Initially Assert libertyPlace(wades_acre). Initially Assert libertyPlace(abbess_court). Initially Assert libertyPlace(ferry_taproom).
  Initially Assert libertyPlace(tanyards). Initially Assert libertyPlace(bear_garden).
  Query inLiberty(p: place) means libertyPlace(p).
  Rule reckoned_seen when reckoningDue(wray) and seenAtRail(party) and not heldInCellar(party) says "At eight the reeve's constable comes for you, with two of the riders, and they are not rough about it, and they take you to the Guildhall cellar." {
    Retract reckoningDue(wray). Assert arrestedParty(party). Assert at(party, guild_cellar). Assert heldInCellar(party). }
  Rule reckoned_hal when reckoningDue(wray) and not seenAtRail(party) and halKept(hal) and halSat(party) and not halHurt(hal) says "In the morning Hal Hulme goes to his father's court before it sits, and says in front of the constable and the clerk and the riders' sergeant that he cut the three down himself, in the night, alone. His father looks at him for a long time, and then has him taken to the cellar. Nobody in Wrayford believes it, and nobody says so." {
    Retract reckoningDue(wray). Assert halTakesBlame(hal). Assert halAway(hal). Assert at(hal, guild_cellar). }
  Rule reckoned_dorcas when reckoningDue(wray) and not kitTaken(kit) and not seenAtRail(party) and boatCrossed(wray) and not (halKept(hal) and halSat(party)) says "The reeve's men go to the ferry-stage, because everybody knows, and Dorcas Mudd stands on her jetty with her oar and tells them, for the whole Wharf to hear, that whatever was on the Wray between the stairs last night was hers by charter, and is landed now, in the Liberty, and if the reeve wants it he can apply to the Abbess. The constable writes it down. Then he goes and takes Kit Pardoe from the yards instead, because somebody has to be taken." {
    Retract reckoningDue(wray). Assert kitBlamed(kit). Assert kitTaken(kit). Assert at(kit, guild_cellar). }
  // With Wat's son already in the cellar, the reeve's men need look no further.
  Rule reckoned_held when reckoningDue(wray) and kitTaken(kit) and not seenAtRail(party) and not (halKept(hal) and halSat(party)) says "In the morning the reeve's men go down to the Guildhall cellar, where they have Kit Pardoe already, and write his name against the cutting-down as well, since it saves going anywhere else." {
    Retract reckoningDue(wray). Assert kitBlamed(kit). }
  Rule reckoned_kit when reckoningDue(wray) and not kitTaken(kit) and not seenAtRail(party) and not boatCrossed(wray) and not (halKept(hal) and halSat(party)) and not travelsWith(kit, party) says "In the morning the reeve's men take Kit Pardoe from the yards, because he is Wat's son and the city knows what it would have done in his place, and he does not deny it, which he could have, and goes with them to the cellar with his head up." {
    Retract reckoningDue(wray). Assert kitBlamed(kit). Assert kitTaken(kit). Assert at(kit, guild_cellar). }
  Rule reckoned_none when reckoningDue(wray) and not seenAtRail(party) and not boatCrossed(wray) and not (halKept(hal) and halSat(party)) and travelsWith(kit, party) says "In the morning the reeve's men come to Wain Row looking for Kit Pardoe, and do not find him, and go away again, and the reeve writes in his book that persons unknown took down the dead." {
    Retract reckoningDue(wray). Assert unknownHands(wray). }
  Relation unknownHands(place).

  // ── The third night: Maudie ───────────────────────────────────────────────────────────────────────────────────────
  Relation maudieTaken(group). Relation maudieHeld(group). Relation maudieGone(group).
  Action hold_maudie(actor: group, site: place) "Keep your mother at home tonight, whatever she says" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pardoe_kitchen) and at(maudie, pardoe_kitchen)
      and homecomer(actor) and (thirdNight() or thirdDay() and hour(clock) >= 18) and stillHanging() and not maudieHeld(maudie).
    Time 1.
    On success { Assert maudieHeld(maudie). }
    Result "She has the bread knife on the table in front of her. You sit down across from her, between her and the door, and do not move. For a long time she looks at you. Then she says, 'You'd stop me.' You say nothing. 'You'd stop me, and let him hang there.' She puts both hands flat on the table either side of the knife and looks at them. 'All right,' she says at last. 'All right. You've your father's look. I'll not forgive you for it.' And she does not go.".
  }
  Action stop_maudie(actor: group, site: place) "Stand in Maudie Pardoe's way, and do not move" {
    Requires able(actor) and company(actor) and at(actor, site) and at(maudie, site) and stranger(actor) and maudieWelcomes(actor)
      and (thirdNight() or thirdDay() and hour(clock) >= 18) and stillHanging() and not maudieHeld(maudie).
    Time 1.
    On success { Assert maudieHeld(maudie). }
    Result "She looks at you as if you were a gate. Then she sits down on the settle with the knife across her knees. 'It's not your business,' she says. 'None of it's your business.' But she does not go.".
  }
  // At two in the morning of the fourth day, if he is still on the rail, she goes.
  Rule maudie_goes when thirdDay() and hour(clock) >= 2 and hour(clock) < 6 and stillHanging() and not maudieHeld(maudie) and not promisedMaudie(party) and not maudieGone(maudie) {
    Assert maudieGone(maudie). Assert at(maudie, gate_road). }
  Rule maudie_promised_waits when thirdDay() and hour(clock) >= 2 and hour(clock) < 6 and stillHanging() and promisedMaudie(party) and not maudieHeld(maudie) { Assert maudieHeld(maudie). }
  Observe maudie_at_gate at gate_road when maudieGone(maudie) and not maudieTaken(maudie) "Maudie Pardoe is at the gate-ward's door in the dark with the bread knife, trying the latch, and up on the leads the captain's riders have heard her, and are coming down.".
  Rule maudie_taken when maudieGone(maudie) and (thirdDay() and hour(clock) >= 3 and hour(clock) < 6 or fourthDay()) and not maudieTaken(maudie) says "Word runs through Northgate in the small hours, door to door: Maudie Pardoe went up to the gatehouse with her bread knife for the cords, and the captain's riders took her at the gate-ward's door, and she is in the Guildhall cellar, and the captain has been woken." {
    Assert maudieTaken(maudie). Assert at(maudie, guild_cellar). }
  // Going with her: she will not be stopped, but she need not go alone.
  Action go_with_maudie(actor: group, site: place) "Go up to the gatehouse with her" {
    Requires able(actor) and company(actor) and at(actor, site) and at(maudie, site) and at(actor, gate_road) and maudieGone(maudie) and not maudieTaken(maudie).
    Time 1.
    On success { Assert maudieTaken(maudie). Assert arrestedParty(actor). Assert at(maudie, guild_cellar).
      Assert at(actor, guild_cellar). Assert heldInCellar(actor). }
    Result "You go up with her, because she is going, and you will not let her go alone. The captain's riders take you both at the head of the stair, not roughly, and she does not let go of your hand all the way down.".
  }
  // Kept in the cellar, the company is let out at the verdict, one way or another (captain.kyr).
}

data/adventures/wrayford/northgate.kyr:
Module wrayford "The Third Night" {
  // ── The drove road ────────────────────────────────────────────────────────────────────────────────────────────────
  Observe drove_home at drove_road when homecomer(party) and not visitedBefore(drove_road) and not dark() "You come over the last rise of the fell road and there it is, all at once, the way it always was: Wrayford in the bottom of the vale, smoke and red roofs, the brown river, and the bridge going over on its nineteen arches to Overbridge and the church tower on the far bank. Three years. Your mother's letter is in your coat, soft with handling: your father went out on the road with the cart, it says, and did not come home. At the near end of the bridge the gatehouse stands up square and red over the first arch, and something hangs off the side of it toward the water that you cannot make out from here, three somethings, and you find you have stopped walking.".
  Observe drove_stranger at drove_road when stranger(party) and not visitedBefore(drove_road) and not dark() "The drove road comes over the last rise of the fells and drops into the vale of the Wray, and there is Wrayford: smoke, red roofs, a brown river, and a long bridge on many arches going over to a second town on the far bank with a church tower. Cattle are coming down the road behind you, and the drovers are talking about the toll. At the near end of the bridge a square red gatehouse stands over the first arch, and from the side of it, toward the water, three shapes hang that are too far off to make out and too still to be washing.".
  Observe drove_again at drove_road when visitedBefore(drove_road) and not dark() "The drove road, where it comes over the last rise above Wrayford: the city below, the bridge, the gatehouse.".
  Observe drove_night at drove_road when dark() "The drove road above Wrayford at night: a scatter of lights in the vale, the line of lamps along the bridge, and the river only a sound.".

  Observe northgate_scene at northgate when not dark() and not visitedBefore(northgate) "Northgate is where the drove roads come into the city: a wide street of yards and stables and inns, horse-dung and straw and the smell of hot iron from the farrier's, carts drawn up in rows with their shafts on the ground. Nobody is loading anything. The carters are standing about in twos and threes in the yard gates with their hands in their pockets, not talking, and the drovers bringing cattle down to the Shambles go past them very politely.".
  Observe northgate_again at northgate when not dark() and visitedBefore(northgate) "Northgate: the yards, the stables, the carters standing in the gateways.".
  Observe northgate_night at northgate when dark() "Northgate at night: the Nine Wheels lit, and every yard gate shut.".

  // ── The Nine Wheels ───────────────────────────────────────────────────────────────────────────────────────────────
  Observe wheels_scene at wheels_taproom when not visitedBefore(wheels_taproom) "The carters' inn: a long low room, smoke, a fire with a kettle, benches worn into the shape of carters. Nailed to the beams overhead for a ceiling are nine cart-wheels, one for every carter the fell road has killed since the inn was built, the oldest black with a century of smoke and the newest with its paint still showing. Over the settle by the fire someone has hung a black ribbon on a nail, and under it nobody sits.".
  Observe wheels_again at wheels_taproom when visitedBefore(wheels_taproom) "The Nine Wheels: wheels in the beams, the fire, the black ribbon over the empty settle.".
  Observe wheels_gault at wheels_taproom when at(gault, wheels_taproom) "In the corner by the door, alone at a table with a jug, Sergeant Gault in his buff coat. The carters drink with their backs to him. He drinks with his back to the wall.".
  Person pell "Pell Saxby" at wheels_taproom {
    Role "who keeps the Nine Wheels". Ancestry human. Profession innkeeper. Peaceable. Pronouns she. Manner compassionate.
    Greets "Pell Saxby wipes her hands on her apron and looks you over. 'Bed, beer or bread,' she says, and then, because she is honest: 'The bread's Maudie Pardoe's. She's sent us forty loaves since Tuesday. I can't sell it and I can't stop her.'".
    Sells rations for 2 coin from 8.
    Sells rope for 1 coin from 2.
  }
  Topic pell_sergeant with pell "Ask Pell why she serves the sergeant" when true once {
    Says "'Because refusing him would be politics, and I've never had any.' She draws a beer and does not look at the corner. 'He hanged three men I've known since they were boys. He comes in at seven and drinks till ten and pays in the lord's silver, and if I put him out he drinks on the leads and his men with him and they're the worse for it at the rail.' She sets the beer down hard. 'This way I know where he is. And I know what he's drinking. And when he's had his three jugs he talks, if anybody's daft enough to sit with him.'".
    On discuss { Assert knows(actor, gault_talks). }
  }
  Discovery gault_talks "Sergeant Gault drinks at the Nine Wheels from seven until ten, three jugs, and after the third he talks to whoever sits with him.".
  Topic pell_news with pell "Ask Pell what is being said" when true {
    Says "'What isn't.' She leans on the bar. 'That the Company's printing Wat's confession, which Wat never said in his life, and selling it at a penny. That old Corbin won't dig and Gidley's aunt's been laid out since Tuesday and Mistress Gidley's beside herself. That the captain comes the day after tomorrow with twenty riders, and that she's Sefton's girl, old Ralf Sefton's, and the old ones in here went quiet when they heard the name, and won't say why. That the young ones,' and she does not look at the young carters by the fire, 'are going to do something about it, and they'll do it as stupid as they know how.'".
  }
  Topic pell_hire with pell "Ask Pell whether she has washing that wants doing" when knows(actor, win_proud) and not washingGiven(pell) once {
    Says "'Washing.' She looks at you. 'I send my sheets up to the laundry on the Hill, like everyone with sheets.' Then she sees what you mean, and her face changes. 'Win Fenner.' She is already pulling a bundle out from under the bar. 'Sheets, the lot, and the bolster-cases. Tell her it's a shilling, it's always been a shilling, and the Hill's been robbing me.' She pushes them at you. 'And don't tell her I said so.'".
    On discuss { Assert washingGiven(pell). Assert knows(actor, washing_given). }
  }
  Relation washingGiven(group).
  Discovery washing_given "Pell Saxby has given you the Nine Wheels' sheets, for Win Fenner to wash at a shilling.".
  Kind washing_kind "a bundle of the Nine Wheels' sheets" is gear worth 0 weighing 4
    described "Two pairs of sheets and the bolster-cases, knotted up in a tablecloth that has seen better inns.".
  Item wheels_washing "the Nine Wheels' sheets" is washing_kind at wheels_taproom hidden until washing_given.

  // Gault, after his third jug.
  Relation gaultSat(group). Relation letterSeen(group).
  Action sit_gault(actor: group, site: place) "Sit down with Sergeant Gault and buy his third jug" {
    Description "Two coin, and the evening, with the man who hanged them.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wheels_taproom) and at(gault, wheels_taproom)
      and not gaultSat(actor) and quantity(actor, gold) >= 2.
    Time 6.
    On success { Assert knows(actor, wade_hymn). Decrease quantity(actor, gold) by 2. Assert gaultSat(actor). }
    Result "He looks at you and the jug and says, 'Suit yourself.' He drinks. He talks about horses, and a woman in Harbury, and the cold on the fell road at four in the morning, and how carters are all the same, and in the end, looking into the jug, how he has hanged eleven men in nineteen years and these were the first who went quiet. 'The big one sang,' he says. 'On the road. Some hymn. Carry me over, something, carry me over.' He looks into the jug. 'Till the rope.'".
  }
  Topic gault_letter with gault "Ask Gault, plainly, as one who has stood a watch, who sent him the letter" when gaultSat(actor) and (craft(actor, craft_arms) or capable(actor, intimidation)) and not letterSeen(actor) once {
    Says "He looks at you for a long time across the jug. 'You've stood a watch,' he says. It is not a question. He reaches into his coat and puts a folded paper on the table between you and does not take his hand off it. 'Midnight. A lad brought it. I don't know the lad.' He lets you read it and then puts it back in his coat. 'Clerk's hand. Gentleman's paper. Your carters don't write like that.'".
    On discuss { Assert letterSeen(actor). Assert knows(actor, letter_read). }
  }
  Action ask_gault_letter(actor: group, site: place) "Ask Gault, as he drinks, whether he kept the letter" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wheels_taproom) and at(gault, wheels_taproom)
      and gaultSat(actor) and not letterSeen(actor) and not triedGault(actor) and knows(actor, word_came).
    Time 1.
    Resolve check(actor, insight, dc_fair).
    On success { Assert letterSeen(actor). Assert knows(actor, letter_read). }
    On failure { Assert triedGault(actor). }
    Result "You watch his hand go to his coat when you ask, and stay there, and you ask again, more quietly, and he takes it out and lays it down. 'Kept it,' he says. 'Kept every warrant I ever had.' He lets you read it.".
    Otherwise "His hand goes to his coat and stays there. 'Drink up,' he says. 'Then go home.'".
  }
  Relation triedGault(group).
  // A thief need not ask: the coat hangs on the back of his chair after the second jug.
  Action lift_letter(actor: group, site: place) "Take the letter out of Gault's coat while he is at the jug" {
    Description "It hangs on the back of his chair. He is not looking.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wheels_taproom) and at(gault, wheels_taproom)
      and capable(actor, stealth) and not letterSeen(actor) and not triedLift(actor) and knows(actor, word_came).
    Time 1.
    Resolve check(actor, stealth, dc_fair).
    On success { Assert letterSeen(actor). Assert knows(actor, letter_read). }
    On failure { Assert triedLift(actor). Assert hostile(gault, actor). }
    Result "Two fingers, a fold of paper, and it is in your sleeve, and you read it in the passage to the yard by the lamp and put it back on your way past, and he never turns round.".
    Otherwise "His hand comes round and closes on your wrist like a door. 'No,' he says. He does not let go for a long time. When he does, he does not look at you again.".
  }
  Relation triedLift(group).
  Discovery letter_read "The letter that sent the riders to the fell road, kept in Sergeant Gault's coat: 'The ringleaders go by the back road to the fells before light, with Pardoe's cart, the red wheels. Take them quietly and there need be no more burning. For the lord's court.' No name. The hand is a clerk's, round and careful, on good paper with the corner torn off where a crest would be.".

  // ── Win Fenner ────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe wash_scene at fenner_copper when true "A wash-house with a copper boiling in the corner and the windows streaming. Lines of other people's shirts. Four children at the table doing nothing very quietly. A woman with red arms is at the copper with a paddle, her back to the door.".
  Person win "Win Fenner" at fenner_copper {
    Role "a laundress, Dunstan Fenner's widow". Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Greets "Win Fenner does not turn round from the copper. 'If it's washing, leave it. If it's pity, you can take it with you.'".
  }
  Discovery win_proud "Win Fenner, Dunstan's widow, has four children and will take no charity from anyone who can be seen giving it: not the parish's bread, not her neighbours'. She takes in washing, and the Hill has stopped sending any." {
    Known by win, pell.
  }
  Relation winHelped(group). Relation winRefused(group). Relation toolsHome(group). Relation winClaims(group).
  Topic win_dunstan with win "Ask Win Fenner about Dunstan" when true once {
    Says "'He went to see the young ones came to no harm.' The paddle goes round. 'Fifty-one years old. He'd done the fells road ten thousand times and he couldn't see a fight without going to stop it.' Round. 'The parish sent bread. I sent it back. The Hill's stopped sending washing; they don't want a felon's widow's hands on their shirts.' Round. 'We'll manage.' Behind her the children do not move.".
    On discuss { Assert knows(actor, win_proud). }
  }
  Topic win_kester with win "Ask Win where her eldest is" when knows(actor, win_proud) once {
    Says "The paddle stops. 'Kester.' She does not turn round. 'He's twelve. He's been taking his father's tools to the pawnshop in Cutler's Lane, one at a time, the good chisels, and bringing back pennies, and telling me he found them.' Her voice does not change. 'I can't stop him, because we have to eat, and I can't let him, because they're his father's, and I can't think which is worse, so I'm doing the washing.'".
    On discuss { Assert knows(actor, tools_pawned). }
  }
  Discovery tools_pawned "Win Fenner's boy Kester has pawned his dead father's chisels, one by one, at the pawnshop in Cutler's Lane.".
  Topic win_shirt with win "Ask Win whose washing she still does" when winHelped(actor) once {
    Says "'The Company's.' She snorts. 'The counting-house linens. They're too mean to change laundress.' She hangs a shirt on the line. 'That collector, Pinch, sent me his shirt the morning after the fire, his good one, and it stank of lamp-oil so I had to boil it twice. A man who keeps a farthing candle in a saucer.' She looks at you over the shirt. 'Funny. I thought so at the time.'".
    On discuss { Assert knows(actor, pinch_shirt). }
  }
  Discovery pinch_shirt "The morning after the fire, Amos Pinch sent Win Fenner his good shirt to wash, stinking of lamp-oil: a man who has never been near a lamp he could avoid.".
  // Three ways to help a proud woman: unseen, as work, or her husband's tools brought home.
  Action leave_bread(actor: group, site: place) "Leave a loaf on Win Fenner's table while her back is to the copper" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, fenner_copper) and at(win, fenner_copper)
      and knows(actor, win_proud) and not winHelped(actor) and not winRefused(actor) and quantity(actor, rations) >= 1.
    Time 2 minutes.
    Resolve check(actor, stealth, dc_fair).
    On success { Decrease quantity(actor, rations) by 1. Assert winHelped(actor). }
    On failure { Assert winRefused(actor). }
    Result "You put it down behind a pile of shirts, where the children can see it and she cannot, and go out while she is lifting the paddle. Through the window you see the eldest girl look at it, and look at her mother's back, and say nothing at all, and cut it.".
    Otherwise "She turns round before your hand is off it. 'Take that away,' she says, very quietly. 'Take it away, and don't come back with it.'".
  }
  Action bring_washing(actor: group, carrier: member, bundle: item, site: place) "Give Win Fenner {bundle} to wash, at a shilling" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, fenner_copper) and at(win, fenner_copper)
      and memberOf(carrier, actor) and ownedItem(bundle, carrier) and itemKind(bundle, washing_kind) and not winHelped(actor)
      and quantity(actor, gold) >= 1.
    Time 2 minutes.
    Resolve drop(bundle, carrier).
    On success { Decrease quantity(actor, gold) by 1. Assert winHelped(actor). }
    Result "She takes the bundle and weighs it in her arms and looks at you hard. 'Pell Saxby's sheets,' she says. 'A shilling.' She takes the coin. 'She used to send them to the Hill.' She puts them in the copper. 'Tell her Thursday.'".
  }
  Kind chisels_kind "Dunstan Fenner's chisels" is gear worth 3 weighing 2
    described "A roll of oiled leather with six chisels in it, the handles dark with a man's hands, the edges kept like razors.".
  Item fenner_chisels "Dunstan Fenner's chisels" is chisels_kind at pawnshop hidden until tools_pawned owned by pratt.
  Action bring_tools(actor: group, carrier: member, roll: item, site: place) "Put {roll} on Win's table" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, fenner_copper) and at(win, fenner_copper)
      and memberOf(carrier, actor) and ownedItem(roll, carrier) and itemKind(roll, chisels_kind) and not toolsHome(win).
    Time 2 minutes.
    Resolve drop(roll, carrier).
    On success { Assert toolsHome(win). Assert winHelped(actor). Assert winClaims(win). }
    Result "She looks at the roll of leather for a long time before she touches it. Then she unrolls it on the table among the children and counts the chisels with one finger, all six, and rolls it up again, and puts it on the high shelf where Kester cannot reach. She does not thank you. She says, 'When they bring him down. Dunstan. I want him in the Acre by the church door, where his mother is,' as if it were a thing you had already agreed between you.".
  }
  Rule win_claims_after when winHelped(party) and not winClaims(win) and knows(party, dead_on_rail) { Assert winClaims(win). }
  // A widow's claim, said aloud: Northgate hears it, and is the angrier and the quieter for it.
  Relation winClaimTold(group).
  Rule win_claim_spreads when winClaims(win) and not winClaimTold(win) and inWrayford() and hour(clock) >= 7 and hour(clock) < 21 says "Word goes round Northgate: Win Fenner went to the Guildhall door with her four children in a row by height and told the reeve's constable to his face that she will have Dunstan in the Acre by the church door, where his mother is, and the constable took his hat off." {
    Assert winClaimTold(win). Increase temper(wray) by 1. }

  // ── The yards ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe yards_scene at carters_yards when not dark() "The carters' yards behind Northgate: wagons up on blocks, wheels stacked against the walls, a forge with the farrier at it. The young carters sit on a dray in the middle of the yard with nothing to do, talking low, and stop when anyone comes in.".
  Observe yards_impounded at carters_yards when not dark() "Three wagon-places along the wall stand empty, swept: where Pardoe's, Fenner's and Wilder's carts stood. The carts are in the Guildhall yard, impounded.".
  Person farrant "Jos Farrant" at carters_yards {
    Role "the Northgate farrier, leather-aproned". Ancestry human. Peaceable. Pronouns he. Manner stoic.
    Greets "Jos Farrant does not stop working the bellows. 'Mind the sparks.'".
  }
  Topic farrant_night with farrant "Ask the farrier where he was on the night of the rising" when true once {
    Says "'At the gate end. Shoeing Ham Ostler's leader, as it happens, because Ham wouldn't pay the toll on her and was going to swim her round by the ford.' The hammer comes down. 'I saw the chain go. I saw the toll-board go in the river. Best thing I've seen this year.' The hammer comes down. 'I saw the fire start. I didn't see who started it. I saw the carts come back off the gate in the press.' He does not look up. 'That's all I saw.'".
  }
  Relation farrantPressed(group).
  Topic farrant_reins with farrant "Ask the farrier who was on the box of Wat Pardoe's cart when it came back off the gate" when knows(actor, tailboard_seen) and not farrantPressed(actor) once {
    Says "The hammer stops. He looks at the iron for a long time, and puts it back in the fire. 'I'll tell you,' he says, 'because you've looked at that cart, I can see it on you, and you'd find out.' He works the bellows. 'The boy. Kit. Wat was at the chain with the old ones. The boy had the reins, and the horse went forward in the press, and he couldn't hold her.' The bellows. 'Then Wat came running and got up and took them off him. That's what I saw.' He looks at you over the fire. 'I've not told the reeve. I'll not tell the reeve. They've hanged the father for it. They'll not get the son off me.'".
    On discuss { Assert farrantPressed(actor). Assert knows(actor, kit_reins). }
  }
  Action read_farrant(actor: group, site: place) "Watch the farrier's face while he says he saw nothing" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, carters_yards) and at(farrant, carters_yards)
      and knows(actor, kit_said_chain) and not farrantPressed(actor) and not knows(actor, kit_reins) and not triedFarrant(actor).
    Time 2 minutes.
    Resolve check(actor, insight, dc_fair).
    On success { Assert farrantPressed(actor). Assert knows(actor, kit_reins). }
    On failure { Assert triedFarrant(actor). }
    Result "When you say Kit's name his hammer misses its stroke, once, and he swears at the iron. You wait. 'All right,' he says at last, low, not looking at you. 'The boy had the reins. Wat came and took them off him. And I've told nobody, and I'll tell nobody, and nor will you if you've any sense.'".
    Otherwise "He goes on hammering. Whatever he saw, his face is not going to tell you.".
  }
  Relation triedFarrant(group).

  // The young carters, and what they mean to do on the second night.
  Person carters "the young carters" at carters_yards {
    Role "half a dozen carters' sons, sitting on a dray". Ancestry human. Calling warrior. Level 1. Numbers 5. Peaceable. Pronouns they. Manner grim.
    Greets "The young carters look at you, and at each other.".
  }
  Rule carters_evening when hour(clock) >= 18 and hour(clock) < 23 and not at(carters, wheels_taproom) and not cartersOut(carters) and not cartersTaken(carters) { Assert at(carters, wheels_taproom). }
  Rule carters_day when (hour(clock) >= 6 and hour(clock) < 18) and not at(carters, carters_yards) and not cartersOut(carters) and not cartersTaken(carters) { Assert at(carters, carters_yards). }
  Relation cartersOut(group). Relation cartersTaken(group).
  Topic carters_night with carters "Ask the young carters about the night of the rising" when true once {
    Says "'We broke the chain,' says the biggest of them, not quietly enough. 'And we threw their board in the river. And we'd do it again.' 'We didn't burn the toll-house,' says another. 'We never burned it.' 'Who cares who burned it,' says the first. 'They hanged Wat for the cart and Dunstan and Joss for nothing. Nothing!' They look at you. 'You'll see,' says the third. 'Tomorrow night. Ask Kit.'".
    On discuss { Assert knows(actor, carters_plan). Assert knows(actor, not_carters_fire). }
  }
  Discovery carters_plan "The young carters mean to do something on the second night, and Kit Pardoe with them." .
  Discovery not_carters_fire "The young carters say they broke the chain and threw the toll-board in the river on the night of the rising, but never burned the toll-house.".

  // Kit's night. What they mean: the Company's counting-house, at midnight, with lamp-oil. Gault is told of it at the
  // Nine Wheels by the Company's clerk, who hears everything, and waits there with two of his riders.
  Discovery kit_plan "At midnight on the second night Kit Pardoe and the young carters mean to burn the Bridge Company's counting-house in the Market, with lamp-oil.".
  Topic kit_plan_told with kit "Ask Kit what he and the others mean to do" when (kitTrusts(actor) or knows(actor, carters_plan)) and not knows(actor, kit_plan) once {
    Says "He looks round to see who is near. 'The counting-house.' Low, and fierce. 'Tomorrow at midnight. The Company's. Where they count the toll and print the lies about Da. Lamp-oil from the yard, and every window.' He is almost smiling. 'Let them hang us for something.'".
    On discuss { Assert knows(actor, kit_plan). }
  }
  Relation kitStoodDown(group). Relation kitTurned(group).
  Query kitPlanning() means knows(party, kit_plan) and not kitStoodDown(kit) and not kitTurned(kit) and not kitTaken(kit).
  Topic kit_down with kit "Tell Kit the counting-house will hang him, and change nothing" when knows(actor, kit_plan) and kitTrusts(actor) and not kitStoodDown(kit) and not kitTurned(kit) and not kitJoined(kit) once {
    Says "'Change nothing.' He says it back as if he were tasting it. 'They'll hang me. And Da'll still be on the rail, and Mam'll still be making bread for nobody.' He looks at the water a long time. 'All right,' he says, and his voice cracks on it like a boy's. 'All right. I'll tell them no.'".
    On discuss { Assert kitStoodDown(kit). Increase kitTrust(kit) by 1. }
  }
  Action argue_kit(actor: group, site: place) "Argue Kit out of the counting-house" {
    Description "He does not trust you. He might listen to reason anyway.".
    Requires able(actor) and company(actor) and at(actor, site) and at(kit, site) and knows(actor, kit_plan)
      and not kitTrusts(actor) and not kitStoodDown(kit) and not kitTurned(kit) and not kitJoined(kit) and not triedKit(actor).
    Time 1.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert kitStoodDown(kit). }
    On failure { Assert triedKit(actor). }
    Result "You tell him what the captain will find if she finds a burned counting-house: a rising, and a reason. He hears you out with his jaw set, and then, without saying you are right, he says he'll tell the others to wait.".
    Otherwise "'You don't know anything,' he says. 'You weren't here.' And goes.".
  }
  Relation triedKit(group).
  Topic kit_turn with kit "Tell Kit that if they must break something, they should sink the Company's new toll-board" when knows(actor, kit_plan) and knows(actor, toll_schedule) and (kitTrusts(actor) or homecomer(actor)) and not kitStoodDown(kit) and not kitTurned(kit) and not kitJoined(kit) once {
    Says "He stares at you. Then, for the first time since you came, he laughs: a real one, that surprises him. 'The board. Again.' He is grinning. 'In the river. Twice in one week. The whole of Wrayford'd laugh till Michaelmas. Pinch'd have to rule from memory.' He sobers. 'And nobody hangs for a board.' He gets up. 'I'll tell them. Midnight, the board, not the counting-house.'".
    On discuss { Assert kitTurned(kit). Increase kitTrust(kit) by 1. }
  }
  Topic kit_join with kit "Tell Kit you'll go with them to the counting-house" when knows(actor, kit_plan) and not kitStoodDown(kit) and not kitTurned(kit) and not kitJoined(kit) once {
    Says "He looks at you a long moment, and then grips your hand, hard. 'Midnight,' he says. 'In the Market. Bring a light.'".
    On discuss { Assert kitJoined(kit). Increase kitTrust(kit) by 1. }
  }
}

data/adventures/wrayford/pardoes.kyr:
Module wrayford "The Third Night" {
  // ── What everyone in Wrayford knows ───────────────────────────────────────────────────────────────────────────────
  Discovery dead_on_rail "Four nights ago the carters rose against the bridge toll, broke the chain and threw the toll-board into the Wray, and the toll-house burned. In the press at the gate the toll-keeper's boy, Ned Hobday, went under a cart. Before dawn the lord's riders took three carters on the back road to the fells, Wat Pardoe, Dunstan Fenner and Joss Wilder, and hanged them from the gatehouse rail under the lord's warrant." {
    Known by maudie, kit, hulme, hal, gault, gidley, pinch, jennet, annis, win, pell, dorcas, corbin, abbess, quoin, ham.
  }
  Discovery decree_known "The reeve's decree is nailed to the gatehouse door: the three are to hang on the rail until the lord's captain comes, at dusk on the third day, so that she finds Wrayford in order. Whoever touches them shall hang beside them." {
    Source decree "the reeve's decree on the gatehouse door" at gate_road readable by party.
    Known by maudie, kit, hulme, hal, gault, gidley, pinch, jennet, dorcas, corbin, abbess.
  }
  Discovery third_night_custom "In Wrayford the dead are watched three nights and buried on the third day. They say one who is not buried by the end of the third night goes looking." {
    Known by maudie, kit, pell, corbin, dorcas, jennet, annis, win.
  }
  Discovery maudie_resolve "Maudie Pardoe will not have her husband out a third night. If he is still on the rail when the third night comes, she will go to the gatehouse herself, with the bread knife, for the cords.".

  // ── The Pardoe house ──────────────────────────────────────────────────────────────────────────────────────────────
  Observe row_scene at wain_row when not dark() and not visitedBefore(wain_row) "Wain Row is a lane of carters' houses, each with its yard and its cart-shed behind, the doors painted the colours carters paint them, red and green and a blue that was once expensive. Four doors along, the Pardoes' is red. Its step has been scrubbed this morning, hard. Two women talking on the next step stop talking when they see you, and go in.".
  Observe row_scene_again at wain_row when not dark() and visitedBefore(wain_row) "Wain Row: cart-sheds, painted doors, the Pardoes' red one with its scrubbed step.".
  Observe row_night at wain_row when dark() "Wain Row in the dark. A lamp in the Pardoes' kitchen, and in no other window.".
  Observe kitchen_home at pardoe_kitchen when homecomer(party) and not visitedBefore(pardoe_kitchen) and at(maudie, pardoe_kitchen) and not verdictGiven(wray) "The kitchen is as it was: the long table, the settle, the bread oven, the hook by the door where your father's coat hangs, which is the first thing you look at and the last thing you will be able to stop looking at. It smells of bread. It always smelled of bread. Your mother is at the table with her sleeves up and flour to the elbow, and she looks at you in the doorway for a long moment, and then goes on kneading.".
  Observe kitchen_strange at pardoe_kitchen when stranger(party) and not visitedBefore(pardoe_kitchen) and at(maudie, pardoe_kitchen) and not verdictGiven(wray) "A carter's kitchen: a long table, a settle, a bread oven, a man's coat on a hook by the door. A woman in her fifties is kneading bread at the table with her sleeves up, and she does not stop when you come in, and she does not ask you to sit.".
  Observe kitchen_again at pardoe_kitchen when visitedBefore(pardoe_kitchen) and not verdictGiven(wray) "The Pardoe kitchen: the table, the oven, the bread proving under a cloth.".
  Observe kitchen_coat at pardoe_kitchen when homecomer(party) and visitedBefore(pardoe_kitchen) and not coatGiven(maudie) "On the hook by the door, Wat Pardoe's coat: brown frieze, the pockets pulled out of shape by thirty years of hands.".
  Observe kitchen_bread at pardoe_kitchen when not verdictGiven(wray) "There is more bread than one woman could eat in a month: loaves on the dresser, on the settle, under cloths on the windowsill. She makes bread when she cannot think.".
  Observe kitchen_bare at pardoe_kitchen when not at(maudie, pardoe_kitchen) and not verdictGiven(wray) and not visitedBefore(pardoe_kitchen) "A carter's kitchen: a long table, a settle, a bread oven, a man's coat on a hook by the door, and nobody in it, and the fire going down.".
  Observe yard_scene at pardoe_yard when not dark() "The yard: the cart-shed with no cart in it, a water-butt, the mounting-block. The cart is in the Guildhall yard, impounded, with the other two. The shed is very clean, as if somebody had swept it for something to do.".
  Observe yard_bramble at pardoe_yard when at(bramble, pardoe_yard) "Bramble lies in the empty cart-shed, in the place where the cart stood, with his chin on his paws.".

  Person maudie "Maudie Pardoe" at pardoe_kitchen {
    Role "a carter's widow of Wain Row". Ancestry human. Peaceable. Pronouns she. Manner stoic.
    Greets "Maudie Pardoe does not stop kneading.".
    Leaves "Maudie Pardoe turns the dough, and pushes it away from her, and does not look up.".
  }
  Relation coatGiven(group). Relation maudieWelcomes(group).
  Measure vigils(group). Measure lastVigil(group).
  Initially Set vigils(maudie) to 0. Initially Set lastVigil(maudie) to 0.

  // Kin.
  Topic maudie_what with maudie "Ask your mother what happened" when homecomer(actor) once {
    Says "'You got the letter, then.' She turns the dough and pushes it away from her with the heels of her hands. 'He went out with the others, the night they broke the chain. He was the oldest of them, he went to see none of the young ones did anything stupid.' Push, turn. 'The riders took him on the back road before light. Him and Dunstan Fenner and Joss Wilder. They hanged them off the gatehouse rail at sunrise and the reeve says they stay there till the lord's captain comes, so she'll see the city's in order.' She stops, with both hands flat in the dough. 'Simon Hulme. Who stood godfather to your brother. He came and told me himself. I'll give him that. He came himself.'".
    On discuss { Assert knows(actor, dead_on_rail). Assert knows(actor, decree_known). }
  }
  Topic maudie_letter with maudie "Ask your mother when she wrote" when homecomer(actor) once {
    Says "'The day the toll went up. A fortnight since.' She does not look up. 'I wrote that he'd gone out with the cart and not come home, because he hadn't, that night, he'd gone up to the fells with a load and the carters were all talking chain and fire, and I thought: if anyone can talk sense into the young ones it's the one who went away. That's what I thought.' She shapes the loaf. 'It took a week to find you. That's not your fault. Don't you start thinking it's your fault. I can see you starting.'".
  }
  // A stranger.
  Topic maudie_stranger with maudie "Ask Maudie Pardoe about her husband" when stranger(actor) once {
    Says "'He's on the bridge,' she says. 'Everybody in Wrayford knows where he is. Go and look at him with the rest of them. It's a penny for the pie-woman and nothing for the looking.' She slaps the dough down. 'You're not from here. You don't owe him anything. Go on.'".
    On discuss { Assert knows(actor, dead_on_rail). }
  }
  Topic maudie_custom with maudie "Ask Maudie about the third night" when knows(actor, dead_on_rail) once {
    Says "'They watch the dead three nights in Wrayford and bury them on the third day. My mother's mother said if you don't, they go looking.' She cuts the dough in two with the edge of her hand. 'I don't believe it. I'm telling you so you'll know I don't believe it.' The other half. 'And I won't have it. He is not going to be out on that rail a third night with the crows at him and that dog under him. If he's there when it comes, I'll go up myself with the bread knife and cut him down, and Simon Hulme can hang me off the rail beside him, and I'd like to see him look at me while he does it.'".
    On discuss { Assert knows(actor, third_night_custom). Assert knows(actor, maudie_resolve). }
  }
  Topic maudie_kit with maudie "Ask your mother about Kit" when homecomer(actor) once {
    Says "'He was at the chain. He came in at dawn with his hands black and hasn't said ten words since. He's at the yards all day doing nothing to the same wheel, and at night he goes off somewhere.' She looks at the door. 'Under the bridge, I'd say. He always went under the bridge when his father shouted at him, from when he was six. Go and find him. He'll talk to you, or he won't talk to anyone.'".
    On discuss { Assert knows(actor, kit_place). }
  }
  Topic maudie_kit_stranger with maudie "Ask Maudie about her son" when stranger(actor) and maudieWelcomes(actor) once {
    Says "'Kit.' She says it as if the name had a weight. 'He was at the chain. He's at the yards all day, and at night he goes off under the bridge, where he always went. He's seventeen. He thinks the world's a thing you can set fire to.' She looks at you. 'If you can talk to him, talk to him. I can't.'".
    On discuss { Assert knows(actor, kit_place). }
  }
  Topic maudie_dog with maudie "Ask Maudie about the dog under the gatehouse" when knows(actor, bramble_there) and not coatGiven(maudie) once {
    Says "'Bramble.' Her hands stop. 'He's lain under the gate since they put Wat up there. He won't come for me. He was never my dog; he was Wat's from a pup.' She wipes her hands on her apron, goes to the hook by the door, and takes down the brown coat, and holds it a moment. 'Here. Lay it down by him. He'll come to the smell of it if he'll come to anything.' She holds it out. 'Bring the coat back. Bring the dog if you can.'".
    On discuss { Assert coatGiven(maudie). Assert knows(actor, coat_given). }
  }
  Discovery coat_given "Maudie Pardoe has given you Wat's coat, to lay down by the dog under the gatehouse.".
  Kind wat_coat_kind "Wat Pardoe's coat" like cloak worth 0 weighing 3
    described "A carter's coat of brown frieze, heavy as a wet blanket, the pockets pulled out of shape by thirty years of hands. It smells of horse, and pipe, and him.".
  Item wat_coat "Wat Pardoe's coat" is wat_coat_kind at pardoe_kitchen hidden until coat_given.

  // The vigil: a night sat up with her. It is what is done in Wrayford for the dead, and she is doing it alone, for a
  // man who is not in the house.
  Action sit_vigil(actor: group, site: place) "Sit up with your mother by the fire" {
    Description "An hour, by the fire, with the bread proving. Nobody needs to say anything.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pardoe_kitchen) and at(maudie, pardoe_kitchen)
      and homecomer(actor) and (hour(clock) >= 20 or hour(clock) < 2) and lastVigil(maudie) != dayN(wray).
    Time 6.
    On success { Increase vigils(maudie) by 1. Set lastVigil(maudie) to dayN(wray). }
    Result "You sit up with her by the fire. The bread proves under its cloth. The clock on the dresser, which your father wound every Sunday, has stopped, and neither of you gets up to wind it.".
  }
  Action sit_vigil_stranger(actor: group, site: place) "Sit up with Maudie Pardoe by the fire" {
    Description "An hour, by the fire. She has let you in; it is what is done in Wrayford for the dead.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, pardoe_kitchen) and at(maudie, pardoe_kitchen)
      and stranger(actor) and maudieWelcomes(actor) and (hour(clock) >= 20 or hour(clock) < 2) and lastVigil(maudie) != dayN(wray).
    Time 6.
    On success { Increase vigils(maudie) by 1. Set lastVigil(maudie) to dayN(wray). }
    Result "You sit up with her by the fire. She does not talk for a long time, and you do not make her.".
  }
  Rule vigil_first at pardoe_kitchen when vigils(maudie) == 1 and not spread(vigil_ford) says "Some time after midnight she says, to the fire, 'He carried a calf across the Wray once. The year of the big snow, when the bridge was shut for ice. In the small hours, when the mills had the river penned and it ran low, he walked across on the old ford-stones under the first arches with a calf round his neck like a collar, and threw his loaf into the black water at Wade's Step first, for the Bargeman, the way the old drovers did, and came back with a wet calf and no feeling in his legs, and the man who owned the calf gave him a shilling and a thrashing for the fright.' She nearly smiles. 'Nobody wades the ford now. But it's there. In the small hours it's there.'" teaches vigil_ford { Assert spread(vigil_ford). }
  Discovery vigil_ford "Under the bridge's first arches the old ford-stones still cross the Wray. In the small hours, when the mills upstream pen the river, it runs low enough there for a man to wade, carrying something heavy.".
  Rule vigil_second at pardoe_kitchen when vigils(maudie) == 2 and homecomer(party) and not spread(vigil_letter) says "She says, without turning round, 'I was angry with you for three years, and then he said, she'll come back when she's had enough of other people's cattle, or he'll come back, or they'll come back, whichever you are, he said, you never could tell, and laughed. He wasn't angry. He was never once angry with you. I want you to know that before anything else happens.' Then, quite briskly: 'Put another log on.'" { Assert spread(vigil_letter). }
  Entity vigil_letter: fact "What Maudie said on the second night".
  Rule vigil_second_stranger at pardoe_kitchen when vigils(maudie) == 2 and stranger(party) and not spread(vigil_letter) says "She says, to nobody, 'Thirty years. He drove to the fells and back two hundred days a year and I never once knew which day he'd be home, and I'd make the bread every day so it'd be fresh for whichever one it was.' She looks at the loaves on every surface. 'Habit,' she says." { Assert spread(vigil_letter). }

  // Her question. She asks it once, of her own child, after the first night sat up.
  Relation maudieAsked(group). Relation promisedMaudie(group). Relation maudieWaits(group).
  Event maudie_asks at pardoe_kitchen when homecomer(party) and vigils(maudie) >= 1 and not dark() and knows(party, maudie_resolve) "Your mother wipes her hands, and sits down across the table from you, which she does not do. 'I'll ask you once,' she says. 'Will you see to it, or must I?'" then { Assert maudieAsked(party). }
  Topic answer_will with maudie "Tell your mother you will see him buried before the third night is out" when maudieAsked(actor) and not promisedMaudie(actor) and not maudieWaits(actor) once {
    Says "She looks at you for a long time. 'Then I'll stop at home,' she says. 'I'll stop at home and make bread, and if you don't, I'll know you couldn't, and not that you wouldn't.' She gets up. 'Don't get yourself hanged. I couldn't bury two.'".
    On discuss { Assert promisedMaudie(actor). }
  }
  Topic answer_wait with maudie "Ask your mother to wait for the reeve to come round" when maudieAsked(actor) and not promisedMaudie(actor) and not maudieWaits(actor) once {
    Says "'Simon Hulme.' She nearly laughs. 'All right. I'll wait for Simon Hulme. I'll wait till the third night.' She picks up the dough again. 'Not an hour after.'".
    On discuss { Assert maudieWaits(actor). }
  }

  // ── Kit ───────────────────────────────────────────────────────────────────────────────────────────────────────────
  // He drove the cart. Nobody knows but him, and Dunstan, who is dead.
  Person kit "Kit Pardoe" at carters_yards {
    Role "a carter's son, seventeen, with black under his nails". Ancestry human. Calling warrior. Level 1. Peaceable. Pronouns he. Manner grim.
    Greets "Kit looks up, and looks away again.".
    Joins "Kit wipes his hands on his trousers and comes, half a step behind, the way he used to.".
    Leaves "Kit nods, once, at the ground.".
    Seen when not at(kit, under_arches) or knows(viewer, kit_place).
  }
  Discovery kit_place "After dark Kit Pardoe goes down under the bridge's first arches, where he always went as a boy when his father shouted at him, and sits there by the water.".
  Measure kitTrust(group). Initially Set kitTrust(kit) to 0.
  Query kitTrusts(a: group) means kitTrust(kit) >= 2 or homecomer(a) and kitTrust(kit) >= 1.
  Relation kitAccount(group). Relation kitConfessed(group). Relation kitSat(group). Relation kitBetrayed(group).
  // Where he is: the yards by day, the Nine Wheels in the evening, under the arches after dark, home to sleep.
  Relation kitTaken(group). Relation kitJoined(group).
  Query kitFree() means not kitTaken(kit) and not travelsWith(kit, party).
  Rule kit_to_wheels when kitFree() and hour(clock) >= 18 and hour(clock) < 21 and not at(kit, wheels_taproom) and not kitOut(kit) {
    Assert at(kit, wheels_taproom). }
  Rule kit_to_arches when kitFree() and hour(clock) >= 21 and not at(kit, under_arches) and not kitOut(kit) {
    Assert at(kit, under_arches). }
  Rule kit_to_bed when kitFree() and hour(clock) >= 1 and hour(clock) < 6 and not at(kit, pardoe_yard) and not kitOut(kit) {
    Assert at(kit, pardoe_yard). }
  Rule kit_to_yards when kitFree() and hour(clock) >= 6 and hour(clock) < 18 and not at(kit, carters_yards) and not kitOut(kit) {
    Assert at(kit, carters_yards). }
  // Out with the young carters on the second night (northgate.kyr).
  Relation kitOut(group).

  Topic kit_hello with kit "Ask Kit how he is" when homecomer(actor) once {
    Says "'How I am.' He puts the brush back in the grease. 'You came, then. A week late and three years late. Good of you.' He works the brush round the hub, round and round, though it was greased an hour ago and the hour before that. 'He talked about you. Every night. Our Wat says this, our Wat says that, when he'd had a drink. You'd have thought you'd hung the moon.'".
  }
  Topic kit_night with kit "Ask Kit about the night of the rising" when not kitAccount(actor) once {
    Says "'I was at the chain.' Fast, as if he had said it before, to himself. 'With the others. Da had the cart at the back, he was only there to keep the young ones from doing anything stupid. There was a press at the gate and somebody's cart went over the Hobday lad, and then the toll-house was burning and everybody ran. I ran.' He does not look up from the hub. 'I didn't see. I didn't see anything. I was at the chain.'".
    On discuss { Assert kitAccount(actor). Assert knows(actor, kit_said_chain). }
  }
  Discovery kit_said_chain "Kit says he was at the chain the whole night of the rising, and saw nothing of the cart that went over Ned Hobday.".
  Topic kit_night_stranger with kit "Ask the carter's son about the night of the rising" when stranger(actor) and not kitAccount(actor) once {
    Says "'Who's asking?' He looks you up and down. 'I was at the chain. Everybody was at the chain. Ask anybody.' He goes back to the hub, round and round. 'I didn't see anything.'".
    On discuss { Assert kitAccount(actor). Assert knows(actor, kit_said_chain). }
  }
  // Under the arches, after dark: the only place he can be talked to.
  Observe arches_kit at under_arches when at(kit, under_arches) and knows(party, kit_place) "Kit is sitting on the ford-stone under the first arch with his knees up, looking at the water going by, which is all there is to look at.".
  Action sit_with_kit(actor: group, site: place) "Sit down by Kit on the ford-stone and say nothing" {
    Description "Half an hour by the water. He will talk or he won't.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, under_arches) and at(kit, under_arches)
      and not kitSat(actor) and not kitBetrayed(kit).
    Time 3.
    On success { Assert kitSat(actor). Increase kitTrust(kit) by 1. }
    Result "You sit down by him. The water goes by. After a long time he says, 'He used to throw me in off this stone to teach me to swim,' and after a longer time, 'I can't swim,' and almost laughs.".
  }
  // What he did. Only to someone he trusts, here, after dark, and only if they already half know it.
  Topic kit_confess with kit "Tell Kit you know he had the reins" when knows(actor, kit_reins) and kitTrusts(actor) and at(kit, under_arches) and not kitConfessed(actor) once {
    Says "For a long time he doesn't say anything. The water goes by. Then: 'He was at the chain. I had the reins. He said hold the horse, she's skittish with the noise, and the crowd came back off the gate all at once and she went forward and I couldn't hold her, and there was a lad under the wheel, and I knew him, I knew it was Ned Hobday, we used to fish off here.' He is shaking. 'Da came and took the reins off me and lifted Ned up into the back like he was a sack of something precious and said get away home, Kit, get away home and say you were at the chain. And drove off up the fell road for the bone-setter at Scar Top. And the riders stopped him on the road with Ned dead in the back.' He puts his face in his knees. 'He told them he was driving. Dunstan told me. Dunstan saw. And they hanged Dunstan too.'".
    On discuss { Assert kitConfessed(actor). Assert knows(actor, kit_driving). Increase kitTrust(kit) by 1. Assert willing(kit, actor). }
  }
  Topic kit_accused with kit "Tell Kit you know he had the reins" when knows(actor, kit_reins) and not kitTrusts(actor) and not kitConfessed(actor) and not kitDenied(actor) once {
    Says "He is on his feet with the grease-brush in his fist before you have finished. 'Who told you that? Who's saying that?' His face is white. 'I was at the chain. I was at the chain. You can tell whoever's saying it I'll knock their teeth in.' He goes, fast, and does not look back.".
    On discuss { Assert kitDenied(actor). }
  }
  Relation kitDenied(group).
  Discovery kit_driving "Kit Pardoe was driving his father's cart when it went over Ned Hobday. Wat took the reins back, lifted the boy into the cart and drove for the bone-setter at Scar Top; Ned died on the way. When the riders stopped them on the fell road, Wat said he had been driving.".
  Discovery kit_reins "The farrier in Northgate saw Kit Pardoe, not his father, on the box of Wat Pardoe's cart at the gate, with the reins in his hands, when the crowd came back off the chain.".

  // ── Bramble ───────────────────────────────────────────────────────────────────────────────────────────────────────
  Person bramble "Bramble" at gate_road {
    Role "a carter's dog, brindled, grey in the muzzle". Species dog. Pronouns he.
    Greets "The brindled dog under the gatehouse lifts his eyes to you, and not his head.".
    Leaves "Bramble lies down in the swept place in the cart-shed, and when you go, he stays.".
  }
  Discovery bramble_there "Wat Pardoe's dog, Bramble, has lain under the gatehouse since they hanged him, and will not eat, and will not come away." {
    Known by maudie, kit, annis, pinch, pell.
  }
  Observe bramble_again at gate_road when at(bramble, gate_road) and not brambleCame(bramble) and visitedBefore(gate_road) "Bramble is still under the wall below the rail.".
  Observe bramble_scene at gate_road when at(bramble, gate_road) and not brambleCame(bramble) and not visitedBefore(gate_road) "Under the gatehouse wall, directly below the rail, a brindled dog lies with his chin on his paws, as close to the wall as he can get, and does not move when people step over him." teaches bramble_there.
  Relation brambleAte(group). Relation brambleCame(group). Relation brambleHome(group). Relation brambleGone(group).
  Action feed_bramble(actor: group, site: place) "Put down bread for the brindled dog" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bramble, site) and not brambleAte(bramble)
      and quantity(actor, rations) >= 1.
    Time 2 minutes.
    On success { Decrease quantity(actor, rations) by 1. Assert brambleAte(bramble). }
    Result "You put it down by his nose. For a long time he does nothing. Then, without getting up, as if it were a thing he were doing for you, he eats it.".
  }
  Action coat_bramble(actor: group, giver: member, site: place) "Lay Wat's coat down by Bramble" {
    Requires able(actor) and company(actor) and at(actor, site) and at(bramble, site) and memberOf(giver, actor)
      and ownedItem(wat_coat, giver) and not brambleCame(bramble) and brambleAte(bramble).
    Time 2 minutes.
    On success { Assert brambleCame(bramble). Assert following(bramble, actor). }
    Result "You spread it on the stones by him. He gets up, stiffly, for the first time in four days, and noses at it, and lies down on it, and then looks up at you, and when you pick it up he stands and waits to be told where.".
  }
  Action wait_bramble(actor: group, site: place) "Sit by Bramble the way a drover sits by a dog, and wait for him" {
    Description "Not looking at him. Letting him come.".
    Requires able(actor) and company(actor) and at(actor, site) and at(bramble, site) and capable(actor, woodcraft)
      and not brambleCame(bramble) and brambleAte(bramble).
    Time 3.
    On success { Assert brambleCame(bramble). Assert following(bramble, actor). }
    Result "You sit with your back to the wall a little way off, and look at the river, and say his name once, and nothing else. After half an hour he gets up and comes and lies against your leg, and when you stand, he stands.".
  }
  Rule bramble_home when following(bramble, party) and at(bramble, pardoe_yard) and not brambleHome(bramble) {
    Retract following(bramble, party). Assert brambleHome(bramble). Assert maudieWelcomes(party). }
  Rule bramble_home_told at pardoe_yard when brambleHome(bramble) and not spread(bramble_home_fact) says "Bramble goes straight to the cart-shed and lies down in the swept place where the cart stood. Maudie Pardoe comes out to the back door and stands there with her floury hands and looks at him, and then at you. 'Well,' she says. 'Well.' She goes in and comes out again with a bowl of milk with bread in it, and puts it down by him, and he eats it." { Assert spread(bramble_home_fact). }
  Entity bramble_home_fact: fact "Bramble came home".
  // A dog walking with you at night goes to find the other one he is missing.
  Rule bramble_finds_kit when following(bramble, party) and dark() and inWrayford() and not knows(party, kit_place) and kitFree() says "Bramble stops in the road and lifts his head, and then goes off at a trot down toward the river, and looks back once to see that you are coming: down Bridge End, along the bank, under the first arch of the bridge." teaches kit_place { }
  // Pinch kicks him every morning when he opens the booth, and on the morning after the third night, if Bramble is
  // still there, the riders have him taken down to the river.
  Rule pinch_kicks at gate_road when hour(clock) == 8 and at(bramble, gate_road) and not brambleCame(bramble) and at(pinch, gate_road) and not kickedToday(bramble) says "Amos Pinch, coming to open the booth, steps over the dog, and then steps back and kicks him, not hard, the way you kick a door that sticks. 'Shift,' he says. The dog does not shift. Annis Pye, at her pitch, says something to Pinch that the crowd enjoys." { Assert kickedToday(bramble). }
  Relation kickedToday(group).
  Rule kick_day_ends when hour(clock) == 9 and kickedToday(bramble) { Retract kickedToday(bramble). }
  Rule bramble_taken when fourthDay() and hour(clock) >= 7 and at(bramble, gate_road) and not brambleCame(bramble) {
    Retract at(bramble, gate_road). Assert brambleGone(bramble). }
  Observe bramble_gone at gate_road when brambleGone(bramble) and not dark() "There is no dog under the gatehouse wall. There is a mark on the stones where he lay.".
}

data/adventures/wrayford/pitch.kyr:
Module wrayford "The Third Night" {
  // ── Annis Pye ─────────────────────────────────────────────────────────────────────────────────────────────────────
  // A pie-seller at the Bridge End, who was to marry Joss Wilder at Harvest, and sells pies to the crowd that comes to
  // look at him, because she has her mother to keep and the crowd is there.
  Person annis "Annis Pye" at gate_road {
    Role "a pie-seller at the Bridge End, with a tray on a strap". Ancestry human. Peaceable. Pronouns she. Manner cheerful.
    Greets "'Pies,' says Annis Pye, very brightly. 'Mutton or eel. A penny.' She does not look up at the rail, carefully, the way you do not look at a bad tooth.".
    Sells rations for 1 coin from 12.
  }
  Relation annisRing(group). Relation annisLeft(group). Relation annisWinPies(group).
  Rule annis_pitch when hour(clock) >= 8 and hour(clock) < 18 and not annisLeft(annis) and not at(annis, gate_road) { Assert at(annis, gate_road). }
  Rule annis_home when (hour(clock) >= 18 or hour(clock) < 8) and not at(annis, bridge_street) { Assert at(annis, bridge_street). }
  Rule annis_leaves_pitch when annisLeft(annis) and at(annis, gate_road) { Retract at(annis, gate_road). Assert at(annis, bridge_street). }
  Observe annis_again at gate_road when at(annis, gate_road) and stillHanging() and visitedBefore(gate_road) "Annis Pye is selling pies, with her back to the gatehouse.".
  Observe annis_crowd at gate_road when at(annis, gate_road) and stillHanging() and not visitedBefore(gate_road) "Annis Pye, a girl with a tray of pies on a strap round her neck, is doing good business with the crowd. She has her back to the gatehouse.".
  Discovery ring_missing "Annis Pye was to marry Joss Wilder at Harvest. She sells pies at the Bridge End, under him. His betrothal ring is not on his hand; she watched them hang him and looked for it, and it was not there." {
    Known by annis.
  }
  Topic annis_joss with annis "Ask the pie-seller about the youngest of the three" when true once {
    Says "'Joss.' She keeps her voice bright, for the customers. 'Joss Wilder. We were to be married at Harvest.' A man buys an eel pie; she gives him change. 'I've my mother to keep, and they're here, all of them, every day, looking, and they're hungry.' Her voice does not change at all. 'His ring's not on his hand. I watched them do it, from here, and I looked, and it wasn't there. I don't know where it is. I'd like it. That's all I'd like.' She turns to the next customer. 'Mutton or eel.'".
    On discuss { Assert knows(actor, ring_missing). }
  }
  Action give_ring(actor: group, giver: member, site: place) "Give Annis Pye Joss Wilder's ring" {
    Requires able(actor) and company(actor) and at(actor, site) and at(annis, site) and memberOf(giver, actor) and ownedItem(joss_ring, giver)
      and not annisRing(annis).
    Time 2 minutes.
    Resolve drop(joss_ring, giver).
    On success { Assert annisRing(annis). Assert annisLeft(annis). Increase temper(wray) by 1. Increase quantity(actor, rations) by 3. }
    Result "She looks at it in your palm for a long time, the tray of pies tilting on its strap. Then she takes it and puts it on her own finger, which it is too big for, and closes her hand on it. She takes the tray off over her head and gives you three pies off it, not for sale, and walks away from the Bridge End along Bridge Street without looking back, with her fist shut, and does not come back to her pitch.".
  }
  Topic annis_win with annis "Ask Annis whether she would sell Win Fenner pies at cost" when annisRing(annis) and knows(actor, win_proud) and not annisWinPies(annis) once {
    Says "'Win.' She thinks about it. 'She'd not take them off you. She'd take them off me.' She nods slowly. 'At cost. Every day, as many as the children want, and she can owe me, and I'll never send in the bill.' She almost smiles. 'She'll know. She'll take them anyway. We're the same now, her and me.'".
    On discuss { Assert annisWinPies(annis). Assert winHelped(actor). }
  }

  // ── The burned toll-house ─────────────────────────────────────────────────────────────────────────────────────────
  Observe ruin_scene at toll_ruin when true "What is left of the toll-house: a stone hearth and chimney standing up out of a heap of black timbers and slates, the smell of wet char, a melted lump that was the toll-keeper's lamp. The fire began at the back, by the look of the scorching, against the wall nearest the river, where the shelves were. The carters were at the front, at the chain.".
  Discovery flask_found "In the ash at the back of the toll-house, under a fallen beam, by the wall where the shelves were and where no carter at the chain came: a tin oil-flask, unstoppered and empty, stamped with the Bridge Company's gold bridge." { Found by searching toll_ruin. }
  Kind flask_kind "a Company oil-flask" is gear worth 0 weighing 1
    described "A tin flask for lamp-oil, scorched black, with the Bridge Company's little gold bridge stamped on its shoulder. Empty. The stopper is gone.".
  Item company_flask "the Company's oil-flask" is flask_kind at toll_ruin hidden until flask_found.
}

data/adventures/wrayford/placed.kyr:
Module wrayford "The Third Night" {
  // The country beyond a march of a generated world: the company that comes in by the road is the world's own.
  Entity party: group "Your company".
}

data/adventures/wrayford/river.kyr:
Module wrayford "The Third Night" {
  // ── The Wharf ─────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe wharf_scene at wharf when not dark() and not visitedBefore(wharf) "The Wharf runs along the river west of the bridge: warehouses with hoists, barges tied two deep, eel-traps, nets drying, a smell of tar and river. Downstream the bridge goes over on its arches, and the water piles up white against the cutwaters and goes through roaring.".
  Observe wharf_again at wharf when not dark() and visitedBefore(wharf) "The Wharf: warehouses, barges, the bridge's arches downstream.".
  Observe wharf_night at wharf when dark() "The Wharf at night: barge-lamps on the black water, and the noise of the river through the arches.".
  Observe arches_scene at under_arches when not dark() "The bank under the bridge's first arch: a strip of mud and stones where the city's boys fish and its drunks sleep, and the great pier going up out of the water beside you into the shadow, green to a man's height and red stone above. High overhead, the gatehouse parapet. Out from the bank, under the brown water, you can just make out a line of big squared stones going across: the old ford.".
  Observe arches_night at under_arches when dark() and not lowWater() "Under the first arch at night the river is loud and close and black, and the pier goes up into the dark. High above, the red glow of the riders' brazier on the gatehouse leads.".
  Observe arches_low at under_arches when dark() and lowWater() "The mills have the river penned, and the Wray under the first arch has dropped and quietened. Across from the bank, a line of square stones stands just under the water, pale in the dark, going over toward the tan-yards on the far side.".
  // The ford: a deep step halfway, where the stones are gone, that has drowned men.
  Thing deep_step "the deep step in the ford" at wades_step {
    State deep "Here two of the ford-stones are gone, and the water goes suddenly deep and black and quiet, a hole in the river the width of a cart: Wade's Step.".
  }
  Initially Assert state(deep_step, deep).
  Discovery ford_way "The old ford goes across the Wray under the first arch from the north bank to the tan-yards, on squared stones, in the small hours when the river is penned. Halfway, two stones are gone, and the way is upstream of the gap, along the pier's foot.".
  // The beasts know it; a woodsman can read it; anyone else risks the step.
  Action read_ford(actor: group, site: place) "Read the ford by the sound of the water, and cross upstream of the deep step" {
    Description "Where the water talks it is shallow; where it goes quiet it is deep.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, under_arches) and lowWater() and capable(actor, woodcraft).
    Time 3.
    On success { Retract at(actor, under_arches). Assert at(actor, tanyards). Assert knows(actor, ford_way). }
    Result "You go slowly, listening: where the water chatters over stone it is a foot deep, and where it goes smooth and quiet it is not. Halfway, it goes quiet in front of you: Wade's Step, black and smooth, and something long turning in it, slowly, as you pass. You go up along the foot of the pier instead, with the cold to your thighs, and come out on the far side among the tan-pits with the stink of the yards in your nose and the city behind you.".
  }
  Action follow_ford(actor: group, site: place) "Cross the ford upstream of the deep step, as you were told" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, under_arches) and lowWater() and knows(actor, ford_way)
      and not capable(actor, woodcraft).
    Time 3.
    On success { Retract at(actor, under_arches). Assert at(actor, tanyards). }
    Result "You find the stones with your feet, one after another, and when the water goes deep and quiet in front of you, you remember, and do not look at what moves in it, and go up along the pier's foot instead, and come out among the tan-pits on the far side wet to the waist.".
  }
  Action follow_ford_back(actor: group, site: place) "Cross the ford back to the city, upstream of the deep step" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, tanyards) and lowWater() and (knows(actor, ford_way) or capable(actor, woodcraft)).
    Time 3.
    On success { Retract at(actor, tanyards). Assert at(actor, under_arches). }
    Result "Back over the stones in the dark, up along the pier's foot past the gap, and out under the first arch.".
  }

  // Ham Ostler's drive, in the small hours of the second night: sixty head over the ford, and anyone who comes.
  Relation hamDriving(group). Relation hamDrove(group). Relation hamGrateful(group).
  Query driveHour() means secondDay() and hour(clock) >= 1 and hour(clock) < 3.
  Rule ham_drives when driveHour() and not hamDrove(ham) and not hamDriving(ham) and not cartersTaken(ham) { Assert hamDriving(ham). Assert at(ham, under_arches). }
  Rule ham_done when (secondDay() and hour(clock) >= 3 and hour(clock) < 6 or dayN(wray) >= 3) and hamDriving(ham) { Retract hamDriving(ham). Assert hamDrove(ham). Assert at(ham, tanyards). }
  Rule ham_back when dayN(wray) >= 3 and hour(clock) >= 7 and hamDrove(ham) and at(ham, tanyards) { Retract at(ham, tanyards). Assert at(ham, shambles). }
  Observe ham_herd at under_arches when hamDriving(ham) "Ham Ostler is here in the dark with his crook, and behind him, filling the bank and the lane down to it, sixty head of fell cattle breathing like a congregation. His old cow stands at the water's edge with her nose down to it.".
  Action drive_with_ham(actor: group, site: place) "Go over the ford with Ham and his beasts" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, under_arches) and hamDriving(ham) and at(ham, under_arches).
    Time 3.
    On success { Retract at(actor, under_arches). Assert at(actor, tanyards). Assert knows(actor, ford_way). Assert hamGrateful(actor). }
    Result "The old cow goes in first, and the rest after her, and you go in among them with your hand on a warm wet flank. She knows the way: halfway, where the water goes deep and quiet at Wade's Step and something under it rolls like a log, she turns upstream along the foot of the pier without being asked, and the herd turns after her like one animal. You come out among the tan-pits on the far side in a steam of cattle, and Ham Ostler laughs in the dark. 'Five shillings,' he says. 'Five shillings the Company'll not have. I'll stand you a drink at Michaelmas.'".
  }

  // ── Dorcas Mudd ───────────────────────────────────────────────────────────────────────────────────────────────────
  Observe stage_scene at ferry_stage when not dark() and not visitedBefore(ferry_stage) "The ferry-stage: a jetty of black piles with a ferry-boat tied to it, broad and old and very well kept, and a hut with a stove-pipe. A painted board: MUDD'S FERRY. BY CHARTER. OVER THE WRAY SINCE BEFORE THAT BRIDGE. ONE PENNY. And under it, smaller and newer: NO FARTHINGS.".
  Observe stage_again at ferry_stage when not dark() and visitedBefore(ferry_stage) "The ferry-stage: the black jetty, the broad boat, MUDD'S FERRY. BY CHARTER.".
  Observe stage_night at ferry_stage when dark() "The ferry-stage at night: the boat drawn up, a lamp in the hut window.".
  Person dorcas "Dorcas Mudd" at ferry_stage {
    Role "the mistress of the ferrymen's company, broad as her boat". Ancestry human. Peaceable. Pronouns she. Manner acerbic.
    Greets "Dorcas Mudd looks you up and down from the stern of her boat. 'Over?' she says. 'A penny. Not a farthing. I'm not a bridge.'".
    Sells rope for 1 coin from 3.
  }
  Rule dorcas_sleeps when (hour(clock) >= 23 or hour(clock) < 5) and not asleep(dorcas) and not ferriesAtNight(party) { Assert asleep(dorcas). }
  Rule dorcas_wakes when hour(clock) >= 5 and hour(clock) < 23 and asleep(dorcas) { Retract asleep(dorcas). }
  Discovery ferry_charter "Dorcas Mudd holds that by the ferrymen's charter, which is older than the bridge, whatever is on the Wray between the stairs is the ferry's until it is landed: not the lord's, not the city's, not the Liberty's.".
  Topic dorcas_bridge with dorcas "Ask Dorcas Mudd about the bridge" when true once {
    Says "'That.' She does not look at it. 'My great-grandfather had six boats on this river and a house on the Hill. Then they built that, and he had one boat and a hut.' She spits over the side. 'Charter's older. Whatever's on the Wray between the stairs is the ferry's till it's landed. Not the lord's, not the reeve's, not her ladyship's over the water. Mine.' She looks up at the gatehouse. 'Including anything that might fall off it.'".
    On discuss { Assert knows(actor, ferry_charter). }
  }
  Relation dorcasTerms(group). Relation corbinTerms(group).
  Topic dorcas_dead with dorcas "Ask Dorcas whether she would carry the dead over the river" when knows(actor, dead_on_rail) once {
    Says "'For nothing,' she says at once. 'Gladly. At night, under the rail, if somebody'll get them down to me. I'd row the three of them to the Acre steps and spit on the bridge as I went.' Then her face shuts. 'When that old fool at the Acre asks me himself. Corbin. Forty years he's not asked me for anything, and he'll not start now, and I'll not row his dead for him till he does.' She coils a rope very hard. 'He won't.'".
    On discuss { Assert dorcasTerms(actor). }
  }
  // Two old people across the water, and the messages carried between them.
  Relation dorcasLied(group). Relation corbinLied(group). Relation corbinAsked(group). Relation reconciled(place).
  Relation dorcasCarries(group). Relation corbinDigs(group). Relation boatArranged(group).
  Action tell_dorcas_lie(actor: group, site: place) "Tell Dorcas that Corbin says she is the only one on the river he'd trust with them" {
    Description "He said nothing of the kind.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, ferry_stage) and at(dorcas, ferry_stage)
      and dorcasTerms(actor) and corbinTerms(actor) and not dorcasLied(actor) and not reconciled(wray) and not triedDorcasLie(actor).
    Time 2 minutes.
    Resolve check(actor, deception, dc_fair).
    On success { Assert dorcasLied(actor). }
    On failure { Assert triedDorcasLie(actor). }
    Result "She goes very still in the stern of her boat. 'He said that?' She looks across the water at the Acre wall. 'The old goat.' She coils the rope again, quite gently this time. 'Well. If he's said it, he can say it to my face, at the stage, and I'll row them.'".
    Otherwise "She looks at you with great contempt. 'Corbin never said that in his life,' she says. 'Corbin doesn't know that many words.'".
  }
  Relation triedDorcasLie(group). Relation triedCorbinLie(group).
  // Both told a kind lie: that evening, at the hour they quarrel, they meet instead.
  Rule they_meet when dorcasLied(party) and corbinLied(party) and hour(clock) == 20 and not reconciled(wray) says "At the hour when Dorcas Mudd and Corbin usually shout at each other across the river, there is no shouting. Instead Dorcas rows over to the Acre steps, and Corbin comes down them, and they stand a yard apart for some time. Then, carried clearly over the water to both banks: 'You never said that.' 'No. Did you?' 'No.' A long silence. 'Well.' 'Well.' And then something you cannot hear, and Dorcas laughs, which nobody in Wrayford has heard her do in years, and Corbin takes his hat off." {
    Assert reconciled(wray). Assert dorcasCarries(party). Assert corbinDigs(party). }
  Action corbin_asks(actor: group, site: place) "Persuade Corbin to row over and ask Dorcas himself" {
    Description "It will take some doing.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wades_acre) and at(corbin, wades_acre)
      and dorcasTerms(actor) and corbinTerms(actor) and not reconciled(wray) and not corbinAsked(actor) and not triedCorbinAsk(actor).
    Time 3.
    Resolve check(actor, persuasion, dc_hard).
    On success { Assert corbinAsked(actor). Assert reconciled(wray). Assert dorcasCarries(actor). Assert corbinDigs(actor). }
    On failure { Assert triedCorbinAsk(actor). }
    Result "It takes half an hour, and he calls you several things, and then he says, 'Fine. Fine,' and puts his hat on, and goes down the Acre steps to the water, and shouts across it, 'Dorcas Mudd! Will you row Wat Pardoe over for me, for I can't do it myself!' And across the water, after a very long time, Dorcas Mudd's voice: 'Since you ask.'".
    Otherwise "'Ask her,' says Corbin. 'Ask her. Me.' He turns his back on you and looks at the river.".
  }
  Relation triedCorbinAsk(group).
  Topic dorcas_boat with dorcas "Ask Dorcas to bring the boat under the gatehouse rail at two in the morning" when dorcasCarries(actor) and not boatArranged(actor) once {
    Says "'Two,' she says. 'When the mills have it penned and it runs quiet.' She looks up at the gatehouse. 'I'll lie under the first arch with the lamp shut. Lower them down to me on a rope, gently, one at a time, and come down after. If anybody's awake on those leads, don't.'".
    On discuss { Assert boatArranged(actor). Assert ferriesAtNight(actor). }
  }
  Observe boat_waiting at under_arches when boatArranged(party) and lowWater() and not boatGone(party) "Out on the black water, just off the pier, a broad shape with no light in it: Dorcas Mudd's boat, lying to her oars.".
  Relation boatGone(group).

  // ── The quarrel at dusk ───────────────────────────────────────────────────────────────────────────────────────────
  Rule dusk_quarrel at ferry_stage when hour(clock) == 20 and not reconciled(wray) and not quarrelled(wray) and at(dorcas, ferry_stage) says "Across the water, at the Acre wall, an old man in a black coat climbs up on the wall and shouts something at the ferry-stage. Dorcas Mudd stands up in her boat and shouts something back. It goes on for a while. Nobody on the Wharf looks up; it has gone on every evening for forty years." { Assert quarrelled(wray). }
  Rule dusk_quarrel_south at wades_acre when hour(clock) == 20 and not reconciled(wray) and not quarrelled(wray) says "Corbin climbs up on the Acre wall, cups his hands, and shouts across the river at the ferry-stage, 'DORCAS MUDD, YOUR BOAT LEAKS.' From the far bank, small and clear: 'YOUR GRAVES ARE CROOKED.' He gets down, satisfied." { Assert quarrelled(wray). }
  Relation quarrelled(place).
  Rule quarrel_over when hour(clock) == 21 and quarrelled(wray) { Retract quarrelled(wray). }
}

data/adventures/wrayford/wade.kyr:
Module wrayford "The Third Night" {
  // ── Saint Wade ────────────────────────────────────────────────────────────────────────────────────────────────────
  // The legend the city lives inside, told in pieces: before the bridge, Wade kept the ford. On the third night after
  // the great flood a drowned child came to his door and asked to be carried over to be buried; at the deep place the
  // child grew heavy as all the dead of the vale, and Wade stumbled there and did not set him down. The dead who are not
  // carried over by the third night go looking for someone who will. The Company has his work for its motto.
  Discovery wade_legend "Before there was a bridge, Wade kept the ford at Wrayford and carried travellers over on his back for nothing. On the third night after the great flood a drowned child came to his door and asked to be carried over to the Acre to be buried. At the deep place in the ford the child grew heavy as all the dead of the vale, and Wade stumbled, and went to his chin, and did not set him down. The deep place is Wade's Step. Since then the dead of Wrayford are carried over; and the ones who are not, by the end of the third night, go looking for someone who will.".
  Discovery wade_hymn "The carters' hymn to Wade, sung on the fell road in the dark: 'Carry me over, Wade, carry me over; the water is deep and the night is long; carry me over.' Wat Pardoe sang it on the road to the rope.".
  Topic abbess_wade with abbess "Ask the Abbess who Saint Wade was" when true once {
    Says "'A ferryman.' She does not look up from her letter. 'A ferryman without a ferry, who carried people over the Wray on his back for nothing, which is the first thing about him the Company has forgotten.' She sands the page. 'On the third night after the great flood a drowned child knocked at his door and asked to be carried over to be buried. Halfway, at the deep place, the child grew heavy: as heavy as all the dead of the vale, the old life says, which is a theologian's way of saying very. Wade went down to his chin at the Step that has his name and did not set him down.' She looks up. 'That is what WE BEAR THE CROSSING means, on a counting-house. My predecessors objected to the motto in writing. It is framed, behind you, upside down.'".
    On discuss { Assert knows(actor, wade_legend). }
  }
  Topic corbin_looking with corbin "Ask Corbin what the dead go looking for" when knows(actor, third_night_custom) or knows(actor, wade_legend) or homecomer(actor) once {
    Says "He takes the pipe out of his mouth. 'Folk think it's vengeance. It's not vengeance.' He looks across the water at the gatehouse. 'They go looking for a back. Someone to carry them over, the way Wade did. That's all the dead ever want of you, a back and a hole.' He puts the pipe back. 'I've the hole. I'll not dig it while they're up there for show. Somebody else can find the back.'".
    On discuss { Assert knows(actor, wade_legend). }
  }
  // The badges on Bridge Street, and the two Wades.
  Observe wade_badges at bridge_street when not dark() and not visitedBefore(bridge_street) "On a tray outside the badge-seller's, tin Saint Wades at a farthing each: a stooping man up to his knees in tin water, with a child on his shoulders. 'Carry me over,' says the badge-seller to nobody, the way a fishwife says 'fresh'.".
  Observe chapel_wade at chapel when true "Over the altar, the old painting: Saint Wade up to his chest in a black river, bent nearly double under a grey child, looking down at his own feet, where the painter has made the riverbed darker in one place than anywhere else. Under it, scratched into the plaster by many hands at many times, the same three words: CARRY ME OVER.".
  Observe nave_wade at nave when not visitedBefore(nave) "The saint over the chancel arch is newer than the church: the Company paid to have him repainted in the year the bridge was opened, and he is up to his ankles in a blue stream, smiling, with a rosy child sitting up on his shoulders like a lord at a fair.".

  // ── The city's past ───────────────────────────────────────────────────────────────────────────────────────────────
  // Thirty-one years ago, at the Michaelmas fair, the city rose against the bridge-penny, and Captain Ralf Sefton
  // hanged ten from the drawbridge chains and burned Water Lane in Overbridge. The reeve was a clerk's boy at the Bridge
  // End; Corbin dug the ten; the captain who comes now is Ralf Sefton's daughter, who held his horses.
  Discovery michaelmas_burning "Thirty-one years ago, at the Michaelmas fair, Wrayford rose against the bridge-penny. The lord's captain, Ralf Sefton, hanged ten men from the drawbridge chains and burned Water Lane in Overbridge, and some of the people in it who would not come out. They are under ten stones by the north wall of Wade's Acre, with one date on all of them.".
  Discovery sefton_daughter "The captain who comes is Lys Sefton, Ralf Sefton's daughter. She was twelve at the Michaelmas Burning, and held her father's horses at the Bridge End while Water Lane burned.".
  Topic hulme_burning with hulme "Ask the reeve whether he has seen a captain's verdict before" when knows(actor, hulme_reasons) once {
    Says "He is quiet a long time. 'Michaelmas fair,' he says. 'I was twelve. A clerk's boy, my father's. He sent me to the Bridge End with a message and I stayed to watch, because I was twelve.' His hand moves on the desk as if it were writing. 'They used the drawbridge chains. Ten. I counted. I was a clerk's boy, I counted everything. And then the wind went round to the south and they fired Water Lane, and the people in the end houses would not come out, because they were the families of the ten.' He looks at the decree on the wall in his son's hand. 'I can smell it now. Thirty-one years. So when you ask me why three men stay on that rail, that is why. Three is not ten. And nobody is in Water Lane.'".
    On discuss { Assert knows(actor, michaelmas_burning). }
  }
  Topic corbin_ten with corbin "Ask Corbin about the ten stones by the north wall" when knows(actor, michaelmas_burning) once {
    Says "'I dug them.' He does not look round at the north wall. 'I was thirty, and digging for my father ten years, and he was sexton still, and he couldn't, after the third. So I did the other seven. In the rain, it was, it rained all that week.' He knocks his pipe out on the wall. 'And then forty years of ordinary dead, which is the best work there is. Old women and drowned boys and babies.' He looks at you. 'That's why I'll not dig for show. I've dug for a captain once.'".
  }
  Observe acre_ten at wades_acre when not dark() and not visitedBefore(wades_acre) "By the north wall, apart from the rest, ten small stones in a row, all the same size, all with the same date and no names, and moss on all of them except where somebody keeps it scraped off the dates.".
  Observe water_lane at overbridge_street when not dark() and not visitedBefore(overbridge_street) "One lane off Overbridge Street is all of a piece, raw brick, every house the same, built in one year: the Liberty calls it the New Row, though it is thirty years old, and nobody under forty knows why it was needed.".
  Topic gault_captain with gault "Ask Gault about the captain who is coming" when not captainHere(wray) once {
    Says "'Sefton.' He turns the cup. 'Old Ralf Sefton's girl. He burned half a street on this river before I was in breeches. She was with him, twelve years old, holding the horses.' He drinks. 'She's been trying not to be him for thirty years. She's a fair captain. Fair's not the same as kind. If she has to choose between the old man's way and getting it wrong, she'll get it wrong his way, and hate it.'".
    On discuss { Assert knows(actor, sefton_daughter). }
  }
  Topic captain_water_lane with sefton "Ask the captain whether she remembers Water Lane" when knows(actor, sefton_daughter) and captainHere(wray) and not verdictGiven(wray) once {
    Says "For the first time something moves in her face. 'I held the horses,' she says. 'At the Bridge End. My father's grey, and his second's, and they would not stand for the smoke.' She puts her cup down very exactly. 'He wrote in his report that Wrayford was pacified. He was right. It has been pacified for thirty-one years.' She looks down the table at the Bench, who are not listening. 'I have the same warrant he had, and the same law. I had rather not have the same report.'".
    On discuss { Increase captainView(sefton) by 1. }
  }

  // ── The days, as chapters ─────────────────────────────────────────────────────────────────────────────────────────
  // The weather walks down the vale with the captain: heat, then thunder in the fells, then the storm on the third
  // evening, then rain on the third night, then a washed morning. Each dawn turns a page.
  Entity chapter_two: fact "The second day". Entity chapter_three: fact "The third day". Entity chapter_night: fact "The third night". Entity chapter_four: fact "The fourth morning".
  Rule dawn_second when secondDay() and hour(clock) >= 6 and inWrayford() and not spread(chapter_two) says "THE SECOND DAY. The heat comes up off the river before the sun is over the fells, and by seven the Market smells of dung and hot stone and, when the wind is from the bridge, of something sweeter underneath that nobody mentions. The crows have found the rail. Somewhere upstream Dunch's mill-wheels are turning; the whole city can hear them when the bell stops." { Assert spread(chapter_two). }
  Rule dawn_third when thirdDay() and hour(clock) >= 6 and inWrayford() and not spread(chapter_three) says "THE THIRD DAY. Thunder in the fells before light, a long way off, like carts going over a bridge. The air is thick and yellow and the swallows are flying low over the water. The dogs of Wrayford will not settle. It is the third day; everybody knows it is the third day, and nobody says so." { Assert spread(chapter_three). }
  Rule night_third_hanging when thirdDay() and hour(clock) >= 21 and stillHanging() and inWrayford() and not spread(chapter_night) says "THE THIRD NIGHT. The storm that has been walking down the vale all day comes over the bridge at the curfew bell: one crack of thunder overhead like a beam breaking, and then the rain, straight down, loud on the leads and the Market and the river. In Northgate the doors are shut that are never shut. Under the gatehouse the dog begins to howl and does not stop." { Assert spread(chapter_night). }
  Rule night_third_down when thirdDay() and hour(clock) >= 21 and not stillHanging() and inWrayford() and not spread(chapter_night) says "THE THIRD NIGHT. The storm comes over the bridge at the curfew bell, and the rain with it, straight down, on the empty rail and on the Acre, where the new turf is darkening by the church door. In Northgate people stand in their doorways and let it rain on them, for no reason they can give." { Assert spread(chapter_night). }
  Rule dawn_fourth when fourthDay() and hour(clock) >= 6 and inWrayford() and not spread(chapter_four) says "THE FOURTH MORNING. Everything is washed: the stones of the Market shine, the river is high and brown and full of sticks, and the air smells of nothing at all for the first time in a week. The captain's riders are saddling in the Bridge End. At nine, the Guildhall." { Assert spread(chapter_four). }
  // The dead, as the days go on, and the heat.
  Observe crows_second at gate_road when secondDay() and stillHanging() and not dark() "Crows on the coping above the three, shifting from foot to foot. Every so often a rider on the leads throws something at them, and they go up, and come down again.".
  Observe crows_third at gate_road when thirdDay() and stillHanging() and not dark() "The crows are bolder today. Nobody throws anything at them now. The sacking over the big man has come loose at one corner and somebody has pinned it back with a hay-fork from the leads, which is worse.".
  Observe heat_gate at gate_road when (secondDay() or thirdDay()) and stillHanging() and not dark() and hour(clock) >= 11 and hour(clock) < 18 "Downwind of the gatehouse the air is sweet and wrong, and people who have to pass breathe through their sleeves.".
  Observe sky_third at market_cross when thirdDay() and hour(clock) >= 12 and hour(clock) < 21 "Over the fells to the north the sky is the colour of a bruise, and the Guildhall clock looks very white against it.".
  Observe rain_night at gate_road when thirdNight() "The rain is coming down the face of the gatehouse in sheets, and off the leads in a spout, and the brazier up there hisses and smokes.".
  Observe washed at market_cross when fourthDay() and hour(clock) < 12 "The Market is washed and steaming in the sun, and the posts are bare where the rain has taken the broadsides off.".

  // ── The third night, uncanny or not ───────────────────────────────────────────────────────────────────────────────
  // Nothing here is confirmed. It is weather, a dog, candles, a river, and what people say.
  Observe omen_chapel at chapel when thirdNight() and stillHanging() "Every candle in the bridge chapel is out, though the door was shut and there is no draught, and the river under the floor is louder than you have heard it.".
  Observe omen_arches at under_arches when thirdNight() and stillHanging() "Out in the dark where Wade's Step is, the water is making a sound like somebody wading, slowly, with something heavy, toward this bank. When you look, there is only the rain on the river.".
  Observe omen_step at wades_step when thirdNight() and stillHanging() "The rain is so loud on the water that you cannot hear your own feet. Once, quite close, you think someone says your name, and it is the river.".
  Rule omen_wharf when thirdDay() and hour(clock) >= 23 and stillHanging() and inWrayford() and not spread(omen_fact) says "Word goes along the Wharf in the rain, from door to door, the way it does: the eel-men on the night barges say they heard someone wading at Wade's Step, out where nobody could be, and singing, low, the carters' hymn. Nobody goes to look." { Assert spread(omen_fact). }
  Entity omen_fact: fact "Someone wading at Wade's Step".

  // ── The Bargeman ──────────────────────────────────────────────────────────────────────────────────────────────────
  // In the deep water at Wade's Step lies an old pike as long as a ferry-boat, that the drovers' cows go round and
  // that Wat Pardoe fed his loaf to, the night he carried the calf. It takes what falls in. Ways past it: knowing the
  // way along the pier's foot (woodcraft, Ham's herd, or being told), Dorcas's boat, the offal cart, the bridge; bread
  // thrown on the water, as Wat did; or a fight that a lone carrier will probably lose.
  Species bargeman_kind "the Bargeman" like great_pike temperament ambush described "A pike older than the bridge, as long as a ferry-boat, the colour of the riverbed, with a lower jaw like a cellar door and eyes like two pennies under water. The eel-men call it the Bargeman because it has taken more cargo off this river than the Company.".
  Person bargeman "the Bargeman" at wades_step {
    Role "an old pike as long as a ferry-boat, that lies in the deep water at Wade's Step". Species bargeman_kind. Level 4. Peaceable. Pronouns it.
  }
  Observe bargeman_seen at wades_step when at(bargeman, wades_step) and able(bargeman) and not tolerates(bargeman, party) "Something moves in the black hole of the Step: not the current. A long shape, longer than you are, turning slowly under the surface with the patience of a thing that has never once been in a hurry.".
  Observe bargeman_fed at wades_step when tolerates(bargeman, party) and able(bargeman) "The long shape lies on the bottom of the Step like a sunk log, its gills working, and lets you by.".
  Discovery bargeman_loaf "When Wat Pardoe carried the calf over the ford in the year of the big snow, he threw his loaf into the deep water at Wade's Step first, for the Bargeman, the way the old drovers did, and went over while it was eating.".
  Action feed_bargeman(actor: group, site: place) "Throw bread into the deep water at Wade's Step, the way the old drovers did" {
    Description "It takes whatever falls in.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wades_step) and at(bargeman, wades_step) and able(bargeman)
      and not tolerates(bargeman, actor) and quantity(actor, rations) >= 1.
    Time 2 minutes.
    On success { Decrease quantity(actor, rations) by 1. Assert tolerates(bargeman, actor). }
    Result "The loaf floats a moment, turning, pale on the black water. Then the water under it bulges, and opens, and there is a mouth there wider than a cart-wheel, and the loaf is gone, and the river closes over the place as if it had never been. You go on along the stones with your heart going, and nothing touches you.".
  }
  Action fight_bargeman(actor: group, site: place) "Go at the Bargeman with whatever you have, there in the water" {
    Description "Up to your thighs in the river, at night, against a thing as long as a boat.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wades_step) and at(bargeman, wades_step) and able(bargeman)
      and not tolerates(bargeman, actor) and not assails(bargeman, actor).
    Time 1 minute.
    On success { Retract peaceable(bargeman). Assert hostile(bargeman, actor). Assert assails(bargeman, actor). }
    Result "You go in at it. The water at the edge of the Step is suddenly not water but a body, cold and solid and moving, and then it turns.".
  }
  // Whoever stands on the Step when the mills stop penning the river is washed back to the bank, if lucky.
  Rule step_floods when at(party, wades_step) and not lowWater() says "The river comes up round your knees, your waist, all at once, as the mills at Wrayholme open their sluices for the morning, and takes your feet from under you. You come up against the pier under the first arch, and drag yourself out on the bank, coughing, with nothing in your hands." {
    Assert at(party, under_arches). }
  Rule bargeman_dead when not able(bargeman) and not spread(bargeman_fact) says "The Bargeman goes down into the Step and does not come up, and then, a long time after, it comes up on its side, pale belly to the rain, and the current takes it away downstream under the arches. In the morning the eel-men find it on the shingle below the tan-yards and stand round it with their caps off, as if at a burying. Ham Ostler comes and looks at it. 'My grandfather fed that fish,' he says, and goes away." { Assert spread(bargeman_fact). Assert at(bargeman, limbo). }
  Entity bargeman_fact: fact "The Bargeman dead".

  // ── Maudie's bread ────────────────────────────────────────────────────────────────────────────────────────────────
  // The one thing in Wrayford nobody counts. She can be asked for it, and it opens what coin cannot.
  Relation maudieBread(group). Relation breadSent(group). Relation jennetBread(group). Relation breadRefused(group).
  Topic maudie_bread with maudie "Ask your mother for bread to take into the city" when homecomer(actor) and not maudieBread(actor) once {
    Says "She looks at the loaves on every surface as if she had not seen them before. 'Take them,' she says. 'Take all of them. Give them to anybody. I can't stop making them and I can't eat them and I can't throw them out.' She is wrapping four in a cloth while she talks, quickly, not looking at you. 'Your father gave bread to anybody. The drovers. That fish of his in the river.' She ties the cloth. 'Give it to the riders, for all I care. Give it to Simon Hulme. Let them choke.' And then, differently: 'No. Let them eat it.'".
    On discuss { Assert maudieBread(actor). Increase quantity(actor, rations) by 4. Assert knows(actor, bargeman_loaf). }
  }
  Topic maudie_bread_stranger with maudie "Ask Maudie Pardoe whether you might take some of her bread to people who need it" when stranger(actor) and maudieWelcomes(actor) and not maudieBread(actor) once {
    Says "She looks at you, and at the loaves, and something in her face gives. 'Need it,' she says. 'Yes. Take it, then.' She wraps four in a cloth. 'My husband fed every drover on the fell road and a fish in the river besides. Give it where it's wanted. Don't tell me where. I'll only argue.'".
    On discuss { Assert maudieBread(actor). Increase quantity(actor, rations) by 4. Assert knows(actor, bargeman_loaf). }
  }
  // Up to the riders on the leads at dusk, in the gate-ward's basket: the widow's bread, to the men who hanged her husband.
  Action send_bread_up(actor: group, site: place) "Send Maudie Pardoe's bread up to the riders on the leads, in the gate-ward's basket" {
    Description "They have been up there four days on the lord's biscuit.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gate_road) and maudieBread(actor) and stillHanging()
      and quantity(actor, rations) >= 2 and hour(clock) >= 17 and hour(clock) < 22 and not breadSent(actor) and at(riders, gate_leads).
    Time 3 minutes.
    On success { Decrease quantity(actor, rations) by 2. Assert breadSent(actor). Assert riderPeaceBought(riders). Assert riderPeace(riders). }
    Result "You put two loaves in the basket that hangs on its rope by the gate-ward's door, and pull the bell, and the basket goes up into the dusk. For a while nothing. Then a rider's face over the parapet, and another. 'Whose?' says Gault's voice. You tell him: Pardoe's widow's. There is a long silence on the leads. Then the basket comes down again, empty, and Gault leans over and looks at you, and at the rail, and says, quite loud, to nobody: 'My lads are tired. They'll sleep sound tonight, all of them. So will I.'".
  }
  Rule bread_peace_ends when hour(clock) == 6 and riderPeaceBought(riders) { Retract riderPeaceBought(riders). Retract riderPeace(riders). }
  // To Jennet: refused, or held.
  Action give_jennet_bread(actor: group, site: place) "Give Jennet Hobday a loaf of Maudie Pardoe's bread" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hobday_room) and at(jennet, hobday_room) and maudieBread(actor)
      and quantity(actor, rations) >= 1 and not jennetBread(jennet) and not breadRefused(jennet) and jennetTrust(jennet) < 2.
    Time 2 minutes.
    On success { Assert breadRefused(jennet). }
    Result "She looks at it, and at you, and you watch her understand whose it is. 'Pardoe bread,' she says. 'Take it out of this room.' She does not raise her voice. You take it out of the room.".
  }
  Action give_jennet_bread_held(actor: group, site: place) "Give Jennet Hobday a loaf of Maudie Pardoe's bread, and say who sent it" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, hobday_room) and at(jennet, hobday_room) and maudieBread(actor)
      and quantity(actor, rations) >= 1 and not jennetBread(jennet) and jennetTrust(jennet) >= 2.
    Time 2 minutes.
    On success { Decrease quantity(actor, rations) by 1. Assert jennetBread(jennet). Increase jennetTrust(jennet) by 1. }
    Result "She takes it in both hands, and holds it in her lap, and does not eat it, and does not give it back. 'She bakes when she can't think,' she says after a long time. 'I've heard that about her. Thirty years across the bridge and I never spoke to her.' She looks at the loaf. 'It's still warm.'".
  }

  // ── What can be seen before it is understood ──────────────────────────────────────────────────────────────────────
  Observe pinch_tally at gate_road when at(pinch, gate_road) and not dark() and not knows(party, daybook_read) and not pinchGone(pinch) "Pinch's tally lies open on the ledge of the booth: a column of entries in ink, very neat, and beside every few lines, so faint you would not see it unless the sun were on the page, a small mark in pencil, like a tick against a sum he is keeping somewhere else.".
  Observe kit_hands at carters_yards when at(kit, carters_yards) and not dark() and not knows(party, kit_driving) "Kit's hands on the grease-brush are scrubbed raw, but there is black in the creases of the knuckles that will not come out. Grease, or something else.".
  Topic maudie_hymn with maudie "Tell your mother that he sang on the road" when homecomer(actor) and knows(actor, wade_hymn) once {
    Says "Her hands stop in the dough. 'Carry me over,' she says. It is not a question. 'He sang it to you when you were small, on the box, coming down off the fells in the dark, when you were frightened of the drop. Carry me over, Wade.' She stands with her floury hands held away from her apron. 'He was never frightened of anything in his life. He sang it for you.' Then she goes back to the dough, and works it very hard, and does not say anything else for a long time.".
  }
  // The Nine Wheels keeps its own count.
  Observe wheels_tenth at wheels_taproom when verdictGiven(wray) and not verdictRebellion(wray) "There is a tenth wheel in the beams of the Nine Wheels now, red, with PARDOE still on the felloe in a carter's paint, and two more beside it that nobody has painted.".
  Topic pell_wheels with pell "Ask Pell about the wheels in the beams" when true once {
    Says "'One for every carter the fell road's had.' She does not look up. 'Fallen off the drop at Scar Top, mostly, or the ice, or a wheel going on the bad bend above the shielings. The first's from my grandmother's time.' She looks up at them. 'There's no wheel for being hanged. There's never been need of one.' She wipes the bar. 'There will be now. The carters have already asked me for the nails.'".
  }
  // Pinch, cornered, has one true thing to say about himself.
  Topic pinch_why with pinch "Ask Pinch why he could not burn the book" when pinchCowed(pinch) once {
    Says "He is quiet so long you think he will not answer. 'Foundling,' he says. 'The Company's charity school, on the Hill. Bread and catechism and sums.' He is looking at the board. 'Nobody ever told me what I was. The board tells you what everything is. A cart is a penny. A beast is a penny.' His voice is very steady. 'The book balances. Both columns. The pencil too; I made it balance. It's the only thing I ever made that was exactly what it said it was.' He looks at you. 'I couldn't burn a true thing. I burned a house down to keep it, and a boy died in the press, and I couldn't burn a book.'".
  }
  // The riders on the gate are from Harbury, and frightened of the thing they guard.
  Topic riders_talk with riders "Ask the riders what they make of the duty" when not asleep(riders) once {
    Says "'Make of it?' The youngest of them laughs, too loud. 'It stinks. That's what we make of it.' Another tells him to shut his mouth. He doesn't. 'Four days. We're from Harbury, we don't know these men from Adam, and every night the big one turns round on his rope to face the town. Every night. There's no wind.' The others are not laughing. 'Sergeant says it's the rope drying. Sergeant says a lot.' He looks along the parapet and away. 'They say here the dead go looking, on the third night.' Somebody throws a crust at him and he catches it and does not eat it.".
  }
  // The tanner keeps his yard's hours.
  Rule crouch_home_night when (hour(clock) >= 22 or hour(clock) < 6) and at(crouch, tanyards) { Assert at(crouch, limbo). }
  Rule crouch_back when hour(clock) >= 6 and hour(clock) < 22 and at(crouch, limbo) { Assert at(crouch, tanyards). }

  // ── Maudie under the rail ─────────────────────────────────────────────────────────────────────────────────────────
  // On the second morning, at the hour Gidley comes to weep, Maudie Pardoe walks down to the Bridge End with a loaf
  // and stands under her husband for an hour, and looks at the gate-ward's door the whole time.
  Relation maudieAtRail(group). Relation stoodWithMaudie(group).
  Rule maudie_to_rail when secondDay() and hour(clock) >= 9 and hour(clock) < 10 and stillHanging() and not maudieAtRail(maudie)
    and at(maudie, pardoe_kitchen) and not mothersWalk(wray) { Assert maudieAtRail(maudie). Assert at(maudie, gate_road). }
  Rule maudie_from_rail when maudieAtRail(maudie) and at(maudie, gate_road) and (hour(clock) >= 10 or not secondDay()) and not maudieGone(maudie) { Assert at(maudie, pardoe_kitchen). }
  Observe maudie_rail at gate_road when at(maudie, gate_road) and maudieAtRail(maudie) and not maudieGone(maudie) "Maudie Pardoe stands under the rail in her apron with a loaf in her two hands, not looking up. Three yards from her, Alderman Gidley weeps beautifully into his handkerchief, and does not see her. The crowd sees both of them. She is looking, the whole time, at the gate-ward's door, and the lock on it, and the decree, the way a carter looks at a gate he means to take a load through.".
  Action stand_with_maudie(actor: group, site: place) "Stand with Maudie Pardoe under the rail" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, gate_road) and at(maudie, gate_road) and maudieAtRail(maudie)
      and not stoodWithMaudie(actor).
    Time 3.
    On success { Assert stoodWithMaudie(actor). Increase temper(wray) by 1. }
    Result "You stand beside her. She does not look at you. After a while she gives you the loaf to hold, because her hands are shaking and she will not have the crowd see it. People stop talking. Gidley finishes weeping and asks Pinch for the takings and goes, and still she stands, and the crowd stays with her, and when the Guildhall clock strikes ten she takes the loaf back and says, to the door, not to you: 'Tomorrow night, then.' And goes home up the Cartway without hurrying.".
  }

  // ── After: Kit ────────────────────────────────────────────────────────────────────────────────────────────────────
  Observe kit_box at carters_yards when verdictGiven(wray) and not kitTaken(kit) and not kitHanged(kit) and not verdictRebellion(wray) "Kit Pardoe is up on the box of the red-wheeled cart, back from the Guildhall yard, with the reins in his hands, not going anywhere. Every so often he speaks to the horse. The other carters leave him to it.".
  Observe kit_grave at wades_acre when verdictGiven(wray) and buried(wat_dead) and not kitTaken(kit) and not kitHanged(kit) and evening() "By the church door, at his father's grave, Kit Pardoe is sitting with his back to the stone, the way he sat on the ford-stone under the arches, looking at the river, which is all there is to look at.".

  // ── Halfway over, with the dead ───────────────────────────────────────────────────────────────────────────────────
  // The one thing that happens to the carrier and is never explained: at the Step, with a body on the back, the
  // weight changes.
  Entity weight_fact: fact "The weight at the Step".
  Rule wade_weight when bearingAny(party) and (at(party, tanyards) or at(party, wades_step) or at(party, wades_acre)) and lowWater() and not spread(weight_fact) says "Halfway over, at the Step, the weight on your back changes. It does not grow heavier, exactly. It grows more: as if what you carried were not one man but a great many, all of them very patient, all of them glad to be going over at last. Your knees go. The water comes to your chest. You do not set him down. And then it is one man again, and cold, and you are on the stones beyond the Step with your breath coming in sobs, and you do not know, then or ever after, what happened." { Assert spread(weight_fact). }

  // ── Carrying, once the way is known ───────────────────────────────────────────────────────────────────────────────
  // The second and third trips are the first one again: once a body has been carried over by the ford and laid in the
  // Acre, the next can be carried the same way in one long choice, and the carrier can go back for the next.
  Relation carriedOver(group).
  Rule first_carried when deadBody(?b) and at(?b, wades_acre) and not borne(?b) and knows(party, ford_way) and not carriedOver(party) { Assert carriedOver(party). }
  Action carry_known_way(actor: group, bearer: member, body: entity, site: place) "Have {bearer} carry {body} over the ford to the Acre, the way you know" {
    Description "The stones, the pier's foot, the far bank, Tanners' Lane, the church, the Acre: the better part of an hour, in the dark, with the weight.".
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, under_arches) and memberOf(bearer, actor) and bearing(bearer, body)
      and carriedOver(actor) and knows(actor, ford_way) and lowWater().
    Time 4.
    On success { Assert at(actor, wades_acre). Retract bearing(bearer, body). Assert at(body, wades_acre). }
    Result "You go the way you went before, and it is worse, because you know it now: the cold to the thighs, the pier's foot under your hand, the black quiet of the Step going by on your left, the tan-pits' stink, the lane, the church door, the Acre. {bearer} sets {body} down by the others.".
  }
  Action go_back_over(actor: group, site: place) "Go back over the ford for the next" {
    Requires able(actor) and company(actor) and at(actor, site) and at(actor, wades_acre) and carriedOver(actor) and knows(actor, ford_way)
      and lowWater() and not bearingAny(actor) and (at(wat_dead, under_arches) or at(dunstan_dead, under_arches) or at(joss_dead, under_arches)).
    Time 3.
    On success { Assert at(actor, under_arches). }
    Result "Back through the church, down the lane, over the stones in the dark with your hands empty, which is somehow harder.".
  }
}

data/assembly/vocabulary.kyr:
Module assembly "What a world is made of, for assembling one" {
  Description "The assembler's commitments are facts in this vocabulary. Geography comes from region modules; kits add powers and what they do to the land. Facts are only ever added while a world is assembled.".
  Kind place. Kind group. Kind sitekind. Kind terrainkind. Kind kit.
  // Geography, read from region modules: areas (settlements, wild country, sites) and the rooms on the ways between.
  Relation region(place). Relation terrain(place, terrainkind). Relation company(group).
  Relation settlement(place). Relation wilds(place). Relation site(place, sitekind).
  Relation within(place, place).
  // A settlement's open middle, where news is heard and trouble arrives; and who keeps its inn.
  Relation square(place, place). Relation keeper(group, place).
  // A room on a road through wild country, a landmark travellers know, a narrow place a road cannot avoid.
  Relation waypoint(place). Relation landmark(place). Relation chokepoint(place). Relation onRoad(place).
  Relation siteKind(place, sitekind).
  Relation adjacent(place, place).
  // Hours between two places by the quickest known way.
  Measure hours(place, place).
  // Powers and their hold on the land.
  Relation power(group). Relation folk(group, entity).
  Relation holds(group, place). Relation raids(group, place). Relation ambushes(group, place).
  Relation tolls(group, place). Relation buysFrom(group, place). Relation serves(group, group).
  Relation buried(place, entity). Relation beneath(place, place).
  // The people a power acts through, as the modules that placed it name them: its chief, its fighting band.
  Relation chief(group, group). Relation band(group, group). Relation bountyOn(place, group).
  // A place given over to one placement's purpose; another kit does not take it.
  Relation taken(place, kit).
  Query free(p: place) means not taken(p, ?k).
  Goal false.
}

